INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开车前起码的要检查一下油量。", "corrected_sentence": "开车前起码要检查一下油量。", "error_description": "“起码”是副词，直接修饰其后的“要”，不能加“的”；应写作“起码要检查”，“起码的要检查”是错误形式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
