INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱来打赌，看谁输谁赢。这样做常常会让人输光钱。", "primary_collocate": null, "pronunciation": "dǔ bó", "ipa": "tu˨˩˦ pwo˧˥", "syllable_count": 2, "sentences": [{"text": "他爱赌博，最后输光了所有的钱。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌博常常让一个家庭变得很穷。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对妈妈保证再也不赌博了。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为赌博欠了很多钱。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家不允许在街上赌博。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们劝他不要再赌博。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌博只会让人输钱，不会让人发财。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赌博过一次，从那以后再也不碰了。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的人都不喜欢赌博。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥迷上了赌博，不去上班了。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赌博了", "label": "体标"}, {"form": "赌博过", "label": "体标"}, {"form": "赌博游戏", "label": "复合"}], "register": "中性", "sense_fingerprint": "用钱打赌比输赢，常让人输光钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赌博", "is_correct": true, "explanation": "正确：“赌博”指用钱打赌，与“输光了所有的钱”相符。"}, {"text": "存钱", "is_correct": false, "explanation": "语义：“存钱”与后半句“输光了所有的钱”矛盾。"}, {"text": "攒钱", "is_correct": false, "explanation": "语义：“攒钱”是积蓄财物，与“输光了钱”的结果不合。"}, {"text": "节约", "is_correct": false, "explanation": "搭配：“爱节约”后接“输光所有的钱”不合逻辑，句意不通。"}], "explanations": {"赌博": "正确：“赌博”指用钱打赌，与“输光了所有的钱”相符。", "存钱": "语义：“存钱”与后半句“输光了所有的钱”矛盾。", "攒钱": "语义：“攒钱”是积蓄财物，与“输光了钱”的结果不合。", "节约": "搭配：“爱节约”后接“输光所有的钱”不合逻辑，句意不通。"}, "sentence_index": 0, "correct_answer": "赌博"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在舞台上赌博跳舞。", "explanation": "这里应该用〈表演〉。“赌博”指用钱打赌，不能用来形容舞台上的表演活动。"}, {"text": "老师赌博了一节课的内容。", "explanation": "这里应该用〈讲解〉。“赌博”是用钱打赌的行为，不能用来指讲解课程。"}, {"text": "这场比赛的赌博是一万元。", "explanation": "这里应该用〈赌注〉。“赌博”指进行赌的行为，所押的钱财要用“赌注”，不能说“赌博是一万元”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赌博", "is_correct": true, "explanation": "正确：“赌博”作主语，说明它只会让人输钱，符合句意。"}, {"text": "存款", "is_correct": false, "explanation": "语义：“存款”不会让人输钱，与“只会让人输钱”矛盾。"}, {"text": "储蓄", "is_correct": false, "explanation": "语义：“储蓄”是积攒钱财，与“只会让人输钱”的意思相反。"}, {"text": "读书", "is_correct": false, "explanation": "搭配：“读书”一般不会“让人输钱”，此处搭配不成立。"}], "explanations": {"赌博": "正确：“赌博”作主语，说明它只会让人输钱，符合句意。", "存款": "语义：“存款”不会让人输钱，与“只会让人输钱”矛盾。", "储蓄": "语义：“储蓄”是积攒钱财，与“只会让人输钱”的意思相反。", "读书": "搭配：“读书”一般不会“让人输钱”，此处搭配不成立。"}, "sentence_index": 6, "correct_answer": "赌博"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和朋友赌博，看谁先到。", "explanation": "这里应该用〈打赌〉。“赌博”指用钱作赌注、靠输赢分配财物的行为，这里没有钱财输赢，只能说打赌。"}, {"text": "她在赌博作业。", "explanation": "这里应该用〈写〉。“赌博”指用钱打赌，不能用来表示写作业。"}, {"text": "医生赌博了一个病人的病情。", "explanation": "这里应该用〈诊断〉。“赌博”不用于医疗活动，医生只能诊断病情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时赌博了过一次，后来就戒了。", "corrected_sentence": "他年轻时赌博过一次，后来就戒了。", "error_description": "错误形式：“赌博了过”。正确形式：“赌博过”。“过”表示经历，应直接接在“赌博”之后，不能与“了”叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们全家都讨厌赌博们。", "corrected_sentence": "我们全家都讨厌赌博。", "error_description": "错误形式：“赌博们”，“们”只用于指人的名词或代词，“赌博”不能加“们”。正确形式：“赌博”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
