INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用金钱作赌注，以偶然的输赢决定财物归属的行为。", "primary_collocate": null, "pronunciation": "dǔ bó", "ipa": "tu˨˩˦ pwo˧˥", "syllable_count": 2, "sentences": [{"text": "赌博是一种用钱决定输赢的行为。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个地方赌博是不合法的。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了几个赌博的人。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上赌博，输赢都很大。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌博不是游戏，是用钱打赌。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律禁止赌博，也禁止开赌场。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赌博的人常常相信自己会赢。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沉迷赌博，丢了工作。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店里有人偷偷赌博。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府正在努力减少赌博。", "target_word": "赌博", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赌博了", "label": "体标"}, {"form": "赌博过", "label": "体标"}, {"form": "赌博游戏", "label": "复合"}], "register": "中性", "sense_fingerprint": "以金钱为赌注靠偶然输赢决定财物归属的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赌博", "is_correct": true, "explanation": "正确：“赌博”指用钱决定输赢的行为，与句子定义相符。"}, {"text": "运动", "is_correct": false, "explanation": "语义：“运动”不是用钱决定输赢的行为。"}, {"text": "储蓄", "is_correct": false, "explanation": "搭配：“储蓄”的结果是存钱，不以输赢决定财物归属，搭配不成立。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“用钱决定输赢”毫无关系。"}], "explanations": {"赌博": "正确：“赌博”指用钱决定输赢的行为，与句子定义相符。", "运动": "语义：“运动”不是用钱决定输赢的行为。", "储蓄": "搭配：“储蓄”的结果是存钱，不以输赢决定财物归属，搭配不成立。", "游泳": "语义：“游泳”与“用钱决定输赢”毫无关系。"}, "sentence_index": 0, "correct_answer": "赌博"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在厨房里赌博做饭。", "explanation": "这里应该用〈烹饪〉。“赌博”指用钱打赌，不能用来表示烹饪这类家务活动。"}, {"text": "学生们在图书馆赌博看书。", "explanation": "这里应该用〈阅读〉。“赌博”指用钱打赌，不能用来表示阅读。"}, {"text": "他把全部赌博都押在了这匹马上。", "explanation": "这里应该用〈赌注〉。“赌博”指进行赌的行为，所押的钱要用“赌注”，不能说“全部赌博”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赌博", "is_correct": true, "explanation": "正确：“赌博的人”指以金钱打赌的人，与“相信自己会赢”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步的人”与“相信自己会赢”没有逻辑联系。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼的人”与“相信自己会赢”没有关系，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“睡觉的人”不会“相信自己会赢”，此处搭配不当。"}], "explanations": {"赌博": "正确：“赌博的人”指以金钱打赌的人，与“相信自己会赢”相符。", "散步": "语义：“散步的人”与“相信自己会赢”没有逻辑联系。", "锻炼": "语义：“锻炼的人”与“相信自己会赢”没有关系，句意不通。", "睡觉": "搭配：“睡觉的人”不会“相信自己会赢”，此处搭配不当。"}, "sentence_index": 6, "correct_answer": "赌博"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和朋友赌博，看谁先写完作业。", "explanation": "这里应该用〈打赌〉。“赌博”指用钱作赌注的行为，这里没有钱财输赢，只能说打赌。"}, {"text": "政府正在修建赌博。", "explanation": "这里应该用〈设施〉。“赌博”是用钱打赌的行为，不是可以修建的设施。"}, {"text": "这个赌博里有很多桌子和机器。", "explanation": "这里应该用〈赌场〉。“赌博”是用钱打赌的行为，不是一个地方；有桌子和机器、供人赌钱的地方叫赌场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他小时候赌博着两次。", "corrected_sentence": "他小时候赌博过两次。", "error_description": "错误形式：“赌博着两次”，“着”表示动作持续，不能表示经历。正确形式：“赌博过两次”，“过”表示曾经有过这种经历，“赌博”是整词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把赌博输了很多钱，最后把房子也卖了。", "corrected_sentence": "他赌博输了很多钱，最后把房子也卖了。", "error_description": "错误形式：“把赌博输了很多钱”，“把”后的宾语应是受事，不能是动词“赌博”。正确形式：“赌博输了很多钱”，“赌博”直接作谓语，后接“输了很多钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
