INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "一个人从脚到头有多高。", "primary_collocate": null, "pronunciation": "shēn gāo", "ipa": "ʂən˥ kau˥", "syllable_count": 2, "sentences": [{"text": "我弟弟的身高已经一米七了。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身高比我高很多。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的身高是多少？", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我的身高长得很快。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身高一米八，是我们班最高的。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的身高跟他爸爸一样。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女儿的身高不到一米三。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和哥哥的身高差不多。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打篮球的人，身高一般都很高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子今年身高长了五厘米。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身高体重", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常说的人有多高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": true, "explanation": "身高：人从脚到头的高度，可以用一米七来表示。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，不能用一米七来表示。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”以岁计，不能说已经一米七了。"}, {"text": "体型", "is_correct": false, "explanation": "体貌：“体型”描述身材轮廓，不以米数计，与“一米七”不符。"}], "explanations": {"身高": "身高：人从脚到头的高度，可以用一米七来表示。", "体重": "语义：“体重”指身体的重量，不能用一米七来表示。", "年龄": "语义：“年龄”以岁计，不能说已经一米七了。", "体型": "体貌：“体型”描述身材轮廓，不以米数计，与“一米七”不符。"}, "sentence_index": 0, "correct_answer": "身高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高很重，有八十公斤。", "explanation": "这里应该用〈体重〉。身高只说高矮，说轻重要用体重。"}, {"text": "我的身高很苗条，大家都羡慕。", "explanation": "这里应该用〈身材〉。身高只说高矮，苗条描述体形，要用身材。"}, {"text": "这座楼的身高有三十层。", "explanation": "身高专指人或动物从脚到头的高度，楼的高低应说高度，此处用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": true, "explanation": "身高：人从脚到头的高度，可以用不到一米三来表示。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，以斤或公斤计，不能说不到一米三。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”多用于衣物或物件，不用来说人的一米三。"}, {"text": "尺码", "is_correct": false, "explanation": "搭配：“尺码”用于衣鞋，不用于人的身长。"}], "explanations": {"身高": "身高：人从脚到头的高度，可以用不到一米三来表示。", "体重": "语义：“体重”指身体的重量，以斤或公斤计，不能说不到一米三。", "尺寸": "搭配：“尺寸”多用于衣物或物件，不用来说人的一米三。", "尺码": "搭配：“尺码”用于衣鞋，不用于人的身长。"}, "sentence_index": 6, "correct_answer": "身高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的身高有三十公斤。", "explanation": "这里应该用〈体重〉。身高按米或厘米计，公斤是体重的单位。"}, {"text": "这个孩子的身高很结实。", "explanation": "这里应该用〈身体〉。结实形容身体强壮，身高只表示长度，不能用来修饰。"}, {"text": "这块蛋糕的身高是十厘米。", "explanation": "“身高”只用于人或动物，蛋糕的高度要说高度，此处用法不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这一年身高长了五斤。", "corrected_sentence": "我这一年身高长了五厘米。", "error_description": "“身高”是长度，应以厘米计；“斤”是重量单位，不能用来计量身高，此处应改为“长了五厘米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷的身高是一百七十公斤。", "corrected_sentence": "爷爷的身高是一百七十厘米。", "error_description": "“身高”是长度，应以厘米计；“公斤”是重量单位，此处应改为“一百七十厘米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
