INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "人体从脚底到头顶的垂直长度。", "primary_collocate": null, "pronunciation": "shēn gāo", "ipa": "ʂən˥ kau˥", "syllable_count": 2, "sentences": [{"text": "医生在学校给学生量身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站好，我来量一下身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格上要写姓名、年龄和身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器能测身高和体重。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士用仪器量了他的身高，是一百七十五厘米。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身高的单位一般是厘米。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办证件时，工作人员问了我的身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年体检都要记下身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把尺子可以用来测身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的线记着孩子每年的身高。", "target_word": "身高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身高体重", "label": "复合"}], "register": "中性", "sense_fingerprint": "测量记录的人体垂直长度数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": true, "explanation": "身高：用尺测得的人体垂直长度，可以被“量”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是人体，医生不会去量它的数据，与“给学生量”不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“量”来测，应说“问”或“看”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心的感受，无法用“量”来测，与此句的测量语境不符。"}], "explanations": {"身高": "身高：用尺测得的人体垂直长度，可以被“量”。", "书包": "语义：书包不是人体，医生不会去量它的数据，与“给学生量”不符。", "年龄": "搭配：“年龄”不能用“量”来测，应说“问”或“看”。", "心情": "语义：“心情”是内心的感受，无法用“量”来测，与此句的测量语境不符。"}, "sentence_index": 0, "correct_answer": "身高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的身高有三千米。", "explanation": "这里应该用〈高度〉。身高只指人或动物的身长，山的高低要用高度。"}, {"text": "这个孩子的身高有五十公斤。", "explanation": "这里应该用〈体重〉。身高按米或厘米计，公斤是体重的单位。"}, {"text": "这件衣服的身高正好。", "explanation": "这里应该用〈尺寸〉。身高指人从脚到头的长度，衣服的大小要说尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": true, "explanation": "身高：办证件时可能被询问的个人身体数据。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音大小，不属于个人证件信息。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心的感受，办证件时工作人员不会询问，与身体数据的语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物件，不能被工作人员询问。"}], "explanations": {"身高": "身高：办证件时可能被询问的个人身体数据。", "音量": "语义：“音量”指声音大小，不属于个人证件信息。", "心情": "语义：“心情”是内心的感受，办证件时工作人员不会询问，与身体数据的语境不符。", "窗户": "语义：“窗户”是物件，不能被工作人员询问。"}, "sentence_index": 6, "correct_answer": "身高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱的身高是一米八。", "explanation": "“身高”只用于人或动物，冰箱的高度要说高度，此处用法不对。"}, {"text": "他的身高比我重了五十斤。", "explanation": "这里应该用〈体重〉。身高说高矮，比较轻重要用体重。"}, {"text": "这把伞的身高太高了，撑不住。", "explanation": "这里应该用〈高度〉。身高只指人或动物从脚到头的长度，伞的高低要说高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士给我称了身高。", "corrected_sentence": "护士给我量了身高。", "error_description": "“称”用于称重，测身高要用“量”，此处应改为“量了身高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "体检时医生量了我的身高，是一百七十公斤。", "corrected_sentence": "体检时医生量了我的身高，是一百七十厘米。", "error_description": "身高是长度，应以厘米计；“公斤”是重量单位，此处应改为“一百七十厘米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
