INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97047, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "说的是不久以前到现在这一小段时间。", "primary_collocate": null, "pronunciation": "jìn lái", "ipa": "tɕin˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "近来天气很冷，我总是穿大衣。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他近来很忙，没时间看电影。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近来我每天都睡得很早。", "target_word": "近来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈近来身体不太好，常去医院。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店近来客人多了不少。", "target_word": "近来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你近来工作怎么样？", "target_word": "近来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟近来喜欢上了踢足球。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近来下了几场雨，花园里的花开了。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我近来在学做中国菜。", "target_word": "近来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老王近来心情很好，每天都笑着。", "target_word": "近来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "近來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "近来：副词，指不久以前到现在这一小段时间，常放在句首或谓语前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“我总是穿大衣”描述的长期习惯不协调。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，修饰动作而不修饰“天气很冷”这类状态，句意不成立。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”修饰动作的即刻发生，不修饰“天气很冷”这类状态。"}, {"text": "近来", "is_correct": true, "explanation": "副词，指不久以前到现在这一小段时间，与“天气很冷”的近期状况相符。"}], "explanations": {"忽然": "语义：“忽然”表示突然发生，与“我总是穿大衣”描述的长期习惯不协调。", "马上": "语义：“马上”表示即刻发生，修饰动作而不修饰“天气很冷”这类状态，句意不成立。", "立刻": "搭配：“立刻”修饰动作的即刻发生，不修饰“天气很冷”这类状态。", "近来": "副词，指不久以前到现在这一小段时间，与“天气很冷”的近期状况相符。"}, "sentence_index": 0, "correct_answer": "近来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那天下午两点，她近来走进了办公室。", "explanation": "这里应该用〈当时〉。“近来”指不久以前到现在的一段时间，不能与某一个具体的过去时刻连用，描述那一刻要用〈当时〉。"}, {"text": "近来，恐龙统治过地球。", "explanation": "这里应该用〈很久以前〉。“近来”只指不久以前到现在，远古的事要用〈很久以前〉。"}, {"text": "他近来明天要出国。", "explanation": "“近来”指不久以前到现在的一段时间，不能与“明天”这样具体的将来时间连用，直接说“他明天要出国”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不变，与“喜欢上了”表示开始的变化不符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即刻发生，与“喜欢上了”这种已形成的状态不协调。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“喜欢上了”的完成态矛盾。"}, {"text": "近来", "is_correct": true, "explanation": "副词，指不久以前到现在这一小段时间，与“喜欢上了踢足球”的变化相符。"}], "explanations": {"一直": "语义：“一直”表示持续不变，与“喜欢上了”表示开始的变化不符。", "马上": "语义：“马上”表示即刻发生，与“喜欢上了”这种已形成的状态不协调。", "正在": "体貌：“正在”表示进行中，与“喜欢上了”的完成态矛盾。", "近来": "副词，指不久以前到现在这一小段时间，与“喜欢上了踢足球”的变化相符。"}, "sentence_index": 6, "correct_answer": "近来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山近来很高。", "explanation": "“近来”表示不久以前到现在的变化，描述山的固定高度不能用，应说“这座山很高”。"}, {"text": "他近来是北京人。", "explanation": "“近来”不能用于说明出身这类固定事实，应说“他是北京人”。"}, {"text": "我近来在2015年去过北京。", "explanation": "“近来”是模糊的近期时段，不能与具体年份连用，应直接说“2015年去过北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "近来得他很累，不想出门。", "corrected_sentence": "近来他很累，不想出门。", "error_description": "“近来”后面多加了“得”。“近来”是副词，后面直接接主语，不能加“得”。正确形式是“近来他很累，不想出门。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "的近来他常常加班。", "corrected_sentence": "近来他常常加班。", "error_description": "“近来”前面多加了“的”。作为副词，它直接放在主语后或句首，不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
