INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97048, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "指不久以前到现在的这段时间。", "primary_collocate": null, "pronunciation": "jìn lái", "ipa": "tɕin˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "近来物价涨得很快，大家都说贵。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她近来常常给我打电话。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我近来睡不好，白天很累。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市近来多了很多新地铁站。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李近来学习很努力，老师夸了他。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近来公司的生意越来越好。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你近来见过老同学吗？", "target_word": "近来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸近来不喝酒了，也不抽烟了。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近来大家都在谈这部新电影。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子近来长高了不少。", "target_word": "近来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "近來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "近来：副词，表示从不久前到现在这段时间里的情况或变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，只能修饰形容词或动词，不能直接修饰主语“物价”，句子不成立。"}, {"text": "马上", "is_correct": false, "explanation": "体貌：“马上”表示即将发生，与已经发生的涨价不协调。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示历经等待后的结果，与“涨得很快”的近期变化无关。"}, {"text": "近来", "is_correct": true, "explanation": "副词，指不久前到现在的情况变化，与“物价涨得很快，大家都说贵”相符。"}], "explanations": {"非常": "语法：“非常”是程度副词，只能修饰形容词或动词，不能直接修饰主语“物价”，句子不成立。", "马上": "体貌：“马上”表示即将发生，与已经发生的涨价不协调。", "终于": "语义：“终于”表示历经等待后的结果，与“涨得很快”的近期变化无关。", "近来": "副词，指不久前到现在的情况变化，与“物价涨得很快，大家都说贵”相符。"}, "sentence_index": 0, "correct_answer": "近来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我近来在昨天晚上给老师打了电话。", "explanation": "“近来”指不久以前到现在的一段时间，不能与“昨天晚上”这样的具体时刻连用，单次动作只需说明那个时刻。"}, {"text": "近来，恐龙统治过地球。", "explanation": "这里应该用〈很久以前〉。“近来”只指不久以前到现在，远古的事要用〈很久以前〉。"}, {"text": "他近来后天要去上海。", "explanation": "“近来”指不久以前到现在的一段时间，不能与“后天”这样具体的将来时间连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与“你见过老同学吗”询问经历的语境不协调。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示即刻发生，不能与“见过”这种经历性动作搭配。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中，与“见过”表示的已有经历矛盾。"}, {"text": "近来", "is_correct": true, "explanation": "副词，指不久前到现在这段时间，与“见过老同学吗”的近期询问相符。"}], "explanations": {"忽然": "语义：“忽然”表示突然发生，与“你见过老同学吗”询问经历的语境不协调。", "立刻": "搭配：“立刻”表示即刻发生，不能与“见过”这种经历性动作搭配。", "正在": "体貌：“正在”表示进行中，与“见过”表示的已有经历矛盾。", "近来": "副词，指不久前到现在这段时间，与“见过老同学吗”的近期询问相符。"}, "sentence_index": 6, "correct_answer": "近来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我近来在三年前搬到了这里。", "explanation": "“近来”是不久以前到现在的模糊时段，不能与“三年前”这样具体的过去时间连用，应直接说“我三年前搬到了这里”。"}, {"text": "这个孩子近来是男孩。", "explanation": "“近来”表示近期的变化，说明性别这类固定事实时不能用，应说“这个孩子是男孩”。"}, {"text": "我近来出生在北京。", "explanation": "“近来”不能用于说明出生这类固定经历，应说“我出生在北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "交通状况很近来改善了很多。", "corrected_sentence": "交通状况近来改善了很多。", "error_description": "“近来”前面被加上了程度副词“很”。“近来”是时间副词，不能被“很”修饰，正确形式是“交通状况近来改善了很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近来的大家都在讨论交通问题。", "corrected_sentence": "近来大家都在讨论交通问题。", "error_description": "“近来”后面多加了“的”，修饰“大家”的结构不成立。正确形式是“近来大家都在讨论交通问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
