INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从危险或不好的环境中逃走并离开。", "primary_collocate": null, "pronunciation": "táo lí", "ipa": "tʰɑʊ˧˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "他终于逃离了那个不幸的家。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人想逃离大城市的压力。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始后，不少家庭逃离了家乡。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了三年时间才逃离那段痛苦的生活。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人冒着危险逃离了战区。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想逃离无聊的工作，过上新的生活。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的鸟成功逃离了危险的森林。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经逃离过那座危险的小岛。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了逃离危险的环境，她搬到了外地。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想逃离贫穷的生活。", "target_word": "逃离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃离了", "label": "完成体"}, {"form": "逃离过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "从危险或不好的环境中逃走并离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃离", "is_correct": true, "explanation": "正确：“逃离”表示从不好的环境中逃走，与“不幸的家”相符。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：装饰是美化的行为，与“不幸的家”以及“终于”表达的解脱之感矛盾。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象通常是人或客人，不能用于“不幸的家”。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是人或事情，“祝贺那个不幸的家”不成立。"}], "explanations": {"逃离": "正确：“逃离”表示从不好的环境中逃走，与“不幸的家”相符。", "装饰": "语义：装饰是美化的行为，与“不幸的家”以及“终于”表达的解脱之感矛盾。", "欢迎": "搭配：“欢迎”的对象通常是人或客人，不能用于“不幸的家”。", "祝贺": "搭配：“祝贺”的对象是人或事情，“祝贺那个不幸的家”不成立。"}, "sentence_index": 0, "correct_answer": "逃离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天七点逃离家去上班。", "explanation": "这里应该用〈离开〉。逃离指从危险或不好的环境中逃走，每天正常出门上班不是这种情况。"}, {"text": "我们明天一早从家里逃离，去郊外玩。", "explanation": "这里应该用〈出发〉。逃离强调从危险或不好的环境中逃走，去郊外玩动身要用〈出发〉。"}, {"text": "他一转身，逃离了飞来的球。", "explanation": "这里应该用〈躲开〉。逃离的对象是地方或环境，躲避飞来的球要用〈躲开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃离", "is_correct": true, "explanation": "正确：“逃离”表示从危险的环境中逃走，与“受伤的鸟”“危险的森林”相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：鸟不会打扫森林，与句意矛盾。"}, {"text": "种植", "is_correct": false, "explanation": "语义：受伤的鸟不能种植森林，“成功种植”与句意不符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：受伤的鸟无力保护森林，且“危险的森林”说明它要离开，而不是守护。"}], "explanations": {"逃离": "正确：“逃离”表示从危险的环境中逃走，与“受伤的鸟”“危险的森林”相符。", "打扫": "语义：鸟不会打扫森林，与句意矛盾。", "种植": "语义：受伤的鸟不能种植森林，“成功种植”与句意不符。", "保护": "语义：受伤的鸟无力保护森林，且“危险的森林”说明它要离开，而不是守护。"}, "sentence_index": 6, "correct_answer": "逃离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一听到门铃，就逃离了厨房去开门。", "explanation": "这里应该用〈走向〉。逃离指躲避危险或不好的环境而离开，去开门只是走过去，应该用〈走向〉。"}, {"text": "他看了几分钟比赛，就逃离了球场去买饮料。", "explanation": "这里应该用〈离开〉。逃离指躲避危险或不好的环境而离开，去买饮料只是离开，应该用〈离开〉。"}, {"text": "他很快逃离了那根绳子。", "explanation": "这里应该用〈挣脱〉。逃离的对象是地方或环境，挣开绳子的束缚要用〈挣脱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个家庭终于逃离着那个危险的地方。", "corrected_sentence": "这个家庭终于逃离了那个危险的地方。", "error_description": "错误：“逃离”后加了“着”。“逃离”是一次性完成的动作，“终于”后应用“了”，应改为“逃离了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只想尽快逃离了那个城市。", "corrected_sentence": "他只想尽快逃离那个城市。", "error_description": "错误：“想”表示尚未实现的愿望，“逃离”后不能加“了”。应改为“他只想尽快逃离那个城市。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
