INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97055, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用导线把两个电器或设备接在一起，使它们能通电或传递信号。", "primary_collocate": null, "pronunciation": "lián xiàn", "ipa": "li̯ɛn³⁵ ɕi̯ɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "他把两个喇叭连线了。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把音箱和电脑连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电工正在给新灯连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先连线，再打开电源。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个机器还没连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥学会了给电视连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会给这台机器连线吗？", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一根长线给两个灯连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "线太短，没法连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连线了", "label": "体标"}, {"form": "连线过", "label": "体标"}, {"form": "連線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用线把两个设备接在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97055, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连线", "is_correct": true, "explanation": "正确：“连线”指用线把两个喇叭接在一起，与“把两个喇叭……了”搭配。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”的对象是文件或软件，不能用于喇叭。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”是不及物动词，不能直接带“把”的宾语。"}, {"text": "通话", "is_correct": false, "explanation": "搭配：“通话”指人或电话之间的通话，不能说“把喇叭通话”。"}], "explanations": {"连线": "正确：“连线”指用线把两个喇叭接在一起，与“把两个喇叭……了”搭配。", "下载": "语义：“下载”的对象是文件或软件，不能用于喇叭。", "见面": "配价：“见面”是不及物动词，不能直接带“把”的宾语。", "通话": "搭配：“通话”指人或电话之间的通话，不能说“把喇叭通话”。"}, "sentence_index": 0, "correct_answer": "连线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条隧道连线两个城市。", "explanation": "这里应该用〈连接〉。“连线”指用线把设备接起来，隧道连接两地不能说“连线”。"}, {"text": "工人用焊枪把两根铁管连线在一起。", "explanation": "这里应该用〈焊接〉。“连线”指用线把设备接起来，焊接金属管要说“焊接”。"}, {"text": "妈妈把两块布连线在一起。", "explanation": "这里应该用〈缝〉。“连线”指用线把电器或设备接通，缝布料要说“缝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连线", "is_correct": true, "explanation": "正确：“给这台机器连线”指用线把机器接上，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，机器不能唱歌，不能说“给这台机器唱”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象须是饮品，不能说“给机器喝”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”是人的情感动作，不能“给机器哭”，句意不通。"}], "explanations": {"连线": "正确：“给这台机器连线”指用线把机器接上，与句意相符。", "唱": "语义：“唱”的对象是歌曲，机器不能唱歌，不能说“给这台机器唱”。", "喝": "搭配：“喝”的对象须是饮品，不能说“给机器喝”。", "哭": "语义：“哭”是人的情感动作，不能“给机器哭”，句意不通。"}, "sentence_index": 6, "correct_answer": "连线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路连线山顶。", "explanation": "这里应该用〈通向〉。“连线”指用线把设备接起来，道路通往山顶要说“通向”。"}, {"text": "他用绳子把狗连线在树上。", "explanation": "这里应该用〈拴〉。“连线”用于电器或通信线路，拴狗要说“拴”。"}, {"text": "我把画连线在墙上。", "explanation": "这里应该用〈挂〉。“连线”指用线接通设备，画挂在墙上要说“挂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经给灯连线着。", "corrected_sentence": "他已经给灯连线了。", "error_description": "体标错误：“已经”表示动作已完成，应与“了”搭配；“着”表示持续，应说“他已经给灯连线了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没给这台机器连线了。", "corrected_sentence": "我还没给这台机器连线。", "error_description": "“没”与“了”不能同用：否定未发生的动作用“没”，去掉“了”，应说“还没给这台机器连线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
