INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使电话、网络等通信线路接通，建立联系。", "primary_collocate": null, "pronunciation": "lián xiàn", "ipa": "li̯ɛn³⁵ ɕi̯ɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "我们现在连线北京的记者。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络太慢，连线失败了。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请稍等，马上为您连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话已经连线了。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主持人和现场记者连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天上午我们连线开会。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和妈妈视频连线。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在网上和学生连线上课。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩在手机上连线玩游戏。", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，怎么才能连线成功？", "target_word": "连线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连线了", "label": "体标"}, {"form": "连线过", "label": "体标"}, {"form": "連線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "接通电话或网络，建立联系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连线", "is_correct": true, "explanation": "正确：“连线”指通过通信线路与北京的记者接通联系。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能用于记者。"}, {"text": "见面", "is_correct": false, "explanation": "配价：“见面”不带直接宾语，应说“和北京的记者见面”。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”的常见义是击打，不表示通过线路接通联系。"}], "explanations": {"连线": "正确：“连线”指通过通信线路与北京的记者接通联系。", "吃": "语义：“吃”的对象是食物，不能用于记者。", "见面": "配价：“见面”不带直接宾语，应说“和北京的记者见面”。", "打": "语义：“打”的常见义是击打，不表示通过线路接通联系。"}, "sentence_index": 0, "correct_answer": "连线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用钉子把两块木板连线在一起。", "explanation": "这里应该用〈钉〉。“连线”指接通通信线路、建立联系，把木板钉在一起要说“钉”。"}, {"text": "工人在河上连线了一座桥。", "explanation": "这里应该用〈架〉。“连线”指接通通信线路、建立联系，在河上建桥要说“架”。"}, {"text": "同学们在操场上连线等候。", "explanation": "这里应该用〈排队〉。“连线”指接通通信线路、建立联系，站队等候要说“排队”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连线", "is_correct": true, "explanation": "正确：“视频连线”指通过视频接通与妈妈的联系。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能用于视频联系。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是切割，与视频联系无关。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”需要具体物体作宾语，不能与“视频”搭配。"}], "explanations": {"连线": "正确：“视频连线”指通过视频接通与妈妈的联系。", "喝": "语义：“喝”的对象是饮品，不能用于视频联系。", "切": "语义：“切”是切割，与视频联系无关。", "搬": "搭配：“搬”需要具体物体作宾语，不能与“视频”搭配。"}, "sentence_index": 6, "correct_answer": "连线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们把积木连线拼成了房子。", "explanation": "这里应该用〈拼〉。“连线”指接通线路或建立通信联系，拼积木要说“拼”。"}, {"text": "他把灯笼连线在门口。", "explanation": "这里应该用〈挂〉。“连线”指接通线路，灯笼挂在门口要说“挂”。"}, {"text": "我们把珠子连线起来。", "explanation": "这里应该用〈串〉。“连线”指接通电话或网络、建立联系，把珠子穿起来要说“串”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天和北京的记者连线着。", "corrected_sentence": "我们昨天和北京的记者连线了。", "error_description": "体标错误：“昨天”指已完成的动作，应与“了”搭配；“着”表示持续，应说“昨天和北京的记者连线了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们还没和北京的记者连线了。", "corrected_sentence": "我们还没和北京的记者连线。", "error_description": "“没”与“了”不能同用：否定未发生的动作用“没”，去掉“了”，应说“还没和北京的记者连线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
