INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97064, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用玻璃等制成、能映出人或物形象的日常用品。", "primary_collocate": null, "pronunciation": "jìng zi", "ipa": "tɕiŋ˥˩ tsɯ", "syllable_count": 2, "sentences": [{"text": "墙上挂着一面大镜子。", "target_word": "镜子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子是玻璃做的。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想买一面小镜子。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "浴室的镜子很干净。", "target_word": "镜子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不小心打破了镜子。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这面镜子挂在门后面。", "target_word": "镜子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子太脏了，要擦一擦。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在衣柜门上装了一面镜子。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "包里放着一面圆圆的小镜子。", "target_word": "镜子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镜子碎了，地上都是玻璃。", "target_word": "镜子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "鏡子", "label": "繁体"}, {"form": "穿衣镜", "label": "复合"}], "register": "中性", "sense_fingerprint": "玻璃等制成的日常用品，可以买、挂、擦、打破", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba7539fe-b5aa-4d48-a3b7-ff2bf389d79f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "镜子", "is_correct": true, "explanation": "正确：“镜子”是能挂在墙上的平面器物，“墙上挂着一面大镜子”与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：桌子的量词用“张”，不说一面大桌子。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能挂在墙上。"}, {"text": "床", "is_correct": false, "explanation": "语义：床太大且不能挂在墙上，句意不通。"}], "explanations": {"镜子": "正确：“镜子”是能挂在墙上的平面器物，“墙上挂着一面大镜子”与句意相符。", "桌子": "搭配：桌子的量词用“张”，不说一面大桌子。", "面包": "语义：面包是食物，不能挂在墙上。", "床": "语义：床太大且不能挂在墙上，句意不通。"}, "sentence_index": 0, "correct_answer": "镜子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房用镜子切菜。", "explanation": "这里应该用〈刀〉。切菜的是刀，镜子是用来映出人影的器物。"}, {"text": "这台相机的镜子很干净。", "explanation": "这里应该用〈镜头〉。相机上的透镜叫镜头，镜子是用来照人影的器物。"}, {"text": "奶奶用镜子看药瓶上的小字，看得清清楚楚。", "explanation": "这里应该用〈放大镜〉。能把小字放大看清的是放大镜，镜子是用来映出人影的器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": true, "explanation": "正确：“镜子”是能照见自己的器物，“这面镜子太脏了”与句意相符。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：碗不用量词“面”，“一面碗”搭配不当。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能用“面”计量，也不需要擦。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是落下的水滴，不能用“面”计量，也不用擦。"}], "explanations": {"镜子": "正确：“镜子”是能照见自己的器物，“这面镜子太脏了”与句意相符。", "碗": "搭配：碗不用量词“面”，“一面碗”搭配不当。", "空气": "语义：空气看不见摸不着，不能用“面”计量，也不需要擦。", "雨": "语义：雨是落下的水滴，不能用“面”计量，也不用擦。"}, "sentence_index": 6, "correct_answer": "镜子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她戴着镜子去上班，很精神。", "explanation": "这里应该用〈眼镜〉。戴在脸上的是眼镜，镜子是用来照人影的器物。"}, {"text": "妈妈在镜子里煮了一碗面。", "explanation": "这里应该用〈锅〉。煮面用的是锅，镜子是用来映出人影的器物。"}, {"text": "这部手机的镜子碎了。", "explanation": "这里应该用〈屏幕〉。手机显示画面的部分叫屏幕，镜子是用来照人影的玻璃器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在商店买了一只小镜子。", "corrected_sentence": "他在商店买了一面小镜子。", "error_description": "“小镜子”的量词应用“面”，不宜用“只”。“只”多用于动物、成对的物品或某些器皿，不用于扁平的镜子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了一面的镜子。", "corrected_sentence": "妈妈给我买了一面镜子。", "error_description": "量词短语“一面”后不能直接加“的”修饰名词，应说“一面镜子”；错误在“一面”与“镜子”之间多出了“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c27a180a-eb20-4381-a774-badff1db7e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
