INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97071, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "唱戏或比赛开始了，大家准备好看。", "primary_collocate": null, "pronunciation": "kāi tái", "ipa": "kʰai˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "戏马上就要开台了，快坐好。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上七点，大戏准时开台。", "target_word": "开台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开台以后，台下一下子安静了。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这出戏七点开台，现场已经坐满了人。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们早早坐在台下，等着戏开台。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的戏班今天下午开台，我们一起去看。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "戏还没开台，演员们正在后台化妆。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说明天京剧开台，你想去吗？", "target_word": "开台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷最爱看戏，每次开台前都早早到场。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "锣鼓敲了三下，大戏开台了。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开台了", "label": "体标"}, {"form": "开过台", "label": "体标"}], "register": "中性", "sense_fingerprint": "戏或比赛开始，观众准备观看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开台", "is_correct": true, "explanation": "开台指戏曲演出开始，与“快坐好”的语境相符。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场指演出结束，与“快坐好”提示开场相矛盾。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：打烊用于商店收市，不说“戏打烊”。"}, {"text": "收摊", "is_correct": false, "explanation": "搭配：收摊指摊贩收工，不用于戏曲演出的开始或结束。"}], "explanations": {"开台": "开台指戏曲演出开始，与“快坐好”的语境相符。", "散场": "语义：散场指演出结束，与“快坐好”提示开场相矛盾。", "打烊": "搭配：打烊用于商店收市，不说“戏打烊”。", "收摊": "搭配：收摊指摊贩收工，不用于戏曲演出的开始或结束。"}, "sentence_index": 0, "correct_answer": "开台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影七点开台，我们快进去。", "explanation": "这里应该用〈开始〉。开台专指戏曲演出或比赛开场，电影不说开台。"}, {"text": "舞会八点开台，大家都到了。", "explanation": "这里应该用〈开场〉。开台限于戏曲演出和比赛，舞会应说开场。"}, {"text": "展览会上午十点开台，欢迎参观。", "explanation": "这里应该用〈开幕〉。开台限于戏曲演出和比赛，展览会应说开幕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开台", "is_correct": true, "explanation": "开台指戏曲演出开始，与“还没”及后台化妆的语境相符。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：打烊用于商店收市，不说“戏打烊”。"}, {"text": "收工", "is_correct": false, "explanation": "语义：收工指劳动或工作结束，不用来说戏曲演出开始，与“演员正在后台化妆”准备开演的语境不符。"}, {"text": "停业", "is_correct": false, "explanation": "搭配：停业用于商店或企业，不说“戏停业”。"}], "explanations": {"开台": "开台指戏曲演出开始，与“还没”及后台化妆的语境相符。", "打烊": "搭配：打烊用于商店收市，不说“戏打烊”。", "收工": "语义：收工指劳动或工作结束，不用来说戏曲演出开始，与“演员正在后台化妆”准备开演的语境不符。", "停业": "搭配：停业用于商店或企业，不说“戏停业”。"}, "sentence_index": 6, "correct_answer": "开台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "婚礼十点开台，客人请准时到。", "explanation": "这里应该用〈举行〉。开台限于戏曲演出和比赛，婚礼应说举行。"}, {"text": "博物馆九点开台，欢迎参观。", "explanation": "这里应该用〈开放〉。开台限于戏曲演出和比赛，博物馆应说开放。"}, {"text": "工厂八点开台，工人请准时上班。", "explanation": "这里应该用〈开工〉。开台限于戏曲演出和比赛，工厂应说开工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚的越剧八点被开台，我们一起去吧。", "corrected_sentence": "今晚的越剧八点开台，我们一起去吧。", "error_description": "被字句错误：“开台”是不及物动词，不能用“被”字句。错句中的“被开台”应改为“开台”，应说“八点开台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大戏已经开台着，观众请入座。", "corrected_sentence": "大戏已经开台了，观众请入座。", "error_description": "“着”误用：“开台”是瞬间完成的动作，不能用“着”表示持续状态，此处应改为“了”，说“大戏已经开台了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
