INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "戏曲等演出或比赛开始。", "primary_collocate": null, "pronunciation": "kāi tái", "ipa": "kʰai˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "京剧晚上七点半开台，别迟到。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "戏台上的灯亮了，戏要开台了。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的越剧下午三点开台。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开台前，演员们都很紧张。", "target_word": "开台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "因为下雨，今天的大戏晚了一个小时才开台。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开台前，班主先给观众鞠了一躬。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天露天的戏准时开台，你来不来？", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都等着，戏终于开台了。", "target_word": "开台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这出戏三点开台，四点半就能结束。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们赶到剧院时，戏刚开台。", "target_word": "开台", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开台了", "label": "体标"}, {"form": "开过台", "label": "体标"}], "register": "中性", "sense_fingerprint": "戏曲演出或比赛正式开始", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开台", "is_correct": true, "explanation": "开台指戏曲演出开始，与“别迟到”提示按时开场的语境相符。"}, {"text": "停演", "is_correct": false, "explanation": "语义：停演指停止演出，与“别迟到”提示按时开场相矛盾。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：打烊用于商店收市，不说“京剧打烊”。"}, {"text": "开业", "is_correct": false, "explanation": "搭配：开业用于商店或企业，不用于京剧演出。"}], "explanations": {"开台": "开台指戏曲演出开始，与“别迟到”提示按时开场的语境相符。", "停演": "语义：停演指停止演出，与“别迟到”提示按时开场相矛盾。", "打烊": "搭配：打烊用于商店收市，不说“京剧打烊”。", "开业": "搭配：开业用于商店或企业，不用于京剧演出。"}, "sentence_index": 0, "correct_answer": "开台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电脑早上开台，请稍等。", "explanation": "这里应该用〈开机〉。开台只用于戏曲演出或比赛开始，电脑应说开机。"}, {"text": "商店明早开台，欢迎光临。", "explanation": "这里应该用〈开业〉。开台限于戏曲演出和比赛，商店应说开业。"}, {"text": "考试九点开台，请准时入场。", "explanation": "这里应该用〈开考〉。开台限于戏曲演出和比赛，考试应说开考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开台", "is_correct": true, "explanation": "开台指戏曲演出开始，与“准时”和邀约的语境相符。"}, {"text": "收场", "is_correct": false, "explanation": "语义：收场指演出结束，与“你来不来”的邀请语境矛盾。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场指观众离场，不能用来邀请观众前来观看。"}, {"text": "关门", "is_correct": false, "explanation": "搭配：关门用于门或店铺，不说戏“准时关门”。"}], "explanations": {"开台": "开台指戏曲演出开始，与“准时”和邀约的语境相符。", "收场": "语义：收场指演出结束，与“你来不来”的邀请语境矛盾。", "散场": "语义：散场指观众离场，不能用来邀请观众前来观看。", "关门": "搭配：关门用于门或店铺，不说戏“准时关门”。"}, "sentence_index": 6, "correct_answer": "开台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议九点开台，请大家准时出席。", "explanation": "这里应该用〈召开〉。开台限于戏曲演出和比赛，会议应说召开。"}, {"text": "航班十点开台，请系好安全带。", "explanation": "这里应该用〈起飞〉。开台限于戏曲演出和比赛，航班应说起飞。"}, {"text": "银行九点开台，欢迎办理业务。", "explanation": "这里应该用〈营业〉。开台限于戏曲演出和比赛，银行应说营业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "越剧晚上七点准时开过台，别迟到。", "corrected_sentence": "越剧晚上七点准时开台，别迟到。", "error_description": "体标错误：“过”表示经历，不能与“晚上七点”这类将来的时间搭配；错句中的“开过台”应改为“开台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这出戏七点被开台了，观众请入座。", "corrected_sentence": "这出戏七点开台了，观众请入座。", "error_description": "被字句错误：“开台”是不及物动词，不能用“被”字句。错句中的“被开台”应改为“开台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
