INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97076, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有条理地叙述事情或说明自己的看法。", "primary_collocate": null, "pronunciation": "chén shù", "ipa": "ʈʂʰən˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在会上陈述了自己的看法。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你简单陈述一下你的理由。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理有条理地陈述了新的计划。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陈述观点时，声音不大，但很清楚。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，每个人都要陈述自己的意见。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的想法陈述得很有条理。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组长向大家陈述了这个办法的好处。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先陈述一下我的看法，再听大家说。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用三句话陈述了自己的主要意见。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时，请清楚地陈述你选择这个工作的原因。", "target_word": "陈述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陈述了", "label": "体标（了）"}, {"form": "陈述过", "label": "体标（过）"}, {"form": "陈述着", "label": "体标（着）"}, {"form": "陈述句", "label": "复合"}], "register": "书面", "sense_fingerprint": "有条理地说明自己的看法、理由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcb9bf9a-83f8-472b-8785-c83fd83bb296') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：陈述 chén shù，表示有条理地叙述事情或说明自己的看法。"}, {"text": "尘世", "is_correct": false, "explanation": "shì 与 shù 韵母不同（i 与 u），尘世意思是人世间，指世俗的世界。"}, {"text": "陈设", "is_correct": false, "explanation": "shè 与 shù 韵母不同（e 与 u），陈设意思是摆设、布置。"}, {"text": "臣属", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，臣属意思是臣子、下属。"}, {"text": "成束", "is_correct": false, "explanation": "chéng 与 chén 韵尾不同（ng 与 n），成束意思是捆成一束。"}], "explanations": {"陈述": "正确：陈述 chén shù，表示有条理地叙述事情或说明自己的看法。", "尘世": "shì 与 shù 韵母不同（i 与 u），尘世意思是人世间，指世俗的世界。", "陈设": "shè 与 shù 韵母不同（e 与 u），陈设意思是摆设、布置。", "臣属": "shǔ（第三声）与 shù（第四声）声调不同，臣属意思是臣子、下属。", "成束": "chéng 与 chén 韵尾不同（ng 与 n），成束意思是捆成一束。"}, "sentence_index": null, "correct_answer": "陈述"}, "level_3": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：“陈述”表示有条理地说明，“他在会上陈述了自己的看法”符合语境。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：举办多用于活动、展览，不能用于“自己的看法”。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：嘲笑的对象多是人或言行，不能说“嘲笑自己的看法”。"}, {"text": "倾听", "is_correct": false, "explanation": "语义：倾听是用心听别人的说法，不能用于自己说出看法。"}], "explanations": {"陈述": "正确：“陈述”表示有条理地说明，“他在会上陈述了自己的看法”符合语境。", "举办": "搭配：举办多用于活动、展览，不能用于“自己的看法”。", "嘲笑": "搭配：嘲笑的对象多是人或言行，不能说“嘲笑自己的看法”。", "倾听": "语义：倾听是用心听别人的说法，不能用于自己说出看法。"}, "sentence_index": 0, "correct_answer": "陈述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她陈述了自己的伤心，哭了一场。", "explanation": "这里应该用〈倾诉〉。陈述用于观点、理由等说明性内容，表达伤心要用“倾诉”。"}, {"text": "她陈述观点时，一个字也没说。", "explanation": "“陈述”表示说出观点，与“一个字也没说”相矛盾；这里表达的是不说，应该用〈沉默〉。"}, {"text": "她陈述了这幅画的颜色和线条。", "explanation": "这里应该用〈描绘〉。陈述用于观点、理由等说明性内容，描绘颜色和线条要用“描绘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陈述", "is_correct": true, "explanation": "正确：“陈述”表示有条理地说明，“小组长向大家陈述了这个办法的好处”符合语境。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理用于机器、物品，不能用于“办法的好处”。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：打印用于文件、材料，不能用于“好处”。"}, {"text": "讥讽", "is_correct": false, "explanation": "语义：讥讽是挖苦嘲弄，与向大家说明办法好处的语境相反。"}], "explanations": {"陈述": "正确：“陈述”表示有条理地说明，“小组长向大家陈述了这个办法的好处”符合语境。", "修理": "搭配：修理用于机器、物品，不能用于“办法的好处”。", "打印": "搭配：打印用于文件、材料，不能用于“好处”。", "讥讽": "语义：讥讽是挖苦嘲弄，与向大家说明办法好处的语境相反。"}, "sentence_index": 6, "correct_answer": "陈述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面试时，请清楚地陈述你的微笑，大家都很喜欢。", "explanation": "这里应该用〈展现〉。陈述用于理由、看法等说明性内容，微笑要用“展现”。"}, {"text": "面试时，请清楚地陈述你选择这个工作的原因，但一句话都不要说。", "explanation": "“陈述”表示说明理由，与“一句话都不要说”相矛盾；这里表达的是不说，应该用〈沉默〉。"}, {"text": "面试时，请清楚地陈述你的紧张，大家都理解。", "explanation": "这里应该用〈表达〉。陈述用于理由、看法等说明性内容，表达紧张这类感情要用“表达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这个计划陈述很清楚。", "corrected_sentence": "他把这个计划陈述得很清楚。", "error_description": "“陈述”后引出补语要用“得”，写作“陈述得很清楚”；缺少“得”，语法错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面试时，请你把理由陈述地清楚一些。", "corrected_sentence": "面试时，请你把理由陈述得清楚一些。", "error_description": "“陈述”后引出补语要用“得”，不能用“地”；“陈述地清楚”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '603e5290-2117-430e-98a8-faaf8fe40b09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
