INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家不在一起，用电话一起说话开会。", "primary_collocate": null, "pronunciation": "diàn huà huì yì", "ipa": "tjɛn˥˩ xwa˥˩ xweɪ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "我们三个人在不同地方，只好开电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸出差了，周末全家开了个电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚八点，同学们开电话会议商量毕业旅行。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会议比见面方便，不用坐车。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长开了一次电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话会议里说话太小声了。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会议结束后，大家都很累。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能参加明天的电话会议吗？", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的电话会议已经开始了。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话会议只有十分钟。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "开电话会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家分开在各处，用电话一起开会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话会议", "is_correct": true, "explanation": "正确：“开”后接会议，电话会议指大家分在各处、用电话一起开的会，与“在不同地方”相符。"}, {"text": "舞会", "is_correct": false, "explanation": "语义：舞会要大家聚在一处跳舞，与“在不同地方”矛盾。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“开”不接“午饭”，应说“吃午饭”。"}, {"text": "体检", "is_correct": false, "explanation": "搭配：“开”不接“体检”，应说“做体检”。"}], "explanations": {"电话会议": "正确：“开”后接会议，电话会议指大家分在各处、用电话一起开的会，与“在不同地方”相符。", "舞会": "语义：舞会要大家聚在一处跳舞，与“在不同地方”矛盾。", "午饭": "搭配：“开”不接“午饭”，应说“吃午饭”。", "体检": "搭配：“开”不接“体检”，应说“做体检”。"}, "sentence_index": 0, "correct_answer": "电话会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用电话会议看到了彼此的笑脸。", "explanation": "这里应该用〈视频会议〉。电话会议只能靠声音，看不到彼此的笑脸；看到人要用视频会议。"}, {"text": "电话会议上，大家一起去郊外游玩。", "explanation": "这里应该用〈郊游〉。电话会议里大家分在各处，不能一起去郊外游玩；集体外出要说郊游。"}, {"text": "我们在电话会议上看到了很多新产品。", "explanation": "这里应该用〈展览会〉。电话会议只能听，看不到实物；看新产品要去展览会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话会议", "is_correct": true, "explanation": "正确：“结束后”前是一个会议，电话会议指多人用电话同时开的会，有明确的结束。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，没有“结束”的过程。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是一个有结束时间的活动。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“结束”不搭配“地址”这类名词。"}], "explanations": {"电话会议": "正确：“结束后”前是一个会议，电话会议指多人用电话同时开的会，有明确的结束。", "咖啡": "语义：咖啡是饮料，没有“结束”的过程。", "感冒": "语义：感冒是疾病，不是一个有结束时间的活动。", "地址": "搭配：“结束”不搭配“地址”这类名词。"}, "sentence_index": 6, "correct_answer": "电话会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们三个人在电话会议上一起包饺子。", "explanation": "这里应该用〈聚餐〉。电话会议里大家不在同一处，无法一起包饺子吃饭；一起动手做饭吃饭要说聚餐。"}, {"text": "妈妈在电话会议上亲手给我们端来了热汤。", "explanation": "这里应该用〈看望〉。电话会议只能通话，不能亲手端东西过来；亲自前来问候要说看望。"}, {"text": "全家在电话会议上一起去超市买了菜。", "explanation": "这里应该用〈购物〉。电话会议只能通话，不能一起去超市买菜；去商店挑选买东西要说购物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几个人分散在各地，只能开三只电话会议。", "corrected_sentence": "我们几个人分散在各地，只能开三场电话会议。", "error_description": "量词用错：“只”用于动物、物件等，会议应用“场”。应说“开三场电话会议”，不说“开三只电话会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把电话会议开了两个小时。", "corrected_sentence": "这场电话会议开了两个小时。", "error_description": "量词用错：“把”用于有把手的东西，会议应用“场”。应说“这场电话会议”，不说“这把电话会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
