INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过电话让相隔两地的多人同时交谈的会议。", "primary_collocate": null, "pronunciation": "diàn huà huì yì", "ipa": "tjɛn˥˩ xwa˥˩ xweɪ˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "明天上午九点我们开电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在参加一个电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为大家在不同的城市，所以开了电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次电话会议要讨论新产品的价格。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会议开了一个小时才结束。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电话会议的时间告诉大家。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在家里参加了公司的电话会议。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午有一场电话会议，你别忘了。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话会议上，北京和上海的同事都发了言。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最怕开电话会议，因为听不清别人说话。", "target_word": "电话会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "开电话会议", "label": "复合"}], "register": "中性", "sense_fingerprint": "多人通过电话在不同地点同时开的会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电话会议", "is_correct": true, "explanation": "正确：“开”后接“会议”，电话会议指通过电话同时开的会，与“明天上午九点”相符。"}, {"text": "日记", "is_correct": false, "explanation": "搭配：“开”不接“日记”，应说“写日记”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不能被“开”，句子说的是要开一个会。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“开”不接“作业”，应说“做作业”。"}], "explanations": {"电话会议": "正确：“开”后接“会议”，电话会议指通过电话同时开的会，与“明天上午九点”相符。", "日记": "搭配：“开”不接“日记”，应说“写日记”。", "感冒": "语义：感冒是一种疾病，不能被“开”，句子说的是要开一个会。", "作业": "搭配：“开”不接“作业”，应说“做作业”。"}, "sentence_index": 0, "correct_answer": "电话会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们通过电话会议看到了对方的脸。", "explanation": "这里应该用〈视频会议〉。电话会议只传递声音，看不到对方的脸；能看见对方要用视频会议。"}, {"text": "电话会议上，大家一起在草地上野餐。", "explanation": "这里应该用〈郊游〉。电话会议里大家不在同一地点，不能一起在草地上野餐；集体外出游玩要说郊游。"}, {"text": "我们在电话会议上看到了新产品的样品。", "explanation": "这里应该用〈展览会〉。电话会议只能听，看不到实物样品；看样品应在展览会上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电话会议", "is_correct": true, "explanation": "正确：“参加”后接会议，电话会议是多人通过电话同时开的会，符合“公司的”语境。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“参加”不接“食堂”这类场所，不能说“参加食堂”。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：宿舍是住的地方，不是可以参加的活动。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是病人的记录，与公司的活动无关。"}], "explanations": {"电话会议": "正确：“参加”后接会议，电话会议是多人通过电话同时开的会，符合“公司的”语境。", "食堂": "搭配：“参加”不接“食堂”这类场所，不能说“参加食堂”。", "宿舍": "语义：宿舍是住的地方，不是可以参加的活动。", "病历": "语义：病历是病人的记录，与公司的活动无关。"}, "sentence_index": 6, "correct_answer": "电话会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在电话会议上一起搬了一张沙发。", "explanation": "这里应该用〈搬家〉。电话会议里大家不在同一地点，无法一起动手搬沙发；一起搬动家里的东西要说搬家。"}, {"text": "电话会议的会场挂满了彩色气球，很热闹。", "explanation": "这里应该用〈晚会〉。电话会议没有实际会场，挂满气球、热闹欢聚的场景属于晚会。"}, {"text": "我们在电话会议上一起逛了一下午的商场。", "explanation": "这里应该用〈逛街〉。电话会议里大家不在同一地点，无法一起逛商场；一起去商场闲逛要说逛街。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下午要开一条电话会议，讨论合同。", "corrected_sentence": "我们下午要开一场电话会议，讨论合同。", "error_description": "量词用错：“条”用于细长的东西，会议应用“场”。应说“开一场电话会议”，不说“开一条电话会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天参加了一位电话会议。", "corrected_sentence": "他今天参加了一场电话会议。", "error_description": "量词用错：“位”用于人，不能修饰“会议”；应说“一场电话会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
