INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事情变坏之前，先发出声音或信号让人知道。", "primary_collocate": null, "pronunciation": "yù jǐng", "ipa": "y˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "汽车靠近障碍物时，会发出声音预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟雾太大，机器会自动预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手表能在心跳太快时预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的灯一闪，就是在预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟大声叫，向同伴预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会用声音提前预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警报器响了，是在向大家预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水位太高时，系统会先预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "倒车时，车会用声音预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它用红灯向路人预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预警了", "label": "体标"}, {"form": "预警信号", "label": "复合"}, {"form": "预警系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "情况变坏前用声音或信号先提醒人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97083, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警 yù jǐng：事情变坏之前用声音或信号先提醒人，本题答案。"}, {"text": "雨景", "is_correct": false, "explanation": "雨景 yǔ jǐng：第一个音节声调不同（yǔ 为第三声，yù 为第四声），意思是下雨时的景色。"}, {"text": "语境", "is_correct": false, "explanation": "语境 yǔ jìng：两个音节的声调都与 yù jǐng 不同，意思是语言所处的环境。"}, {"text": "玉镜", "is_correct": false, "explanation": "玉镜 yù jìng：第二个音节声调不同（jìng 为第四声，jǐng 为第三声），意思是玉做的镜子。"}], "explanations": {"预警": "预警 yù jǐng：事情变坏之前用声音或信号先提醒人，本题答案。", "雨景": "雨景 yǔ jǐng：第一个音节声调不同（yǔ 为第三声，yù 为第四声），意思是下雨时的景色。", "语境": "语境 yǔ jìng：两个音节的声调都与 yù jǐng 不同，意思是语言所处的环境。", "玉镜": "玉镜 yù jìng：第二个音节声调不同（jìng 为第四声，jǐng 为第三声），意思是玉做的镜子。"}, "sentence_index": null, "correct_answer": "预警"}, "level_3": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警：在事情变坏之前用声音提醒人，与“发出声音”相符。"}, {"text": "刹车", "is_correct": false, "explanation": "语义：刹车是司机踩刹车的动作，不是汽车自己发出声音，与句意不符。"}, {"text": "闪烁", "is_correct": false, "explanation": "语义：闪烁形容光亮时明时暗，不能用来修饰“声音”。"}, {"text": "报告", "is_correct": false, "explanation": "搭配：“报告”要说明报告的内容或对象，不能与“发出声音”直接搭配。"}], "explanations": {"预警": "预警：在事情变坏之前用声音提醒人，与“发出声音”相符。", "刹车": "语义：刹车是司机踩刹车的动作，不是汽车自己发出声音，与句意不符。", "闪烁": "语义：闪烁形容光亮时明时暗，不能用来修饰“声音”。", "报告": "搭配：“报告”要说明报告的内容或对象，不能与“发出声音”直接搭配。"}, "sentence_index": 0, "correct_answer": "预警"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈轻轻预警我，该出门了。", "explanation": "这里应该用〈提醒〉。预警用于灾害或危险来临之前的警告，出门这类日常提示不能说“预警”。"}, {"text": "学校预警家长，明天放假。", "explanation": "这里应该用〈通知〉。放假是好事，不是即将变坏的事，不能用“预警”。"}, {"text": "电脑会预警文件已经保存。", "explanation": "这里应该用〈提示〉。文件保存好是已经完成的好结果，不是需要提前警告的危险，不能用“预警”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警：在危险来临前用声音或信号警告大家，与“警报器响了”相符。"}, {"text": "亮起", "is_correct": false, "explanation": "配价：“亮起”是不及物动词，不能带“向大家”引出的对象，句子读起来不通。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：鼓掌是人为致意或庆祝的动作，与“警报器响了”所表示的危险信号不符。"}, {"text": "调研", "is_correct": false, "explanation": "配价：“调研”的对象是被调查的事物，不能用“向大家”引出，句子不通。"}], "explanations": {"预警": "预警：在危险来临前用声音或信号警告大家，与“警报器响了”相符。", "亮起": "配价：“亮起”是不及物动词，不能带“向大家”引出的对象，句子读起来不通。", "鼓掌": "语义：鼓掌是人为致意或庆祝的动作，与“警报器响了”所表示的危险信号不符。", "调研": "配价：“调研”的对象是被调查的事物，不能用“向大家”引出，句子不通。"}, "sentence_index": 6, "correct_answer": "预警"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师预警他写得很好。", "explanation": "这里应该用〈夸奖〉。预警用于即将发生的坏事，表扬别人的好表现不能用“预警”。"}, {"text": "他预警了大家这个好消息。", "explanation": "这里应该用〈宣布〉。预警表示提前发出危险或坏事的警告，好消息不能用“预警”。"}, {"text": "我预警了朋友今晚的电影时间。", "explanation": "这里应该用〈告诉〉。预警表示提前发出危险或坏事的警告，电影时间不是需要警告的事，不能用“预警”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雷达发现前面有车，会先把声音预警司机。", "corrected_sentence": "雷达发现前面有车，会先用声音预警司机。", "error_description": "错误在“把”。“用声音”表示方式，要用“用”引出，不能换成“把”。应说“会先用声音预警司机”，“把声音预警司机”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水位一上涨，系统就会很预警村民。", "corrected_sentence": "水位一上涨，系统就会预警村民。", "error_description": "“很”一般修饰形容词，不能直接修饰“预警”这样的行为动词。应删去“很”，说“就会预警村民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
