INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在灾害或危险发生之前，提前发出警告。", "primary_collocate": null, "pronunciation": "yù jǐng", "ipa": "y˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "气象台提前两天预警台风。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震前，专家没有办法预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区下大雨，政府及时预警了。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地政府已经向居民预警洪水。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会在地震来之前预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的城市要提前预警大浪。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家预警今年夏天会有大雨。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水涨得太快，要马上预警。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校通过广播预警，让学生离开操场。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预警这个冬天会有流感。", "target_word": "预警", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预警了", "label": "体标"}, {"form": "预警信号", "label": "复合"}, {"form": "预警系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "灾害或危险来临前提前警告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警 yù jǐng：在灾害或危险来临之前提前发出警告，本题答案。"}, {"text": "雨景", "is_correct": false, "explanation": "雨景 yǔ jǐng：第一个音节声调不同（yǔ 为第三声，yù 为第四声），意思是下雨时的景色。"}, {"text": "语境", "is_correct": false, "explanation": "语境 yǔ jìng：两个音节的声调都与 yù jǐng 不同，意思是语言所处的环境。"}, {"text": "玉镜", "is_correct": false, "explanation": "玉镜 yù jìng：第二个音节声调不同（jìng 为第四声，jǐng 为第三声），意思是玉做的镜子。"}], "explanations": {"预警": "预警 yù jǐng：在灾害或危险来临之前提前发出警告，本题答案。", "雨景": "雨景 yǔ jǐng：第一个音节声调不同（yǔ 为第三声，yù 为第四声），意思是下雨时的景色。", "语境": "语境 yǔ jìng：两个音节的声调都与 yù jǐng 不同，意思是语言所处的环境。", "玉镜": "玉镜 yù jìng：第二个音节声调不同（jìng 为第四声，jǐng 为第三声），意思是玉做的镜子。"}, "sentence_index": null, "correct_answer": "预警"}, "level_3": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警：在危险发生前提前发出警告，与“提前两天”和“台风”相符。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”指人或动物为了避开危险而行动，气象台不能“躲避”台风，不符合句意。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路等建筑，不能与“台风”搭配。"}, {"text": "解除", "is_correct": false, "explanation": "搭配：“解除”多用于警报、武装等，台风不能被“解除”。"}], "explanations": {"预警": "预警：在危险发生前提前发出警告，与“提前两天”和“台风”相符。", "躲避": "语义：“躲避”指人或动物为了避开危险而行动，气象台不能“躲避”台风，不符合句意。", "修建": "搭配：“修建”用于房屋、道路等建筑，不能与“台风”搭配。", "解除": "搭配：“解除”多用于警报、武装等，台风不能被“解除”。"}, "sentence_index": 0, "correct_answer": "预警"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校预警家长，下周要开运动会。", "explanation": "这里应该用〈通知〉。预警指灾害或危险来临前提前发出警告，开运动会是普通安排，不能用“预警”。"}, {"text": "我预警朋友帮了我的忙。", "explanation": "这里应该用〈感谢〉。预警表示提前警告危险，朋友的帮助是好事，不能用“预警”。"}, {"text": "大家预警他考上了大学。", "explanation": "这里应该用〈祝贺〉。考上大学是好事，不是即将变坏的事，不能用“预警”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预警", "is_correct": true, "explanation": "预警：在灾害发生前提前提醒人，与“今年夏天会有大雨”这种预测相符。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”针对人的行为，不能用来引出“会有大雨”这样的自然现象。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝的是值得高兴的事，“会有大雨”这样的预告不适合用“庆祝”。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”的宾语应是可以买的东西，不能接“今年夏天会有大雨”这样的小句。"}], "explanations": {"预警": "预警：在灾害发生前提前提醒人，与“今年夏天会有大雨”这种预测相符。", "禁止": "语义：“禁止”针对人的行为，不能用来引出“会有大雨”这样的自然现象。", "庆祝": "语义：庆祝的是值得高兴的事，“会有大雨”这样的预告不适合用“庆祝”。", "购买": "配价：“购买”的宾语应是可以买的东西，不能接“今年夏天会有大雨”这样的小句。"}, "sentence_index": 6, "correct_answer": "预警"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向老板预警了他的生日。", "explanation": "这里应该用〈提醒〉。预警表示提前警告危险或坏事，生日不是需要警告的事，不能用“预警”。"}, {"text": "老师预警他写得很好。", "explanation": "这里应该用〈夸奖〉。预警表示提前警告危险，表扬好的表现不能用“预警”。"}, {"text": "裁判预警了比赛的结果。", "explanation": "这里应该用〈公布〉。预警表示提前发出危险或坏事的警告，比赛结果是事后公布的，不能用“预警”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风快要来了，气象局会提前的预警居民。", "corrected_sentence": "台风快要来了，气象局会提前预警居民。", "error_description": "“的”不能加在动词“预警”前面，“提前”后应直接接动词。应删去“的”，说“会提前预警居民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河水涨得太快，村长会马上预警过大家。", "corrected_sentence": "河水涨得太快，村长会马上预警大家。", "error_description": "“过”表示曾经有过的经历，与将来的“会马上”矛盾。正确说法是“会马上预警大家”，不能说“会马上预警过大家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
