INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "喂养并照料动物，使其生长。", "primary_collocate": null, "pronunciation": "sì yǎng", "ipa": "sɿ˥˩ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "农民在村子里饲养了很多牛。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢饲养小鸟。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家农场饲养着几百只羊。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饲养鸡鸭要每天喂水和喂食。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家没有地方饲养大狗。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷饲养过十年蜜蜂。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在城市里饲养宠物需要办证。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把这些小猪饲养得很健康。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校允许学生饲养小兔子。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饲养熊猫需要很多竹子。", "target_word": "饲养", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "饲养了", "label": "体标"}, {"form": "饲养着", "label": "体标"}, {"form": "饲养过", "label": "体标"}, {"form": "饲养场", "label": "复合"}], "register": "书面", "sense_fingerprint": "喂养并照料动物使其生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饲养", "is_correct": true, "explanation": "正确：“饲养”指喂养并照料动物，与“很多牛”相符。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植的对象是植物，不能用于牛。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路，不能说“修建很多牛”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地，不说“打扫很多牛”。"}], "explanations": {"饲养": "正确：“饲养”指喂养并照料动物，与“很多牛”相符。", "种植": "语义：种植的对象是植物，不能用于牛。", "修建": "搭配：“修建”用于房屋、道路，不能说“修建很多牛”。", "打扫": "搭配：“打扫”的对象是场地，不说“打扫很多牛”。"}, "sentence_index": 0, "correct_answer": "饲养"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校饲养了很多优秀的学生。", "explanation": "这里应该用〈培养〉。饲养只用于动物，培养人才要用“培养”。"}, {"text": "农民在田里饲养了很多玉米。", "explanation": "这里应该用〈种植〉。饲养的对象是动物，玉米是植物，要用“种植”。"}, {"text": "奶奶每天饲养生病的孙子。", "explanation": "这里应该用〈照顾〉。饲养只用于动物，照顾生病的人要用“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饲养", "is_correct": true, "explanation": "正确：“饲养”指喂养并照料动物，与“宠物”相符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象多是物品、作品，不说“收藏宠物”。"}, {"text": "维修", "is_correct": false, "explanation": "语义：“维修”针对机器、设备，不能用于动物。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化物件或房间，与宠物无关。"}], "explanations": {"饲养": "正确：“饲养”指喂养并照料动物，与“宠物”相符。", "收藏": "搭配：“收藏”的对象多是物品、作品，不说“收藏宠物”。", "维修": "语义：“维修”针对机器、设备，不能用于动物。", "装饰": "语义：“装饰”是美化物件或房间，与宠物无关。"}, "sentence_index": 6, "correct_answer": "饲养"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位园丁饲养了很多名贵的兰花。", "explanation": "这里应该用〈栽培〉。饲养用于动物，兰花是植物，要用“栽培”。"}, {"text": "妈妈每天饲养宝宝，按时给他喂奶。", "explanation": "这里应该用〈喂养〉。饲养用于动物，给婴儿喂奶要用“喂养”。"}, {"text": "奶奶饲养他长大，他很感激。", "explanation": "这里应该用〈抚养〉。饲养用于动物，把孩子养大要用“抚养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把三只小鸡饲养后院。", "corrected_sentence": "他把三只小鸡饲养在后院。", "error_description": "处所前缺“在”：“饲养”后接处所要加“在”，应说“饲养在后院”，不说“饲养后院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山上饲养了着很多羊。", "corrected_sentence": "他们在山上饲养着很多羊。", "error_description": "“了”与“着”不能同时出现：应说“饲养着很多羊”，不说“饲养了着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
