INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97096, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "高原反应的简称，指到高海拔地区后出现头痛、气短等不适。", "primary_collocate": null, "pronunciation": "gāo fǎn", "ipa": "kɑʊ˥ fan˨˩˦", "syllable_count": 2, "sentences": [{"text": "到拉萨以后，我有高反，头很疼。", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去高原旅行，要先了解高反。", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说，高反一般两三天就会好。", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种药可以帮你缓解高反。", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高反的症状有头痛、气短。", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我同学高反很轻，只是有点气短。", "target_word": "高反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去青海前，我买了防高反的药。", "target_word": "高反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游说第一天别洗澡，免得高反。", "target_word": "高反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了高海拔地区，有人没有高反。", "target_word": "高反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有高反，头疼不疼？", "target_word": "高反", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "高反：高原反应的简称，头痛气短等症状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高反", "is_correct": true, "explanation": "正确：高反，到高原后出现的头痛、气短等不适。"}, {"text": "高原", "is_correct": false, "explanation": "语义：“高原”指地形，不是身体的症状，“我有高原”说不通。"}, {"text": "高山", "is_correct": false, "explanation": "语义：“高山”指很高的山，不能表示身体的不适。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“有”后面要接症状或疾病，“海拔”是高度数值，不能说“有海拔”。"}], "explanations": {"高反": "正确：高反，到高原后出现的头痛、气短等不适。", "高原": "语义：“高原”指地形，不是身体的症状，“我有高原”说不通。", "高山": "语义：“高山”指很高的山，不能表示身体的不适。", "海拔": "搭配：“有”后面要接症状或疾病，“海拔”是高度数值，不能说“有海拔”。"}, "sentence_index": 0, "correct_answer": "高反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃了太多冰淇淋，肚子高反了。", "explanation": "这里应该用〈不舒服〉。高反只指到高海拔地区后的头痛、气短，吃坏肚子不能用高反。"}, {"text": "我一紧张就高反，手心直出汗。", "explanation": "这里不能用高反。高反只指到高海拔地区后的不适，不能形容紧张时的反应。"}, {"text": "夏天要注意防高反，多喝水。", "explanation": "这里应该用〈中暑〉。高反只指高海拔地区的不适，夏天怕热引起的病要用中暑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高反", "is_correct": true, "explanation": "正确：高反，去高原后头痛、气短等不适，所以要买药预防。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：药不能防盗，“防小偷的药”说不通。"}, {"text": "火灾", "is_correct": false, "explanation": "语义：药不能防火，“防火灾的药”说不通。"}, {"text": "雷电", "is_correct": false, "explanation": "搭配：“防”后面通常接身体上的病或不适，“雷电”不能这样搭配。"}], "explanations": {"高反": "正确：高反，去高原后头痛、气短等不适，所以要买药预防。", "小偷": "语义：药不能防盗，“防小偷的药”说不通。", "火灾": "语义：药不能防火，“防火灾的药”说不通。", "雷电": "搭配：“防”后面通常接身体上的病或不适，“雷电”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "高反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一喝咖啡就高反，睡不着觉。", "explanation": "这里不能用高反。高反只指到高海拔地区后的头晕、气短，喝咖啡后的不适不能用它。"}, {"text": "你对花粉有没有高反，要说一下。", "explanation": "这里应该用〈过敏〉。高反只指高海拔引起的不适，对花粉引起的反应要用过敏。"}, {"text": "他一坐船就高反，吐了好几次。", "explanation": "这里应该用〈晕船〉。高反只指高海拔引起的不适，坐船引起的不适要用晕船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年在青海有过一条高反。", "corrected_sentence": "他去年在青海有过一次高反。", "error_description": "错误：“高反”前的量词用了“条”，“条”用于细长的东西。正确：高反是一次发作，要用“次”，说“一次高反”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "到了拉萨，他有了一张很严重的高反。", "corrected_sentence": "到了拉萨，他有了一次很严重的高反。", "error_description": "错误：“高反”前的量词用了“张”，“张”用于平的东西。正确：高反是一次发作，要用“次”，说“一次很严重的高反”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
