INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "高速铁路的简称，也指在其上运行的高速列车。", "primary_collocate": null, "pronunciation": "gāo tiě", "ipa": "kɑʊ˥ tʰiɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "现在坐高铁去北京只要四个小时。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市刚开通了高铁。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近正在修一条高铁。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国的高铁已经连起了很多大城市。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高铁比普通火车快得多，票也贵一些。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周末都坐高铁回老家。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明天一早要坐高铁去上海出差。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了高铁，两个城市之间的来往方便多了。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多外国游客来中国都想坐一次高铁。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那条高铁明年就能通车。", "target_word": "高铁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "列", "label": "量词"}, {"form": "趟", "label": "量词"}, {"form": "高铁站", "label": "复合"}, {"form": "高鐵", "label": "繁体"}], "register": "中性", "sense_fingerprint": "高速铁路及其列车的简称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高铁", "is_correct": true, "explanation": "正确：“坐高铁”是交通方式，四个小时到北京符合常识。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯只在楼内上下，不能用来去北京。"}, {"text": "马车", "is_correct": false, "explanation": "语义：马车远比高铁慢，四个小时到不了北京，与句意矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“坐”后接的是交通工具或座位，不能接“空气”。"}], "explanations": {"高铁": "正确：“坐高铁”是交通方式，四个小时到北京符合常识。", "电梯": "语义：电梯只在楼内上下，不能用来去北京。", "马车": "语义：马车远比高铁慢，四个小时到不了北京，与句意矛盾。", "空气": "搭配：“坐”后接的是交通工具或座位，不能接“空气”。"}, "sentence_index": 0, "correct_answer": "高铁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐高铁去超市买菜。", "explanation": "这里应该用〈公交车〉。高铁连接城市之间，超市在市内，每天去超市买菜要用〈公交车〉或地铁。"}, {"text": "我们坐高铁去北京，一路上走了两天。", "explanation": "这里应该用〈普通火车〉。高铁速度很快，一路走两天不符合它的特点，这种慢速旅行要用〈普通火车〉。"}, {"text": "我们坐高铁去上海，车速慢得像散步。", "explanation": "这里应该用〈慢车〉。高铁以速度快著称，车速慢得像散步要用〈慢车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高铁", "is_correct": true, "explanation": "正确：“坐高铁”去上海出差是常见说法，符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯只在楼内上下，不能带人去上海出差。"}, {"text": "摇篮", "is_correct": false, "explanation": "语义：摇篮是婴儿的床，不能用来出差。"}, {"text": "公路", "is_correct": false, "explanation": "搭配：“坐”后接交通工具，不能接道路“公路”。"}], "explanations": {"高铁": "正确：“坐高铁”去上海出差是常见说法，符合句意。", "电梯": "语义：电梯只在楼内上下，不能带人去上海出差。", "摇篮": "语义：摇篮是婴儿的床，不能用来出差。", "公路": "搭配：“坐”后接交通工具，不能接道路“公路”。"}, "sentence_index": 6, "correct_answer": "高铁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐高铁去郊外，路上堵了两个小时。", "explanation": "这里应该用〈汽车〉。高铁在铁轨上运行，不会在路上堵车，路上堵车要用〈汽车〉。"}, {"text": "这列高铁从机场的跑道上起飞了。", "explanation": "这里应该用〈飞机〉。高铁在铁轨上运行，不会从跑道起飞，起飞的是〈飞机〉。"}, {"text": "这班高铁每分钟只能开一公里，慢慢地挪。", "explanation": "这里应该用〈慢车〉。高铁速度很快，每分钟只开一公里要用〈慢车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐了一台高铁去苏州。", "corrected_sentence": "我们坐了一列高铁去苏州。", "error_description": "错误：“高铁”的量词应为“列”，“台”用于机器、电视等，不能用于高铁。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下个月坐了高铁去广州出差。", "corrected_sentence": "我下个月坐高铁去广州出差。", "error_description": "错误：“下个月”表示将来，动作还没发生，“坐”后不能加“了”。应改为“我下个月坐高铁去广州出差。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走路", "is_correct": false, "explanation": "与“上车”无反义关系，“走路”不是“上车”这一义项的反义词。"}, {"text": "下车", "is_correct": true, "explanation": "正确。“下车”与“上车”是反义词，指离开车厢。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“上车”无反义关系，二者不属于同一语义场。"}, {"text": "写字", "is_correct": false, "explanation": "与“上车”无反义关系，“写字”与乘车动作无关。"}], "correct_answer": "下车", "explanations": {"走路": "与“上车”无反义关系，“走路”不是“上车”这一义项的反义词。", "下车": "正确。“下车”与“上车”是反义词，指离开车厢。", "睡觉": "与“上车”无反义关系，二者不属于同一语义场。", "写字": "与“上车”无反义关系，“写字”与乘车动作无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "与“上车”无反义关系，“唱歌”与乘车动作无关。"}, {"text": "做饭", "is_correct": false, "explanation": "与“上车”无反义关系，二者不属于同一语义场。"}, {"text": "下车", "is_correct": true, "explanation": "正确。“下车”与“上车”是反义词，指离开车厢。"}, {"text": "读书", "is_correct": false, "explanation": "与“上车”无反义关系，“读书”不是“上车”的反义词。"}], "correct_answer": "下车", "explanations": {"唱歌": "与“上车”无反义关系，“唱歌”与乘车动作无关。", "做饭": "与“上车”无反义关系，二者不属于同一语义场。", "下车": "正确。“下车”与“上车”是反义词，指离开车厢。", "读书": "与“上车”无反义关系，“读书”不是“上车”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "走进公共汽车或火车里面。", "primary_collocate": null, "pronunciation": "shàng chē", "ipa": "ʂaŋ˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "请大家排好队，慢慢上车。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公共汽车来了，我们快上车吧。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在火车站上车，坐在窗边。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上车以后，请先刷卡。", "target_word": "上车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们上车时，司机笑着等他们。", "target_word": "上车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人上车的时候，年轻人让了座。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在中山路上车，在公园下车。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我第一次上车就找到了座位。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乘客都上车了，火车要开了。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，大家都急着上车。", "target_word": "上车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了车", "label": "体标"}, {"form": "上过车", "label": "体标"}, {"form": "上車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上车：动词（离合词），乘客进入公共汽车、火车等车厢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跳舞", "is_correct": false, "explanation": "语义：排队登车时不能跳舞，与“排好队”的场景不符。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”与排好队、有序登车的场景不协调。"}, {"text": "上车", "is_correct": true, "explanation": "正确。“上车”指进入车厢，与“排好队，慢慢上车”相符。"}, {"text": "插队", "is_correct": false, "explanation": "语义：“插队”与“排好队”的要求正好相反。"}], "explanations": {"跳舞": "语义：排队登车时不能跳舞，与“排好队”的场景不符。", "大喊": "语义：“大喊”与排好队、有序登车的场景不协调。", "上车": "正确。“上车”指进入车厢，与“排好队，慢慢上车”相符。", "插队": "语义：“插队”与“排好队”的要求正好相反。"}, "sentence_index": 0, "correct_answer": "上车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅客从登机口上车，飞机马上就要起飞了。", "explanation": "这里应该用〈登机〉。上车用于汽车、火车等陆上车辆，乘飞机要说登机。"}, {"text": "游客上车以后，船慢慢离开了码头。", "explanation": "这里应该用〈上船〉。上车指登上陆上车辆，乘船要说上船。"}, {"text": "同学们进了教室，一个个上车坐下。", "explanation": "这里应该用〈入座〉。上车指登上车辆，在教室里坐下要说入座。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登机", "is_correct": false, "explanation": "搭配：“登机”用于飞机，中山路是街道，不能搭配。"}, {"text": "下车", "is_correct": false, "explanation": "语义：后句已有“在公园下车”，此处再说“下车”前后矛盾。"}, {"text": "上车", "is_correct": true, "explanation": "正确。“上车”指在中山路登车，与后句“在公园下车”相呼应。"}, {"text": "上课", "is_correct": false, "explanation": "语义：中山路是街道，不能在那里“上课”，与乘车的场景不符。"}], "explanations": {"登机": "搭配：“登机”用于飞机，中山路是街道，不能搭配。", "下车": "语义：后句已有“在公园下车”，此处再说“下车”前后矛盾。", "上车": "正确。“上车”指在中山路登车，与后句“在公园下车”相呼应。", "上课": "语义：中山路是街道，不能在那里“上课”，与乘车的场景不符。"}, "sentence_index": 6, "correct_answer": "上车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乘客在闸口上车，等着刷卡。", "explanation": "这里应该用〈进站〉。上车指登上车厢，进入车站要说进站。"}, {"text": "观众陆续上车，走进了体育馆。", "explanation": "这里应该用〈入场〉。上车指登上车辆，进入体育馆、剧场要说入场。"}, {"text": "老师走进教室，上车给我们讲课。", "explanation": "这里应该用〈上台〉。上车指登上车辆，走上讲台要说上台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快上车了公交车。", "corrected_sentence": "他很快上车了。", "error_description": "宾语错误：“上车”是离合词，不能直接带宾语，“上车了公交车”是错误的。应说“他很快上车了”；要说明上到哪辆车，应说“他很快上了公交车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他先上车了去，我们在后面。", "corrected_sentence": "他先上车去了，我们在后面。", "error_description": "趋向补语位置错误：“去”应紧跟在“上车”之后，应说“上车去了”，不能说“上车了去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走路", "is_correct": false, "explanation": "与“上车”无反义关系，“走路”不是“上车”这一义项的反义词。"}, {"text": "下车", "is_correct": true, "explanation": "正确。“下车”与“上车”是反义词，指离开车辆。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“上车”无反义关系，二者不属于同一语义场。"}, {"text": "写字", "is_correct": false, "explanation": "与“上车”无反义关系，“写字”与乘车动作无关。"}], "correct_answer": "下车", "explanations": {"走路": "与“上车”无反义关系，“走路”不是“上车”这一义项的反义词。", "下车": "正确。“下车”与“上车”是反义词，指离开车辆。", "睡觉": "与“上车”无反义关系，二者不属于同一语义场。", "写字": "与“上车”无反义关系，“写字”与乘车动作无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱歌", "is_correct": false, "explanation": "与“上车”无反义关系，“唱歌”与乘车动作无关。"}, {"text": "做饭", "is_correct": false, "explanation": "与“上车”无反义关系，二者不属于同一语义场。"}, {"text": "下车", "is_correct": true, "explanation": "正确。“下车”与“上车”是反义词，指离开车辆。"}, {"text": "读书", "is_correct": false, "explanation": "与“上车”无反义关系，“读书”不是“上车”的反义词。"}], "correct_answer": "下车", "explanations": {"唱歌": "与“上车”无反义关系，“唱歌”与乘车动作无关。", "做饭": "与“上车”无反义关系，二者不属于同一语义场。", "下车": "正确。“下车”与“上车”是反义词，指离开车辆。", "读书": "与“上车”无反义关系，“读书”不是“上车”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "登上车辆。", "primary_collocate": null, "pronunciation": "shàng chē", "ipa": "ʂaŋ˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "他拉开门，上车走了。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我叫了出租车，请你先上车。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机说：“请上车，我们该走了。”", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让孩子先上车，再关门。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，快上车吧。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他上车后马上系好安全带。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都上车了，车子开动了。", "target_word": "上车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人上车前，司机先把门打开。", "target_word": "上车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包放好，才上车。", "target_word": "上车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在门口等着，学生一个个上车。", "target_word": "上车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了车", "label": "体标"}, {"form": "上过车", "label": "体标"}, {"form": "上車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "上车：动词（离合词），登上汽车、出租车等车辆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c67bcbe8-38ec-4a35-acf2-3747b2cdd35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗澡", "is_correct": false, "explanation": "语义：拉开门后去洗澡，与后文“走了”的动作不连贯，句意不通。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”必须带受事宾语，“放走了”缺少对象，句子不成立。"}, {"text": "上车", "is_correct": true, "explanation": "正确。“上车”指登上车辆，与“他拉开门，上车走了”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不能与“走了”构成离开的动作，句意不通。"}], "explanations": {"洗澡": "语义：拉开门后去洗澡，与后文“走了”的动作不连贯，句意不通。", "放": "配价：“放”必须带受事宾语，“放走了”缺少对象，句子不成立。", "上车": "正确。“上车”指登上车辆，与“他拉开门，上车走了”相符。", "睡觉": "语义：“睡觉”不能与“走了”构成离开的动作，句意不通。"}, "sentence_index": 0, "correct_answer": "上车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅客从登机口上车，飞机马上就要起飞了。", "explanation": "这里应该用〈登机〉。上车用于汽车、火车等陆上车辆，乘飞机要说登机。"}, {"text": "游客上车以后，船慢慢离开了码头。", "explanation": "这里应该用〈上船〉。上车指登上陆上车辆，乘船要说上船。"}, {"text": "孩子们，饭好了，快上车吃饭！", "explanation": "这里应该用〈上楼〉。上车指登上车辆，回楼上吃饭要说上楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进教室", "is_correct": false, "explanation": "语义：“车子开动了”说明人在车上，“进教室”与车的场景不符。"}, {"text": "下雨", "is_correct": false, "explanation": "搭配：“下雨”的主语不是人，不能说“大家都下雨了”。"}, {"text": "上车", "is_correct": true, "explanation": "正确。“上车”指登上车辆，与“大家都上车了，车子开动了”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与“车子开动了”无关，句子不成立。"}], "explanations": {"进教室": "语义：“车子开动了”说明人在车上，“进教室”与车的场景不符。", "下雨": "搭配：“下雨”的主语不是人，不能说“大家都下雨了”。", "上车": "正确。“上车”指登上车辆，与“大家都上车了，车子开动了”相符。", "考试": "语义：“考试”与“车子开动了”无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "上车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "观众一个个上车，陆续走进了体育馆。", "explanation": "这里应该用〈入场〉。上车指登上车辆，进入体育馆、剧场要说入场。"}, {"text": "乘客在闸口一个个上车，等着刷卡。", "explanation": "这里应该用〈进站〉。上车指登上车厢，进入车站要说进站。"}, {"text": "他推开门，上车进了屋。", "explanation": "这里应该用〈进屋〉。上车指登上车辆，走进房屋要说进屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈打开车门，他上车了去。", "corrected_sentence": "妈妈打开车门，他上车去了。", "error_description": "趋向补语位置错误：“去”应紧跟在“上车”之后，应说“上车去了”，不能说“上车了去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上车了公交车，去了机场。", "corrected_sentence": "他上车了，去了机场。", "error_description": "宾语错误：“上车”是离合词，不能直接带宾语。“上车了公交车”应改为“上车了”；要说上了哪辆车，应说“上了公交车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85ce5070-73b9-4171-83e3-7e39fa8300e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
