INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97115, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "讲故事时，转过来说另一件事。", "primary_collocate": null, "pronunciation": "qiě shuō", "ipa": "tɕʰiɛ˨˩ ʂuo˥", "syllable_count": 2, "sentences": [{"text": "且说小红回到家，妈妈正在做饭。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事讲到这里，且说老张那边又出了新事。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明去了北京，且说他弟弟在家里做些什么。", "target_word": "且说", "complexity_tier": "T3", "furigana": "xiǎo míng qù le běi jīng，qiě shuō tā dì di zài jiā lǐ zuò xiē shén me。", "sentence_source": "generated"}, {"text": "大王的事讲完了，且说小王子后来怎么样。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷讲故事说：“且说那只老虎走进山里。”", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里写完了城里的事，且说山里的人在做什么。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "且说那天夜里，下起了大雨，路上没有人。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先不说她，且说她哥哥回到了村子。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说书人喝了口茶，接着说：“且说那位将军回到了城里。”", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，皇帝走后，且说公主在宫里等着他。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "讲故事时转说另一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "且说", "is_correct": true, "explanation": "且说：讲故事时转到另一件事，放在句首引出新的情节，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "语法：“只好”是副词，须位于主语之后，不能放在句首“小红”之前。"}, {"text": "不得不", "is_correct": false, "explanation": "语法：“不得不”是副词，须位于主语之后，不能放在句首“小红”之前。"}, {"text": "即使", "is_correct": false, "explanation": "配价：“即使”要与后面的“也”或“还”配合，这句没有相应的副词，句子不完整。"}], "explanations": {"且说": "且说：讲故事时转到另一件事，放在句首引出新的情节，符合句意。", "只好": "语法：“只好”是副词，须位于主语之后，不能放在句首“小红”之前。", "不得不": "语法：“不得不”是副词，须位于主语之后，不能放在句首“小红”之前。", "即使": "配价：“即使”要与后面的“也”或“还”配合，这句没有相应的副词，句子不完整。"}, "sentence_index": 0, "correct_answer": "且说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先吃了午饭，且说他又去了图书馆。", "explanation": "这里应该用〈然后〉。同一个人的先后动作要用“然后”；“且说”表示转到另一件事或另一个人，这里只是同一人的先后顺序。"}, {"text": "我们明天去爬山吧，且说你带了水没有？", "explanation": "这里应该用〈对了〉。“且说”是书面连词，只用于讲故事时转入另一件事，日常对话里不这样说。"}, {"text": "我去超市买牛奶，且说买了几个苹果。", "explanation": "这里应该用〈顺便〉。“顺便”表示做一件事时顺带做另一件事；“且说”是讲故事时转入另一件事的书面套语，不用于口语中说自己顺带做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "且说", "is_correct": true, "explanation": "且说：讲故事时转到另一件事，引出夜里的情况，符合句意。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”是副词，须修饰动词，不能放在时间词“那天夜里”之前。"}, {"text": "马上", "is_correct": false, "explanation": "语法：“马上”是副词，须修饰动词，不能放在时间词“那天夜里”之前。"}, {"text": "只要", "is_correct": false, "explanation": "配价：“只要”后面要用“就”来配合，这句没有“就”，句子不完整。"}], "explanations": {"且说": "且说：讲故事时转到另一件事，引出夜里的情况，符合句意。", "正在": "语法：“正在”是副词，须修饰动词，不能放在时间词“那天夜里”之前。", "马上": "语法：“马上”是副词，须修饰动词，不能放在时间词“那天夜里”之前。", "只要": "配价：“只要”后面要用“就”来配合，这句没有“就”，句子不完整。"}, "sentence_index": 6, "correct_answer": "且说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很努力，且说成绩却一直没有提高。", "explanation": "这里表示转折，应该用〈但是〉。“且说”只表示转入另一件事，不表示前后对立。"}, {"text": "他生病了，且说今天没来上课。", "explanation": "这里表示结果，应该用〈所以〉。“且说”不用于说明因果关系，只用于讲故事时转入另一件事。"}, {"text": "我觉得这个方案很好，且说我们应该马上执行。", "explanation": "这里应该用〈再说〉。“且说”只用于讲故事时转入另一件事，不用来补充自己的建议；这里应用“再说”引出补充的理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "且说了老王听到消息，马上赶了过去。", "corrected_sentence": "且说老王听到消息，马上赶了过去。", "error_description": "错误形式：“且说了”，“且说”是连词，不能带动态助词“了”。正确形式：“且说老王听到消息”，“且说”直接放在句首，引出转入的事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在且说那天早上，老张去了城里。", "corrected_sentence": "且说那天早上，老张去了城里。", "error_description": "错误形式：“在且说那天早上”，“且说”是连词，前面不能加介词“在”。正确形式：“且说那天早上，老张去了城里”，“且说”直接放在句首。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
