INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97116, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "且让我说；旧小说中用来转入另一话题的语句。", "primary_collocate": null, "pronunciation": "qiě shuō", "ipa": "tɕʰiɛ˨˩ ʂuo˥", "syllable_count": 2, "sentences": [{"text": "且说刘备领兵回到了城中。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "且说天下大势，合久必分。", "target_word": "且说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "且说宝玉那天去看林妹妹。", "target_word": "且说", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "且说那位书生进京赶考，路上遇到了大雨。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "且说两人分手之后，各自回了家。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "且说张三走后，李四在家中愁眉不展。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "掌柜的话刚说完，且说门外来了一个客人。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "且说那座古庙里，住着一位老和尚。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "众人散去，且说小姐回到房中，心里很不安。", "target_word": "且说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "且说皇上听完这话，心里十分生气。", "target_word": "且说", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "古旧", "sense_fingerprint": "旧小说转入另一话题的套语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "且说", "is_correct": true, "explanation": "且说：旧小说中转入另一个话题的套语，放在句首，符合句意。"}, {"text": "只好", "is_correct": false, "explanation": "语法：“只好”是副词，须位于主语之后，不能放在句首“刘备”之前。"}, {"text": "不得不", "is_correct": false, "explanation": "语法：“不得不”是副词，须位于主语之后，不能放在句首“刘备”之前。"}, {"text": "即使", "is_correct": false, "explanation": "配价：“即使”要与后面的“也”或“还”配合，这句缺少相应的副词，句子不完整。"}], "explanations": {"且说": "且说：旧小说中转入另一个话题的套语，放在句首，符合句意。", "只好": "语法：“只好”是副词，须位于主语之后，不能放在句首“刘备”之前。", "不得不": "语法：“不得不”是副词，须位于主语之后，不能放在句首“刘备”之前。", "即使": "配价：“即使”要与后面的“也”或“还”配合，这句缺少相应的副词，句子不完整。"}, "sentence_index": 0, "correct_answer": "且说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他吃完饭，且说出门散步去了。", "explanation": "这里应该用〈然后〉。同一个人的先后动作用“然后”；“且说”是旧小说转入另一个话题的套语，不用于现代叙述同一人的动作。"}, {"text": "我们一起去吃饭吧，且说你想吃什么？", "explanation": "这里应该用〈对了〉。“且说”是古旧书面套语，只用于旧小说转入另一话题，日常口语里不用。"}, {"text": "新闻报道说，且说今天股市大涨。", "explanation": "这里应该用〈另外〉。“且说”是旧小说转入另一话题的套语，用在新闻报道里不合适；转入另一条消息应用现代的“另外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "且说", "is_correct": true, "explanation": "且说：旧小说中转入另一件事的套语，引出门外的新情况，符合句意。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表原因，需要说明前面的事情是由门外的客人引起的，句意不通。"}, {"text": "虽然", "is_correct": false, "explanation": "配价：“虽然”要与后面的“但是”或“却”配合，这句缺少相应的词，句子不完整。"}, {"text": "只好", "is_correct": false, "explanation": "语法：“只好”是副词，须位于主语之后，不能放在“门外”之前。"}], "explanations": {"且说": "且说：旧小说中转入另一件事的套语，引出门外的新情况，符合句意。", "因为": "语义：“因为”表原因，需要说明前面的事情是由门外的客人引起的，句意不通。", "虽然": "配价：“虽然”要与后面的“但是”或“却”配合，这句缺少相应的词，句子不完整。", "只好": "语法：“只好”是副词，须位于主语之后，不能放在“门外”之前。"}, "sentence_index": 6, "correct_answer": "且说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直很用功，且说考试的成绩却不理想。", "explanation": "这里表示转折，应该用〈但是〉。“且说”只表示转入另一件事，不表示前后对立。"}, {"text": "他昨晚没睡好，且说今天上课才打瞌睡。", "explanation": "这里表示因果，应该用〈所以〉。“且说”不用于说明因果关系。"}, {"text": "做饭时先放油，且说油热了以后再放菜。", "explanation": "这里应该用〈然后〉。“且说”是旧小说转入另一话题的套语，不用于说明做事的步骤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "且说老王走后，他的弟弟且说回到了家中。", "corrected_sentence": "且说老王走后，他的弟弟回到了家中。", "error_description": "“且说”是连词，全句只用一次，放在句首，表示转入另一个话题，不能再出现在主语和动词之间。错误形式：他的弟弟且说回到了家中。正确形式：他的弟弟回到了家中。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "且说老头子听了这话，便且说起身出了门。", "corrected_sentence": "且说老头子听了这话，便起身出了门。", "error_description": "“且说”是连词，只能放在句首，表示转入另一件事，不能插在“便”和“起身”之间。错误形式：便且说起身出了门。正确形式：便起身出了门。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
