INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比刚学的难一点，但还没有最难的那一级。", "primary_collocate": null, "pronunciation": "zhōng jí", "ipa": "ʈʂʊŋ⁵⁵ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "我现在学中级汉语。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的英语课已经上到中级了。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是给中级学生看的。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想报名中级班。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中级课比初级课难一点。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她报的游泳课已经上到中级了。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我要考中级考试。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个中级班有十五个学生。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学了一年，才到中级。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中级听力对我还有点难。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中级班", "label": "复合词"}, {"form": "中級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学习阶段中间的一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97119, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：中级 zhōng jí，指学习阶段中间的一级。"}, {"text": "中计", "is_correct": false, "explanation": "zhòng jì（第四声）与 zhōng jí 两个音节的声调都不同，意思是“中了圈套”。"}, {"text": "重击", "is_correct": false, "explanation": "zhòng jī 与 zhōng jí 两个音节的声调都不同，意思是“用力打击”。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng jì（第四声）与 zhōng jí 第二音节声调不同，意思是“中途转接”。"}], "explanations": {"中级": "正确：中级 zhōng jí，指学习阶段中间的一级。", "中计": "zhòng jì（第四声）与 zhōng jí 两个音节的声调都不同，意思是“中了圈套”。", "重击": "zhòng jī 与 zhōng jí 两个音节的声调都不同，意思是“用力打击”。", "中继": "zhōng jì（第四声）与 zhōng jí 第二音节声调不同，意思是“中途转接”。"}, "sentence_index": null, "correct_answer": "中级"}, "level_3": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：“学中级汉语”指学习中间一级的汉语。"}, {"text": "中心", "is_correct": false, "explanation": "语义：“中心”指中央的地点，不能表示学习阶段。"}, {"text": "中年", "is_correct": false, "explanation": "语义：“中年”指年龄段，不能修饰“汉语”。"}, {"text": "中间", "is_correct": false, "explanation": "搭配：“中间”不修饰课程或语言，不能说“学中间汉语”。"}], "explanations": {"中级": "正确：“学中级汉语”指学习中间一级的汉语。", "中心": "语义：“中心”指中央的地点，不能表示学习阶段。", "中年": "语义：“中年”指年龄段，不能修饰“汉语”。", "中间": "搭配：“中间”不修饰课程或语言，不能说“学中间汉语”。"}, "sentence_index": 0, "correct_answer": "中级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在队伍的中级。", "explanation": "这里应该用〈中间〉。“中级”指学习或等级，不表示位置，站在队伍中间要说“中间”。"}, {"text": "这件衣服的尺码是中级。", "explanation": "这里应该用〈中号〉。“中级”指学习或等级，不用于尺码，衣服尺码要说“中号”。"}, {"text": "我要一杯中级的咖啡。", "explanation": "这里应该用〈中杯〉。“中级”指学习阶段的等级，不表示饮料大小，应说“一杯中杯咖啡”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：“中级考试”指中间一级的考试。"}, {"text": "中风", "is_correct": false, "explanation": "语义：“中风”是疾病名，不能用来修饰考试。"}, {"text": "中秋", "is_correct": false, "explanation": "语义：“中秋”是节日，不能修饰考试。"}, {"text": "中场", "is_correct": false, "explanation": "搭配：“中场”是球赛的术语，不能与“考试”搭配。"}], "explanations": {"中级": "正确：“中级考试”指中间一级的考试。", "中风": "语义：“中风”是疾病名，不能用来修饰考试。", "中秋": "语义：“中秋”是节日，不能修饰考试。", "中场": "搭配：“中场”是球赛的术语，不能与“考试”搭配。"}, "sentence_index": 6, "correct_answer": "中级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在正处于人生的中级。", "explanation": "这里应该用〈中年〉。“中级”指学习或等级，不指人生阶段，应说“中年”。"}, {"text": "这里是城市的中级。", "explanation": "这里应该用〈中心〉。“中级”不表示地点，说城市的中心要用“中心”。"}, {"text": "我在中级教数学。", "explanation": "这里应该用〈中学〉。“中级”指等级，不指学校，应说“在中学教数学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的水平是一中级。", "corrected_sentence": "她的水平是中级。", "error_description": "数量错误：“一”后应接量词，此处应去掉“一”，说“她的水平是中级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想报名一门中级班。", "corrected_sentence": "我想报名一个中级班。", "error_description": "量词错误：“班”的量词是“个”，不能用“门”（门多用于课程），应说“一个中级班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
