INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各类等级划分（如职称、会员）中居中的一级。", "primary_collocate": null, "pronunciation": "zhōng jí", "ipa": "ʈʂʊŋ⁵⁵ tɕi³⁵", "syllable_count": 2, "sentences": [{"text": "他是中级工程师。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有中级会计师证。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司是中级，不是高级。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考上了中级职称。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥是中级教师。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有初级、中级和高级。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中级会员可以免费使用游泳池。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年拿到了中级证书。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中级管理人员每月开一次会。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的中级职位有五个。", "target_word": "中级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中级工", "label": "复合词"}, {"form": "中級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "职称、会员等分级中的中等一级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97120, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：中级 zhōng jí，指职称等分级中的中等一级。"}, {"text": "中计", "is_correct": false, "explanation": "zhòng jì（第四声）与 zhōng jí 两个音节的声调都不同，意思是“中了圈套”。"}, {"text": "重击", "is_correct": false, "explanation": "zhòng jī 与 zhōng jí 两个音节的声调都不同，意思是“用力打击”。"}, {"text": "中继", "is_correct": false, "explanation": "zhōng jì（第四声）与 zhōng jí 第二音节声调不同，意思是“中途转接”。"}], "explanations": {"中级": "正确：中级 zhōng jí，指职称等分级中的中等一级。", "中计": "zhòng jì（第四声）与 zhōng jí 两个音节的声调都不同，意思是“中了圈套”。", "重击": "zhòng jī 与 zhōng jí 两个音节的声调都不同，意思是“用力打击”。", "中继": "zhōng jì（第四声）与 zhōng jí 第二音节声调不同，意思是“中途转接”。"}, "sentence_index": null, "correct_answer": "中级"}, "level_3": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：“中级工程师”指职称等级中的中级。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间，不能修饰“工程师”。"}, {"text": "中学", "is_correct": false, "explanation": "语义：“中学”指学校，不能用来说职称等级。"}, {"text": "中场", "is_correct": false, "explanation": "搭配：“中场”是球赛位置，不能与“工程师”搭配。"}], "explanations": {"中级": "正确：“中级工程师”指职称等级中的中级。", "中午": "语义：“中午”是时间，不能修饰“工程师”。", "中学": "语义：“中学”指学校，不能用来说职称等级。", "中场": "搭配：“中场”是球赛位置，不能与“工程师”搭配。"}, "sentence_index": 0, "correct_answer": "中级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街的中级有一家超市。", "explanation": "这里应该用〈中段〉。“中级”指职称或等级，不指位置，街道中段要说“中段”。"}, {"text": "这套房子的面积是中级。", "explanation": "这里应该用〈中等〉。“中级”用于职称或等级，描述面积大小要用“中等”。"}, {"text": "我们大学提供中级教育。", "explanation": "这里应该用〈高等〉。“中级”不用于教育阶段，大学教育要说“高等教育”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中级", "is_correct": true, "explanation": "正确：“中级会员”指会员等级中的中间一级。"}, {"text": "中秋", "is_correct": false, "explanation": "语义：“中秋”是节日，不能指会员的等级。"}, {"text": "中场", "is_correct": false, "explanation": "搭配：“中场”是球赛术语，不能修饰“会员”。"}, {"text": "中旬", "is_correct": false, "explanation": "语义：“中旬”指一个月的时间段，不能指会员等级。"}], "explanations": {"中级": "正确：“中级会员”指会员等级中的中间一级。", "中秋": "语义：“中秋”是节日，不能指会员的等级。", "中场": "搭配：“中场”是球赛术语，不能修饰“会员”。", "中旬": "语义：“中旬”指一个月的时间段，不能指会员等级。"}, "sentence_index": 6, "correct_answer": "中级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在中级离开了会议。", "explanation": "这里应该用〈中途〉。“中级”指职称或等级，不指过程的中间，中途离开要说“中途”。"}, {"text": "学校就在市中级。", "explanation": "这里应该用〈中心〉。“中级”不表示地点，说城市的中心要用“中心”。"}, {"text": "他在一所中级工作。", "explanation": "这里应该用〈中学〉。“中级”指等级，不指学校，应说“在一所中学工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还没评上中级职称了。", "corrected_sentence": "他还没评上中级职称。", "error_description": "“没”与“了”不能同用：否定未完成的事用“没”，去掉“了”，应说“还没评上中级职称”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司有三条中级职位。", "corrected_sentence": "这家公司有三个中级职位。", "error_description": "量词错误：“职位”的量词是“个”，不能用“条”（条多用于线状或长形事物），应说“三个中级职位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客观", "is_correct": true, "explanation": "反义：“客观”指依据事实、不掺杂个人想法，与“主观”构成反义，适用于“我的看法有点儿主观”。"}, {"text": "冷静", "is_correct": false, "explanation": "“冷静”指情绪平稳，不是“主观”的反义词，二者没有对立关系。"}, {"text": "精确", "is_correct": false, "explanation": "“精确”指准确无误，与“主观”没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "“粗心”指做事不仔细，与“主观”的意思不构成对立。"}], "correct_answer": "客观", "explanations": {"客观": "反义：“客观”指依据事实、不掺杂个人想法，与“主观”构成反义，适用于“我的看法有点儿主观”。", "冷静": "“冷静”指情绪平稳，不是“主观”的反义词，二者没有对立关系。", "精确": "“精确”指准确无误，与“主观”没有反义关系。", "粗心": "“粗心”指做事不仔细，与“主观”的意思不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客观", "is_correct": true, "explanation": "反义：“客观”指不带个人想法、依据事实，与“主观”构成反义，适用于“记者的报道”。"}, {"text": "严谨", "is_correct": false, "explanation": "“严谨”形容做事细致周密，与“主观”没有反义关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "“慷慨”形容大方、不吝啬，与“主观”没有对立关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与“主观”的意思没有反义关系。"}], "correct_answer": "客观", "explanations": {"客观": "反义：“客观”指不带个人想法、依据事实，与“主观”构成反义，适用于“记者的报道”。", "严谨": "“严谨”形容做事细致周密，与“主观”没有反义关系。", "慷慨": "“慷慨”形容大方、不吝啬，与“主观”没有对立关系。", "迟钝": "“迟钝”形容反应慢，与“主观”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只按自己心里想的看事情，不看事情本来的样子。", "primary_collocate": null, "pronunciation": "zhǔ guān", "ipa": "ʈʂu˨˩ kwan˥", "syllable_count": 2, "sentences": [{"text": "你这样想太主观了。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看问题很主观，不听别人的话。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做决定总是太主观，不看事实。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的看法有点儿主观。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很主观，从来不问别人的意见。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章写得太主观，没有数据。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "判断一个人不能太主观，要多了解他。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别这么主观，先听听大家怎么说。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很主观，只代表他自己。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者的报道不应该太主观。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主观性", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容人的看法、判断只凭自己的想法、不顾事实，作谓语（太主观了、很主观），含批评意味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主观", "is_correct": true, "explanation": "主观：只凭自己的想法看事情，与“太……了”和批评的语气相符，句意通顺。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水分多，不能用来形容一个人的想法。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材或外形，不能用来评价一个人的想法。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体或身体坚固，不能说“想法太结实了”。"}], "explanations": {"主观": "主观：只凭自己的想法看事情，与“太……了”和批评的语气相符，句意通顺。", "潮湿": "语义：“潮湿”形容空气或物体含水分多，不能用来形容一个人的想法。", "高大": "体貌：“高大”形容身材或外形，不能用来评价一个人的想法。", "结实": "搭配：“结实”形容物体或身体坚固，不能说“想法太结实了”。"}, "sentence_index": 0, "correct_answer": "主观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他判断事情很主观，每次都用仪器精确测量后再下结论。", "explanation": "此句把“主观”用成了“客观”的意思（依据测量得出结论）。“主观”指只凭自己的想法看事情、不顾事实，与“客观”相反，这里不能用。"}, {"text": "他做决定很主观，总是先认真分析各方面的情况。", "explanation": "此句把“主观”用成了“理性”的意思（先分析情况再决定）。“主观”指只凭自己的想法看事情、不顾事实，与“理性”的做法相反。"}, {"text": "他遇事很主观，总是先查清事实再做决定。", "explanation": "此句把“主观”用成了“冷静”的意思（先弄清事实）。“主观”指只凭自己的想法看事情、不顾事实，与“冷静”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主观", "is_correct": true, "explanation": "主观：判断时只凭自己的想法，与“不能太……”的语境相符，句意通顺。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”形容事物缺少水分，不能修饰“判断”。"}, {"text": "粗壮", "is_correct": false, "explanation": "语义：“粗壮”形容身体或物体粗大结实，无法用来说明判断的特点。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”多形容光线或颜色，不能与“判断”搭配。"}], "explanations": {"主观": "主观：判断时只凭自己的想法，与“不能太……”的语境相符，句意通顺。", "干燥": "语义：“干燥”形容事物缺少水分，不能修饰“判断”。", "粗壮": "语义：“粗壮”形容身体或物体粗大结实，无法用来说明判断的特点。", "明亮": "搭配：“明亮”多形容光线或颜色，不能与“判断”搭配。"}, "sentence_index": 6, "correct_answer": "主观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的计时很主观，全部用电子设备记录。", "explanation": "此句把“主观”用成了“精确”的意思（用设备记录、不靠个人看法）。“主观”指只凭自己的想法看事情，与此不符。"}, {"text": "他的报道很主观，凡事都以事实为准。", "explanation": "此句把“主观”用成了“中立”的意思（不偏不倚、以事实为准）。“主观”指只凭自己的想法看事情、不顾事实，与“中立”相反。"}, {"text": "这篇论文的论证很主观，每个观点都有数据支撑。", "explanation": "此句把“主观”用成了“严谨”的意思（论证有数据支撑）。“主观”指只凭自己的想法看事情、不顾事实，与“严谨”相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他主观的看问题，总是只听自己的。", "corrected_sentence": "他主观地看问题，总是只听自己的。", "error_description": "“主观”在这里作状语修饰动词“看”，前面应加“地”，写作“主观地看问题”；这里误用了“的”，“的”不能接在动词前作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划太主观的，没有考虑实际。", "corrected_sentence": "这份计划太主观了，没有考虑实际。", "error_description": "“的”是结构助词，不能代替句末语气助词“了”。“太……了”作谓语时句末应用“了”；这里用了“的”，句子无法完结。正确说法：“这份计划太主观了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客观", "is_correct": true, "explanation": "反义：“客观”指依据事实、不掺杂个人因素，与“主观”构成反义，适用于“主观原因”与“客观原因”的对立。"}, {"text": "客气", "is_correct": false, "explanation": "“客气”形容态度有礼貌，与“主观”没有对立关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度庄重，不能作为“主观”的反义词。"}, {"text": "懒散", "is_correct": false, "explanation": "“懒散”形容做事不积极，与“主观”没有反义关系。"}], "correct_answer": "客观", "explanations": {"客观": "反义：“客观”指依据事实、不掺杂个人因素，与“主观”构成反义，适用于“主观原因”与“客观原因”的对立。", "客气": "“客气”形容态度有礼貌，与“主观”没有对立关系。", "严肃": "“严肃”形容态度庄重，不能作为“主观”的反义词。", "懒散": "“懒散”形容做事不积极，与“主观”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "客观", "is_correct": true, "explanation": "反义：“客观”指依据事实、不带个人想法，与“主观”构成反义，适用于“个人想法”与“实际情况”的对立。"}, {"text": "温柔", "is_correct": false, "explanation": "“温柔”形容性情或态度柔和，与“主观”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”形容不紧张、不费力，与“主观”没有对立关系。"}, {"text": "慷慨", "is_correct": false, "explanation": "“慷慨”形容大方、不吝啬，与“主观”没有反义关系。"}], "correct_answer": "客观", "explanations": {"客观": "反义：“客观”指依据事实、不带个人想法，与“主观”构成反义，适用于“个人想法”与“实际情况”的对立。", "温柔": "“温柔”形容性情或态度柔和，与“主观”没有反义关系。", "轻松": "“轻松”形容不紧张、不费力，与“主观”没有对立关系。", "慷慨": "“慷慨”形容大方、不吝啬，与“主观”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从自己的想法出发，不顾客观实际；也指人的意识。", "primary_collocate": null, "pronunciation": "zhǔ guān", "ipa": "ʈʂu˨˩ kwan˥", "syllable_count": 2, "sentences": [{"text": "失败的原因有主观的，也有客观的。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有成功的主观愿望，但条件不够。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主观努力和客观条件都很重要。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的主观原因是他太马虎。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习好不好，主观上要靠自己。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看主观愿望，要看实际情况。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是主观的看法，不一定是事实。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在主观上想帮忙，但是能力不够。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学里常说主观与客观的关系。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事情要把主观想法和实际情况放在一起想。", "target_word": "主观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主观上", "label": "复合"}, {"form": "主观性", "label": "复合"}], "register": "书面", "sense_fingerprint": "与“客观”相对，指人的意识、想法一方，多作定语或用于“主观上”（主观愿望、主观努力、主观原因）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主观", "is_correct": true, "explanation": "主观：指人的意识或内在因素，作定语修饰“的”后的“原因”，句意通顺。"}, {"text": "冰冷", "is_correct": false, "explanation": "语义：“冰冷”形容温度低，不能修饰“原因”。"}, {"text": "圆形", "is_correct": false, "explanation": "搭配：“圆形”指形状，不能说“原因有圆形的”。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”形容速度快，与“原因”的性质不相符。"}], "explanations": {"主观": "主观：指人的意识或内在因素，作定语修饰“的”后的“原因”，句意通顺。", "冰冷": "语义：“冰冷”形容温度低，不能修饰“原因”。", "圆形": "搭配：“圆形”指形状，不能说“原因有圆形的”。", "迅速": "语义：“迅速”形容速度快，与“原因”的性质不相符。"}, "sentence_index": 0, "correct_answer": "主观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛失败的主观原因是天气太热。", "explanation": "此句把“主观原因”用成了“客观原因”的意思：天气属于外部条件，应说“客观原因”。“主观”指从自己的想法或内在因素出发，与此相反。"}, {"text": "他解题的过程很主观，每一步都有依据。", "explanation": "此句把“主观”用成了“严谨”的意思（每一步都有依据）。“主观”指从自己的想法出发、不顾客观实际，与“严谨”相反。"}, {"text": "他面对争议时很主观，总会先查清楚事实。", "explanation": "此句把“主观”用成了“冷静”的意思（先查清事实）。“主观”指从自己的想法出发、不顾客观实际，与“冷静”的态度相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主观", "is_correct": true, "explanation": "主观：指个人的看法和想法，修饰“看法”，句意通顺。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”形容颜色，不能修饰“看法”。"}, {"text": "漆黑", "is_correct": false, "explanation": "体貌：“漆黑”形容颜色，不符合看法的性质。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”形容身体的状态，不能用来形容看法。"}], "explanations": {"主观": "主观：指个人的看法和想法，修饰“看法”，句意通顺。", "雪白": "体貌：“雪白”形容颜色，不能修饰“看法”。", "漆黑": "体貌：“漆黑”形容颜色，不符合看法的性质。", "饥饿": "语义：“饥饿”形容身体的状态，不能用来形容看法。"}, "sentence_index": 6, "correct_answer": "主观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位评委打分很主观，每一分都有依据。", "explanation": "此句把“主观”用成了“公正”的意思（每一分都有依据）。“主观”指从自己的想法出发、不顾客观实际，与“公正”相反。"}, {"text": "他对朋友的看法很主观，总会先了解事实再下结论。", "explanation": "此句把“主观”用成了“理智”的意思（先了解事实）。“主观”指从自己的想法出发、不顾客观实际，与“理智”相反。"}, {"text": "这次实验的记录很主观，每个数据都经过核对。", "explanation": "此句把“主观”用成了“科学”的意思（数据经过核对）。“主观”指从自己的想法出发、不顾客观实际，与“科学”的做法相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在主观很想帮忙，可惜时间不够。", "corrected_sentence": "我在主观上很想帮忙，可惜时间不够。", "error_description": "“在……上”是固定的方位结构，表示“在某方面”。“在主观”后须加“上”，写作“在主观上”；这里漏掉了“上”，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在主观的想要帮忙，结果没做成。", "corrected_sentence": "他在主观上想要帮忙，结果没做成。", "error_description": "“主观上”是固定的状语形式，表示从主观方面说，“上”不能换成“的”；这里误用了“的”，应改为“主观上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
