INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一些人在一起帮别人做事、办事的地方。", "primary_collocate": null, "pronunciation": "shì wù suǒ", "ipa": "ʂʐ̩˥˩ u˥˩ suo˨˩˦", "syllable_count": 3, "sentences": [{"text": "他在一家事务所工作。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家事务所在市中心。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所里有五六个人。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我明天要去事务所办手续。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所的人帮我们办好了所有事。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个朋友开了一家事务所。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所下午五点关门。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个事务所很小，只有两个房间。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在事务所上班，工作不太忙。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所的电话一直占线。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "律师事务所", "label": "复合"}, {"form": "会计师事务所", "label": "复合"}, {"form": "事務所", "label": "繁体"}], "register": "中性", "sense_fingerprint": "替人办事的办公场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事务所", "is_correct": true, "explanation": "正确答案。事务所是替人办事的办公场所，“在一家事务所工作”符合句意。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：“一家”搭配的是店铺、机构，不说“一家草原”。"}, {"text": "雕塑", "is_correct": false, "explanation": "语义：雕塑是艺术作品，不是可以去工作的地方。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学体裁，不是工作的场所。"}], "explanations": {"事务所": "正确答案。事务所是替人办事的办公场所，“在一家事务所工作”符合句意。", "草原": "搭配：“一家”搭配的是店铺、机构，不说“一家草原”。", "雕塑": "语义：雕塑是艺术作品，不是可以去工作的地方。", "诗歌": "语义：诗歌是文学体裁，不是工作的场所。"}, "sentence_index": 0, "correct_answer": "事务所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天去一家事务所吃晚饭。", "explanation": "这里应该用〈饭店〉。事务所是替人办事的办公场所，不是吃饭的地方。"}, {"text": "他每天去一家事务所买书。", "explanation": "这里应该用〈书店〉。事务所不卖书，买书要去书店。"}, {"text": "妈妈周末去一家事务所买衣服。", "explanation": "这里应该用〈商场〉。事务所不卖衣服，买衣服要去商场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事务所", "is_correct": true, "explanation": "正确答案。事务所是机构，“事务所下午五点关门”符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能“关门”。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“关门”用于店铺、机构，不说报纸。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“关门”用于店铺、机构，不说花瓶。"}], "explanations": {"事务所": "正确答案。事务所是机构，“事务所下午五点关门”符合句意。", "天空": "语义：天空不能“关门”。", "报纸": "搭配：“关门”用于店铺、机构，不说报纸。", "花瓶": "搭配：“关门”用于店铺、机构，不说花瓶。"}, "sentence_index": 6, "correct_answer": "事务所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我生病了，去事务所打针。", "explanation": "这里应该用〈医院〉。事务所是替人办事的办公场所，打针要去医院。"}, {"text": "孩子们每天早上去事务所上课。", "explanation": "这里应该用〈学校〉。事务所是办公场所，上课要去学校。"}, {"text": "晚上我们在事务所睡觉、过夜。", "explanation": "这里应该用〈宾馆〉。事务所是办公场所，不是住宿的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在一只事务所里办手续。", "corrected_sentence": "我在一家事务所里办手续。", "error_description": "量词用错。事务所应该用量词“家”，“只”用于动物或小件物品，不能用于事务所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一家事务办公。", "corrected_sentence": "他在一家事务所办公。", "error_description": "词语不完整。“事务所”不能缩写为“事务”，应写作“事务所”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
