INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事法律、会计等专业服务的机构。", "primary_collocate": null, "pronunciation": "shì wù suǒ", "ipa": "ʂʐ̩˥˩ u˥˩ suo˨˩˦", "syllable_count": 3, "sentences": [{"text": "这家事务所专门帮公司打官司。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在事务所当会计，每天算账。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请事务所检查了账目。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所的律师帮我看了合同。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家事务所的法律服务很专业。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后进了一家事务所做会计。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务所帮我们解决了法律问题。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找事务所帮忙交税。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家事务所的会计很认真。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请事务所写了一份报告。", "target_word": "事务所", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "律师事务所", "label": "复合"}, {"form": "会计师事务所", "label": "复合"}, {"form": "事務所", "label": "繁体"}], "register": "中性", "sense_fingerprint": "提供法律会计等专业服务的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事务所", "is_correct": true, "explanation": "正确答案。这家事务所是提供法律服务的机构，可以替公司打官司。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店不替人打官司。"}, {"text": "花店", "is_correct": false, "explanation": "语义：花店不替人打官司。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“打官司”搭配的是律师、法院，不说幼儿园。"}], "explanations": {"事务所": "正确答案。这家事务所是提供法律服务的机构，可以替公司打官司。", "饭店": "语义：饭店不替人打官司。", "花店": "语义：花店不替人打官司。", "幼儿园": "搭配：“打官司”搭配的是律师、法院，不说幼儿园。"}, "sentence_index": 0, "correct_answer": "事务所"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的车坏了，送到事务所去修。", "explanation": "这里应该用〈修车厂〉。事务所提供法律、会计服务，修车要去修车厂。"}, {"text": "我去事务所买了一斤苹果。", "explanation": "这里应该用〈水果店〉。事务所提供专业服务，不卖水果。"}, {"text": "周末我们去事务所吃饭。", "explanation": "这里应该用〈餐厅〉。事务所提供法律、会计服务，不是吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事务所", "is_correct": true, "explanation": "正确答案。事务所是提供法律服务的机构，能帮我们解决法律问题。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不替人解决法律问题。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“解决问题”需要能处理事情的施事，厨房不能充当。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能替人解决法律问题。"}], "explanations": {"事务所": "正确答案。事务所是提供法律服务的机构，能帮我们解决法律问题。", "医院": "语义：医院不替人解决法律问题。", "厨房": "配价：“解决问题”需要能处理事情的施事，厨房不能充当。", "花园": "语义：花园不能替人解决法律问题。"}, "sentence_index": 6, "correct_answer": "事务所"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈每周都去事务所看病。", "explanation": "这里应该用〈诊所〉。事务所提供法律、会计服务，看病要去诊所。"}, {"text": "他每天放学后去事务所练琴。", "explanation": "这里应该用〈琴行〉。事务所不教琴，学琴要去琴行。"}, {"text": "我们周末去事务所打篮球。", "explanation": "这里应该用〈体育馆〉。事务所不是运动场所，打篮球要去体育馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家事务所成立过十年。", "corrected_sentence": "这家事务所成立了十年。", "error_description": "“过”与时间段搭配不当。说已经成立了多久，应用“了”，“成立过十年”不自然，应改为“成立了十年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们请一只事务所处理这件事。", "corrected_sentence": "我们请一家事务所处理这件事。", "error_description": "量词用错。事务所应该用量词“家”，“只”用于动物或小件物品，不能用于事务所。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
