INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97135, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "先做好准备，这样坏事就不会发生。", "primary_collocate": null, "pronunciation": "yǐ miǎn", "ipa": "i˨˩˦ mjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "出门带上伞，以免下雨时淋湿衣服。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早点出发，以免路上堵车迟到。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先把手机充好电，以免明天别人联系不上你。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前多检查几遍，以免做错题。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看病前先预约，以免等很久。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡觉前关好门窗，以免晚上有小偷进来。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提前复习了功课，以免考试时紧张。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子正在学走路，大人要看好他，以免摔倒。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把重要的文件多备份一份，以免丢失。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票要早，以免节日时没有座位。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "先做准备，使不好的事不发生（以免）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97135, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词，表示为了避免不希望发生的情况。"}, {"text": "一面", "is_correct": false, "explanation": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。"}, {"text": "椅面", "is_correct": false, "explanation": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。"}, {"text": "意面", "is_correct": false, "explanation": "意面（yì miàn）与 yǐ miǎn 两个音节的声调都不同（第四声对第三声），意思是意大利面。"}], "explanations": {"以免": "目标词，表示为了避免不希望发生的情况。", "一面": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。", "椅面": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。", "意面": "意面（yì miàn）与 yǐ miǎn 两个音节的声调都不同（第四声对第三声），意思是意大利面。"}, "sentence_index": null, "correct_answer": "以免"}, "level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示避免“下雨时淋湿衣服”，与带伞的目的一致。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，句子却说带伞是为了防淋湿，结果与目的相反。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等配套，这里没有转折的主句。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示为达到某个目的，但淋湿衣服不是带伞要达到的目的。"}], "explanations": {"以免": "目标词：表示避免“下雨时淋湿衣服”，与带伞的目的一致。", "所以": "语义：“所以”引出结果，句子却说带伞是为了防淋湿，结果与目的相反。", "虽然": "搭配：“虽然”要与“但是”“却”等配套，这里没有转折的主句。", "以便": "语义：“以便”表示为达到某个目的，但淋湿衣服不是带伞要达到的目的。"}, "sentence_index": 0, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早起，以免赶上班车。", "explanation": "这里应该用〈为了〉。以免引出要避免的情况，而“赶上班车”是希望达到的目的。"}, {"text": "妈妈先把饭做好，以免孩子们按时吃饭。", "explanation": "这里应该用〈好让〉。以免后面接要避免的情况，而“孩子们按时吃饭”是希望发生的事。"}, {"text": "他把行李提前整理好，以免明天出发。", "explanation": "这里应该用〈以便〉。以免表示避免，而“明天出发”是计划中的事，应当用表示目的的〈以便〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示复习是为了避免考试时紧张。"}, {"text": "好让", "is_correct": false, "explanation": "语义：“好让”表示为了使某事发生，句子却要让他“考试时紧张”，与复习的目的相反。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”要与“仍然”“还是”等配套，这里后面没有主句。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示由此导致的结果，但复习功课不会因此导致紧张，句义不通。"}], "explanations": {"以免": "目标词：表示复习是为了避免考试时紧张。", "好让": "语义：“好让”表示为了使某事发生，句子却要让他“考试时紧张”，与复习的目的相反。", "尽管": "搭配：“尽管”要与“仍然”“还是”等配套，这里后面没有主句。", "因而": "语义：“因而”表示由此导致的结果，但复习功课不会因此导致紧张，句义不通。"}, "sentence_index": 6, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们提前做好准备，以免赢得了比赛。", "explanation": "这里应该用〈从而〉。以免表示要避免的情况，而“赢得比赛”是希望出现的结果。"}, {"text": "这次考试我复习得很充分，以免成绩很好。", "explanation": "这里应该用〈所以〉。以免后面只能接要避免的情况，而“成绩很好”是希望出现的结果。"}, {"text": "他每天坚持练习，以免进步很快。", "explanation": "这里应该用〈因而〉。以免表示避免，而“进步很快”是希望出现的结果，应使用表示顺承结果的〈因而〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把钥匙挂在门口，以免了忘记带。", "corrected_sentence": "我把钥匙挂在门口，以免忘记带。", "error_description": "“以免”是连词，后面不能加“了”。忘记带钥匙是要避免的情况，应说“以免忘记带”，不说“以免了忘记带”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "晚饭后早点睡，以免免得明天起不来。", "corrected_sentence": "晚饭后早点睡，以免明天起不来。", "error_description": "“以免”和“免得”意思相同，同一句中不能叠用，应只用“以免”。正确说法：晚饭后早点睡，以免明天起不来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
