INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示为了避免不希望发生的情况。", "primary_collocate": null, "pronunciation": "yǐ miǎn", "ipa": "i˨˩˦ mjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "说话小声一点，以免吵醒孩子。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时不要看手机，以免发生危险。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭时别说话，以免噎着。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天出门要穿暖，以免感冒。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "重要的事要写下来，以免忘记。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我提前给他打了电话，以免他白跑一趟。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开教室前请关灯，以免浪费电。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说话要想清楚，以免让别人不高兴。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过马路时看看左右，以免发生事故。", "target_word": "以免", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把药放在高处，以免小孩子拿到。", "target_word": "以免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "连词，表示为避免不希望的情况（目的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词，表示为了避免不希望发生的情况。"}, {"text": "一面", "is_correct": false, "explanation": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。"}, {"text": "椅面", "is_correct": false, "explanation": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。"}, {"text": "意面", "is_correct": false, "explanation": "意面（yì miàn）与 yǐ miǎn 两个音节的声调都不同（第四声对第三声），意思是意大利面。"}], "explanations": {"以免": "目标词，表示为了避免不希望发生的情况。", "一面": "一面（yí miàn，“一”在第四声前变读第二声）与 yǐ miǎn 两个音节的声调都不同，意思是“一边”或“一方面”。", "椅面": "椅面（yǐ miàn）只有第二音节声调不同（miàn 第四声，miǎn 第三声），意思是椅子的座面。", "意面": "意面（yì miàn）与 yǐ miǎn 两个音节的声调都不同（第四声对第三声），意思是意大利面。"}, "sentence_index": null, "correct_answer": "以免"}, "level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示说话小声是为了避免吵醒孩子。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，“吵醒孩子”不能是小声说话的结果，句意相反。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等配套，这里后面没有主句。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示为达到目的，但吵醒孩子不是说话小声要达到的目的。"}], "explanations": {"以免": "目标词：表示说话小声是为了避免吵醒孩子。", "所以": "语义：“所以”引出结果，“吵醒孩子”不能是小声说话的结果，句意相反。", "虽然": "搭配：“虽然”要与“但是”“却”等配套，这里后面没有主句。", "以便": "语义：“以便”表示为达到目的，但吵醒孩子不是说话小声要达到的目的。"}, "sentence_index": 0, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天练琴，以免学好钢琴。", "explanation": "这里应该用〈为了〉。以免引出要避免的情况，而“学好钢琴”是希望达到的目的。"}, {"text": "老师把答案写在黑板上，以免学生看懂题。", "explanation": "这里应该用〈好让〉。以免表示避免，而“学生看懂题”是希望发生的事。"}, {"text": "我们提前出发，以免赶上最后一班车。", "explanation": "这里应该用〈以便〉。以免后接的应是要避免的情况，而“赶上最后一班车”是希望达到的目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以免", "is_correct": true, "explanation": "目标词：表示关灯是为了避免浪费电。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，“请关灯”的结果却是“浪费电”，与关灯的目的相反。"}, {"text": "好让", "is_correct": false, "explanation": "语义：“好让”表示为了使某事发生，句子却要使“浪费电”发生，与关灯的目的相反。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”要并列同类内容，“请关灯”与“浪费电”不搭配。"}], "explanations": {"以免": "目标词：表示关灯是为了避免浪费电。", "因此": "语义：“因此”引出结果，“请关灯”的结果却是“浪费电”，与关灯的目的相反。", "好让": "语义：“好让”表示为了使某事发生，句子却要使“浪费电”发生，与关灯的目的相反。", "而且": "搭配：“而且”要并列同类内容，“请关灯”与“浪费电”不搭配。"}, "sentence_index": 6, "correct_answer": "以免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们认真备课，以免提高了成绩。", "explanation": "这里应该用〈从而〉。以免表示要避免的情况，而“提高成绩”是希望出现的结果。"}, {"text": "这家店服务很好，以免顾客很满意。", "explanation": "这里应该用〈所以〉。以免后面要接要避免的情况，而“顾客很满意”是希望出现的结果。"}, {"text": "他每天坚持跑步，以免身体变好。", "explanation": "这里应该用〈因而〉。以免表示避免，而“身体变好”是希望达到的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秋天晚上要盖好被子，以免了着凉。", "corrected_sentence": "秋天晚上要盖好被子，以免着凉。", "error_description": "“以免”是连词，后面不能加“了”；着凉是尚未发生、要避免的情况。正确说法：秋天晚上要盖好被子，以免着凉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "关好窗户，以免免得雨水进来。", "corrected_sentence": "关好窗户，以免雨水进来。", "error_description": "“以免”和“免得”意思相同，不能在同一句中叠用，应只用“以免”。正确说法：关好窗户，以免雨水进来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
