INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西不是直直的，一边高一边低。", "primary_collocate": null, "pronunciation": "qīng xié", "ipa": "tɕʰiŋ˥ ɕiɛ˧˥", "syllable_count": 2, "sentences": [{"text": "地板有点倾斜，球一放就滚走了。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子倾斜了，左边高，右边低。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路向河边倾斜，下雨时水往下流。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶倾斜得很厉害，雪都滑下来了。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "船一边重一边轻，所以慢慢倾斜了。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张画挂得有些倾斜，一边高一边低。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球场的地面是倾斜的，跑起来很累。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盘子倾斜了，汤就流出来了。", "target_word": "倾斜", "complexity_tier": "T3", "furigana": "pán zi qīng xié le，tāng jiù liú chū lái le。", "sentence_source": "generated"}, {"text": "他的桌子一直倾斜着，因为一条腿短了。", "target_word": "倾斜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架倾斜以后，上面的书都掉了下来。", "target_word": "倾斜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倾斜了", "label": "完成体"}, {"form": "倾斜着", "label": "持续体"}, {"form": "倾斜过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "物体一边高一边低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倾斜", "is_correct": true, "explanation": "倾斜：东西一边高一边低，不是直直的，用来描述地板的状态，符合句意。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，地板不会融化，句意不通。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，地板不会生锈，与“球一放就滚走”也无关。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指东西长霉，与球滚走的现象无关，句意不通。"}], "explanations": {"倾斜": "倾斜：东西一边高一边低，不是直直的，用来描述地板的状态，符合句意。", "融化": "语义：“融化”指固体遇热变成液体，地板不会融化，句意不通。", "生锈": "语义：“生锈”指金属被氧化，地板不会生锈，与“球一放就滚走”也无关。", "发霉": "语义：“发霉”指东西长霉，与球滚走的现象无关，句意不通。"}, "sentence_index": 0, "correct_answer": "倾斜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他倾斜着眼睛看了我一眼，没有说话。", "explanation": "这里应该用〈斜〉。“斜眼”指斜着眼睛看人；“倾斜”指整体一边高一边低，不用于眼睛这样的局部。"}, {"text": "他倾斜着嘴角笑了一下。", "explanation": "这里应该用〈歪〉。“嘴角歪”指嘴角偏向一边；“倾斜”不用于嘴角这类局部。"}, {"text": "他倾斜着耳朵听我说话。", "explanation": "这里应该用〈侧〉。“侧耳”指把耳朵转向一边听；“倾斜”不用于耳朵这类局部动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倾斜", "is_correct": true, "explanation": "倾斜：地面不平，一边高一边低，符合“球场的地面是……的”这个结构和“跑起来很累”的语境。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”指人或动物流泪出声，地面不会哭泣，句意不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”只能用于人，不能用来形容地面。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指人在水中运动，与地面的状态无关，句意不通。"}], "explanations": {"倾斜": "倾斜：地面不平，一边高一边低，符合“球场的地面是……的”这个结构和“跑起来很累”的语境。", "哭泣": "语义：“哭泣”指人或动物流泪出声，地面不会哭泣，句意不通。", "咳嗽": "搭配：“咳嗽”只能用于人，不能用来形容地面。", "游泳": "语义：“游泳”指人在水中运动，与地面的状态无关，句意不通。"}, "sentence_index": 6, "correct_answer": "倾斜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的讲话倾斜着，大家都听不明白。", "explanation": "这里应该用〈含糊〉。“倾斜”指物体一边高一边低，不用来形容说话。"}, {"text": "他的声音倾斜了，听起来很难受。", "explanation": "这里应该用〈沙哑〉。“倾斜”指物体一边高一边低，不用来形容声音。"}, {"text": "他的心情倾斜了，很不痛快。", "explanation": "这里应该用〈低落〉。“倾斜”指东西一边高一边低，不能用来形容心情；表示心情不好要用“低落”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路倾斜的很厉害，车子不好开。", "corrected_sentence": "这条路倾斜得很厉害，车子不好开。", "error_description": "“倾斜”后面接补语，要用助词“得”，不用“的”。错误形式：倾斜的很厉害。正确形式：倾斜得很厉害。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙壁倾斜了着，快要倒了。", "corrected_sentence": "墙壁倾斜着，快要倒了。", "error_description": "“倾斜”表示持续状态时用“着”，不能再加“了”。错误形式：倾斜了着。正确形式：倾斜着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
