INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向一侧歪斜，不处于垂直或水平的状态。", "primary_collocate": null, "pronunciation": "qīng xié", "ipa": "tɕʰiŋ˥ ɕiɛ˧˥", "syllable_count": 2, "sentences": [{"text": "那座塔向东倾斜，看起来很危险。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风把树吹得倾斜了。", "target_word": "倾斜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比萨斜塔倾斜了几百年，一直没倒。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝醉了，身体向左倾斜，差点摔倒。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震以后，这栋楼有点倾斜。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旗杆倾斜了，不再是直直的。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老树的树干向河边倾斜着。", "target_word": "倾斜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体微微倾斜，靠在墙上。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车转弯时，车身会向外倾斜。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那根电线杆倾斜得很厉害，快倒了。", "target_word": "倾斜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "倾斜了", "label": "完成体"}, {"form": "倾斜着", "label": "持续体"}, {"form": "倾斜过", "label": "经历体"}], "register": "通用", "sense_fingerprint": "向一侧歪斜偏离垂直", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倾斜", "is_correct": true, "explanation": "倾斜：塔向一侧歪，偏离垂直，符合句意，与“看起来很危险”相合。"}, {"text": "融化", "is_correct": false, "explanation": "语义：“融化”指固体遇热变成液体，塔不会融化，句意不通。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与塔的歪斜无关，句意不通。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指东西长霉，与塔的状态无关，句意不通。"}], "explanations": {"倾斜": "倾斜：塔向一侧歪，偏离垂直，符合句意，与“看起来很危险”相合。", "融化": "语义：“融化”指固体遇热变成液体，塔不会融化，句意不通。", "生锈": "语义：“生锈”指金属被氧化，与塔的歪斜无关，句意不通。", "发霉": "语义：“发霉”指东西长霉，与塔的状态无关，句意不通。"}, "sentence_index": 0, "correct_answer": "倾斜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旗杆倾斜得笔直，看着很稳。", "explanation": "这里应该用〈挺〉。“倾斜”表示不直，与“笔直”自相矛盾；表示直立的旗杆要用“挺”。"}, {"text": "一脚踢出去，球倾斜了，没有进门。", "explanation": "这里应该用〈偏〉。“偏”指方向不对；“倾斜”指物体一边高一边低，不用来形容球的运动。"}, {"text": "妈妈把汤倾斜进碗里。", "explanation": "这里应该用〈倒〉。“倾斜”指物体本身偏离垂直或水平，不能表示把液体倒进容器的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倾斜", "is_correct": true, "explanation": "倾斜：老树的树干偏向河边，不是直直的，符合句意和“向河边”的方向。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”指人或动物流泪出声，树干不会哭泣，句意不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”只能用于人或动物，不能用来形容树干。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”指在水中运动，与树干的方向无关，句意不通。"}], "explanations": {"倾斜": "倾斜：老树的树干偏向河边，不是直直的，符合句意和“向河边”的方向。", "哭泣": "语义：“哭泣”指人或动物流泪出声，树干不会哭泣，句意不通。", "咳嗽": "搭配：“咳嗽”只能用于人或动物，不能用来形容树干。", "游泳": "语义：“游泳”指在水中运动，与树干的方向无关，句意不通。"}, "sentence_index": 6, "correct_answer": "倾斜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩倾斜了，这次考得很差。", "explanation": "这里应该用〈下滑〉。“倾斜”指物体偏离垂直或水平，不用于成绩；成绩变差要用“下滑”。"}, {"text": "他说话很倾斜，大家都听不懂。", "explanation": "这里应该用〈含糊〉。“倾斜”指物体偏离垂直或水平，不用来形容说话。"}, {"text": "他的笑声倾斜了，听起来很刺耳。", "explanation": "这里应该用〈尖〉。“倾斜”指物体偏离垂直或水平，不用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那棵树倾斜的很厉害，快要倒了。", "corrected_sentence": "那棵树倾斜得很厉害，快要倒了。", "error_description": "“倾斜”后面接补语，要用助词“得”，不用“的”。错误形式：倾斜的很厉害。正确形式：倾斜得很厉害。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大风一吹，电线杆倾斜了了。", "corrected_sentence": "大风一吹，电线杆倾斜了。", "error_description": "“了”只用一个，不能重复。错误形式：倾斜了了。正确形式：倾斜了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
