INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个人写的所有书放在一起。", "primary_collocate": null, "pronunciation": "quán jí", "ipa": "tɕʰɥɛn˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我想买一套《巴金全集》。", "target_word": "全集", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位作家的全集放在书架最上面。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把《钱钟书全集》都借回家了。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全集太贵了，我只买了其中一本。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套全集的封面是蓝色的，很好看。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里有《沈从文全集》，你可以去借。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她收藏了这位诗人的全集。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友送我的生日礼物是一套《海明威全集》。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读完了他的全集，还想再读一遍。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家写了很多书，出版社要出他的全集。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套全集", "label": "量词"}, {"form": "一部全集", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人写的所有书合在一起成为一套", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全集", "is_correct": true, "explanation": "全集指巴金全部作品的汇编，与“一套”和“《巴金……》”的书名搭配相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是书，“《巴金地图》”不成书名，与“买一套”的书籍语境不符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是书，“《巴金花园》”不成书名，与“买一套”的书籍语境不符。"}, {"text": "厨具", "is_correct": false, "explanation": "语义：厨具与书名无关，“《巴金厨具》”不是书，不符合“买”的对象。"}], "explanations": {"全集": "全集指巴金全部作品的汇编，与“一套”和“《巴金……》”的书名搭配相符。", "地图": "语义：地图不是书，“《巴金地图》”不成书名，与“买一套”的书籍语境不符。", "花园": "语义：花园不是书，“《巴金花园》”不成书名，与“买一套”的书籍语境不符。", "厨具": "语义：厨具与书名无关，“《巴金厨具》”不是书，不符合“买”的对象。"}, "sentence_index": 0, "correct_answer": "全集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套全集收了他最有名的几篇小说，别的都没收。", "explanation": "这里应该用〈选集〉。全集收录全部作品，只挑几篇应称选集。"}, {"text": "这套全集收了各种家常菜的做法，很实用。", "explanation": "这里应该用〈大全〉。全集只收同一位作者的全部作品，收录各种菜谱的汇编应称大全。"}, {"text": "这套全集收了三位作家的小说，每位写了两本。", "explanation": "这里应该用〈丛书〉。全集只收同一位作者的全部作品，三位作家的作品应称丛书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全集", "is_correct": true, "explanation": "全集指这位诗人全部作品的汇编，可以被收藏，与句意相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是书，“收藏厨房”不合理，与诗人的作品无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“收藏”不与“天气”搭配，“诗人的天气”不成词组。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地理数值，不能被收藏，也与诗人的作品无关。"}], "explanations": {"全集": "全集指这位诗人全部作品的汇编，可以被收藏，与句意相符。", "厨房": "语义：厨房不是书，“收藏厨房”不合理，与诗人的作品无关。", "天气": "搭配：“收藏”不与“天气”搭配，“诗人的天气”不成词组。", "海拔": "语义：海拔是地理数值，不能被收藏，也与诗人的作品无关。"}, "sentence_index": 6, "correct_answer": "全集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部全集收录了两万条词条，查阅很方便。", "explanation": "这里应该用〈辞书〉。全集收录一位作者的作品，收录词条的工具书应称辞书。"}, {"text": "这本全集收了去年全国的统计数据，很有参考价值。", "explanation": "这里应该用〈年鉴〉。全集收录作者的全部作品，收录年度统计数据的应称年鉴。"}, {"text": "这套全集收了三十位诗人的诗歌，很厚。", "explanation": "这里应该用〈合集〉。全集只收同一位作者的全部作品，收录多位诗人作品应称合集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹把一只《张爱玲全集》送给了朋友。", "corrected_sentence": "妹妹把一套《张爱玲全集》送给了朋友。", "error_description": "量词错误：“全集”应用量词“套”或“部”，“只”不能用来数书籍。错句中的“一只”应改为“一套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家的全集把他读完了。", "corrected_sentence": "这位作家的全集被他读完了。", "error_description": "介词错误：“全集”是被读完的对象，应用“被”字句，不能用“把”。错句中的“把”应改为“被”，应说“被他读完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
