INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某人的全部作品汇集成的书。", "primary_collocate": null, "pronunciation": "quán jí", "ipa": "tɕʰɥɛn˧˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "图书馆新买了一套《鲁迅全集》。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想把这位作家的全集都读一遍。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书架上放着一套《李白全集》。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套全集一共有二十卷，很厚。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸生日那天，我送他一套《老舍全集》。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位诗人去世后，朋友出版了他的全集。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店找到了莎士比亚全集。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部全集收了他所有的小说和诗。", "target_word": "全集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买全集比一本一本买便宜多了。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过这位作家的全集，所以很了解他。", "target_word": "全集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套全集", "label": "量词"}, {"form": "一部全集", "label": "量词"}], "register": "中性", "sense_fingerprint": "某位作家的全部作品汇集而成的书，常以套、部计", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全集", "is_correct": true, "explanation": "全集指一位作家全部作品的汇编，与“一套《鲁迅……》”的书名搭配相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是作家作品的汇编，与“图书馆新买了一套《鲁迅……》”的书名不符。"}, {"text": "厨具", "is_correct": false, "explanation": "语义：厨具不是书，“《鲁迅厨具》”也不成书名，与图书馆买书的语境无关。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是书，“《鲁迅花园》”不成书名，与图书馆买书的语境不符。"}], "explanations": {"全集": "全集指一位作家全部作品的汇编，与“一套《鲁迅……》”的书名搭配相符。", "地图": "语义：地图不是作家作品的汇编，与“图书馆新买了一套《鲁迅……》”的书名不符。", "厨具": "语义：厨具不是书，“《鲁迅厨具》”也不成书名，与图书馆买书的语境无关。", "花园": "语义：花园不是书，“《鲁迅花园》”不成书名，与图书馆买书的语境不符。"}, "sentence_index": 0, "correct_answer": "全集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套全集只收了他的十篇散文，其余作品都没有收。", "explanation": "这里应该用〈散文选〉。全集要收录作者的全部作品，只选十篇散文应称散文选。"}, {"text": "这本全集收了各类旅行攻略，很实用。", "explanation": "这里应该用〈大全〉。全集只收同一位作者的全部作品，收录各类攻略的汇编应称大全。"}, {"text": "这套全集收了他最好的小说和诗，别的都没收。", "explanation": "这里应该用〈选集〉。全集收录全部作品，只挑最好的作品应称选集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全集", "is_correct": true, "explanation": "全集指莎士比亚全部作品的汇编，在书店可以找到，与句意相符。"}, {"text": "棋谱", "is_correct": false, "explanation": "语义：棋谱是棋局记录，与莎士比亚无关，“莎士比亚棋谱”不成词组，与书店找书的语境不符。"}, {"text": "药方", "is_correct": false, "explanation": "语义：药方不是作家作品的汇编，“莎士比亚药方”不通，与书店找书的语境不符。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票不是书，“莎士比亚车票”不成词组，与书店找书的语境不符。"}], "explanations": {"全集": "全集指莎士比亚全部作品的汇编，在书店可以找到，与句意相符。", "棋谱": "语义：棋谱是棋局记录，与莎士比亚无关，“莎士比亚棋谱”不成词组，与书店找书的语境不符。", "药方": "语义：药方不是作家作品的汇编，“莎士比亚药方”不通，与书店找书的语境不符。", "车票": "语义：车票不是书，“莎士比亚车票”不成词组，与书店找书的语境不符。"}, "sentence_index": 6, "correct_answer": "全集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套全集收了五位作家的作品，很厚。", "explanation": "这里应该用〈合集〉。全集只收同一位作者的全部作品，收录多位作家的作品应称合集。"}, {"text": "这本全集收了去年全省的经济数据，很有参考价值。", "explanation": "这里应该用〈年鉴〉。全集收录作者的全部作品，收录年度统计数据的应称年鉴。"}, {"text": "这部全集收了两万个词，很有用。", "explanation": "这里应该用〈词典〉。全集收录一位作者的作品，收录两万个词条的工具书应称词典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只《巴金全集》，放在客厅里。", "corrected_sentence": "他买了一套《巴金全集》，放在客厅里。", "error_description": "量词错误：“全集”应用量词“套”（或“部”），“只”不能用来数书籍。错句中的“一只”应改为“一套”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一张全集，送给爸爸。", "corrected_sentence": "我想买一部全集，送给爸爸。", "error_description": "量词错误：“全集”应用量词“部”或“套”，“张”用于平面的纸张，不能用于书籍。错句中的“一张”应改为“一部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
