INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97147, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "左边和右边这两个边。", "primary_collocate": null, "pronunciation": "liǎng cè", "ipa": "ljɑŋ˨˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "路的两侧都是树。", "target_word": "两侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河两侧有很多小房子。", "target_word": "两侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子两侧各放一把椅子。", "target_word": "两侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你站在门的两侧。", "target_word": "两侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的头发两侧很短。", "target_word": "两侧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "马路两侧停满了汽车。", "target_word": "两侧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山路两侧开着很多野花。", "target_word": "两侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书放在电脑两侧的架子上。", "target_word": "两侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼梯两侧有扶手，老人可以扶着走。", "target_word": "两侧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车两侧的窗户都开着。", "target_word": "两侧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体或道路左右两个边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60d9e4b5-858a-436f-a0ee-7c5a7eef59b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两侧", "is_correct": true, "explanation": "正确答案：两侧 liǎng cè，指左右两边。"}, {"text": "良策", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liǎng（第三声）不同，意思是好的计策。"}, {"text": "两次", "is_correct": false, "explanation": "韵母不同：cì 与 cè 韵母不同，意思是两回。"}, {"text": "量测", "is_correct": false, "explanation": "声调不同：liáng（第二声）与 liǎng（第三声）不同，意思是测量。"}, {"text": "两色", "is_correct": false, "explanation": "声母不同：sè 与 cè 声母不同，意思是两种颜色。"}], "explanations": {"两侧": "正确答案：两侧 liǎng cè，指左右两边。", "良策": "声调不同：liáng（第二声）与 liǎng（第三声）不同，意思是好的计策。", "两次": "韵母不同：cì 与 cè 韵母不同，意思是两回。", "量测": "声调不同：liáng（第二声）与 liǎng（第三声）不同，意思是测量。", "两色": "声母不同：sè 与 cè 声母不同，意思是两种颜色。"}, "sentence_index": null, "correct_answer": "两侧"}, "level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空在头顶，不可能是“都是树”的地方。"}, {"text": "两侧", "is_correct": true, "explanation": "两侧指路的左右两边，正是树排列的位置，符合语境。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”指朝向，不能说路的朝向“都是树”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”说色彩，不能与“都是树”搭配。"}], "explanations": {"天空": "语义：天空在头顶，不可能是“都是树”的地方。", "两侧": "两侧指路的左右两边，正是树排列的位置，符合语境。", "方向": "语义：“方向”指朝向，不能说路的朝向“都是树”。", "颜色": "搭配：“颜色”说色彩，不能与“都是树”搭配。"}, "sentence_index": 0, "correct_answer": "两侧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的两侧都很忙。", "explanation": "这里应用〈前后〉。月初和月末称“前后”，“两侧”只指空间的左右两边，不指时间。"}, {"text": "这次旅行的两侧都很精彩。", "explanation": "这里应用〈首尾〉。旅行的开头和结尾称“首尾”，“两侧”不指时间。"}, {"text": "他两侧看了看，才过马路。", "explanation": "这里应用〈左右〉。“左右看”是动词性用法，“两侧”是名词，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两手", "is_correct": false, "explanation": "语义：“两手”指双手，不能用来指山路的两边。"}, {"text": "两侧", "is_correct": true, "explanation": "两侧指山路左右两边，野花开在路旁，符合语境。"}, {"text": "两层", "is_correct": false, "explanation": "语义：“两层”指层数或楼层，与山路的左右两边不符。"}, {"text": "两天", "is_correct": false, "explanation": "语义：“两天”指时间，不能指山路的左右两边。"}], "explanations": {"两手": "语义：“两手”指双手，不能用来指山路的两边。", "两侧": "两侧指山路左右两边，野花开在路旁，符合语境。", "两层": "语义：“两层”指层数或楼层，与山路的左右两边不符。", "两天": "语义：“两天”指时间，不能指山路的左右两边。"}, "sentence_index": 6, "correct_answer": "两侧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气两侧都很好。", "explanation": "这里应用〈两方面〉。天气没有左右两边，“两侧”只指物体或道路的左右两边。"}, {"text": "这节课的两侧都很有趣。", "explanation": "这里应用〈前后〉。课的开头和结尾是时间，“两侧”只指空间的左右两边。"}, {"text": "他的想法两侧都很新。", "explanation": "这里应用〈各方面〉。想法不是物体，没有左右两边，不能用“两侧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河的一个两侧都种着柳树。", "corrected_sentence": "河的两侧都种着柳树。", "error_description": "错误：“一个两侧”。应为“两侧”。“两侧”已含“两”的数量，前面不能再加数量词“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街道两侧们都挂着灯笼。", "corrected_sentence": "街道两侧都挂着灯笼。", "error_description": "错误：“两侧们”。应为“两侧”。“们”只用于指人，“两侧”是方位名词，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed384b3a-f42d-417f-89b9-819ce15b2bbf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
