INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "定时印出来给大家看的纸本，有很多文章。", "primary_collocate": null, "pronunciation": "kān wù", "ipa": "kʰan⁵⁵ u⁵¹", "syllable_count": 2, "sentences": [{"text": "图书馆里有很多文学刊物。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份刊物每个月出一次。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个星期都看这种刊物上的文章。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份刊物里有很多有意思的文章。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸订了一份历史刊物，每月寄到家里。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种刊物是每周出版的，很多人喜欢看。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一份学校刊物上发表了第一篇文章。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班办了一份刊物，大家都写了文章。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖各种刊物，有周刊也有月刊。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧刊物可以在图书馆旁边的架子上找到。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "学术刊物", "label": "复合"}], "register": "中性", "sense_fingerprint": "定期印出、供人阅读、收有许多文章的纸本出版物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刊物", "is_correct": true, "explanation": "正确：“文学刊物”指刊载文学作品的定期出版物，放在“图书馆里有很多”之后最自然。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“文学”只能修饰作品、读物一类，不能说“文学桌子”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与“文学”无关，句子读起来不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“文学”不能修饰电脑，“文学电脑”不是可以说的组合。"}], "explanations": {"刊物": "正确：“文学刊物”指刊载文学作品的定期出版物，放在“图书馆里有很多”之后最自然。", "桌子": "搭配：“文学”只能修饰作品、读物一类，不能说“文学桌子”。", "钢琴": "语义：钢琴是乐器，与“文学”无关，句子读起来不通。", "电脑": "搭配：“文学”不能修饰电脑，“文学电脑”不是可以说的组合。"}, "sentence_index": 0, "correct_answer": "刊物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学术会议上发表了一份刊物。", "explanation": "这里应该用〈论文〉。发表的是论文、文章等作品；刊物是定期出版的纸本，应说“出版刊物”，不说“发表刊物”。"}, {"text": "图书馆门口放着一把刊物。", "explanation": "量词用错。刊物是纸本，应当用“份”或“本”；“把”用于有柄的器具，不能用来数刊物。"}, {"text": "他花了三年写了一份刊物。", "explanation": "这里应该用〈书〉。写的是书；刊物是定期出版的纸本，要靠编辑、办刊，不说“写一份刊物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刊物", "is_correct": true, "explanation": "正确：“一份学校刊物”指学校办的定期出版物，可以在上面发表文章。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是能发表文章的载体，句子读起来不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是球类，不能在上面发表文章，与“发表文章”不搭。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：“雨伞”不能说“一份”，而且“雨伞上发表文章”也不成立。"}], "explanations": {"刊物": "正确：“一份学校刊物”指学校办的定期出版物，可以在上面发表文章。", "冰箱": "语义：冰箱是家电，不是能发表文章的载体，句子读起来不通。", "足球": "语义：足球是球类，不能在上面发表文章，与“发表文章”不搭。", "雨伞": "搭配：“雨伞”不能说“一份”，而且“雨伞上发表文章”也不成立。"}, "sentence_index": 6, "correct_answer": "刊物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电台每天早上播一份刊物。", "explanation": "这里应该用〈新闻〉。电台播放的是新闻和节目；刊物是纸本，不能说“播”。"}, {"text": "我想买一首刊物送给朋友。", "explanation": "量词用错。“首”用于诗歌、歌曲；刊物应说“一份”或“一本”。"}, {"text": "老师昨晚批改了一份刊物。", "explanation": "这里应该用〈作业〉。“批改”用于作业、试卷；刊物是出版物，不能批改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每个星期都买这辆刊物。", "corrected_sentence": "我每个星期都买这份刊物。", "error_description": "量词用错。“刊物”应使用“份”，“辆”用于车辆，不能用来数刊物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这只刊物放在书架上了。", "corrected_sentence": "我把这份刊物放在书架上了。", "error_description": "量词用错。“刊物”应使用“份”，“只”多用于动物，不能用来数刊物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
