INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "定期出版的书报杂志的总称。", "primary_collocate": null, "pronunciation": "kān wù", "ipa": "kʰan⁵⁵ u⁵¹", "syllable_count": 2, "sentences": [{"text": "杂志和报纸都是定期出版的刊物。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店里的刊物很多，有杂志也有报纸。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校图书馆订了很多刊物。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家对刊物的管理很严格。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常常在刊物上写文章。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新出版的刊物每个月都会送到学院。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就爱读各种刊物。", "target_word": "刊物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市有几十种刊物，其中既有报纸也有杂志。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这些旧刊物放到书架上。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们办的刊物在学生中很受欢迎。", "target_word": "刊物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "定期刊物", "label": "复合"}], "register": "中性", "sense_fingerprint": "定期出版的书、报纸、杂志的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刊物", "is_correct": true, "explanation": "正确：“定期出版的刊物”指报纸、杂志等定期出版物的统称，与“杂志和报纸”正好对应。"}, {"text": "电影", "is_correct": false, "explanation": "语义：句子前半说的是“杂志和报纸”，电影不是报刊，不能概括杂志和报纸。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具不是出版物，“定期出版”的说法不成立。"}, {"text": "手表", "is_correct": false, "explanation": "语义：手表不能定期出版，句子读起来不通。"}], "explanations": {"刊物": "正确：“定期出版的刊物”指报纸、杂志等定期出版物的统称，与“杂志和报纸”正好对应。", "电影": "语义：句子前半说的是“杂志和报纸”，电影不是报刊，不能概括杂志和报纸。", "家具": "语义：家具不是出版物，“定期出版”的说法不成立。", "手表": "语义：手表不能定期出版，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "刊物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在晚会上朗诵了一份刊物。", "explanation": "这里应该用〈诗〉。“朗诵”的对象是诗歌、散文；刊物是纸本出版物，不能朗诵。"}, {"text": "书店里摆着一颗刊物。", "explanation": "量词用错。“颗”用于粒状或球形的东西；刊物是纸本，应说“一份”或“一本”。"}, {"text": "他给妈妈写了一份刊物。", "explanation": "这里应该用〈信〉。写的是信件；刊物是定期出版的纸本，不说“写一份刊物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刊物", "is_correct": true, "explanation": "正确：“读各种刊物”指阅读各类定期出版的书报杂志，与“读”搭配自然。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说“读音乐”。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是用来玩的，不能“读”，句子读起来不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“读歌曲”不成立，应说“唱歌曲”。"}], "explanations": {"刊物": "正确：“读各种刊物”指阅读各类定期出版的书报杂志，与“读”搭配自然。", "音乐": "搭配：“读”的对象是文字，不能说“读音乐”。", "游戏": "语义：游戏是用来玩的，不能“读”，句子读起来不通。", "歌曲": "搭配：“读歌曲”不成立，应说“唱歌曲”。"}, "sentence_index": 6, "correct_answer": "刊物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在书店买了一块刊物。", "explanation": "量词用错。“块”用于块状的东西；刊物是纸本，应说“一份”或“一本”。"}, {"text": "他花了一周时间绘制了一份刊物。", "explanation": "这里应该用〈地图〉。绘制的是地图、图样；刊物是定期印刷的纸本，不能说“绘制”。"}, {"text": "剧团演出了一份刊物。", "explanation": "这里应该用〈话剧〉。“演出”用于戏剧、节目；刊物是印刷品，不能演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书店里摆着很多刊物们。", "corrected_sentence": "书店里摆着很多刊物。", "error_description": "词尾错误。“们”只用于指人或拟人的复数，刊物是物品，不能加“们”，应说“很多刊物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每月都订一只刊物。", "corrected_sentence": "他每月都订一份刊物。", "error_description": "量词用错。“刊物”应使用“份”，“只”多用于动物，不能用来数刊物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
