INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97155, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看谁对谁错，然后决定怎么办。", "primary_collocate": null, "pronunciation": "pàn", "ipa": "pʰan˥˩", "syllable_count": 1, "sentences": [{"text": "两个孩子吵架，妈妈判小明对。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "体育课上，老师判我们队输了。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事谁对谁错，请你来判一判。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷看了看两个孩子，判弟弟错了。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板听完双方的话，判小王对，小李错。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次辩论，评委判我们这一队赢了。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们让村长来判，看谁说得对。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球是不是出界了？老师判它没出界。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你来判，你会判谁对呢？", "target_word": "判", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师听了两个学生的话，判小红说得对。", "target_word": "判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判了", "label": "完成体"}, {"form": "判过", "label": "经历体"}, {"form": "判一判", "label": "重叠"}], "register": "通用", "sense_fingerprint": "分出对错后作出裁定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：判（pàn，第四声）指分出对错后作出裁定。"}, {"text": "胖", "is_correct": false, "explanation": "pàng（第四声）与 pàn 韵母不同（ang 与 an），意思是胖。"}, {"text": "盘", "is_correct": false, "explanation": "pán（第二声）与 pàn 声调不同，意思是盘子。"}, {"text": "攀", "is_correct": false, "explanation": "pān（第一声）与 pàn 声调不同，意思是攀登。"}, {"text": "办", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是办理。"}, {"text": "犯", "is_correct": false, "explanation": "fàn 与 pàn 声母不同（f 与 p），意思是犯错。"}], "explanations": {"判": "正确：判（pàn，第四声）指分出对错后作出裁定。", "胖": "pàng（第四声）与 pàn 韵母不同（ang 与 an），意思是胖。", "盘": "pán（第二声）与 pàn 声调不同，意思是盘子。", "攀": "pān（第一声）与 pàn 声调不同，意思是攀登。", "办": "bàn 与 pàn 声母不同（b 与 p），意思是办理。", "犯": "fàn 与 pàn 声母不同（f 与 p），意思是犯错。"}, "sentence_index": null, "correct_answer": "判"}, "level_3": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：“判”指分清对错并作出断定，符合“妈妈判小明对”。"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”后要带“做某事”的动作，不能直接接形容词“对”。"}, {"text": "哄", "is_correct": false, "explanation": "语义：“哄”是安抚、诱导，不表示断定是非。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示责备，与“判断对错”不是一回事。"}], "explanations": {"判": "正确：“判”指分清对错并作出断定，符合“妈妈判小明对”。", "劝": "配价：“劝”后要带“做某事”的动作，不能直接接形容词“对”。", "哄": "语义：“哄”是安抚、诱导，不表示断定是非。", "骂": "语义：“骂”表示责备，与“判断对错”不是一回事。"}, "sentence_index": 0, "correct_answer": "判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈判我做饭做得很好吃。", "explanation": "这里应该用〈夸〉。“判”指分出对错并作出裁定，不用于称赞别人的厨艺。"}, {"text": "他判了一下门，门就开了。", "explanation": "这里应该用〈推〉。“判”指分出对错并作出裁定，不能用来形容推门的动作。"}, {"text": "学校判了他的努力。", "explanation": "这里应该用〈表彰〉。“判”指作出对错的裁断，不用于授予荣誉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97155, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：判（pàn，第四声）指分出对错后作出裁定。"}, {"text": "伴", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是伴随。"}, {"text": "拌", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是搅拌。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 pàn 声母不同（f 与 p），意思是米饭。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是一半。"}, {"text": "贩", "is_correct": false, "explanation": "fàn 与 pàn 声母不同（f 与 p），意思是贩卖。"}], "explanations": {"判": "正确：判（pàn，第四声）指分出对错后作出裁定。", "伴": "bàn 与 pàn 声母不同（b 与 p），意思是伴随。", "拌": "bàn 与 pàn 声母不同（b 与 p），意思是搅拌。", "饭": "fàn 与 pàn 声母不同（f 与 p），意思是米饭。", "半": "bàn 与 pàn 声母不同（b 与 p），意思是一半。", "贩": "fàn 与 pàn 声母不同（f 与 p），意思是贩卖。"}, "sentence_index": null, "correct_answer": "判"}, "level_3": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：“判”指作出是非裁断，符合“让村长来判，看谁说得对”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是歌唱，与“看谁说得对”无关。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“分出谁对谁错”毫无关系，句意不通。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理物品，不能用来裁定是非。"}], "explanations": {"判": "正确：“判”指作出是非裁断，符合“让村长来判，看谁说得对”。", "唱": "语义：“唱”是歌唱，与“看谁说得对”无关。", "吃": "语义：“吃”与“分出谁对谁错”毫无关系，句意不通。", "修": "搭配：“修”用于修理物品，不能用来裁定是非。"}, "sentence_index": 6, "correct_answer": "判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导游判了这座古城的历史。", "explanation": "这里应该用〈介绍〉。“判”用于分出对错，不能用来讲解历史。"}, {"text": "他判了一眼窗外的风景。", "explanation": "这里应该用〈望〉。“判”指分出对错并作出裁定，不能用来形容看风景。"}, {"text": "大家都判那个孤单的老人。", "explanation": "这里应该用〈同情〉。“判”是分出对错、作出裁定，不能用来表达怜悯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师了判小明对，小明很高兴。", "corrected_sentence": "老师判了小明对，小明很高兴。", "error_description": "错误形式：“了判”，把动态助词“了”放在动词“判”之前。正确形式：“判了”，“了”接在“判”之后，表示动作已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判把判这次犯规无效。", "corrected_sentence": "裁判判这次犯规无效。", "error_description": "错误形式：“把判这次犯规无效”，“把”后应接受事宾语，不能直接接动词“判”。正确形式：“判这次犯规无效”，“判”带宾语“这次犯规”，结果补语“无效”接在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
