INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由法院依法作出裁决。", "primary_collocate": null, "pronunciation": "pàn", "ipa": "pʰan˥˩", "syllable_count": 1, "sentences": [{"text": "法官判他三年。", "target_word": "判", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法官判这家公司赔钱给他。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官判他无罪，他高兴极了。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院判这个人有罪。", "target_word": "判", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个案子，法院昨天判了。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官判他两年，他没有不服。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院判小李给小王五千块钱。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官听完双方的话，判她赢了官司。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为他偷了东西，法院判他进了监狱。", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样的案子，法院一般会判多久？", "target_word": "判", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "判了", "label": "完成体"}, {"form": "判过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "法院作出裁决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6dceebf9-b9ed-4f26-9a5c-9d9dcbda909f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：判（pàn，第四声）指法院作出裁决。"}, {"text": "半", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是一半。"}, {"text": "贩", "is_correct": false, "explanation": "fàn 与 pàn 声母不同（f 与 p），意思是贩卖。"}, {"text": "盘", "is_correct": false, "explanation": "pán（第二声）与 pàn 声调不同，意思是盘子。"}, {"text": "攀", "is_correct": false, "explanation": "pān（第一声）与 pàn 声调不同，意思是攀登。"}], "explanations": {"判": "正确：判（pàn，第四声）指法院作出裁决。", "半": "bàn 与 pàn 声母不同（b 与 p），意思是一半。", "贩": "fàn 与 pàn 声母不同（f 与 p），意思是贩卖。", "盘": "pán（第二声）与 pàn 声调不同，意思是盘子。", "攀": "pān（第一声）与 pàn 声调不同，意思是攀登。"}, "sentence_index": null, "correct_answer": "判"}, "level_3": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：“判”用于法官作出刑期裁决，符合“法官判他三年”。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”可以送进监狱，但不能直接带“三年”作刑期。"}, {"text": "罚", "is_correct": false, "explanation": "搭配：“罚”多用于罚款或处罚，不说“罚他三年”的刑期。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，与法官作出刑期裁决毫无关系。"}], "explanations": {"判": "正确：“判”用于法官作出刑期裁决，符合“法官判他三年”。", "送": "搭配：“送”可以送进监狱，但不能直接带“三年”作刑期。", "罚": "搭配：“罚”多用于罚款或处罚，不说“罚他三年”的刑期。", "夸": "语义：“夸”是称赞，与法官作出刑期裁决毫无关系。"}, "sentence_index": 0, "correct_answer": "判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察判了他两天。", "explanation": "这里应该用〈拘留〉。“判”的刑罚由法院作出，警察只能拘留。"}, {"text": "检察院判了他，案子交给了法院。", "explanation": "这里应该用〈起诉〉。“判”只能由法院作出，检察院只能向法院提起诉讼。"}, {"text": "老板判了他一个月的工资。", "explanation": "这里应该用〈扣〉。“判”只能由法院作出裁决，老板只能扣工资。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97156, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：判（pàn，第四声）指法院作出裁决。"}, {"text": "伴", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是伴随。"}, {"text": "拌", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是搅拌。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 pàn 声母不同（f 与 p），意思是米饭。"}, {"text": "办", "is_correct": false, "explanation": "bàn 与 pàn 声母不同（b 与 p），意思是办理。"}], "explanations": {"判": "正确：判（pàn，第四声）指法院作出裁决。", "伴": "bàn 与 pàn 声母不同（b 与 p），意思是伴随。", "拌": "bàn 与 pàn 声母不同（b 与 p），意思是搅拌。", "饭": "fàn 与 pàn 声母不同（f 与 p），意思是米饭。", "办": "bàn 与 pàn 声母不同（b 与 p），意思是办理。"}, "sentence_index": null, "correct_answer": "判"}, "level_3": {"options": [{"text": "判", "is_correct": true, "explanation": "正确：“判”用于法院作出赔偿裁决，符合“法院判小李给小王五千块钱”。"}, {"text": "借", "is_correct": false, "explanation": "语义：“借”表示借出，与法院作出赔偿裁决无关。"}, {"text": "赔", "is_correct": false, "explanation": "配价：“赔”后应接赔偿的对象和物品，不能直接接“小李”作为被判的对象。"}, {"text": "请", "is_correct": false, "explanation": "语义：“请”表示邀请或请求，与法院作出裁决不符。"}], "explanations": {"判": "正确：“判”用于法院作出赔偿裁决，符合“法院判小李给小王五千块钱”。", "借": "语义：“借”表示借出，与法院作出赔偿裁决无关。", "赔": "配价：“赔”后应接赔偿的对象和物品，不能直接接“小李”作为被判的对象。", "请": "语义：“请”表示邀请或请求，与法院作出裁决不符。"}, "sentence_index": 6, "correct_answer": "判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生判了一瓶药。", "explanation": "这里应该用〈开〉。“判”只能由法院作出裁决，医生只能开药。"}, {"text": "公司判他一千元。", "explanation": "这里应该用〈罚〉。“判”只能由法院作出，公司只能罚款。"}, {"text": "朋友判我去吃饭。", "explanation": "这里应该用〈邀请〉。“判”是作出裁决，不能用来表示邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官判给他三年，他没有不服。", "corrected_sentence": "法官判他三年，他没有不服。", "error_description": "错误形式：“判给他三年”，“判给”表示把东西判归某人，不用于刑期。正确形式：“判他三年”，表示法官对他判处三年刑期。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院判他罪无，他很高兴。", "corrected_sentence": "法院判他无罪，他很高兴。", "error_description": "错误形式：“判他罪无”。正确形式：“判他无罪”。“无罪”是动词“判”的结果补语，语序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2f3acb3-6de4-409e-8b44-988bdf5cd041') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
