INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在漂亮的地方，有花园的大房子。", "primary_collocate": null, "pronunciation": "bié shù", "ipa": "pjɛ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "山上有一栋带花园的别墅。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋别墅很大，前面有一个花园。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在海边买了一栋带花园的别墅。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别墅的院子里种着很多花。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的别墅有花园和游泳池，我们去玩了。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋别墅的花园里有一棵大树。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "住在别墅里，空气好，也很安静。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想在湖边盖一栋别墅，养几只狗。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座别墅有五个房间，一个大花园。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，一家人常去山上有花园的别墅住几天。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "座", "label": "量词"}, {"form": "海边别墅", "label": "复合"}], "register": "中性", "sense_fingerprint": "漂亮的地方、带花园的大房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅 bié shù：在漂亮的地方、带花园的大房子，本题答案。"}, {"text": "倍数", "is_correct": false, "explanation": "倍数 bèi shù：韵母不同（bèi 为 ei，bié 为 ie），声调也不同，意思是数学上的倍数。"}, {"text": "避暑", "is_correct": false, "explanation": "避暑 bì shǔ：韵母不同（bì 为 i，bié 为 ie），第二个音节声调也不同（shǔ 为第三声），意思是躲避夏天的暑热。"}, {"text": "别处", "is_correct": false, "explanation": "别处 bié chù：第二个音节声母不同（chù 为 ch，shù 为 sh），意思是别的地方。"}], "explanations": {"别墅": "别墅 bié shù：在漂亮的地方、带花园的大房子，本题答案。", "倍数": "倍数 bèi shù：韵母不同（bèi 为 ei，bié 为 ie），声调也不同，意思是数学上的倍数。", "避暑": "避暑 bì shǔ：韵母不同（bì 为 i，bié 为 ie），第二个音节声调也不同（shǔ 为第三声），意思是躲避夏天的暑热。", "别处": "别处 bié chù：第二个音节声母不同（chù 为 ch，shù 为 sh），意思是别的地方。"}, "sentence_index": null, "correct_answer": "别墅"}, "level_3": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅：独栋带花园的大房子，与“带花园的”相符。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车库是停车的地方，一般不住人，也不会带花园，与句意不符。"}, {"text": "菜市场", "is_correct": false, "explanation": "语义：菜市场是卖菜的公共场所，不是带花园的住宅。"}, {"text": "猫", "is_correct": false, "explanation": "搭配：量词“栋”只用于建筑，不能用来数“猫”。"}], "explanations": {"别墅": "别墅：独栋带花园的大房子，与“带花园的”相符。", "车库": "语义：车库是停车的地方，一般不住人，也不会带花园，与句意不符。", "菜市场": "语义：菜市场是卖菜的公共场所，不是带花园的住宅。", "猫": "搭配：量词“栋”只用于建筑，不能用来数“猫”。"}, "sentence_index": 0, "correct_answer": "别墅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把别墅放进了书包里。", "explanation": "这里应该用〈书〉。别墅是大房子，不能放进书包。"}, {"text": "这家餐厅的别墅很好吃。", "explanation": "这里应该用〈菜〉。别墅是住宅，不能用来形容食物好不好吃。"}, {"text": "学生们住在学校的别墅里。", "explanation": "这里应该用〈宿舍〉。别墅是私人住宅，学校给学生住的是宿舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅：带花园的独栋住宅，适合安静地居住，与“空气好，也很安静”相符。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站人来人往、比较吵闹，与“也很安静”矛盾。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“住在……里”一般不用于地铁，地铁不供人长期居住。"}, {"text": "矿井", "is_correct": false, "explanation": "语义：矿井里空气差，与“空气好”矛盾。"}], "explanations": {"别墅": "别墅：带花园的独栋住宅，适合安静地居住，与“空气好，也很安静”相符。", "车站": "语义：车站人来人往、比较吵闹，与“也很安静”矛盾。", "地铁": "搭配：“住在……里”一般不用于地铁，地铁不供人长期居住。", "矿井": "语义：矿井里空气差，与“空气好”矛盾。"}, "sentence_index": 6, "correct_answer": "别墅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把别墅挂在了墙上。", "explanation": "这里应该用〈画〉。别墅是大型住宅，不能挂在墙上。"}, {"text": "他骑着别墅去学校。", "explanation": "这里应该用〈自行车〉。别墅是房子，不能骑。"}, {"text": "我口渴了，想喝一杯别墅。", "explanation": "这里应该用〈水〉。别墅是房子，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父母在湖边盖了一只别墅，每年夏天去住。", "corrected_sentence": "我父母在湖边盖了一栋别墅，每年夏天去住。", "error_description": "量词“只”多用于小动物等，不能用于建筑。别墅应该用“栋”或“座”，正确说法是“盖了一栋别墅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末，我们在山上租了一只别墅。", "corrected_sentence": "周末，我们在山上租了一栋别墅。", "error_description": "量词“只”多用于小动物等，不能用于建筑。别墅应该用“栋”或“座”，正确说法是“租了一栋别墅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
