INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建在郊外或风景区、带有庭院的独栋住宅。", "primary_collocate": null, "pronunciation": "bié shù", "ipa": "pjɛ˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他在郊外买了一栋别墅。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风景区旁边有很多别墅，环境很好。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋别墅建在郊外，有一个小庭院。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王在城外住别墅，每天开车上班。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖边的别墅都有自己的庭院。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风景区里新建了几栋别墅。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把郊外的别墅租给了一家外国人。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在郊外的别墅，每天早上都能听到鸟叫。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套别墅离市中心很远，在山脚下。", "target_word": "别墅", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在风景区租了一栋别墅，准备住一个星期。", "target_word": "别墅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栋", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "独栋别墅", "label": "复合"}, {"form": "别墅区", "label": "复合"}], "register": "中性", "sense_fingerprint": "郊外或风景区的独栋带庭院住宅", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅 bié shù：建在郊外或风景区、带庭院的独栋住宅，本题答案。"}, {"text": "倍数", "is_correct": false, "explanation": "倍数 bèi shù：韵母不同（bèi 为 ei，bié 为 ie），声调也不同，意思是数学上的倍数。"}, {"text": "避暑", "is_correct": false, "explanation": "避暑 bì shǔ：韵母不同（bì 为 i，bié 为 ie），第二个音节声调也不同（shǔ 为第三声），意思是躲避夏天的暑热。"}, {"text": "别处", "is_correct": false, "explanation": "别处 bié chù：第二个音节声母不同（chù 为 ch，shù 为 sh），意思是别的地方。"}], "explanations": {"别墅": "别墅 bié shù：建在郊外或风景区、带庭院的独栋住宅，本题答案。", "倍数": "倍数 bèi shù：韵母不同（bèi 为 ei，bié 为 ie），声调也不同，意思是数学上的倍数。", "避暑": "避暑 bì shǔ：韵母不同（bì 为 i，bié 为 ie），第二个音节声调也不同（shǔ 为第三声），意思是躲避夏天的暑热。", "别处": "别处 bié chù：第二个音节声母不同（chù 为 ch，shù 为 sh），意思是别的地方。"}, "sentence_index": null, "correct_answer": "别墅"}, "level_3": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅：郊外或风景区的独栋带庭院住宅，与“郊外”相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学校的场所，不是人在郊外买来居住的房子。"}, {"text": "图书", "is_correct": false, "explanation": "搭配：量词“栋”只用于建筑，不能用来数“图书”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，“栋”不能用于汽车。"}], "explanations": {"别墅": "别墅：郊外或风景区的独栋带庭院住宅，与“郊外”相符。", "教室": "语义：教室是学校的场所，不是人在郊外买来居住的房子。", "图书": "搭配：量词“栋”只用于建筑，不能用来数“图书”。", "汽车": "搭配：汽车的量词是“辆”，“栋”不能用于汽车。"}, "sentence_index": 0, "correct_answer": "别墅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在郊外喝了一杯别墅。", "explanation": "这里应该用〈茶〉。别墅是住宅，不能用来喝。"}, {"text": "工人住在工地的别墅里。", "explanation": "这里应该用〈宿舍〉。别墅是独栋带庭院的住宅，不会建在工地上给工人住。"}, {"text": "探险队在草原上搭起了别墅。", "explanation": "这里应该用〈帐篷〉。别墅是盖起来的固定建筑，不能像帐篷一样搭起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别墅", "is_correct": true, "explanation": "别墅：可以出租的独栋住宅，与“租给了一家外国人”相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“租”一般搭配房屋、土地等可出租的东西，不能搭配“空气”。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想不能被出租给别人，句子读起来不通。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不能像房屋一样被“租给”别人。"}], "explanations": {"别墅": "别墅：可以出租的独栋住宅，与“租给了一家外国人”相符。", "空气": "搭配：“租”一般搭配房屋、土地等可出租的东西，不能搭配“空气”。", "思想": "语义：思想不能被出租给别人，句子读起来不通。", "老师": "语义：老师是人，不能像房屋一样被“租给”别人。"}, "sentence_index": 6, "correct_answer": "别墅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐别墅去上班。", "explanation": "这里应该用〈地铁〉。别墅是住宅，不是交通工具，不能用来“坐”。"}, {"text": "运货的别墅开进了城里。", "explanation": "这里应该用〈卡车〉。别墅是固定的住宅，不能开进城里。"}, {"text": "游客坐别墅去岛上参观。", "explanation": "这里应该用〈船〉。别墅是住宅，不是船，不能用来“坐”去岛上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在湖边盖了一只别墅，周末去住。", "corrected_sentence": "妈妈在湖边盖了一栋别墅，周末去住。", "error_description": "别墅是建筑，量词应用“栋”，不能用“只”（“只”多用于小动物等）。正确说法是“盖了一栋别墅”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年在湖边租了一只别墅。", "corrected_sentence": "我们去年在湖边租了一栋别墅。", "error_description": "量词“只”多用于小动物等，不能用于建筑。别墅应该用“栋”或“座”，正确说法是“租了一栋别墅”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
