INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "除了这个以外，没有别的了。", "primary_collocate": null, "pronunciation": "bié wú", "ipa": "pje˧˥ u˧˥", "syllable_count": 2, "sentences": [{"text": "我对这件事别无意见。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她来中国别无目的，只是想学汉语。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，回家路上别无他人。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里很干净，桌子上别无其他东西。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "孩子对妈妈说，除了你，我别无所求。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小村子很偏僻，四周的山上别无人烟。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "公司没有钱了，老板别无办法，只好关门。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这份工作别无他求，能养家就很满足。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "老人一个人住，别无子女。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她穿着一件旧衣服，别无装饰。", "target_word": "别无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "除了已提到的，再没有别的事物或办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别无", "is_correct": true, "explanation": "别无：表示除了这件事以外没有别的意见，与句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“意见”搭配，应说“提出意见”。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”一般接请求或建议，不能说“拒绝意见”。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有意见”强调仅仅有意见，与“别无”表示的“除此之外没有别的”重复，语义不顺。"}], "explanations": {"别无": "别无：表示除了这件事以外没有别的意见，与句意相符。", "吃": "搭配：“吃”不能与“意见”搭配，应说“提出意见”。", "拒绝": "搭配：“拒绝”一般接请求或建议，不能说“拒绝意见”。", "只有": "语义：“只有意见”强调仅仅有意见，与“别无”表示的“除此之外没有别的”重复，语义不顺。"}, "sentence_index": 0, "correct_answer": "别无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小组别无三名队员。", "explanation": "这里应该用〈只有〉。“别无”表示除此之外没有别的，不用来限定人数；说小组仅有三名队员，应用〈只有〉。"}, {"text": "他别无去过北京，很遗憾。", "explanation": "这里应该用〈没有〉。“别无”后面接名词性成分，不能直接接动词短语；说他没有去过北京，应用〈没有〉。"}, {"text": "她的字别无漂亮。", "explanation": "这里应该用〈很〉。“别无”后面接名词性成分，不能直接修饰形容词；说字很漂亮，应用〈很〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别无", "is_correct": true, "explanation": "别无：表示除此之外没有别的办法，与“只好关门”相符。"}, {"text": "另有", "is_correct": false, "explanation": "语义：“另有办法”说明还有出路，与后面的“只好关门”矛盾。"}, {"text": "找到", "is_correct": false, "explanation": "语义：“找到办法”意味着有了出路，与“只好关门”矛盾。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”一般不接“办法”，应说“想出办法”。"}], "explanations": {"别无": "别无：表示除此之外没有别的办法，与“只好关门”相符。", "另有": "语义：“另有办法”说明还有出路，与后面的“只好关门”矛盾。", "找到": "语义：“找到办法”意味着有了出路，与“只好关门”矛盾。", "打开": "搭配：“打开”一般不接“办法”，应说“想出办法”。"}, "sentence_index": 6, "correct_answer": "别无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛别无两名选手。", "explanation": "这里应该用〈只有〉。“别无”表示除此之外没有别的，不用来限定人数；说比赛仅有两名选手，应用〈只有〉。"}, {"text": "他昨天别无吃药，所以病得很重。", "explanation": "这里应该用〈没有〉。“别无”后面接名词性成分，不能直接接动词短语；说他昨天没有吃药，应用〈没有〉。"}, {"text": "这件衣服别无好看。", "explanation": "这里应该用〈很〉。“别无”后面接名词性成分，不能直接修饰形容词；说衣服很好看，应用〈很〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间旧房子很简单，屋里别无的其他家具。", "corrected_sentence": "这间旧房子很简单，屋里别无其他家具。", "error_description": "“别无”后面不能加“的”；应说“别无其他家具”，不说“别无的其他家具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子大了，父母别无的所求，只希望他们健康。", "corrected_sentence": "孩子大了，父母别无所求，只希望他们健康。", "error_description": "“别无”后面不能直接加“的”接“所求”；应说“别无所求”，不说“别无的所求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
