INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有其他的；除此之外再没有。", "primary_collocate": null, "pronunciation": "bié wú", "ipa": "pje˧˥ u˧˥", "syllable_count": 2, "sentences": [{"text": "事已至此，我们别无选择。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "除了等待，我们别无他法。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这座城市别无亲人。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钱都花完了，他别无办法，只好回家。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上积满了雪，我们别无他路，只能等雪停。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "她孤身一人，别无依靠。", "target_word": "别无", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家小店没有空调，夏天别无他法，只能开窗。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "他的房间很朴素，书架上别无其他装饰。", "target_word": "别无", "complexity_tier": "T3", "furigana": "bié wú", "sentence_source": "generated"}, {"text": "想学好中文，别无捷径，只有多练习。", "target_word": "别无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "门锁着，他别无选择，只能在外面等。", "target_word": "别无", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "除此之外没有别的（后接名词，如别无选择）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别无", "is_correct": true, "explanation": "别无：表示除此之外没有别的，与“事已至此”所说的无路可走相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃选择”是主动舍弃，与“事已至此”只能接受的处境不符。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有选择”表示手里有可选项，与“事已至此”的意思相反。"}, {"text": "有", "is_correct": false, "explanation": "语义：“有选择”说明还有出路，与句中“事已至此”的无路可走相矛盾。"}], "explanations": {"别无": "别无：表示除此之外没有别的，与“事已至此”所说的无路可走相符。", "放弃": "语义：“放弃选择”是主动舍弃，与“事已至此”只能接受的处境不符。", "拥有": "语义：“拥有选择”表示手里有可选项，与“事已至此”的意思相反。", "有": "语义：“有选择”说明还有出路，与句中“事已至此”的无路可走相矛盾。"}, "sentence_index": 0, "correct_answer": "别无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈别无做饭，每天都在外面吃。", "explanation": "这里应该用〈没有〉。“别无”后面接名词性成分，不能直接接动词短语；说妈妈没有做饭，应用〈没有〉。"}, {"text": "这间屋子的灯别无亮。", "explanation": "这里应该用〈很〉。“别无”后面接名词性成分，不能直接修饰形容词；说灯很亮，应用〈很〉。"}, {"text": "这个班别无三名女生。", "explanation": "这里应该用〈只有〉。“别无”表示除此之外没有别的，不用来限定班里的人数；说班里仅有三名女生，应用〈只有〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "别无", "is_correct": true, "explanation": "别无：表示除此之外没有其他办法，与“只能开窗”相符。"}, {"text": "另有", "is_correct": false, "explanation": "语义：“另有他法”说明还有别的办法，与后面的“只能开窗”矛盾。"}, {"text": "找到", "is_correct": false, "explanation": "语义：“找到他法”意味着已经有了出路，与“只能开窗”矛盾。"}, {"text": "想出", "is_correct": false, "explanation": "语义：“想出他法”说明还有别的办法，与“只能开窗”矛盾。"}], "explanations": {"别无": "别无：表示除此之外没有其他办法，与“只能开窗”相符。", "另有": "语义：“另有他法”说明还有别的办法，与后面的“只能开窗”矛盾。", "找到": "语义：“找到他法”意味着已经有了出路，与“只能开窗”矛盾。", "想出": "语义：“想出他法”说明还有别的办法，与“只能开窗”矛盾。"}, "sentence_index": 6, "correct_answer": "别无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训别无两名老师。", "explanation": "这里应该用〈只有〉。“别无”表示除此之外没有别的，不用来限定人数；说培训仅有两名老师，应用〈只有〉。"}, {"text": "他每天别无早起，所以总是迟到。", "explanation": "这里应该用〈没有〉。“别无”后面接名词性成分，不能直接接动词短语；说他每天没有早起，应用〈没有〉。"}, {"text": "这个村子的路别无远。", "explanation": "这里应该用〈很〉。“别无”后面接名词性成分，不能直接修饰形容词；说村子的路很远，应用〈很〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电脑坏了，我们别无的选择，只能送去修。", "corrected_sentence": "电脑坏了，我们别无选择，只能送去修。", "error_description": "“别无”是固定的词语，后面不能加“的”；应说“别无选择”，不说“别无的选择”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门锁着，我们别无了选择，只能在外面等。", "corrected_sentence": "门锁着，我们别无选择，只能在外面等。", "error_description": "“别无”是固定的词语，中间不能加“了”；应说“别无选择”，不说“别无了选择”。错句中的“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安定", "is_correct": true, "explanation": "“安定”与“动荡”构成反义，指生活或局势稳定、不变动。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”与“动荡”无反义关系，指心里愉快。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“动荡”无反义关系，指明白、分明。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”与“动荡”无反义关系，指排列有序。"}], "correct_answer": "安定", "explanations": {"安定": "“安定”与“动荡”构成反义，指生活或局势稳定、不变动。", "高兴": "“高兴”与“动荡”无反义关系，指心里愉快。", "清楚": "“清楚”与“动荡”无反义关系，指明白、分明。", "整齐": "“整齐”与“动荡”无反义关系，指排列有序。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稳定", "is_correct": true, "explanation": "“稳定”与“动荡”构成反义，指不变动、安稳。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”与“动荡”无反义关系，指场面繁华、人多声杂。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”与“动荡”无反义关系，指清楚分明。"}, {"text": "笔直", "is_correct": false, "explanation": "“笔直”与“动荡”无反义关系，指不弯曲。"}], "correct_answer": "稳定", "explanations": {"稳定": "“稳定”与“动荡”构成反义，指不变动、安稳。", "热闹": "“热闹”与“动荡”无反义关系，指场面繁华、人多声杂。", "清晰": "“清晰”与“动荡”无反义关系，指清楚分明。", "笔直": "“笔直”与“动荡”无反义关系，指不弯曲。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一会儿这样，一会儿那样，不安定。", "primary_collocate": null, "pronunciation": "dòng dàng", "ipa": "tʊŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的生活很动荡，一会儿在北京，一会儿在上海。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年我换了好几份工作，生活很动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段时间他到处找工作，日子过得很动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活很动荡，搬了好几次家，很难好好睡觉。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的心情动荡，一会儿笑，一会儿哭。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种动荡的生活让孩子很不安。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过着动荡的日子，没有一个家。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常搬家，生活太动荡了，我想安定下来。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的生活一直很动荡，今天在这儿，明天在那儿。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时过得很动荡，现在才安静下来。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动荡不安", "label": "复合"}], "register": "中性", "sense_fingerprint": "变来变去、不安定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指生活不安定、一会儿这样一会儿那样，与“一会儿在北京，一会儿在上海”相符。"}, {"text": "稳定", "is_correct": false, "explanation": "语义：“稳定”指不变动，与“一会儿在北京，一会儿在上海”矛盾。"}, {"text": "规律", "is_correct": false, "explanation": "语义：“规律”指有常规、不乱变，与一会儿换城市的说法矛盾。"}, {"text": "静止", "is_correct": false, "explanation": "搭配：“静止”多用于物体不动，不用来形容人的生活。"}], "explanations": {"动荡": "正确：动荡指生活不安定、一会儿这样一会儿那样，与“一会儿在北京，一会儿在上海”相符。", "稳定": "语义：“稳定”指不变动，与“一会儿在北京，一会儿在上海”矛盾。", "规律": "语义：“规律”指有常规、不乱变，与一会儿换城市的说法矛盾。", "静止": "搭配：“静止”多用于物体不动，不用来形容人的生活。"}, "sentence_index": 0, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很动荡，大家都说好吃。", "explanation": "这里应该用〈好吃〉。动荡形容生活或心情不安定、变来变去，菜的味道好要用好吃。"}, {"text": "房间很动荡，我找不到钥匙。", "explanation": "这里应该用〈乱〉。动荡形容生活或局势不安定、变来变去，形容房间杂乱要用乱。"}, {"text": "他的字写得很动荡，老师看不懂。", "explanation": "这里应该用〈潦草〉。动荡形容生活或心情不安定，字写得不工整要用潦草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡修饰“日子”，指生活不安定，与“没有一个家”相符。"}, {"text": "安定", "is_correct": false, "explanation": "语义：“安定”指生活平稳、有固定居所，与“没有一个家”矛盾。"}, {"text": "美满", "is_correct": false, "explanation": "语义：「美满」指生活圆满、家庭幸福，与「没有一个家」矛盾。"}, {"text": "温馨", "is_correct": false, "explanation": "语义：“温馨”指家庭的温暖氛围，与“没有一个家”矛盾。"}], "explanations": {"动荡": "正确：动荡修饰“日子”，指生活不安定，与“没有一个家”相符。", "安定": "语义：“安定”指生活平稳、有固定居所，与“没有一个家”矛盾。", "美满": "语义：「美满」指生活圆满、家庭幸福，与「没有一个家」矛盾。", "温馨": "语义：“温馨”指家庭的温暖氛围，与“没有一个家”矛盾。"}, "sentence_index": 6, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "教室里很动荡，老师说话都听不清。", "explanation": "这里应该用〈嘈杂〉。动荡指生活、局势、心情不安定，教室里声音吵闹要用嘈杂。"}, {"text": "妈妈把厨房收拾得很动荡。", "explanation": "这里应该用〈干净〉。动荡不用于形容整洁，厨房收拾得整齐干净要用干净。"}, {"text": "这块蛋糕很动荡，孩子们都爱吃。", "explanation": "这里应该用〈甜〉。动荡形容生活、局势、心情不安定，食物的味道要用甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那段时间他的工作很动荡地，老是换单位。", "corrected_sentence": "那段时间他的工作很动荡，老是换单位。", "error_description": "“动荡”作谓语时后面不加“地”，「很动荡地」错误，应为「很动荡」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97165, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他童年过着动荡地日子，常常转学。", "corrected_sentence": "他童年过着动荡的日子，常常转学。", "error_description": "“动荡”修饰名词“日子”，应用“的”，不用“地”（“地”多用于动词前）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稳定", "is_correct": true, "explanation": "“稳定”与“动荡”构成反义，指局势或社会安稳、不变动。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”与“动荡”无反义关系，指事情多、忙碌。"}, {"text": "狭窄", "is_correct": false, "explanation": "“狭窄”与“动荡”无反义关系，指空间不宽。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”与“动荡”无反义关系，指清楚分明。"}], "correct_answer": "稳定", "explanations": {"稳定": "“稳定”与“动荡”构成反义，指局势或社会安稳、不变动。", "繁忙": "“繁忙”与“动荡”无反义关系，指事情多、忙碌。", "狭窄": "“狭窄”与“动荡”无反义关系，指空间不宽。", "清晰": "“清晰”与“动荡”无反义关系，指清楚分明。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安定", "is_correct": true, "explanation": "“安定”与“动荡”构成反义，指社会平安稳定。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”与“动荡”无反义关系，指待人友好。"}, {"text": "厚实", "is_correct": false, "explanation": "“厚实”与“动荡”无反义关系，指厚而结实。"}, {"text": "轻盈", "is_correct": false, "explanation": "“轻盈”与“动荡”无反义关系，指轻快灵巧。"}], "correct_answer": "安定", "explanations": {"安定": "“安定”与“动荡”构成反义，指社会平安稳定。", "热情": "“热情”与“动荡”无反义关系，指待人友好。", "厚实": "“厚实”与“动荡”无反义关系，指厚而结实。", "轻盈": "“轻盈”与“动荡”无反义关系，指轻快灵巧。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "社会、局势不稳定，变化不定。", "primary_collocate": null, "pronunciation": "dòng dàng", "ipa": "tʊŋ˥˩ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那个国家的局势很动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动荡的年代里，人们过得很辛苦。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年市场很动荡，生意不好做。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个地方变得动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会动荡时，很多人想离开家。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生在一个动荡的时代。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说那里的局势越来越动荡。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济动荡，很多工厂关门了。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城市曾经很动荡，现在安全多了。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动荡的局面让商人不敢投资。", "target_word": "动荡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动荡不安", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会或局势不稳定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指社会或局势不稳定，与“那个国家的局势”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或街市，不用来形容局势。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容局势。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：“甜蜜”指感情愉快，与局势不稳定的意思矛盾。"}], "explanations": {"动荡": "正确：动荡指社会或局势不稳定，与“那个国家的局势”相符。", "热闹": "搭配：“热闹”形容场面或街市，不用来形容局势。", "清脆": "搭配：“清脆”形容声音，不能用来形容局势。", "甜蜜": "语义：“甜蜜”指感情愉快，与局势不稳定的意思矛盾。"}, "sentence_index": 0, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花的颜色很动荡。", "explanation": "这里应该用〈鲜艳〉。动荡指社会、局势不稳定，花朵颜色明亮要用鲜艳。"}, {"text": "这座桥的结构动荡，车不能过。", "explanation": "这里应该用〈不稳定〉。动荡多用于社会、局势、生活，桥梁结构的稳固程度要用不稳定。"}, {"text": "书架上的东西很动荡，找不到书。", "explanation": "这里应该用〈杂乱〉。动荡不用于摆放的东西，东西摆放无序要用杂乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动荡", "is_correct": true, "explanation": "正确：动荡指社会局势不稳定，与“新闻说那里的局势越来越”相符。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”多形容场所或时节，不用来形容局势。"}, {"text": "辛辣", "is_correct": false, "explanation": "语义：“辛辣”指味道刺激，与局势无关。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指快乐，与“越来越”形容的局势变化矛盾。"}], "explanations": {"动荡": "正确：动荡指社会局势不稳定，与“新闻说那里的局势越来越”相符。", "冷清": "搭配：“冷清”多形容场所或时节，不用来形容局势。", "辛辣": "语义：“辛辣”指味道刺激，与局势无关。", "欢乐": "语义：“欢乐”指快乐，与“越来越”形容的局势变化矛盾。"}, "sentence_index": 6, "correct_answer": "动荡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服很动荡，店员说只要三十块。", "explanation": "这里应该用〈便宜〉。动荡指社会、局势不稳定，价格低要用便宜。"}, {"text": "这个问题很动荡，老师讲了半天也没人懂。", "explanation": "这里应该用〈清楚〉。动荡指不安定、变来变去，道理明白要用清楚。"}, {"text": "图书馆里很动荡，同学们都在看书。", "explanation": "这里应该用〈安静〉。动荡指社会、局势不稳，环境清静无声要用安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个地区的局势很动荡地，很多人都搬走了。", "corrected_sentence": "那个地区的局势很动荡，很多人都搬走了。", "error_description": "“动荡”作谓语时后面不加“地”，「很动荡地」错误，应为「很动荡」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那是一个动荡地年代，人们都很辛苦。", "corrected_sentence": "那是一个动荡的年代，人们都很辛苦。", "error_description": "“动荡”修饰名词“年代”，应用“的”，不用“地”（“地”多用于动词前）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
