INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97169, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把东西包好，里面有东西要寄给别人。", "primary_collocate": null, "pronunciation": "bāo guǒ", "ipa": "pɑʊ˥ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我今天收到了一个包裹。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包裹是从北京寄来的。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把包裹放在门口的桌子上。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我寄了一个大包裹。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "包裹里有几本书和一件毛衣。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去邮局取包裹了。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包裹太重，我拿不动。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的包裹已经到了，快来拿吧。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天寄的包裹，明天就能到。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邮局的人说，包裹一周后到。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "邮政包裹", "label": "复合"}], "register": "中性", "sense_fingerprint": "寄给别人的包好的邮件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "包裹", "is_correct": true, "explanation": "包裹 bāo guǒ，指包好、要寄给别人的东西。"}, {"text": "包过", "is_correct": false, "explanation": "「过」为第四声，与「裹」（第三声）声调不同，意思是包过（保证通过）。"}, {"text": "保过", "is_correct": false, "explanation": "「保」和「过」的声调都与目标词不同，意思是保证通过。"}, {"text": "报过", "is_correct": false, "explanation": "「报」为第四声，与「包」（第一声）声调不同，意思是报过（已经报告）。"}, {"text": "抛过", "is_correct": false, "explanation": "「抛」pāo 与「包」bāo 声母不同（p 与 b），「过」guò 与「裹」guǒ 声调也不同，意思是扔过。"}], "explanations": {"包裹": "包裹 bāo guǒ，指包好、要寄给别人的东西。", "包过": "「过」为第四声，与「裹」（第三声）声调不同，意思是包过（保证通过）。", "保过": "「保」和「过」的声调都与目标词不同，意思是保证通过。", "报过": "「报」为第四声，与「包」（第一声）声调不同，意思是报过（已经报告）。", "抛过": "「抛」pāo 与「包」bāo 声母不同（p 与 b），「过」guò 与「裹」guǒ 声调也不同，意思是扔过。"}, "sentence_index": null, "correct_answer": "包裹"}, "level_3": {"options": [{"text": "包裹", "is_correct": true, "explanation": "正确：「收到」后面接的是寄来、包好的东西。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：「夏天」是季节，不能被「收到」，「收到了一个夏天」荒谬。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能被寄来或收到，「收到了一个月亮」荒谬。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不能被寄来或送来，「收到了一个大象」荒谬。"}], "explanations": {"包裹": "正确：「收到」后面接的是寄来、包好的东西。", "夏天": "语义：「夏天」是季节，不能被「收到」，「收到了一个夏天」荒谬。", "月亮": "语义：月亮不能被寄来或收到，「收到了一个月亮」荒谬。", "大象": "语义：大象不能被寄来或送来，「收到了一个大象」荒谬。"}, "sentence_index": 0, "correct_answer": "包裹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个包裹写了三页，内容很长。", "explanation": "这里应该用〈信〉。写内容、写页数的是信件；包裹是寄送的包好的物品，不能这样说。"}, {"text": "这次出国，我的包裹只有一个箱子。", "explanation": "这里应该用〈行李〉。包裹指寄送或收到的包好的东西，出国随身带的东西要说〈行李〉。"}, {"text": "这个包裹金额很大，要下个月付清。", "explanation": "这里应该用〈账单〉。金额和付款期限是账单的内容；包裹是寄送的物品，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包裹", "is_correct": true, "explanation": "正确：「太重，拿不动」描述的是包好的东西，符合包裹。"}, {"text": "羽毛", "is_correct": false, "explanation": "语义：羽毛很轻，与「太重，拿不动」矛盾。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子没有重量，「拿不动」说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「空气」不可数，不能用「个」计量，也不能被拿起。"}], "explanations": {"包裹": "正确：「太重，拿不动」描述的是包好的东西，符合包裹。", "羽毛": "语义：羽毛很轻，与「太重，拿不动」矛盾。", "影子": "语义：影子没有重量，「拿不动」说不通。", "空气": "搭配：「空气」不可数，不能用「个」计量，也不能被拿起。"}, "sentence_index": 6, "correct_answer": "包裹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天发来一个包裹，主题是下周开会。", "explanation": "这里应该用〈邮件〉。邮件有主题；包裹是包好的实物，没有主题，不能这样说。"}, {"text": "他昨晚写完了包裹，交给了老师。", "explanation": "这里应该用〈作业〉。写完、交给老师的是作业；包裹是包好的物品，不能写。"}, {"text": "这个包裹读起来很感人。", "explanation": "这里应该用〈故事〉。能读、能让人感动的是故事；包裹是包好的物品，不能这样读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天寄了一本包裹给朋友。", "corrected_sentence": "我昨天寄了一个包裹给朋友。", "error_description": "「包裹」的量词应为「个」或「件」，「本」多用于书籍，不能用来数包裹。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下午送来了一条包裹。", "corrected_sentence": "他下午送来了一个包裹。", "error_description": "「包裹」的量词应为「个」或「件」，「条」多用于长条形的东西，不能用来数包裹。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
