INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布、纸等包扎好的一包东西。", "primary_collocate": null, "pronunciation": "bāo guǒ", "ipa": "pɑʊ˥ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他背着一个大包裹走进了村子。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开包裹，里面是一件旧衣服。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一个用蓝布包好的包裹。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把包裹放在腿上，一直没松手。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩抱着包裹，不愿意放下。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边有一个没人要的包裹。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把所有的衣服都装进了一个包裹。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包裹是用红布扎起来的。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车上，她紧紧抱着自己的包裹。", "target_word": "包裹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他肩上的包裹看起来很重。", "target_word": "包裹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "小包裹", "label": "复合"}], "register": "中性", "sense_fingerprint": "用布纸等包扎好的一包东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97170, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "包裹", "is_correct": true, "explanation": "包裹 bāo guǒ，指用布纸等包好的一包东西。"}, {"text": "包过", "is_correct": false, "explanation": "「过」为第四声，与「裹」（第三声）声调不同，意思是包过（保证通过）。"}, {"text": "保过", "is_correct": false, "explanation": "「保」和「过」的声调都与目标词不同，意思是保证通过。"}, {"text": "报过", "is_correct": false, "explanation": "「报」为第四声，与「包」（第一声）声调不同，意思是报过（已经报告）。"}, {"text": "抛过", "is_correct": false, "explanation": "「抛」pāo 与「包」bāo 声母不同（p 与 b），「过」guò 与「裹」guǒ 声调也不同，意思是扔过。"}], "explanations": {"包裹": "包裹 bāo guǒ，指用布纸等包好的一包东西。", "包过": "「过」为第四声，与「裹」（第三声）声调不同，意思是包过（保证通过）。", "保过": "「保」和「过」的声调都与目标词不同，意思是保证通过。", "报过": "「报」为第四声，与「包」（第一声）声调不同，意思是报过（已经报告）。", "抛过": "「抛」pāo 与「包」bāo 声母不同（p 与 b），「过」guò 与「裹」guǒ 声调也不同，意思是扔过。"}, "sentence_index": null, "correct_answer": "包裹"}, "level_3": {"options": [{"text": "包裹", "is_correct": true, "explanation": "正确：「背着一个大……走进村子」指随身背的一包东西。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被人背着走进村子。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵飘在天上，不能被背着走进村子。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「空气」不可数，不用「个」计量，也不能背。"}], "explanations": {"包裹": "正确：「背着一个大……走进村子」指随身背的一包东西。", "房子": "语义：房子不能被人背着走进村子。", "云朵": "语义：云朵飘在天上，不能被背着走进村子。", "空气": "搭配：「空气」不可数，不用「个」计量，也不能背。"}, "sentence_index": 0, "correct_answer": "包裹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个包裹的主题是下周开会。", "explanation": "这里应该用〈邮件〉。邮件才有主题；包裹是包好的实物，没有主题，不能这样说。"}, {"text": "这个包裹的金额很大，下个月要付清。", "explanation": "这里应该用〈账单〉。账单才有金额和付款期限；包裹是包好的物品，不能这样说。"}, {"text": "这个包裹听起来很好听。", "explanation": "这里应该用〈歌曲〉。能听、好听的是歌曲；包裹是包好的物品，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包裹", "is_correct": true, "explanation": "正确：「把所有的衣服都装进了一个……」指可以装东西的包好的一包。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能用来装衣服。"}, {"text": "树", "is_correct": false, "explanation": "搭配：「树」应用「棵」计量，「一个树」不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能被装进任何东西里。"}], "explanations": {"包裹": "正确：「把所有的衣服都装进了一个……」指可以装东西的包好的一包。", "窗户": "语义：窗户不能用来装衣服。", "树": "搭配：「树」应用「棵」计量，「一个树」不成立。", "太阳": "语义：太阳不能被装进任何东西里。"}, "sentence_index": 6, "correct_answer": "包裹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他昨天写完了包裹，交给了老师。", "explanation": "这里应该用〈作业〉。写完、交给老师的是作业；包裹是包好的物品，不能写。"}, {"text": "这个包裹是他去年拍的，看起来很清楚。", "explanation": "这里应该用〈照片〉。拍的、看起来清楚的是照片；包裹是包好的物品，不能这样说。"}, {"text": "这个包裹有三十页，他花了一年写完。", "explanation": "这里应该用〈论文〉。有页数、要花时间写完的是论文；包裹是包好的物品，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她背着一本大包裹走过了桥。", "corrected_sentence": "她背着一个大包裹走过了桥。", "error_description": "「包裹」的量词应为「个」或「件」，「本」多用于书籍，不能用来数包裹。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
