INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97173, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "请你再去另外一个地方看一看。", "primary_collocate": null, "pronunciation": "cān jiàn", "ipa": "tsʰan˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "详细的做法，请参见第五页的说明。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想知道更多的内容，请参见本书最后一章。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词的用法很多，请参见下面的例句。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于地图的画法，请参见附录里的图表。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表格里的数字有疑问时，请参见第二部分的注释。", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格的问题，请参见网页最下面的说明。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "安装方法太长，这里不写，请参见产品说明书。", "target_word": "参见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图片的来源，请参见书后的名单。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "具体的时间安排，请参见公司的通知。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些规定的意思，请参见法律书里的解释。", "target_word": "参见", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "參見", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "请读者去另一处查看相关内容（指引）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参见", "is_correct": true, "explanation": "正确：“参见”表示请读者去另一处查看相关内容，这里指向第五页的说明。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说“吃第五页的说明”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、器物，不能说“修理说明”。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”表示扯开纸张，与请读者去查看说明的意思不符。"}], "explanations": {"参见": "正确：“参见”表示请读者去另一处查看相关内容，这里指向第五页的说明。", "吃": "语义：“吃”的对象是食物，不能说“吃第五页的说明”。", "修理": "搭配：“修理”的对象是机器、器物，不能说“修理说明”。", "撕": "语义：“撕”表示扯开纸张，与请读者去查看说明的意思不符。"}, "sentence_index": 0, "correct_answer": "参见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去博物馆参见了古画。", "explanation": "这里应该用〈参观〉。“参见”是请读者去查阅文中别处内容，去博物馆看展品要用〈参观〉。"}, {"text": "我在书店里参见了很多新书。", "explanation": "这里应该用〈翻阅〉。“参见”指请读者去看文中另一处，随手翻看书刊要用〈翻阅〉。"}, {"text": "我们下午去参见了开幕式。", "explanation": "这里应该用〈参加〉。“参见”指请读者去查看文中别处，不表示到场参与活动，参加开幕式要用〈参加〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参见", "is_correct": true, "explanation": "正确：“参见”指请读者去查看产品说明书，这里表示安装方法请查阅说明书。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，不能说“喝产品说明书”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”用于歌曲、戏曲，与说明书无关。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、器皿，纸质说明书不能洗。"}], "explanations": {"参见": "正确：“参见”指请读者去查看产品说明书，这里表示安装方法请查阅说明书。", "喝": "语义：“喝”的对象是液体，不能说“喝产品说明书”。", "唱": "语义：“唱”用于歌曲、戏曲，与说明书无关。", "洗": "搭配：“洗”的对象是衣物、器皿，纸质说明书不能洗。"}, "sentence_index": 6, "correct_answer": "参见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每周都参见篮球训练。", "explanation": "这里应该用〈参加〉。“参见”不表示参与活动，参加训练要用〈参加〉。"}, {"text": "我去图书馆参见了资料。", "explanation": "这里应该用〈查阅〉。“参见”只指引读者去看文中另一处，去图书馆查资料要用〈查阅〉。"}, {"text": "他没有参见这次会议。", "explanation": "这里应该用〈出席〉。“参见”不表示到场，去会议现场要用〈出席〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "如果想了解更多，请参见了第四章的讨论。", "corrected_sentence": "如果想了解更多，请参见第四章的讨论。", "error_description": "“参见”是祈使指引，后面不能加“了”。应说“请参见第四章的讨论”；加“了”表示动作已完成，与请人查阅的语气矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "想知道具体价格，请参见过网页最下面的表格。", "corrected_sentence": "想知道具体价格，请参见网页最下面的表格。", "error_description": "“参见”用于请人查阅的祈使句，后面不加“过”。应说“请参见网页最下面的表格”；“参见过”表示已经查阅过，与请人去查的指引不合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
