INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97177, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以前得到过，或者经历过。", "primary_collocate": null, "pronunciation": "shòu guò", "ipa": "ʂoʊ˥˩ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "她受过很好的教育。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候受过一次伤。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师受过专业训练。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在国外受过三年教育。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗受过特别的训练。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以前受过这样的帮助吗？", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都受过他的照顾。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过很多苦，所以特别努力。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前受过医生的批评，现在很小心。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子受过老师的表扬。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受了", "label": "体标"}, {"form": "没受过", "label": "否定"}], "register": "中性", "sense_fingerprint": "以前得到或经历过某种待遇、教育、训练", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受过", "is_correct": true, "explanation": "正确：“受过”表示以前接受过教育，与“很好的教育”搭配，句意通顺。"}, {"text": "吃过", "is_correct": false, "explanation": "搭配：“吃”一般不与“教育”搭配，不能说“吃过教育”。"}, {"text": "穿过", "is_correct": false, "explanation": "搭配：“穿”多用于衣服等物品，不与“教育”搭配。"}, {"text": "踢过", "is_correct": false, "explanation": "搭配：“踢”不与“教育”搭配，不能说“踢过教育”。"}], "explanations": {"受过": "正确：“受过”表示以前接受过教育，与“很好的教育”搭配，句意通顺。", "吃过": "搭配：“吃”一般不与“教育”搭配，不能说“吃过教育”。", "穿过": "搭配：“穿”多用于衣服等物品，不与“教育”搭配。", "踢过": "搭配：“踢”不与“教育”搭配，不能说“踢过教育”。"}, "sentence_index": 0, "correct_answer": "受过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候受过一封信。", "explanation": "这里应该用〈收过〉。收过可以指接到信件、东西；受过用于遭受、经历或接受待遇、教育，不能说“受过一封信”。"}, {"text": "他受过一个好成绩。", "explanation": "这里应该用〈取得过〉。取得可以跟成绩、成果搭配；受过不能以“成绩”作宾语。"}, {"text": "我们受过一次比赛。", "explanation": "这里应该用〈参加过〉。参加可以跟比赛、活动搭配；受过不能以“比赛”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受过", "is_correct": true, "explanation": "正确：“受过”表示曾经接受过他的照顾，句意通顺。"}, {"text": "挨过", "is_correct": false, "explanation": "语义：“挨”多指遭受不好的事，与“照顾”的好意相矛盾。"}, {"text": "偷过", "is_correct": false, "explanation": "语义：“偷”表示窃取，与“照顾”的意思不合。"}, {"text": "摸过", "is_correct": false, "explanation": "搭配：“摸”不与“照顾”搭配，不能说“摸过他的照顾”。"}], "explanations": {"受过": "正确：“受过”表示曾经接受过他的照顾，句意通顺。", "挨过": "语义：“挨”多指遭受不好的事，与“照顾”的好意相矛盾。", "偷过": "语义：“偷”表示窃取，与“照顾”的意思不合。", "摸过": "搭配：“摸”不与“照顾”搭配，不能说“摸过他的照顾”。"}, "sentence_index": 6, "correct_answer": "受过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子受过全校第一名。", "explanation": "这里应该用〈获得过〉。获得可以跟名次、奖项搭配；受过是遭受或接受待遇，不能以“第一名”作宾语。"}, {"text": "这个孩子受过一枚金牌。", "explanation": "这里应该用〈拿过〉。拿过可以指得到奖牌、奖项；受过不能以“金牌”作宾语。"}, {"text": "这个孩子受过满分。", "explanation": "这里应该用〈考过〉。考过可以跟分数、成绩搭配；受过不能以“满分”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年受过一把伤。", "corrected_sentence": "他去年受过一次伤。", "error_description": "错误在量词。“把”用于有柄的器物，不能用于“伤”，应说“受过一次伤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位医生不受过严格的训练。", "corrected_sentence": "那位医生没受过严格的训练。", "error_description": "错误：“受过”的否定用错，写成“不受过”。“受过”表示经历过，否定应用“没”，正确说法是“没受过严格的训练”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
