INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97178, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "曾经受到或经历过某事。", "primary_collocate": null, "pronunciation": "shòu guò", "ipa": "ʂoʊ˥˩ kwo˥˩", "syllable_count": 2, "sentences": [{"text": "他在工作中受过不少批评。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市受过大雨的影响。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我受过他的帮助，一直记得。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李受过两次伤，现在好了。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过不少委屈。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候受过很多苦。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的人都受过战争的伤害。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你受过什么样的伤害？", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受过老师的影响，也喜欢画画。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子受过洪水的威胁。", "target_word": "受过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受了", "label": "体标"}, {"form": "没受过", "label": "否定"}], "register": "中性", "sense_fingerprint": "曾经遭遇或承受过某种影响、伤害、批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受过", "is_correct": true, "explanation": "正确：“受过”表示曾经遭受过不少批评，句意通顺。"}, {"text": "穿过", "is_correct": false, "explanation": "搭配：“穿”不与“批评”搭配，不能说“穿过批评”。"}, {"text": "跑过", "is_correct": false, "explanation": "搭配：“跑”不与“批评”搭配，不能说“跑过批评”。"}, {"text": "摸过", "is_correct": false, "explanation": "语义：“摸”指用手接触，与“批评”的意思完全不合。"}], "explanations": {"受过": "正确：“受过”表示曾经遭受过不少批评，句意通顺。", "穿过": "搭配：“穿”不与“批评”搭配，不能说“穿过批评”。", "跑过": "搭配：“跑”不与“批评”搭配，不能说“跑过批评”。", "摸过": "语义：“摸”指用手接触，与“批评”的意思完全不合。"}, "sentence_index": 0, "correct_answer": "受过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小李受过两次金奖。", "explanation": "这里应该用〈获得过〉。获得可以跟奖项、名次搭配；受过是遭受或接受待遇，不能以“金奖”作宾语。"}, {"text": "小李受过两次高分。", "explanation": "这里应该用〈考过〉。考过可以跟分数、成绩搭配；受过不能以“高分”作宾语。"}, {"text": "小李受过全班第一名。", "explanation": "这里应该用〈得过〉。得过可以跟名次、奖项搭配；受过不能以“全班第一名”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受过", "is_correct": true, "explanation": "正确：“受过”表示那里的人曾经遭受过战争的伤害，句意通顺。"}, {"text": "吃过", "is_correct": false, "explanation": "搭配：“吃”不与“伤害”搭配，不能说“吃过战争的伤害”。"}, {"text": "欣赏过", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱、赏识，不能以“战争的伤害”作对象，句意不通。"}, {"text": "享过", "is_correct": false, "explanation": "语义：“享”表示享受，与“伤害”的负面意思相矛盾。"}], "explanations": {"受过": "正确：“受过”表示那里的人曾经遭受过战争的伤害，句意通顺。", "吃过": "搭配：“吃”不与“伤害”搭配，不能说“吃过战争的伤害”。", "欣赏过": "语义：“欣赏”表示喜爱、赏识，不能以“战争的伤害”作对象，句意不通。", "享过": "语义：“享”表示享受，与“伤害”的负面意思相矛盾。"}, "sentence_index": 6, "correct_answer": "受过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子受过一次会议。", "explanation": "这里应该用〈开过〉。开可以跟会议、活动搭配；受过是遭受或接受待遇，不能以“会议”作宾语。"}, {"text": "这个村子受过两次演出。", "explanation": "这里应该用〈举办过〉。举办可以跟演出、活动搭配；受过不能以“演出”作宾语。"}, {"text": "这个村子受过一场婚礼。", "explanation": "这里应该用〈举行过〉。举行可以跟婚礼、仪式搭配；受过不能以“婚礼”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年受过三把伤。", "corrected_sentence": "他去年受过三次伤。", "error_description": "错误在量词。“把”用于有柄的器物，不能用于“伤”，应说“受过三次伤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市不受过地震的破坏。", "corrected_sentence": "这座城市没受过地震的破坏。", "error_description": "错误：“受过”的否定用错，写成“不受过”。“受过”表示曾经经历，否定应用“没”，应说“没受过地震的破坏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
