INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在差不多的那一段时间里。", "primary_collocate": null, "pronunciation": "tóng shí qī", "ipa": "tʰʊŋ˧˥ ʂʐ̩˧˥ tɕʰi˥˥", "syllable_count": 3, "sentences": [{"text": "今年的销量比去年同时期高了很多。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和三年前同时期相比，他的收入翻了一番。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季度的利润跟去年同时期差不多。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月的天气比去年同时期冷。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天的雨水比前年同时期少了一些。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这学期的成绩比去年同时期进步了不少。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和去年同时期比，这里的游客少多了。", "target_word": "同时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和五年前同时期相比，这所学校的学生多了很多。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跟去年同时期相比，今年的新员工少了两个。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上说，价格比去年同时期涨了一成。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "同时期：与某时间相比，差不多的那段时间（常与去年、他人对比）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b8aedc-5ff5-4137-89ea-9c5261b723e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97181, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同时期", "is_correct": true, "explanation": "同时期：与去年相比，差不多的那段时间，与“销量比去年……”相合。"}, {"text": "时代", "is_correct": false, "explanation": "搭配：“销量”不能与“时代”比较高低。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“比去年年代高”说不通，“年代”不是可以比较数量的时段。"}, {"text": "季节", "is_correct": false, "explanation": "语义：“季节”指一年中的一段，不能用来指与去年对应的同一阶段的数量对比。"}], "explanations": {"同时期": "同时期：与去年相比，差不多的那段时间，与“销量比去年……”相合。", "时代": "搭配：“销量”不能与“时代”比较高低。", "年代": "搭配：“比去年年代高”说不通，“年代”不是可以比较数量的时段。", "季节": "语义：“季节”指一年中的一段，不能用来指与去年对应的同一阶段的数量对比。"}, "sentence_index": 0, "correct_answer": "同时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我的同时期，我们常一起打球。", "explanation": "这里应该用〈同学〉。同时期指一段时间，不能用来指人。"}, {"text": "这家公司的同时期很大，有几千名员工。", "explanation": "这里应该用〈规模〉。同时期指一段时间，不能用来说公司的大小。"}, {"text": "我在同时期吃午饭，一边看书。", "explanation": "〈同时期〉是名词，不能表示动作同时发生；这里应该用〈同时〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时期", "is_correct": true, "explanation": "同时期：与去年那段时间相比，与“游客少多了”的比较相合。"}, {"text": "名胜", "is_correct": false, "explanation": "语义：“名胜”是景点，不是时间段，不能用来与去年比较。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”是空间概念，与“去年……比”的时间比较不合。"}, {"text": "人手", "is_correct": false, "explanation": "语义：“和去年……比”要求比较对象是时间段，“人手”不是时间，无法与“游客少了”对应。"}], "explanations": {"同时期": "同时期：与去年那段时间相比，与“游客少多了”的比较相合。", "名胜": "语义：“名胜”是景点，不是时间段，不能用来与去年比较。", "地点": "语义：“地点”是空间概念，与“去年……比”的时间比较不合。", "人手": "语义：“和去年……比”要求比较对象是时间段，“人手”不是时间，无法与“游客少了”对应。"}, "sentence_index": 6, "correct_answer": "同时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同时期我还小，什么都不懂。", "explanation": "这里应该用〈那时候〉。同时期需要有明确的比较对象，不能单独作时间状语。"}, {"text": "这件事的同时期很长，我们等了很久。", "explanation": "这里应该用〈时间〉。同时期只指相同的时段，不能用来说一件事持续的长短。"}, {"text": "他这次的同时期很好，拿了第一名。", "explanation": "这里应该用〈成绩〉。同时期指一段时间，不能用来评价表现的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的收入去年同时期多了不少。", "corrected_sentence": "今年的收入比去年同时期多了不少。", "error_description": "“比”漏掉：比较对象前要用“比”，应说“比去年同时期”，不能省去“比”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的销量比去年同时期很高。", "corrected_sentence": "今年的销量比去年同时期高。", "error_description": "程度副词误用：比字句中形容词前不能加“很”，应说“比去年同时期高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
