INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一时期；在相同的时间阶段。", "primary_collocate": null, "pronunciation": "tóng shí qī", "ipa": "tʰʊŋ˧˥ ʂʐ̩˧˥ tɕʰi˥˥", "syllable_count": 3, "sentences": [{"text": "这两座古塔建于同时期。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同时期的两位诗人互相认识。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆里放着同时期的瓷器。", "target_word": "同时期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们比较同时期的两种文化。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "李白和杜甫是同时期的诗人。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些都是同时期的老房子，样子差不多。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同时期的电影里，这一部最有名。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们读的是同时期的两篇文章。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那几位科学家生活在同时期，常常通信。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服和那件是同时期的流行款式。", "target_word": "同时期", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "同时期：属于同一个历史或时间阶段（常修饰人物、作品、事物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63b8aedc-5ff5-4137-89ea-9c5261b723e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同时期", "is_correct": true, "explanation": "同时期：属于同一个时间阶段，与“建于”相合。"}, {"text": "年份", "is_correct": false, "explanation": "语义：“建于年份”说不通，“年份”不指具体的历史阶段。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“建于”后接时间，不能接表示地点的“地点”。"}, {"text": "材料", "is_correct": false, "explanation": "搭配：“建于”只接时间，不能说“建于材料”。"}], "explanations": {"同时期": "同时期：属于同一个时间阶段，与“建于”相合。", "年份": "语义：“建于年份”说不通，“年份”不指具体的历史阶段。", "地点": "语义：“建于”后接时间，不能接表示地点的“地点”。", "材料": "搭配：“建于”只接时间，不能说“建于材料”。"}, "sentence_index": 0, "correct_answer": "同时期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的同时期都已经毕业了。", "explanation": "这里应该用〈同学〉。同时期指一段时间，不能用来指同班的人。"}, {"text": "这座城市的同时期很干净，游客也多。", "explanation": "这里应该用〈环境〉。同时期指一段时间，不能用来描述城市的卫生状况。"}, {"text": "两个人的同时期一起出发了。", "explanation": "这里应该用〈同时〉。同时期指时段，不能表示两人同一时刻出发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时期", "is_correct": true, "explanation": "同时期：指同一时期的电影，与“同时期的电影里”相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格的电影”说不通，“价格”不指电影所属的时期。"}, {"text": "剧本", "is_correct": false, "explanation": "搭配：“剧本的电影”不能作定语修饰“电影”表示时期。"}, {"text": "票价", "is_correct": false, "explanation": "语义：“票价”是门票的价格，与电影所属的时期无关，句意不通。"}], "explanations": {"同时期": "同时期：指同一时期的电影，与“同时期的电影里”相合。", "价格": "语义：“价格的电影”说不通，“价格”不指电影所属的时期。", "剧本": "搭配：“剧本的电影”不能作定语修饰“电影”表示时期。", "票价": "语义：“票价”是门票的价格，与电影所属的时期无关，句意不通。"}, "sentence_index": 6, "correct_answer": "同时期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆的同时期很好吃。", "explanation": "这里应该用〈菜〉。同时期指一个时间阶段，不能用“好吃”形容。"}, {"text": "他把同时期放进了书包。", "explanation": "这里应该用〈课本〉。同时期是时间阶段，不是能放进书包的东西。"}, {"text": "我们几个人的同时期都很用功。", "explanation": "这里应该用〈同学〉。同时期指一段时间，不能用来指一群人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件瓷器是同时期烧制。", "corrected_sentence": "这两件瓷器是同时期烧制的。", "error_description": "“的”遗漏：“是……的”强调结构中，“的”不能省，应说“是同时期烧制的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两位作家是同时期，关系很好。", "corrected_sentence": "这两位作家是同时期的人，关系很好。", "error_description": "“同时期”是时段，不能直接当作“人”来用；修饰“人”或作判断词时要说“同时期的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a00aa39e-fd20-4302-8758-7dae4caec72e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
