INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97185, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人在群体中的高低位置。", "primary_collocate": null, "pronunciation": "míng wèi", "ipa": "miŋ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "在这个家族里，他的名位很高。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在家族里，他的名位比哥哥低。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司的名位比我高一些。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人按名位的高低安排了座位。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那个村子里，他的名位最高。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个团队里没有名位高低之分。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来，大家还不清楚他的名位。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里开会，大家都按名位排座次。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老同学中间，她的名位并不高。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时朋友之间不分名位。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人在群体中的高低位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97185, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。名位指一个人在群体中的高低位置。"}, {"text": "名为", "is_correct": false, "explanation": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。"}, {"text": "零位", "is_correct": false, "explanation": "líng wèi（零位）与 míng wèi 的声母不同（l 与 m），声调相同，意思是零的位置。"}, {"text": "灵位", "is_correct": false, "explanation": "líng wèi（灵位）与 míng wèi 的声母不同（l 与 m），意思是供奉死者的牌位。"}], "explanations": {"名位": "正确答案。名位指一个人在群体中的高低位置。", "名为": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。", "零位": "líng wèi（零位）与 míng wèi 的声母不同（l 与 m），声调相同，意思是零的位置。", "灵位": "líng wèi（灵位）与 míng wèi 的声母不同（l 与 m），意思是供奉死者的牌位。"}, "sentence_index": null, "correct_answer": "名位"}, "level_3": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。名位指人在群体中的排位，与“很高”搭配，符合句意。"}, {"text": "家规", "is_correct": false, "explanation": "语义：“家规”是家里的规定，不能用“很高”来形容。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说大小、好坏，不说“很高”。"}, {"text": "家业", "is_correct": false, "explanation": "搭配：“家业”说大小、多少，不用“很高”来形容。"}], "explanations": {"名位": "正确答案。名位指人在群体中的排位，与“很高”搭配，符合句意。", "家规": "语义：“家规”是家里的规定，不能用“很高”来形容。", "脾气": "搭配：“脾气”说大小、好坏，不说“很高”。", "家业": "搭配：“家业”说大小、多少，不用“很高”来形容。"}, "sentence_index": 0, "correct_answer": "名位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的名位就在靠窗的那张桌子旁边。", "explanation": "这里应该用〈位置〉。名位指人在群体中的高低排位，不指具体的座位或场所。"}, {"text": "他有一只名位，大家都很羡慕。", "explanation": "这里应该用〈个〉。名位是抽象名词，不能用“只”（多用于动物或小件物品）来数。"}, {"text": "我每天早上都给名位浇水。", "explanation": "这里应该用〈植物〉。名位是抽象的排位，不能浇水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97185, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。名位指一个人在群体中的高低位置。"}, {"text": "明媚", "is_correct": false, "explanation": "míng mèi（明媚）与 míng wèi 只差第二音节声母（m 与 w），意思是明亮秀丽。"}, {"text": "民委", "is_correct": false, "explanation": "mín wěi（民委）与 míng wèi 读音相近：第一音节 -n 与 -ng 不同，第二音节声调不同（第三声与第四声），意思是民族事务委员会。"}, {"text": "领位", "is_correct": false, "explanation": "lǐng wèi（领位）与 míng wèi 的声母不同（l 与 m），第一音节声调不同（第三声与第二声），意思是引导客人入座。"}], "explanations": {"名位": "正确答案。名位指一个人在群体中的高低位置。", "明媚": "míng mèi（明媚）与 míng wèi 只差第二音节声母（m 与 w），意思是明亮秀丽。", "民委": "mín wěi（民委）与 míng wèi 读音相近：第一音节 -n 与 -ng 不同，第二音节声调不同（第三声与第四声），意思是民族事务委员会。", "领位": "lǐng wèi（领位）与 míng wèi 的声母不同（l 与 m），第一音节声调不同（第三声与第二声），意思是引导客人入座。"}, "sentence_index": null, "correct_answer": "名位"}, "level_3": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。“大家还不清楚他的名位”指不了解他在群体中的排位，符合句意。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“清楚”说的是情况、身份，不说“脚印”。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“清楚”不用于“香味”这类气味。"}, {"text": "回声", "is_correct": false, "explanation": "语义：回声是声音的反射，不是可以“不清楚”的对象。"}], "explanations": {"名位": "正确答案。“大家还不清楚他的名位”指不了解他在群体中的排位，符合句意。", "脚印": "搭配：“清楚”说的是情况、身份，不说“脚印”。", "香味": "搭配：“清楚”不用于“香味”这类气味。", "回声": "语义：回声是声音的反射，不是可以“不清楚”的对象。"}, "sentence_index": 6, "correct_answer": "名位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班上有一本名位，大家都很羡慕。", "explanation": "这里应该用〈个〉。名位是抽象的，不能用“本”（书册用）来数。"}, {"text": "老师把他的名位安排在最后一排。", "explanation": "这里应该用〈座位〉。“安排”的是具体座位，名位指人在群体中的排位，不能这样安排。"}, {"text": "他把名位放进了行李箱。", "explanation": "这里应该用〈物品〉。名位是抽象的排位，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在学校里，他的名位很多，大家都很尊敬他。", "corrected_sentence": "在学校里，他的名位很高，大家都很尊敬他。", "error_description": "“名位”后的形容词用错。说人的地位高低要用“高”，“多”用于数量，“名位很多”不成立，应改为“名位很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在公司里有一只很高的名位。", "corrected_sentence": "他在公司里有一个很高的名位。", "error_description": "量词用错。名位是抽象名词，应该用“个”，“只”不能修饰名位，应改为“一个很高的名位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
