INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97186, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名誉和地位。", "primary_collocate": null, "pronunciation": "míng wèi", "ipa": "miŋ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他一生不追求名位，只想做好工作。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了名位，他得罪了很多朋友。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了名位以后，他变得很忙。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不贪图名位，过着简单的生活。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人为名位忙了一辈子。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名位对他来说并不重要。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了名位，回到了家乡。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不要只想着名位和钱。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师从来不争名位。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名位会让人忘了最初的想法。", "target_word": "名位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名誉和社会地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdf1dcf0-7984-4ff9-bdd1-b3a9f761ebb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97186, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。名位指名誉和社会地位。"}, {"text": "名为", "is_correct": false, "explanation": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。"}, {"text": "零位", "is_correct": false, "explanation": "líng wèi（零位）与 míng wèi 的声母不同（l 与 m），声调相同，意思是零的位置。"}, {"text": "灵位", "is_correct": false, "explanation": "líng wèi（灵位）与 míng wèi 的声母不同（l 与 m），意思是供奉死者的牌位。"}], "explanations": {"名位": "正确答案。名位指名誉和社会地位。", "名为": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。", "零位": "líng wèi（零位）与 míng wèi 的声母不同（l 与 m），声调相同，意思是零的位置。", "灵位": "líng wèi（灵位）与 míng wèi 的声母不同（l 与 m），意思是供奉死者的牌位。"}, "sentence_index": null, "correct_answer": "名位"}, "level_3": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。“他一生不追求名位”指不追求名誉和地位，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人可以追求的目标，不能说“不追求天气”。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“追求”的对象多是理想、名利，不说“脚印”。"}, {"text": "嗓子", "is_correct": false, "explanation": "语义：嗓子是身体器官，不是可以追求的对象。"}], "explanations": {"名位": "正确答案。“他一生不追求名位”指不追求名誉和地位，符合句意。", "天气": "语义：“天气”不是人可以追求的目标，不能说“不追求天气”。", "脚印": "搭配：“追求”的对象多是理想、名利，不说“脚印”。", "嗓子": "语义：嗓子是身体器官，不是可以追求的对象。"}, "sentence_index": 0, "correct_answer": "名位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的名位很靠前。", "explanation": "这里应该用〈名次〉。名位指名誉和地位，不是考试中的排列次序。"}, {"text": "这位老人有一台名位，大家都很佩服。", "explanation": "这里应该用〈个〉。名位是抽象名词，不能用“台”（机器、设备用）来数。"}, {"text": "他把名位装进了行李箱，带回了老家。", "explanation": "这里应该用〈物品〉。名位指名誉和地位，是抽象的，不能装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97186, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。名位指名誉和社会地位。"}, {"text": "名为", "is_correct": false, "explanation": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。"}, {"text": "民委", "is_correct": false, "explanation": "mín wěi（民委）与 míng wèi 读音相近：第一音节 -n 与 -ng 不同，第二音节声调不同，意思是民族事务委员会。"}, {"text": "明媚", "is_correct": false, "explanation": "míng mèi（明媚）与 míng wèi 只差第二音节声母（m 与 w），意思是明亮秀丽。"}], "explanations": {"名位": "正确答案。名位指名誉和社会地位。", "名为": "míng wéi（名为）与 míng wèi 的第二音节声调不同（第二声与第四声），意思是“名称叫做”。", "民委": "mín wěi（民委）与 míng wèi 读音相近：第一音节 -n 与 -ng 不同，第二音节声调不同，意思是民族事务委员会。", "明媚": "míng mèi（明媚）与 míng wèi 只差第二音节声母（m 与 w），意思是明亮秀丽。"}, "sentence_index": null, "correct_answer": "名位"}, "level_3": {"options": [{"text": "名位", "is_correct": true, "explanation": "正确答案。“他放弃了名位，回到了家乡”指放弃名誉和地位，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“放弃”的对象多是机会、理想，不说“颜色”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子由光线形成，不是可以放弃的东西。"}, {"text": "发音", "is_correct": false, "explanation": "搭配：“放弃”不能与“发音”搭配。"}], "explanations": {"名位": "正确答案。“他放弃了名位，回到了家乡”指放弃名誉和地位，符合句意。", "颜色": "搭配：“放弃”的对象多是机会、理想，不说“颜色”。", "影子": "语义：影子由光线形成，不是可以放弃的东西。", "发音": "搭配：“放弃”不能与“发音”搭配。"}, "sentence_index": 6, "correct_answer": "名位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一张名位，很得意。", "explanation": "这里应该用〈个〉。名位是抽象的，不能用“张”（纸、桌子用）来数。"}, {"text": "他把名位用秤称了一下。", "explanation": "这里应该用〈物品〉。名位是抽象的，不能用秤称重。"}, {"text": "他有一颗名位，每天都很得意。", "explanation": "这里应该用〈个〉。名位是抽象的，不能用“颗”（粒状东西用）来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年轻时也追求过名位过。", "corrected_sentence": "他年轻时也追求过名位。", "error_description": "“过”多出一个：经历体“过”只紧跟动词，句末不能再出现“过”，应删去末尾多余的“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把名位看很重。", "corrected_sentence": "他把名位看得很重。", "error_description": "补语错误：“看”后面带程度补语“很重”，中间要加“得”，不能说“看很重”。应改为“看得很重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e75eea6-85d8-4670-bbac-4ca1277908aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
