INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "问得别人答不上来。", "primary_collocate": null, "pronunciation": "wèn zhù", "ipa": "wən˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这个问题问住了所有人，没有人能回答。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的问题太难，一下子就问住了我。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问住了几个同学，他们站着不说话。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩一句话就问住了妈妈。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试时，经理问住了他，他半天说不出话。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没问住他，他很快就答出来了。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别想问住我，这些题我都会。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的问题常常问住爸爸，他只好去查书。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生问住了年轻人，大家都不说话了。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个难题问住过很多学生，只有她答对了。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "問住", "label": "繁体"}, {"form": "问住了", "label": "体标"}, {"form": "问住过", "label": "体标"}], "register": "口语", "sense_fingerprint": "问住·问得别人答不上来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "问住", "is_correct": true, "explanation": "正确答案。「问住」：问得别人答不上来。"}, {"text": "稳住", "is_correct": false, "explanation": "「稳住」第一个音节是第三声，与「问」（第四声）声调不同，意思是使稳定。"}, {"text": "挽住", "is_correct": false, "explanation": "「挽住」第一个音节的韵母是 an，与「问」的 en 不同，声调也不同，意思是拉住。"}, {"text": "吻住", "is_correct": false, "explanation": "「吻住」第一个音节是第三声 wěn，与「问」（第四声 wèn）声调不同，意思是用嘴唇贴住。"}], "explanations": {"问住": "正确答案。「问住」：问得别人答不上来。", "稳住": "「稳住」第一个音节是第三声，与「问」（第四声）声调不同，意思是使稳定。", "挽住": "「挽住」第一个音节的韵母是 an，与「问」的 en 不同，声调也不同，意思是拉住。", "吻住": "「吻住」第一个音节是第三声 wěn，与「问」（第四声 wèn）声调不同，意思是用嘴唇贴住。"}, "sentence_index": null, "correct_answer": "问住"}, "level_3": {"options": [{"text": "问住", "is_correct": true, "explanation": "「问住」：问题让所有人答不上来，与后句「没有人能回答」一致。"}, {"text": "答应", "is_correct": false, "explanation": "语义：「答应」指应允，问题不会应允别人，且与后句「没有人能回答」相冲突。"}, {"text": "见面", "is_correct": false, "explanation": "配价：「见面」是离合词，不能直接带宾语「所有人」。"}, {"text": "穿上", "is_correct": false, "explanation": "搭配：「穿上」的宾语应是衣物，不能说穿上所有人。"}], "explanations": {"问住": "「问住」：问题让所有人答不上来，与后句「没有人能回答」一致。", "答应": "语义：「答应」指应允，问题不会应允别人，且与后句「没有人能回答」相冲突。", "见面": "配价：「见面」是离合词，不能直接带宾语「所有人」。", "穿上": "搭配：「穿上」的宾语应是衣物，不能说穿上所有人。"}, "sentence_index": 0, "correct_answer": "问住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一堵墙问住了我的去路。", "explanation": "这里应该用〈挡住〉。「问住」是用问题难住人，墙不能提问；堵住去路应说「挡住」。"}, {"text": "她一句话就问住了那个秘密。", "explanation": "这里应该用〈问出〉。「问住」是让对方答不上来，秘密不能被问住；从对方那里问到秘密应说「问出」。"}, {"text": "我听见同学在后面喊，就跑过去把他问住了。", "explanation": "这里应该用〈叫住〉。「问住」是用问题难住人，不表示喊人停下；叫人停下来应说「叫住」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97189, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问住", "is_correct": true, "explanation": "「问住」：想用问题难住我，与后句「这些题我都会」形成对照。"}, {"text": "买下", "is_correct": false, "explanation": "搭配：「买下」的宾语应是物品，不能说买下一个人。"}, {"text": "扶起", "is_correct": false, "explanation": "语义：「扶起」是把人扶着站起来，与「这些题我都会」的语境不相符。"}, {"text": "道歉", "is_correct": false, "explanation": "配价：「道歉」是离合词，应说「向我道歉」，不能直接带宾语「我」。"}], "explanations": {"问住": "「问住」：想用问题难住我，与后句「这些题我都会」形成对照。", "买下": "搭配：「买下」的宾语应是物品，不能说买下一个人。", "扶起": "语义：「扶起」是把人扶着站起来，与「这些题我都会」的语境不相符。", "道歉": "配价：「道歉」是离合词，应说「向我道歉」，不能直接带宾语「我」。"}, "sentence_index": 6, "correct_answer": "问住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我问住了他的电话号码，然后就打过去了。", "explanation": "「问住」表示用问题难住对方，不表示询问信息。这句说的是问出号码，「问住」在此不这样用。"}, {"text": "一个大箱子把门问住了，我推不开。", "explanation": "这里应该用〈堵住〉。「问住」是用问题让人答不上来，箱子不会提问；挡着门打不开应说「堵住」。"}, {"text": "很多学生问住过那个难题，只有她答对了。", "explanation": "主宾颠倒：「问住」的主语是提问的人或问题，被难住的是人。这里应说「那个难题问住过很多学生」，不能说学生问住了难题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题把全班同学都问住。", "corrected_sentence": "这道题把全班同学都问住了。", "error_description": "「把」字句表示已经发生的结果，动词后要加「了」。应说「这道题把全班同学都问住了」，不能省略「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹没把哥哥问住了，哥哥很快就回答了。", "corrected_sentence": "妹妹没把哥哥问住，哥哥很快就回答了。", "error_description": "否定句中动词后不能加「了」。应说「没把哥哥问住」，「问住」后的「了」是多余的，去掉即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
