INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用问题把对方难住，使其答不出来。", "primary_collocate": null, "pronunciation": "wèn zhù", "ipa": "wən˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "学生的一个问题把老师问住了。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者一连串的问题问住了市长。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明想问住爸爸，就问了一个很难的问题。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把我问住，可是我答出来了。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师用几个问题就把证人问住了。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都想问住这位聪明的老先生，却一直没成功。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们想问住新来的数学老师，没想到他笑着答了。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提了个怪问题，一下子问住了全班同学。", "target_word": "问住", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友常用怪问题把大人问住，还笑个不停。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的主持人用一个小问题问住了嘉宾。", "target_word": "问住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "問住", "label": "繁体"}, {"form": "问住了", "label": "体标"}, {"form": "问住过", "label": "体标"}], "register": "口语", "sense_fingerprint": "问住·用问题故意难住对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97190, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "问住", "is_correct": true, "explanation": "正确答案。「问住」：用问题把对方难住，使其答不上来。"}, {"text": "稳住", "is_correct": false, "explanation": "「稳住」第一个音节是第三声，与「问」（第四声）声调不同，意思是使稳定。"}, {"text": "挽住", "is_correct": false, "explanation": "「挽住」第一个音节的韵母是 an，与「问」的 en 不同，声调也不同，意思是拉住。"}, {"text": "吻住", "is_correct": false, "explanation": "「吻住」第一个音节是第三声 wěn，与「问」（第四声 wèn）声调不同，意思是用嘴唇贴住。"}], "explanations": {"问住": "正确答案。「问住」：用问题把对方难住，使其答不上来。", "稳住": "「稳住」第一个音节是第三声，与「问」（第四声）声调不同，意思是使稳定。", "挽住": "「挽住」第一个音节的韵母是 an，与「问」的 en 不同，声调也不同，意思是拉住。", "吻住": "「吻住」第一个音节是第三声 wěn，与「问」（第四声 wèn）声调不同，意思是用嘴唇贴住。"}, "sentence_index": null, "correct_answer": "问住"}, "level_3": {"options": [{"text": "问住", "is_correct": true, "explanation": "「问住」：学生的问题让老师答不上来，与句意相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：问题不能夸奖人，这句话说的是老师被难住，不是被称赞。"}, {"text": "卖掉", "is_correct": false, "explanation": "语义：老师是人，不能卖掉，句子说的是提问造成的结果。"}, {"text": "戴上", "is_correct": false, "explanation": "搭配：「戴上」只用于帽子、眼镜等物品，不能带人作宾语。"}], "explanations": {"问住": "「问住」：学生的问题让老师答不上来，与句意相符。", "夸奖": "语义：问题不能夸奖人，这句话说的是老师被难住，不是被称赞。", "卖掉": "语义：老师是人，不能卖掉，句子说的是提问造成的结果。", "戴上": "搭配：「戴上」只用于帽子、眼镜等物品，不能带人作宾语。"}, "sentence_index": 0, "correct_answer": "问住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一阵大雨把我问住了，我出不了门。", "explanation": "这里应该用〈困住〉。「问住」是用问题让对方答不上来，大雨不会提问；被雨围住、出不了门应说「困住」。"}, {"text": "我一直在追问老师，终于把那个真相问住了。", "explanation": "这里应该用〈问出〉。「问住」是让对方答不上来，真相不能被问住；问到真相应说「问出」。"}, {"text": "我在路口问住了一位路人，请他告诉我去车站怎么走。", "explanation": "这里应该用〈问路〉。「问住」是用问题让对方答不上来，不表示向人打听方向；问去车站怎么走应说「问路」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问住", "is_correct": true, "explanation": "「问住」：想用问题难住老师，与后文「没想到他笑着答了」相呼应。"}, {"text": "见面", "is_correct": false, "explanation": "配价：「见面」是离合词，不能直接带人作宾语，应说「和老师见面」。"}, {"text": "撞倒", "is_correct": false, "explanation": "语义：「撞倒」是用身体撞翻，与后文「笑着答了」的语境不相符。"}, {"text": "买下", "is_correct": false, "explanation": "搭配：「买下」的宾语应是物品，不能说买下一位老师。"}], "explanations": {"问住": "「问住」：想用问题难住老师，与后文「没想到他笑着答了」相呼应。", "见面": "配价：「见面」是离合词，不能直接带人作宾语，应说「和老师见面」。", "撞倒": "语义：「撞倒」是用身体撞翻，与后文「笑着答了」的语境不相符。", "买下": "搭配：「买下」的宾语应是物品，不能说买下一位老师。"}, "sentence_index": 6, "correct_answer": "问住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一句话就把那只猫问住了。", "explanation": "这里应该用〈逗〉。「问住」只用于能回答问题的人，猫不能被问住；想说用一句话逗猫、让它玩耍，应说「逗」。"}, {"text": "我一直问住他的名字，最后才知道他叫什么。", "explanation": "「问住」表示用问题难住对方，不表示询问信息。这句说的是打听名字，「问住」在此不这样用。"}, {"text": "他的答案把大家问住了，大家都说他很聪明。", "explanation": "这里应该用〈难住〉。「问住」的主语必须是提问的人或问题，答案不会提问；让大家答不上来应说「难住」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的提问把考官问住。", "corrected_sentence": "他的提问把考官问住了。", "error_description": "「把」字句叙述已经发生的事，句末要加「了」。应说「他的提问把考官问住了」，不能省略「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不把老师问住，他很快就答出来了。", "corrected_sentence": "我没把老师问住，他很快就答出来了。", "error_description": "错误形式是“不把老师问住”，正确形式是“没把老师问住”。叙述过去没有发生的事，否定要用“没”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
