INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97193, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被关在监狱里的人。", "primary_collocate": null, "pronunciation": "qiú fàn", "ipa": "tɕʰju˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "这个囚犯在监狱里已经住了十年。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "监狱里有一百多名囚犯。", "target_word": "囚犯", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那名囚犯每天早上六点起床。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察把囚犯送回了监狱。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "囚犯在院子里走了半个小时。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当过十年的囚犯，现在在做生意。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "囚犯想家，就给家人写了一封信。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影讲的是一名囚犯逃出监狱的故事。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每个星期都来监狱给囚犯看病。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "监狱里的囚犯穿着一样的衣服，一眼就能认出来。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名囚犯", "label": "量词"}, {"form": "一个囚犯", "label": "量词"}], "register": "中性", "sense_fingerprint": "囚犯·被关在监狱里的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97193, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "囚犯", "is_correct": true, "explanation": "「囚犯」：被关在监狱里的人，与「在监狱里已经住了十年」相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能被关在监狱里，句子说的是被关押的人。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能被关在监狱里住十年，句子说的是被关押的人。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能被关在监狱里住十年，句子说的是被关押的人。"}], "explanations": {"囚犯": "「囚犯」：被关在监狱里的人，与「在监狱里已经住了十年」相符。", "房子": "语义：房子不能被关在监狱里，句子说的是被关押的人。", "钥匙": "语义：钥匙不能被关在监狱里住十年，句子说的是被关押的人。", "树": "语义：树不能被关在监狱里住十年，句子说的是被关押的人。"}, "sentence_index": 0, "correct_answer": "囚犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察在街上抓住了一名囚犯，他刚刚作案。", "explanation": "这里应该用〈罪犯〉。「囚犯」指已经被关在监狱里的人；刚作案、还没关进监狱的应说「罪犯」。"}, {"text": "这名囚犯在国际会议上发表了演讲，大家都很佩服他。", "explanation": "这里应该用〈专家〉。「囚犯」指被关押的人，不能用来指在会议上发言的人；受邀发言的专业人士应说「专家」。"}, {"text": "这个小区里住着很多囚犯。", "explanation": "这里应该用〈居民〉。囚犯被关在监狱里，不住在小区；住在小区里的人应说「居民」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97193, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "囚犯", "is_correct": true, "explanation": "「囚犯」：被关押的人有家可想，与「给家人写了一封信」相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「想家」要求有感情的人或动物做主语，石头不能说想家。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「想家」不搭配无生命的物体，窗户不能说想家。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会写信，与「就给家人写了一封信」的句意相冲突。"}], "explanations": {"囚犯": "「囚犯」：被关押的人有家可想，与「给家人写了一封信」相符。", "石头": "搭配：「想家」要求有感情的人或动物做主语，石头不能说想家。", "窗户": "搭配：「想家」不搭配无生命的物体，窗户不能说想家。", "小狗": "语义：小狗不会写信，与「就给家人写了一封信」的句意相冲突。"}, "sentence_index": 6, "correct_answer": "囚犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "囚犯把我关进了监狱，我很害怕。", "explanation": "这里应该用〈看守〉。囚犯是被关押的人，不能把别人关进监狱；负责关押犯人的人应说「看守」。"}, {"text": "囚犯每天自由地去超市买东西。", "explanation": "这里应该用〈市民〉。「囚犯」指被关押的人，不能自由外出；能自由去超市买东西的人应说「市民」。"}, {"text": "这些囚犯都是我们学校的老师，每天给我们上课。", "explanation": "这里应该用〈教职员工〉。「囚犯」指被关押的人，不能是学校里的教师；在学校任教的人应说「教职员工」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那部小说写的是一只囚犯越狱的经过。", "corrected_sentence": "那部小说写的是一名囚犯越狱的经过。", "error_description": "量词错误：指人的「囚犯」应用「名」，「只」用于动物。应说「一名囚犯」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两名囚犯们在院子里干活。", "corrected_sentence": "两名囚犯在院子里干活。", "error_description": "「囚犯」前已有数量词「两名」，后面不能再加「们」。应说「两名囚犯」；「们」只用于不带数量词的复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
