INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被关押在监狱中的犯人。", "primary_collocate": null, "pronunciation": "qiú fàn", "ipa": "tɕʰju˧˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "他是一名囚犯，已经在监狱里关了五年。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官说，这名囚犯还要在监狱里待三年。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位囚犯表现很好，提前出狱了。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "监狱给每个囚犯发了一张床。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "囚犯们在监狱里做木工，也学习文化。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看守每天检查囚犯的房间。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一名囚犯想逃跑，但看守发现了他。", "target_word": "囚犯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家监狱里的囚犯每天要工作八个小时。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，讲的是自己当囚犯的日子。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人每个月来看一次囚犯，还带来了衣服。", "target_word": "囚犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名囚犯", "label": "量词"}, {"form": "一个囚犯", "label": "量词"}], "register": "中性", "sense_fingerprint": "囚犯·被关押在监狱中的犯人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "囚犯", "is_correct": true, "explanation": "「囚犯」：被关押在监狱中的犯人，与「已经在监狱里关了五年」相符。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不会被关在监狱里五年，句子说的是服刑。"}, {"text": "新生", "is_correct": false, "explanation": "语义：「新生」指刚入学的学生，不能被关在监狱里五年。"}, {"text": "店员", "is_correct": false, "explanation": "语义：店员在店里工作，不会被关在监狱里五年，句子说的是服刑。"}], "explanations": {"囚犯": "「囚犯」：被关押在监狱中的犯人，与「已经在监狱里关了五年」相符。", "游客": "语义：游客不会被关在监狱里五年，句子说的是服刑。", "新生": "语义：「新生」指刚入学的学生，不能被关在监狱里五年。", "店员": "语义：店员在店里工作，不会被关在监狱里五年，句子说的是服刑。"}, "sentence_index": 0, "correct_answer": "囚犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两名囚犯是我们公司的新员工，今天第一次上班。", "explanation": "这里应该用〈员工〉。「囚犯」指被关押在监狱中的人，不能指在公司上班的人；新来公司工作的人应说「员工」。"}, {"text": "法官判决了一名囚犯，他还没进过监狱。", "explanation": "这里应该用〈罪犯〉。「囚犯」指已经被关押的人；判决前还未入狱的应说「罪犯」。"}, {"text": "这位囚犯从来没有被关过，他一直住在家里。", "explanation": "这里应该用〈被告〉。「囚犯」指已经被关押的人；还没入狱、仍住在家中的人应说「被告」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "囚犯", "is_correct": true, "explanation": "「囚犯」：被看守管着、想要逃跑的人，与句子情节相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会被关押，也不会想办法逃跑，与「看守发现了他」的情节冲突。"}, {"text": "天使", "is_correct": false, "explanation": "语义：天使不会被关押，也不会想逃跑，与「看守发现了他」的情节冲突。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵不会想逃跑，也不会被看守抓住，与句子情节冲突。"}], "explanations": {"囚犯": "「囚犯」：被看守管着、想要逃跑的人，与句子情节相符。", "婴儿": "语义：婴儿不会被关押，也不会想办法逃跑，与「看守发现了他」的情节冲突。", "天使": "语义：天使不会被关押，也不会想逃跑，与「看守发现了他」的情节冲突。", "花朵": "语义：花朵不会想逃跑，也不会被看守抓住，与句子情节冲突。"}, "sentence_index": 6, "correct_answer": "囚犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "囚犯每个月来看一次家人，还带来了衣服。", "explanation": "这里应该用〈家属〉作主语。「囚犯」是被探望的人，不能主动去看别人；来探望囚犯的亲人应说「家属」。"}, {"text": "这位囚犯是我的老板，每天给我发工资。", "explanation": "这里应该用〈雇主〉。「囚犯」指被关押的人，不能给别人发工资；给我发工资的人应说「雇主」。"}, {"text": "囚犯一放学就跑回家吃饭。", "explanation": "这里应该用〈学生〉。「囚犯」指被关押的人，不会放学回家；放学回家吃饭的人应说「学生」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只囚犯被关在监狱里很多年。", "corrected_sentence": "一名囚犯被关在监狱里很多年。", "error_description": "量词错误：「囚犯」指人，应用「名」，「只」用于动物。应说「一名囚犯被关在监狱里很多年」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两名囚犯们在院子里干活。", "corrected_sentence": "两名囚犯在院子里干活。", "error_description": "「囚犯」前已有数量词「两名」，后面不能再加「们」。应说「两名囚犯」；「们」只用于不带数量词的复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
