INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最主要、最要紧的几件事。", "primary_collocate": null, "pronunciation": "jī běn diǎn", "ipa": "tɕi⁵⁵ pən²¹⁴ tjɛn²¹⁴", "syllable_count": 3, "sentences": [{"text": "这篇文章有三个基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会前，请大家先记住这几个基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把课文的基本点写在黑板上。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学游泳有两个基本点，一是不怕水，二是放松。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意的基本点，你是否都已经清楚？", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了安全生活的基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快就说出了计划的基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先说一下这件事的基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几个基本点，每个学生都要记住。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要我们先弄清工作的基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "基本點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "最主要、最要紧的几件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本点", "is_correct": true, "explanation": "正确：“三个基本点”指三件最主要的事，与“这篇文章有”搭配自然。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑构件，文章没有窗户，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，与文章无关，句子读起来不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体器官，文章里没有眼睛，句子不通。"}], "explanations": {"基本点": "正确：“三个基本点”指三件最主要的事，与“这篇文章有”搭配自然。", "窗户": "语义：窗户是建筑构件，文章没有窗户，句子不通。", "汽车": "语义：汽车是交通工具，与文章无关，句子读起来不通。", "眼睛": "语义：眼睛是身体器官，文章里没有眼睛，句子不通。"}, "sentence_index": 0, "correct_answer": "基本点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正在打好英语基本点。", "explanation": "这里应该用〈基础〉。“打基础”是固定说法；基本点指几件最主要的事，不能被“打好”。"}, {"text": "老师在黑板上写了一只基本点。", "explanation": "量词用错。“只”多用于动物、成对的器官等；基本点不能用“只”来数，应说“一个基本点”。"}, {"text": "这栋楼的基本点很牢固。", "explanation": "这里应该用〈地基〉。基本点指要紧的几件事，不是建筑的底部，不能说“很牢固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本点", "is_correct": true, "explanation": "正确：“说出了计划的基本点”指说出计划中最要紧的几件事，搭配自然。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，计划里不会有沙发，句子读起来不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是用来报时的，与“计划”无关，句子不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“说出”的对象是话语、想法，不能说“说出钢笔”。"}], "explanations": {"基本点": "正确：“说出了计划的基本点”指说出计划中最要紧的几件事，搭配自然。", "沙发": "语义：沙发是家具，计划里不会有沙发，句子读起来不通。", "闹钟": "语义：闹钟是用来报时的，与“计划”无关，句子不通。", "钢笔": "搭配：“说出”的对象是话语、想法，不能说“说出钢笔”。"}, "sentence_index": 6, "correct_answer": "基本点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "信封上写着收件人的基本点。", "explanation": "这里应该用〈地址〉。基本点指要紧的几件事，不是地方，信封上写的应是地址。"}, {"text": "门口停着一辆基本点。", "explanation": "量词用错。“辆”用于车辆；基本点是抽象的事项，应说“一个基本点”。"}, {"text": "他每月拿到一笔基本点。", "explanation": "这里应该用〈工资〉。基本点指要紧的几件事，不是钱，不能说“拿到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师讲了三份基本点。", "corrected_sentence": "老师讲了三个基本点。", "error_description": "量词用错。“基本点”应使用“个”，“份”多用于报纸、文件等，不能用来数基本点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划有两只基本点。", "corrected_sentence": "这份计划有两个基本点。", "error_description": "量词用错。基本点应使用“个”，“只”多用于动物，不能用来数基本点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
