INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最基本的要点。", "primary_collocate": null, "pronunciation": "jī běn diǎn", "ipa": "tɕi⁵⁵ pən²¹⁴ tjɛn²¹⁴", "syllable_count": 3, "sentences": [{"text": "这是学汉语的基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试前要复习课本的基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个基本点十分重要，不可忽视。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听懂了这堂课的基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作文有一个基本点，就是句子要清楚。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把读书的基本点告诉了弟弟。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份说明讲清了使用的基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家抓住这篇报道的基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是法律课的第一个基本点。", "target_word": "基本点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李做笔记时只写基本点。", "target_word": "基本点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "基本點", "label": "繁体"}], "register": "书面", "sense_fingerprint": "最基本的要点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基本点", "is_correct": true, "explanation": "正确：“学汉语的基本点”指学习汉语最基本的要点，搭配自然。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与学习汉语无关，句子不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球是体育用品，与“学汉语”无关，句子读起来不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“学汉语的”后面不能接家电，“学汉语的冰箱”不成立。"}], "explanations": {"基本点": "正确：“学汉语的基本点”指学习汉语最基本的要点，搭配自然。", "厨房": "语义：厨房是做饭的地方，与学习汉语无关，句子不通。", "足球": "语义：足球是体育用品，与“学汉语”无关，句子读起来不通。", "冰箱": "搭配：“学汉语的”后面不能接家电，“学汉语的冰箱”不成立。"}, "sentence_index": 0, "correct_answer": "基本点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在本子上写下了一台基本点。", "explanation": "量词用错。“台”用于机器、电器；基本点不能用“台”来数，应说“一个基本点”。"}, {"text": "他做完了这堂课的基本点。", "explanation": "这里应该用〈作业〉。基本点是要点，不能“做完”，做完的是作业。"}, {"text": "这块地的基本点很平坦。", "explanation": "这里应该用〈地形〉。“平坦”形容地面的起伏；基本点指最基本的要点，不能用来形容地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基本点", "is_correct": true, "explanation": "正确：“这份说明讲清了使用的基本点”指使用方法中最基本的要点，搭配自然。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以讲清楚的使用对象，句子读起来不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“使用”不能和大海搭配，“使用的大海”不成立。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮与说明书的使用方法无关，句子不通。"}], "explanations": {"基本点": "正确：“这份说明讲清了使用的基本点”指使用方法中最基本的要点，搭配自然。", "天空": "语义：天空不是可以讲清楚的使用对象，句子读起来不通。", "大海": "搭配：“使用”不能和大海搭配，“使用的大海”不成立。", "月亮": "语义：月亮与说明书的使用方法无关，句子不通。"}, "sentence_index": 6, "correct_answer": "基本点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把朋友的基本点存进了手机。", "explanation": "这里应该用〈电话号码〉。基本点是要点，不是可以存进手机的号码，应说“电话号码”。"}, {"text": "这座城市有一座基本点。", "explanation": "量词用错。“座”用于山、楼房等大型固定物；基本点应说“个”。"}, {"text": "服务员递来一份基本点。", "explanation": "这里应该用〈菜单〉。基本点是要点，不能被递来，递来的是菜单。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班讨论了三只基本点。", "corrected_sentence": "我们班讨论了三个基本点。", "error_description": "量词用错。基本点应使用“个”，“只”多用于动物，不能用来数基本点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班要讨论这几把基本点。", "corrected_sentence": "我们班要讨论这几个基本点。", "error_description": "量词用错。基本点应使用“个”，“把”多用于有柄的器具，不能用来数基本点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
