INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97205, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力压住，不让它动或不让它说话。", "primary_collocate": null, "pronunciation": "yā zhì", "ipa": "ja˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "警察用力压制住了那个小偷。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一下子把对手压制住，按在地上。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人才压制住那头发疯的牛。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手压制着乱动的小狗。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安压制了打架的男人，不让他乱动。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生压制着病人的手，护士打了针。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用膝盖压制住对方，让对方动不了。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人压制着他，不让他喊叫。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想站起来，哥哥用手压制着他。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们终于压制住了那匹马。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压制住", "label": "结果补语"}, {"form": "压制了", "label": "体标（了）"}, {"form": "压制着", "label": "体标（着）"}, {"form": "压制过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "用身体或手的力量把人或动物按住，使其不能动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97205, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压制", "is_correct": true, "explanation": "正确：压制指用力按住人，与“用力……住了那个小偷”相符。"}, {"text": "放松", "is_correct": false, "explanation": "语义：“放松”与“用力”矛盾，不能用来形容按住小偷。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”不能带“住了”，不指按住人。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”指接纳、迎接，不能用于按住人。"}], "explanations": {"压制": "正确：压制指用力按住人，与“用力……住了那个小偷”相符。", "放松": "语义：“放松”与“用力”矛盾，不能用来形容按住小偷。", "讨论": "搭配：“讨论”不能带“住了”，不指按住人。", "欢迎": "搭配：“欢迎”指接纳、迎接，不能用于按住人。"}, "sentence_index": 0, "correct_answer": "压制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用石头压制住纸，纸就不会被风吹走。", "explanation": "这里应该用〈压住〉。压制用于制服人或动物使其不能动，压纸要用压住。"}, {"text": "他用木板压制住了破窗户。", "explanation": "这里应该用〈堵住〉。压制用于制服人或动物，不用来形容堵窗户，堵住破口要用堵住。"}, {"text": "一块大石头压制住了路。", "explanation": "这里应该用〈挡住〉。压制不用于形容路，路被东西挡住要用挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97205, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压制", "is_correct": true, "explanation": "正确：压制指用身体力量按住对方，与“让对方动不了”相符。"}, {"text": "松开", "is_correct": false, "explanation": "语义：“松开”与“让对方动不了”矛盾。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：“讲解”不用于按住对方的身体。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”指使人安心，不指用膝盖按住对方。"}], "explanations": {"压制": "正确：压制指用身体力量按住对方，与“让对方动不了”相符。", "松开": "语义：“松开”与“让对方动不了”矛盾。", "讲解": "搭配：“讲解”不用于按住对方的身体。", "安慰": "搭配：“安慰”指使人安心，不指用膝盖按住对方。"}, "sentence_index": 6, "correct_answer": "压制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里压制了一块面包。", "explanation": "这里应该用〈烤〉。压制指用力压住人或动物使其不动，做面包要用烤。"}, {"text": "他用一根火柴压制了炉子。", "explanation": "这里应该用〈点燃〉。压制指用力压住人或动物使其不动，炉火燃起要用点燃。"}, {"text": "警察压制了那座小楼。", "explanation": "这里应该用〈包围〉。压制不用于建筑，把房子围起来要用包围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个孩子乱踢，爸爸一下子就把他压制了住。", "corrected_sentence": "那个孩子乱踢，爸爸一下子就把他压制住了。", "error_description": "结果补语“住”要紧跟动词，应说“压制住了”，不说“压制了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个坏人想跑，警察一下子就压制住了他的。", "corrected_sentence": "那个坏人想跑，警察一下子就压制住了他。", "error_description": "语法错误：“压制住了”后面直接接宾语“他”，多出的“的”使句子不通，应说“压制住了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
