INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "用强力压下去，不让发展或表达。", "primary_collocate": null, "pronunciation": "yā zhì", "ipa": "ja˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "公司压制新想法，员工都不敢说话。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他压制着心里的怒火，没有说话。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板压制不同的意见。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家压制人民的自由表达。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司想压制小公司的发展。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她压制着笑声，怕吵醒睡着的孩子。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要压制孩子的兴趣，让他们自己选。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位官员压制了所有批评他的声音。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直压制着想哭的心情。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去有人压制过这位作家的作品。", "target_word": "压制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压制住", "label": "结果补语"}, {"form": "压制了", "label": "体标（了）"}, {"form": "压制着", "label": "体标（着）"}, {"form": "压制过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "用权力或意志压下他人的意见、发展或自己的情绪，使其无法表达", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压制", "is_correct": true, "explanation": "正确：压制指用权力或意志压下意见，与“公司……新想法，员工都不敢说话”相符。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”与“员工都不敢说话”矛盾。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”与“员工都不敢说话”矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“新想法”搭配。"}], "explanations": {"压制": "正确：压制指用权力或意志压下意见，与“公司……新想法，员工都不敢说话”相符。", "支持": "语义：“支持”与“员工都不敢说话”矛盾。", "鼓励": "语义：“鼓励”与“员工都不敢说话”矛盾。", "唱": "搭配：“唱”不能与“新想法”搭配。"}, "sentence_index": 0, "correct_answer": "压制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在厨房里压制了鸡蛋，很快就好了。", "explanation": "这里应该用〈煮〉。压制指用强力压下去、不让发展或表达，煮鸡蛋要用煮。"}, {"text": "师傅压制了那台坏掉的收音机。", "explanation": "这里应该用〈修理〉。压制指用强力压下去、不让发展或表达，修好机器要用修理。"}, {"text": "她压制了那道数学题，很快就做完了。", "explanation": "这里应该用〈解〉。压制用于压下意见、发展或情绪，做题要用解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压制", "is_correct": true, "explanation": "正确：压制指用权力或意志压下他人的兴趣或发展，与“不要……孩子的兴趣”相符。"}, {"text": "讲解", "is_correct": false, "explanation": "搭配：「讲解」不能与「兴趣」搭配，句意不通。"}, {"text": "考验", "is_correct": false, "explanation": "搭配：「考验」指检验能力或意志，不能用来指孩子的兴趣。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”不能与“兴趣”搭配。"}], "explanations": {"压制": "正确：压制指用权力或意志压下他人的兴趣或发展，与“不要……孩子的兴趣”相符。", "讲解": "搭配：「讲解」不能与「兴趣」搭配，句意不通。", "考验": "搭配：「考验」指检验能力或意志，不能用来指孩子的兴趣。", "打扫": "搭配：“打扫”不能与“兴趣”搭配。"}, "sentence_index": 6, "correct_answer": "压制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了省钱，他压制了开支。", "explanation": "这里应该用〈压缩〉。压制用于压下意见、发展等，削减开支要用压缩。"}, {"text": "他每天早上压制一杯牛奶当早饭。", "explanation": "这里应该用〈喝〉。压制指用强力压下意见、发展或情绪，喝牛奶要用喝。"}, {"text": "我们周末去公园压制了风筝。", "explanation": "这里应该用〈放〉。压制用于压下意见、发展或情绪，放风筝要用放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个部门压制了住这份报告，大家都没看到。", "corrected_sentence": "那个部门压制住了这份报告，大家都没看到。", "error_description": "结果补语“住”要紧跟动词，“了”放在补语之后，应说“压制住了这份报告”，不说“压制了住这份报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不要压制了孩子的想法，让他们多说话。", "corrected_sentence": "不要压制孩子的想法，让他们多说话。", "error_description": "“不要”表示劝阻，后面的“压制”不能带“了”，应说“不要压制孩子的想法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
