INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "里屋以外的房间，多指外屋。", "primary_collocate": null, "pronunciation": "wài jiān", "ipa": "wai̯˥˩ tɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "里屋住着爷爷，外间是客厅。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子分里屋和外间，外间放着桌椅。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把衣服晾在外间，里屋太小了。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外间有一张床，里屋有一个大柜子。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在外间玩，大人在里屋聊天。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在里屋睡觉，你小声点，在外间说话。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外间的炉子烧着，里屋也很暖和。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套房子分里外两间，外间吃饭，里屋睡觉。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在外间等着，病人在里屋休息。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住外间，哥哥住里屋。", "target_word": "外间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "外间屋", "label": "复合词"}, {"form": "外間", "label": "繁体"}], "register": "口语", "sense_fingerprint": "与里屋相对的外屋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c091977-6e47-4361-b22e-fc75be886fea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97210, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：wài jiān，指与里屋相对的外屋。"}, {"text": "外键", "is_correct": false, "explanation": "外键 wài jiàn 与 wài jiān 声调不同（第四声与第一声），是数据库术语。"}, {"text": "外加", "is_correct": false, "explanation": "外加 wài jiā 与 wài jiān 韵母不同（少了 n），意思是另外再加上。"}, {"text": "外迁", "is_correct": false, "explanation": "外迁 wài qiān 与 wài jiān 声母不同（q 与 j），意思是迁往外地居住。"}], "explanations": {"外间": "外间：wài jiān，指与里屋相对的外屋。", "外键": "外键 wài jiàn 与 wài jiān 声调不同（第四声与第一声），是数据库术语。", "外加": "外加 wài jiā 与 wài jiān 韵母不同（少了 n），意思是另外再加上。", "外迁": "外迁 wài qiān 与 wài jiān 声母不同（q 与 j），意思是迁往外地居住。"}, "sentence_index": null, "correct_answer": "外间"}, "level_3": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：与里屋相对的外屋，与“里屋住着爷爷”形成对照，作客厅合适。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：“卧室”一般是睡觉的房间，与前句“里屋住着爷爷”的居住空间重复，且不能作客厅。"}, {"text": "大门", "is_correct": false, "explanation": "语义：“大门”是出入口，不能作客厅。"}, {"text": "内室", "is_correct": false, "explanation": "语域：“内室”偏书面，且与“里屋”同指一处，不能与之并列作客厅。"}], "explanations": {"外间": "外间：与里屋相对的外屋，与“里屋住着爷爷”形成对照，作客厅合适。", "卧室": "语义：“卧室”一般是睡觉的房间，与前句“里屋住着爷爷”的居住空间重复，且不能作客厅。", "大门": "语义：“大门”是出入口，不能作客厅。", "内室": "语域：“内室”偏书面，且与“里屋”同指一处，不能与之并列作客厅。"}, "sentence_index": 0, "correct_answer": "外间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的外间很厚，坐着很舒服。", "explanation": "这里应该用〈坐垫〉。外间指房间，不能指椅子的软垫。"}, {"text": "他一口气买下了两座外间。", "explanation": "这里应该用〈幢〉或〈套〉。外间是房间，不能用“座”计量。"}, {"text": "外间的情绪很稳定，从不发脾气。", "explanation": "这里应该用〈他〉或〈她〉。外间是房间，不能有情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外间", "is_correct": true, "explanation": "外间：与里屋相对的外屋，“炉子烧着”与“里屋也很暖和”形成对照，合乎语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”上不会装炉子，不能说“窗户的炉子烧着”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：“墙”不能装炉子，与句子的语境不符。"}, {"text": "湖", "is_correct": false, "explanation": "语义：“湖”是水域，不能装炉子，句子不通。"}], "explanations": {"外间": "外间：与里屋相对的外屋，“炉子烧着”与“里屋也很暖和”形成对照，合乎语境。", "窗户": "语义：“窗户”上不会装炉子，不能说“窗户的炉子烧着”。", "墙": "语义：“墙”不能装炉子，与句子的语境不符。", "湖": "语义：“湖”是水域，不能装炉子，句子不通。"}, "sentence_index": 6, "correct_answer": "外间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我弟弟的外间很高，已经快赶上爸爸了。", "explanation": "这里应该用〈个子〉。外间是房间，不能形容人的身高。"}, {"text": "这双鞋的外间很软，穿着很舒服。", "explanation": "这里应该用〈鞋面〉。外间指房间，不能指鞋的外层。"}, {"text": "她今天的外间很激动，说话都发抖。", "explanation": "这里应该用〈心情〉或〈情绪〉。外间是房间，不能形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5632fdf-a0ca-42cf-8019-c58011907793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
