INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97213, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说出来的数字比真的多。", "primary_collocate": null, "pronunciation": "duō bào", "ipa": "tuo⁵⁵ pau⁵¹", "syllable_count": 2, "sentences": [{"text": "他多报了两个人。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板问人数，小王多报了五个。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多报了自己的工龄，想多拿点补助。", "target_word": "多报", "complexity_tier": "T3", "furigana": "tā duō bào le zìjǐ de gōnglíng, xiǎng duō ná diǎn bǔzhù.", "sentence_source": "generated"}, {"text": "这笔账你为什么多报了十块钱？", "target_word": "多报", "complexity_tier": "T3", "furigana": "zhè bǐ zhàng nǐ wèi shénme duō bào le shí kuài qián?", "sentence_source": "generated"}, {"text": "他多报了三百块，所以多拿了钱。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说人数的时候，别多报也别少报。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "统计表上的数字多报了一些。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生人数多报了，书就订多了。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意多报了一天的工时。", "target_word": "多报", "complexity_tier": "T3", "furigana": "tā gùyì duō bào le yì tiān de gōngshí.", "sentence_source": "generated"}, {"text": "这个数字多报了很多。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多报了", "label": "体标"}, {"form": "多报过", "label": "体标"}, {"form": "多報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "报出的数字比实际的多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多报", "is_correct": true, "explanation": "正确：“多报”指报出的数目比实际多，符合“他……两个人”的句意。"}, {"text": "多吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃“两个人”，句子不通。"}, {"text": "多睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“两个人”作宾语。"}, {"text": "多哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能带“两个人”作宾语。"}], "explanations": {"多报": "正确：“多报”指报出的数目比实际多，符合“他……两个人”的句意。", "多吃": "语义：“吃”的对象是食物，不能说吃“两个人”，句子不通。", "多睡": "配价：“睡”是不及物动词，后面不能带“两个人”作宾语。", "多哭": "配价：“哭”是不及物动词，后面不能带“两个人”作宾语。"}, "sentence_index": 0, "correct_answer": "多报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多报了一个噩梦。", "explanation": "这里应该用〈多做〉。多报用于报告数字，噩梦不能报；说梦见的次数多要用“多做”。"}, {"text": "他多报了一个笑话。", "explanation": "这里应该用〈多讲〉。多报用于报告数字，笑话不是数字，不能报；说讲的内容多要用“多讲”。"}, {"text": "她多报了一个想法。", "explanation": "这里应该用〈多提〉。多报用于报告数字，想法不能报；说提出的意见多要用“多提”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多报", "is_correct": true, "explanation": "正确：“多报”指报的数字比实际多，符合“统计表上的数字”和“一些”的语境。"}, {"text": "多唱", "is_correct": false, "explanation": "语义：“数字”不会唱歌，与主语“数字”不相容。"}, {"text": "多跑", "is_correct": false, "explanation": "语义：“数字”不会跑，与主语“数字”不相容。"}, {"text": "多卖", "is_correct": false, "explanation": "搭配：“卖”的对象是货物，“数字”不能作“卖”的对象，二者不搭配。"}], "explanations": {"多报": "正确：“多报”指报的数字比实际多，符合“统计表上的数字”和“一些”的语境。", "多唱": "语义：“数字”不会唱歌，与主语“数字”不相容。", "多跑": "语义：“数字”不会跑，与主语“数字”不相容。", "多卖": "搭配：“卖”的对象是货物，“数字”不能作“卖”的对象，二者不搭配。"}, "sentence_index": 6, "correct_answer": "多报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他多报了一个愿望。", "explanation": "这里应该用〈多许〉。多报用于报告数字，愿望不能报；说许下的愿望多要用“多许”。"}, {"text": "我多报了一阵笑声。", "explanation": "这里应该用〈多笑〉。多报用于报告数字，笑声不能报；说笑的时间多要用“多笑”。"}, {"text": "他多报了一句玩笑话。", "explanation": "这里应该用〈多说〉。多报用于报告数字，玩笑话不能报；说多余的话要用“多说”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我多报着三天的工时。", "corrected_sentence": "我多报了三天的工时。", "error_description": "体标用错。“多报”表示动作已完成，应说“多报了”，“着”表示动作持续，不能说“多报着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告里的数字多报是一点。", "corrected_sentence": "这份报告里的数字多报了一点。", "error_description": "错误形式是“多报是一点”，正确形式是“多报了一点”。“是”不能用在动词后表示动作已经完成，表示完成要用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
