INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "多报数目；报告的数量超过实际。", "primary_collocate": null, "pronunciation": "duō bào", "ipa": "tuo⁵⁵ pau⁵¹", "syllable_count": 2, "sentences": [{"text": "公司多报了今年的销量。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人多报了工作时间。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店多报了进货的数量。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多报了自己的出勤天数，结果查出来了。", "target_word": "多报", "complexity_tier": "T3", "furigana": "tā duō bào le zìjǐ de chūqín tiānshù, jiéguǒ chá chūlái le.", "sentence_source": "generated"}, {"text": "村里多报了受灾的人数，后来有人发现了。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要多报这个月的开支。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班长多报了一个人的饭钱。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂多报了产量，大家都知道。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这次表格里的人数多报了。", "target_word": "多报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔开支多报了，要退回去。", "target_word": "多报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多报了", "label": "体标"}, {"form": "多报过", "label": "体标"}, {"form": "多報", "label": "繁体"}], "register": "中性", "sense_fingerprint": "向上级或他人报告的数量超过实际", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97214, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多报", "is_correct": true, "explanation": "正确：“多报”指向上级或他人报告的数量超过实际，符合句意。"}, {"text": "多唱", "is_correct": false, "explanation": "语义：“公司”不能唱“销量”，句子无意义。"}, {"text": "多卖", "is_correct": false, "explanation": "搭配：“卖”的对象是货物，不能说“卖了销量”，二者不搭配。"}, {"text": "多睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“销量”作宾语。"}], "explanations": {"多报": "正确：“多报”指向上级或他人报告的数量超过实际，符合句意。", "多唱": "语义：“公司”不能唱“销量”，句子无意义。", "多卖": "搭配：“卖”的对象是货物，不能说“卖了销量”，二者不搭配。", "多睡": "配价：“睡”是不及物动词，后面不能带“销量”作宾语。"}, "sentence_index": 0, "correct_answer": "多报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店员多报了一个眼神。", "explanation": "这里应该用〈多看〉。多报用于报告数字，眼神不能报；说看的次数多要用“多看”。"}, {"text": "他多报了一个主意。", "explanation": "这里应该用〈多想〉。多报用于报告数字，主意不是数字，不能报；说想出的主意多要用“多想”。"}, {"text": "她多报了一首诗。", "explanation": "这里应该用〈多写〉。多报用于报告数字，诗不能报；说写下的诗多要用“多写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多报", "is_correct": true, "explanation": "正确：“多报”指报出的数目超过实际，符合“班长”报饭钱的语境。"}, {"text": "多睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“饭钱”作宾语。"}, {"text": "多笑", "is_correct": false, "explanation": "语义：“笑”不能以“饭钱”为对象，与句意不符。"}, {"text": "多哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，后面不能带“饭钱”作宾语。"}], "explanations": {"多报": "正确：“多报”指报出的数目超过实际，符合“班长”报饭钱的语境。", "多睡": "配价：“睡”是不及物动词，后面不能带“饭钱”作宾语。", "多笑": "语义：“笑”不能以“饭钱”为对象，与句意不符。", "多哭": "配价：“哭”是不及物动词，后面不能带“饭钱”作宾语。"}, "sentence_index": 6, "correct_answer": "多报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天多报了一个哈欠。", "explanation": "这里应该用〈多打〉。多报用于报告数字，哈欠不能报；说打哈欠的次数多要用“多打”。"}, {"text": "她对着孩子多报了一个微笑。", "explanation": "这里应该用〈多给〉。多报用于报告数字，微笑不能报；说给别人的微笑多要用“多给”。"}, {"text": "他多报了一声叹息。", "explanation": "这里应该用〈多叹〉。多报用于报告数字，叹息不能报；说叹气的次数多要用“多叹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他多报着三次加班的时间。", "corrected_sentence": "他多报了三次加班的时间。", "error_description": "错误形式是“多报着”，正确形式是“多报了”。报告是一次性完成的动作，表示完成要用“了”，“着”表示持续状态，不能用在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里把上个月的产量多报。", "corrected_sentence": "厂里把上个月的产量多报了。", "error_description": "错误形式是“把……多报”末尾缺少“了”，正确形式是“把……多报了”。“把”字句中的动词通常要带“了”或其他成分，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：“单一”指只有一种、不多样，与“多样”正相对。"}, {"text": "轻松", "is_correct": false, "explanation": "无关：“轻松”形容不紧张、不费力，与“多样”没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：“温暖”形容气温或感觉不冷，与“多样”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "无关：“陡峭”形容坡度大，与“多样”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：“单一”指只有一种、不多样，与“多样”正相对。", "轻松": "无关：“轻松”形容不紧张、不费力，与“多样”没有反义关系。", "温暖": "无关：“温暖”形容气温或感觉不冷，与“多样”没有反义关系。", "陡峭": "无关：“陡峭”形容坡度大，与“多样”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：“单一”指只有一种、不多样，与“多样”正相对。"}, {"text": "狭窄", "is_correct": false, "explanation": "无关：“狭窄”形容空间小，与“多样”没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "无关：“潮湿”形容含水分多，与“多样”没有反义关系。"}, {"text": "沉默", "is_correct": false, "explanation": "无关：“沉默”形容不说话，与“多样”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：“单一”指只有一种、不多样，与“多样”正相对。", "狭窄": "无关：“狭窄”形容空间小，与“多样”没有反义关系。", "潮湿": "无关：“潮湿”形容含水分多，与“多样”没有反义关系。", "沉默": "无关：“沉默”形容不说话，与“多样”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有很多种，不是都一样。", "primary_collocate": null, "pronunciation": "duō yàng", "ipa": "tu̯ɔ˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "商店里的鞋很多样，大小和颜色都不同。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场上的水果多样，苹果、梨和西瓜都有。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的早饭很多样，今天吃面，明天吃饺子。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们玩的游戏很多样，没有两个一样。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的衣服多样，每天都穿不一样的。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个公园里的树多样，高的矮的、粗的细的都有。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的冰淇淋口味多样，我每次都买不同的。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的小吃多样，每家卖的都不一样。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书很多样，有故事书，也有画册。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的菜多样，吃一个月也不会重复。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多樣", "label": "繁体"}, {"form": "多样化", "label": "复合"}, {"form": "多样性", "label": "复合"}], "register": "中性", "sense_fingerprint": "多样·有很多种、不是都一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多样", "is_correct": true, "explanation": "正确：“多样”指有很多种、不都一样，与“大小和颜色都不同”的句意相符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与“大小和颜色都不同”的句意相矛盾。"}, {"text": "统一", "is_correct": false, "explanation": "语义：“统一”指一致、没有差别，与“大小和颜色都不同”的句意相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体积，不用来说鞋的种类和样式。"}], "explanations": {"多样": "正确：“多样”指有很多种、不都一样，与“大小和颜色都不同”的句意相符。", "单一": "语义：“单一”指只有一种，与“大小和颜色都不同”的句意相矛盾。", "统一": "语义：“统一”指一致、没有差别，与“大小和颜色都不同”的句意相矛盾。", "高大": "搭配：“高大”形容人或物的体积，不用来说鞋的种类和样式。"}, "sentence_index": 0, "correct_answer": "多样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的饭量很多样。", "explanation": "这里应该用〈大〉。多样指种类不单一，说饭量的多少要用“大”。"}, {"text": "这壶水很多样。", "explanation": "这里应该用〈烫〉。多样指种类不单一，说水的温度高要用“烫”。"}, {"text": "这个孩子很多样。", "explanation": "这里应该用〈活泼〉。多样指种类不单一，说孩子的性格精神要用“活泼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多样", "is_correct": true, "explanation": "正确：“多样”指有很多种，与“我每次都买不同的”的句意相符。"}, {"text": "单调", "is_correct": false, "explanation": "语义：“单调”指变化少，与“我每次都买不同的”的句意相矛盾。"}, {"text": "粗大", "is_correct": false, "explanation": "搭配：“粗大”形容物体的粗细，不用来形容“口味”。"}, {"text": "矮小", "is_correct": false, "explanation": "搭配：“矮小”形容人或物体的高矮、体积，不用来形容“口味”。"}], "explanations": {"多样": "正确：“多样”指有很多种，与“我每次都买不同的”的句意相符。", "单调": "语义：“单调”指变化少，与“我每次都买不同的”的句意相矛盾。", "粗大": "搭配：“粗大”形容物体的粗细，不用来形容“口味”。", "矮小": "搭配：“矮小”形容人或物体的高矮、体积，不用来形容“口味”。"}, "sentence_index": 6, "correct_answer": "多样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座楼很多样。", "explanation": "这里应该用〈高〉。多样说种类不单一，说楼的高度要用“高”。"}, {"text": "他走路很多样。", "explanation": "这里应该用〈慢〉。多样说种类不单一，说走路的速度要用“慢”。"}, {"text": "天很多样。", "explanation": "这里应该用〈黑〉。多样说种类不单一，说天色的状态要用“黑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的水果很很多样，有苹果、香蕉和葡萄。", "corrected_sentence": "这家超市的水果很多样，有苹果、香蕉和葡萄。", "error_description": "错误形式是“很很多样”，正确形式是“很多样”。“很”只需用一次修饰“多样”，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜很的多样。", "corrected_sentence": "这家店的菜很多样。", "error_description": "错误形式是“很的多样”，正确形式是“很多样”。“很”后面直接接形容词，多加的“的”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
