INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "反义：“单一”指只有一种、不多样，与“多样”正相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地软，与“多样”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线充足，与“多样”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容没有声音，与“多样”没有反义关系。"}], "correct_answer": "单一", "explanations": {"单一": "反义：“单一”指只有一种、不多样，与“多样”正相对。", "柔软": "无关：“柔软”形容质地软，与“多样”没有反义关系。", "明亮": "无关：“明亮”形容光线充足，与“多样”没有反义关系。", "安静": "无关：“安静”形容没有声音，与“多样”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形式或种类繁多，不单一。", "primary_collocate": null, "pronunciation": "duō yàng", "ipa": "tu̯ɔ˥ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校的课外活动形式多样，有音乐、体育和美术。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的商品种类多样，什么都能买到。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志的内容多样，有新闻、旅行和美食。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的教学方法多样，有游戏也有小组讨论。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览上的作品形式多样，有画、有照片，还有雕塑。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的饮食文化多样，各地的菜都能吃到。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表达方式多样，有时说，有时用图画。", "target_word": "多样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的产品多样，能满足不同客人的需要。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆提供多样的借阅方式，网上借和到馆借都行。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的晚会节目多样，有唱歌、跳舞和相声。", "target_word": "多样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多樣", "label": "繁体"}, {"form": "多样化", "label": "复合"}, {"form": "多样性", "label": "复合"}], "register": "中性", "sense_fingerprint": "多样·形式或种类繁多、不单一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '087b1334-eb14-4da2-86a2-a80f7438ffb0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多样", "is_correct": true, "explanation": "正确：“多样”指形式种类繁多，与后文列举的音乐、体育和美术相符。"}, {"text": "单一", "is_correct": false, "explanation": "语义：“单一”指只有一种，与后文列举多种活动相矛盾。"}, {"text": "单调", "is_correct": false, "explanation": "语义：“单调”指变化少、不丰富，与后文列举多种活动相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容人或物的体积，不用来形容“形式”。"}], "explanations": {"多样": "正确：“多样”指形式种类繁多，与后文列举的音乐、体育和美术相符。", "单一": "语义：“单一”指只有一种，与后文列举多种活动相矛盾。", "单调": "语义：“单调”指变化少、不丰富，与后文列举多种活动相矛盾。", "高大": "搭配：“高大”形容人或物的体积，不用来形容“形式”。"}, "sentence_index": 0, "correct_answer": "多样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很多样。", "explanation": "这里应该用〈高〉。多样指种类不单一，说一个人的个子高矮要用“高”。"}, {"text": "这间屋子很多样。", "explanation": "这里应该用〈宽敞〉。多样指种类不单一，说房间的面积大要用“宽敞”。"}, {"text": "这把椅子很多样。", "explanation": "这里应该用〈结实〉。多样指种类不单一，说椅子的坚固程度要用“结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多样", "is_correct": true, "explanation": "正确：“多样”指表达方式种类繁多，与“有时说，有时用图画”的句意相符。"}, {"text": "呆板", "is_correct": false, "explanation": "语义：“呆板”指僵化不变，与“有时说，有时用图画”的多种方式相矛盾。"}, {"text": "粗大", "is_correct": false, "explanation": "搭配：“粗大”形容物体的粗细，不用来形容“表达方式”。"}, {"text": "矮小", "is_correct": false, "explanation": "搭配：“矮小”形容人或物体的高矮、体积，不用来形容“表达方式”。"}], "explanations": {"多样": "正确：“多样”指表达方式种类繁多，与“有时说，有时用图画”的句意相符。", "呆板": "语义：“呆板”指僵化不变，与“有时说，有时用图画”的多种方式相矛盾。", "粗大": "搭配：“粗大”形容物体的粗细，不用来形容“表达方式”。", "矮小": "搭配：“矮小”形容人或物体的高矮、体积，不用来形容“表达方式”。"}, "sentence_index": 6, "correct_answer": "多样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕很多样。", "explanation": "这里应该用〈甜〉。多样指种类不单一，说蛋糕的甜度要用“甜”。"}, {"text": "那座山很多样。", "explanation": "这里应该用〈高大〉。多样说种类不单一，说山的体型要用“高大”。"}, {"text": "他跑得很多样。", "explanation": "这里应该用〈快〉。多样说种类不单一，说跑的速度要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校的课外活动很很多样。", "corrected_sentence": "这所学校的课外活动很多样。", "error_description": "错误形式是“很很多样”，正确形式是“很多样”。“很”只需用一次修饰“多样”，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目单的内容很的多样。", "corrected_sentence": "这个节目单的内容很多样。", "error_description": "错误形式是“很的多样”，正确形式是“很多样”。“很”后面直接接形容词，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '457d3c31-77cc-4712-93b8-9a54595ed3d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
