INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97217, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做了好事，后来得到好的回报。", "primary_collocate": null, "pronunciation": "hǎo bào", "ipa": "xaʊ˨˩ paʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他常帮助别人，后来真的有了好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好人有好报，这话一点不错。", "target_word": "好报", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她帮过很多人，现在得到了好报。", "target_word": "好报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人常说，做好事会有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他帮助别人，从来不图好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多年后，他的善心终于有了好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对人这么好，一定会有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶相信好人一定有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他救过一个孩子，后来有了好报。", "target_word": "好报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生一辈子行善，终于有了好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做好事之后得到的好回报", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97217, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好报", "is_correct": true, "explanation": "好报：做善事后得到的善果，与“有了”及“后来”搭配，句意通顺。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是地理事物，不会因为帮助别人而“有了”。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”与“帮助别人”的语境相反，句子语义冲突。"}, {"text": "祸根", "is_correct": false, "explanation": "语域：“祸根”偏书面，与口语语境不符，且语义与“帮助别人”相悖。"}], "explanations": {"好报": "好报：做善事后得到的善果，与“有了”及“后来”搭配，句意通顺。", "河流": "语义：“河流”是地理事物，不会因为帮助别人而“有了”。", "仇人": "语义：“仇人”与“帮助别人”的语境相反，句子语义冲突。", "祸根": "语域：“祸根”偏书面，与口语语境不符，且语义与“帮助别人”相悖。"}, "sentence_index": 0, "correct_answer": "好报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作的好报很高。", "explanation": "这里应该用〈报酬〉。好报指做善事后得到的善果，不指工作的薪酬。"}, {"text": "他在比赛中获得了很多好报。", "explanation": "这里应该用〈奖励〉。好报指做善事后得到的善果，比赛的奖品要用奖励。"}, {"text": "今年的粮食好报很好。", "explanation": "这里应该用〈收成〉。好报指做善事后得到的善果，庄稼的产量要用收成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好报", "is_correct": true, "explanation": "好报：善待他人后得到的善果，与“对人这么好”的语境一致。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“对人这么好”之后不会“有敌人”，语义冲突。"}, {"text": "恶果", "is_correct": false, "explanation": "语义：“恶果”指坏的结果，与“对人这么好”的语义相反。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有”后接“天气”语义不通，不符合句意。"}], "explanations": {"好报": "好报：善待他人后得到的善果，与“对人这么好”的语境一致。", "敌人": "语义：“对人这么好”之后不会“有敌人”，语义冲突。", "恶果": "语义：“恶果”指坏的结果，与“对人这么好”的语义相反。", "天气": "搭配：“有”后接“天气”语义不通，不符合句意。"}, "sentence_index": 6, "correct_answer": "好报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "坏人作恶多年，终于有了好报。", "explanation": "这里应该用〈报应〉。“好报”指善行得到的善果，作恶之人的结果要用报应。"}, {"text": "这笔投资的好报很可观。", "explanation": "这里应该用〈回报〉。“好报”指做善事后的善果，投资的收益要用回报。"}, {"text": "他学到了很多知识，好报很大。", "explanation": "这里应该用〈收获〉。“好报”指善行带来的善果，学习所得要用收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一生乐于助人，晚年终于了有好报。", "corrected_sentence": "他一生乐于助人，晚年终于有了好报。", "error_description": "“了”位置错误：“了”应紧跟在“有”之后，应为“有了好报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位医生一辈子行善，晚年得到着好报。", "corrected_sentence": "这位医生一辈子行善，晚年得到了好报。", "error_description": "体标误用：「得到」表示已完成的结果，应用「了」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
