INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "善有善报，好的结果。", "primary_collocate": null, "pronunciation": "hǎo bào", "ipa": "xaʊ˨˩ paʊ˥˩", "syllable_count": 2, "sentences": [{"text": "坚持学习的人，总会有好报。", "target_word": "好报", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他努力工作多年，终于有了好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种树的人，几年后会有好报。", "target_word": "好报", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她对邻居很好，最后也有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孝顺父母的人，常有好报。", "target_word": "好报", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "做生意要讲诚信，诚信会有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直守规矩，现在有了好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们都说，好心人会有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，认真读书会有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她吃了很多苦，如今终于有好报。", "target_word": "好报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "善行或努力带来的好结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好报", "is_correct": true, "explanation": "好报：善行或努力带来的好结果，与“坚持学习”的语境相合。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与“坚持学习”语义相反，句子冲突。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“有”后接“天气”语义不通，不符合句意。"}, {"text": "祸根", "is_correct": false, "explanation": "语域：“祸根”偏书面，且语义与“坚持学习”相悖。"}], "explanations": {"好报": "好报：善行或努力带来的好结果，与“坚持学习”的语境相合。", "懒惰": "语义：“懒惰”与“坚持学习”语义相反，句子冲突。", "天气": "搭配：“有”后接“天气”语义不通，不符合句意。", "祸根": "语域：“祸根”偏书面，且语义与“坚持学习”相悖。"}, "sentence_index": 0, "correct_answer": "好报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃这个药有很多好报。", "explanation": "这里应该用〈好处〉。“好报”指善行或努力带来的善果，药物的益处要用好处。"}, {"text": "他学到了很多知识，好报很大。", "explanation": "这里应该用〈收获〉。“好报”指善行或努力的善果，学习所得要用收获。"}, {"text": "公司年底发了很多好报。", "explanation": "这里应该用〈奖金〉。好报指做善事后得到的善果，公司发给员工的钱要用奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好报", "is_correct": true, "explanation": "好报：善行或努力带来的好结果，与“守规矩”的语境相合。"}, {"text": "坏名声", "is_correct": false, "explanation": "语义：“守规矩”之后不会“有坏名声”，语义相反。"}, {"text": "灰尘", "is_correct": false, "explanation": "语义：“灰尘”是物体，不能表示守规矩带来的结果。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有了颜色”语义不通，不符合句意。"}], "explanations": {"好报": "好报：善行或努力带来的好结果，与“守规矩”的语境相合。", "坏名声": "语义：“守规矩”之后不会“有坏名声”，语义相反。", "灰尘": "语义：“灰尘”是物体，不能表示守规矩带来的结果。", "颜色": "搭配：“有了颜色”语义不通，不符合句意。"}, "sentence_index": 6, "correct_answer": "好报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "骗子作恶多年，终于有了好报。", "explanation": "这里应该用〈报应〉。“好报”指善行或努力带来的善果，作恶者的结果要用报应。"}, {"text": "这笔生意好报很好。", "explanation": "这里应该用〈收益〉。“好报”指善行或努力带来的善果，不指生意的盈利。"}, {"text": "今年的粮食好报很好。", "explanation": "这里应该用〈收成〉。“好报”指善行或努力带来的善果，庄稼的产量要用收成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她诚实待人，最后终于了有好报。", "corrected_sentence": "她诚实待人，最后终于有了好报。", "error_description": "“了”位置错误：“了”应紧跟在“有”之后，应为“有了好报”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
