INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里分成的四段，每段三个月。", "primary_collocate": null, "pronunciation": "jì dù", "ipa": "tɕi˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "一年有四个季度。", "target_word": "季度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第一个季度是一月到三月。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季度我们卖得很好。", "target_word": "季度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "第二季度从四月开始。", "target_word": "季度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司每个季度开一次大会。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上个季度的销售不太好。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第三季度是七月到九月。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年第四季度，我们要搬到新办公室。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想在下个季度换工作。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季度的工资已经发了。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "第一季度", "label": "复合"}, {"form": "季度报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年分成的四段之一，每段三个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97221, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：季度指一年里分成的四段，每段三个月。"}, {"text": "记录", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），意思是记录。"}, {"text": "极度", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是极度。"}, {"text": "几度", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是几次。"}], "explanations": {"季度": "正确：季度指一年里分成的四段，每段三个月。", "记录": "dù 与 lù 声母不同（d 与 l），意思是记录。", "极度": "jí（第二声）与 jì（第四声）声调不同，意思是极度。", "几度": "jǐ（第三声）与 jì（第四声）声调不同，意思是几次。"}, "sentence_index": null, "correct_answer": "季度"}, "level_3": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：“季度”指一年分成的四段，“一年有四个季度”成立。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是七天一周，不能在一年内分成四个。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“小时”是时间单位，与“一年分成四段”的意思不符。"}, {"text": "月份", "is_correct": false, "explanation": "搭配：“月份”指一年中的某一个月，不用来指年内的分段。"}], "explanations": {"季度": "正确：“季度”指一年分成的四段，“一年有四个季度”成立。", "星期": "语义：“星期”是七天一周，不能在一年内分成四个。", "小时": "语义：“小时”是时间单位，与“一年分成四段”的意思不符。", "月份": "搭配：“月份”指一年中的某一个月，不用来指年内的分段。"}, "sentence_index": 0, "correct_answer": "季度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "第二只季度从四月开始。", "explanation": "这里应该用〈个〉。季度的量词是“个”，“只”多用于动物或成对、单个的东西，不能说“第二只季度”。"}, {"text": "第二张季度从四月开始。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，不用于季度。"}, {"text": "第二条季度从四月开始。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不用于季度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：“第三季度”指一年中的第三个三个月，是七月到九月。"}, {"text": "课时", "is_correct": false, "explanation": "语义：“课时”指一节课的时间，与七月到九月这段较长时间不符。"}, {"text": "时刻", "is_correct": false, "explanation": "语义：“时刻”指某一个时间点，不能是三个月的一段。"}, {"text": "年", "is_correct": false, "explanation": "搭配：“第三年”指一年的顺序，不能与“七月到九月”搭配。"}], "explanations": {"季度": "正确：“第三季度”指一年中的第三个三个月，是七月到九月。", "课时": "语义：“课时”指一节课的时间，与七月到九月这段较长时间不符。", "时刻": "语义：“时刻”指某一个时间点，不能是三个月的一段。", "年": "搭配：“第三年”指一年的顺序，不能与“七月到九月”搭配。"}, "sentence_index": 6, "correct_answer": "季度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每季度早上七点起床。", "explanation": "这里应该用〈每天〉。起床是日常事务，按季度计算不合常理。"}, {"text": "我们每季度吃午饭。", "explanation": "这里应该用〈每天〉。吃午饭是每天的日常，按季度计算不合常理。"}, {"text": "他每季度喝一杯水。", "explanation": "这里应该用〈每小时〉。季度指三个月，不能用来说明喝水这种短时间的频率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们每只季度都要交一次报告。", "corrected_sentence": "他们每个季度都要交一次报告。", "error_description": "错误：季度前的量词用“只”。正确：应为“每个季度”，“个”是季度最常用的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "第一只季度的收入比去年多。", "corrected_sentence": "第一季度的收入比去年多。", "error_description": "错误：多加了量词“只”，写成“第一只季度”。正确：“第一季度”是序数加“季度”的固定说法，不加量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
