INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中按三个月划分的一段时间。", "primary_collocate": null, "pronunciation": "jì dù", "ipa": "tɕi˥˩ tu˥˩", "syllable_count": 2, "sentences": [{"text": "每三个月是一个季度。", "target_word": "季度", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司每个季度都会发一份报告。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们这个季度的目标是卖五千台。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第一季度的销售比去年好。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在第二季度开了新店。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季度过得真快，马上就到年底了。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上一个季度，我们赚了很多钱。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校每个季度都检查一次学生的成绩。", "target_word": "季度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第四季度有圣诞节和新年。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下个季度公司要招五个新人。", "target_word": "季度", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "上季度", "label": "复合"}, {"form": "季度报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年中按三个月划分的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75197a94-e390-4c63-9429-82b277c6ee79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97222, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：季度指一年中按三个月划分的一段时间。"}, {"text": "记录", "is_correct": false, "explanation": "dù 与 lù 声母不同（d 与 l），意思是记录。"}, {"text": "极度", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，意思是极度。"}, {"text": "几度", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，意思是几次。"}], "explanations": {"季度": "正确：季度指一年中按三个月划分的一段时间。", "记录": "dù 与 lù 声母不同（d 与 l），意思是记录。", "极度": "jí（第二声）与 jì（第四声）声调不同，意思是极度。", "几度": "jǐ（第三声）与 jì（第四声）声调不同，意思是几次。"}, "sentence_index": null, "correct_answer": "季度"}, "level_3": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：“季度”指一年中按三个月划分的一段时间，句意符合。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是七天一周，与“三个月”的长度不符。"}, {"text": "小时", "is_correct": false, "explanation": "语义：“小时”是六十分钟，与“三个月”的长度相差太大。"}, {"text": "月份", "is_correct": false, "explanation": "搭配：“一个月份”指一个月，不能说“每三个月是一个月份”。"}], "explanations": {"季度": "正确：“季度”指一年中按三个月划分的一段时间，句意符合。", "星期": "语义：“星期”是七天一周，与“三个月”的长度不符。", "小时": "语义：“小时”是六十分钟，与“三个月”的长度相差太大。", "月份": "搭配：“一个月份”指一个月，不能说“每三个月是一个月份”。"}, "sentence_index": 0, "correct_answer": "季度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "第一张季度的销售比去年好。", "explanation": "这里应该用〈个〉。季度不用“张”计量，应说“第一季度”或“第一个季度”。"}, {"text": "第一只季度的销售比去年好。", "explanation": "这里应该用〈个〉。“只”多用于动物或成对的东西，不用于季度。"}, {"text": "第一条季度的销售比去年好。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不用于季度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季度", "is_correct": true, "explanation": "正确：“上一个季度”指刚过去的三个月，与“赚了很多钱”句意通顺。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学习任务，与“赚了很多钱”没有关系。"}, {"text": "眼镜", "is_correct": false, "explanation": "量词：“眼镜”通常用“副”计量，且不能指一段时间，句子不通。"}, {"text": "字典", "is_correct": false, "explanation": "量词：“字典”用“本”计量，且不能指一段时间，句子不通。"}], "explanations": {"季度": "正确：“上一个季度”指刚过去的三个月，与“赚了很多钱”句意通顺。", "作业": "语义：“作业”指学习任务，与“赚了很多钱”没有关系。", "眼镜": "量词：“眼镜”通常用“副”计量，且不能指一段时间，句子不通。", "字典": "量词：“字典”用“本”计量，且不能指一段时间，句子不通。"}, "sentence_index": 6, "correct_answer": "季度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每季度早上九点开门。", "explanation": "这里应该用〈每天〉。季度指三个月，不能和“早上九点”这种具体时刻搭配；开门是每天的事。"}, {"text": "妈妈每季度晚上十点做饭。", "explanation": "这里应该用〈每晚〉。季度是三个月的时间段，不能用来指做饭这种每晚都有的具体时刻。"}, {"text": "他每季度上午十点喝咖啡。", "explanation": "这里应该用〈每天〉。季度是三个月，不能用来说明喝咖啡这种每天的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每只季度都要开会。", "corrected_sentence": "我们每个季度都要开会。", "error_description": "错误：季度前的量词用“只”，应为“个”。正确：“每个季度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只季度的利润比上个季度高。", "corrected_sentence": "这个季度的利润比上个季度高。", "error_description": "错误：“这”后的量词用了“只”，写成“这只季度”。正确：“这个季度”，“个”是季度的量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fcffe7f-6024-45d0-b45f-12da5b0befc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
