INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有缺点、十全十美的人。", "primary_collocate": null, "pronunciation": "wán rén", "ipa": "wan˧˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "他又聪明又善良，像个完人。", "target_word": "完人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小说里的主人公几乎是个完人。", "target_word": "完人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不要求朋友是完人。", "target_word": "完人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大家眼里是完人，没有缺点。", "target_word": "完人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对谁都很友善，大家都把她当成完人。", "target_word": "完人", "complexity_tier": "T3", "furigana": "tā duì shéi dōu hěn yǒushàn, dàjiā dōu bǎ tā dàngchéng wánrén.", "sentence_source": "generated"}, {"text": "完人是不存在的，每个人都有缺点。", "target_word": "完人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当完人，什么都做得很好。", "target_word": "完人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的老师在学生眼里是个完人。", "target_word": "完人", "complexity_tier": "T3", "furigana": "zhè bù diànyǐng lǐ de lǎoshī zài xuésheng yǎn lǐ shì gè wánrén.", "sentence_source": "generated"}, {"text": "爸爸在孩子心里是个完人。", "target_word": "完人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别把他看成完人，他也有缺点。", "target_word": "完人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "完人：没有缺点、十全十美的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2207342d-854a-4a15-943c-61e058b32ef4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "完人", "is_correct": true, "explanation": "完人（wán rén）指没有缺点、十全十美的人，这就是听到的词。"}, {"text": "凡人", "is_correct": false, "explanation": "fán 与 wán 声母不同（f 与 w），意思是普通人、凡夫俗子。"}, {"text": "文人", "is_correct": false, "explanation": "wén 与 wán 韵母不同（-en 与 -an），意思是读书人、文化人。"}, {"text": "万人", "is_correct": false, "explanation": "wàn（第四声）与 wán（第二声）声调不同，意思是一万人。"}], "explanations": {"完人": "完人（wán rén）指没有缺点、十全十美的人，这就是听到的词。", "凡人": "fán 与 wán 声母不同（f 与 w），意思是普通人、凡夫俗子。", "文人": "wén 与 wán 韵母不同（-en 与 -an），意思是读书人、文化人。", "万人": "wàn（第四声）与 wán（第二声）声调不同，意思是一万人。"}, "sentence_index": null, "correct_answer": "完人"}, "level_3": {"options": [{"text": "完人", "is_correct": true, "explanation": "完人指没有缺点的人，符合“又聪明又善良”的赞美描写，语义通顺。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有聪明、善良的特征，与前文的褒义描写矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "语域：“垃圾”是贬义口语，与“又聪明又善良”的赞美语气冲突。"}, {"text": "胖子", "is_correct": false, "explanation": "体貌：“胖子”描写外形，与前文的性格评价不一致。"}], "explanations": {"完人": "完人指没有缺点的人，符合“又聪明又善良”的赞美描写，语义通顺。", "石头": "语义：石头没有聪明、善良的特征，与前文的褒义描写矛盾。", "垃圾": "语域：“垃圾”是贬义口语，与“又聪明又善良”的赞美语气冲突。", "胖子": "体貌：“胖子”描写外形，与前文的性格评价不一致。"}, "sentence_index": 0, "correct_answer": "完人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是数学完人，什么题都会做。", "explanation": "这里应该用〈天才〉。完人强调各方面没有缺点，不限于某一科；某个学科能力突出要用〈天才〉。"}, {"text": "他是医学完人，诊断从来没出过错。", "explanation": "这里应该用〈专家〉。完人不限于某一专业，形容某个专业上权威的人要用〈专家〉。"}, {"text": "他是象棋完人，每一局都能赢。", "explanation": "这里应该用〈高手〉。完人指没有缺点的人，形容某项技能特别厉害要用〈高手〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "完人", "is_correct": true, "explanation": "完人（wán rén）指没有缺点、十全十美的人，这就是听到的词。"}, {"text": "外人", "is_correct": false, "explanation": "wài 与 wán 韵母不同（-ai 与 -an），声调也不同，意思是关系疏远的人、局外人。"}, {"text": "犯人", "is_correct": false, "explanation": "fàn 与 wán 声母不同（f 与 w），声调也不同，意思是犯了罪的人。"}, {"text": "男人", "is_correct": false, "explanation": "nán 与 wán 声母不同（n 与 w），意思是男性。"}], "explanations": {"完人": "完人（wán rén）指没有缺点、十全十美的人，这就是听到的词。", "外人": "wài 与 wán 韵母不同（-ai 与 -an），声调也不同，意思是关系疏远的人、局外人。", "犯人": "fàn 与 wán 声母不同（f 与 w），声调也不同，意思是犯了罪的人。", "男人": "nán 与 wán 声母不同（n 与 w），意思是男性。"}, "sentence_index": null, "correct_answer": "完人"}, "level_3": {"options": [{"text": "完人", "is_correct": true, "explanation": "完人指没有缺点的人，与“想当”的理想化语气相合，语义通顺。"}, {"text": "懒虫", "is_correct": false, "explanation": "语义：“懒虫”指懒惰的人，与“什么都做得很好”矛盾。"}, {"text": "废物", "is_correct": false, "explanation": "语域：“废物”是贬义口语，与“想当”的积极意愿冲突。"}, {"text": "老古董", "is_correct": false, "explanation": "语义：“老古董”指守旧落后的人，与“什么都做得很好”不协调。"}], "explanations": {"完人": "完人指没有缺点的人，与“想当”的理想化语气相合，语义通顺。", "懒虫": "语义：“懒虫”指懒惰的人，与“什么都做得很好”矛盾。", "废物": "语域：“废物”是贬义口语，与“想当”的积极意愿冲突。", "老古董": "语义：“老古董”指守旧落后的人，与“什么都做得很好”不协调。"}, "sentence_index": 6, "correct_answer": "完人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个完人，可是经常迟到。", "explanation": "这里应该用〈好人〉。完人指没有任何缺点，后句说“经常迟到”，前后矛盾；只说为人好要用〈好人〉。"}, {"text": "他是个完人，却总把事情搞砸。", "explanation": "这里应该用〈能人〉。完人指没有任何缺点，后句说“总把事情搞砸”，前后矛盾；只说本事大、能干要用〈能人〉。"}, {"text": "他是个完人，说话却常常伤人。", "explanation": "这里应该用〈人才〉。完人指没有任何缺点，后句说“说话常常伤人”，前后矛盾；只说有才干要用〈人才〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从来没见过很完人。", "corrected_sentence": "我从来没见过真正的完人。", "error_description": "修饰错误：“完人”是名词，不能受“很”修饰，应说“真正的完人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们都把他当成一块完人。", "corrected_sentence": "同学们都把他当成一个完人。", "error_description": "量词错误：“完人”指人，不能用量词“块”，应改为“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70bd1005-a63f-4589-8328-c30a6a7b3915') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
