INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在政府里做事的人，常常管着很多人。", "primary_collocate": null, "pronunciation": "guān liáo", "ipa": "kwan˥ ljaʊ˧˥", "syllable_count": 2, "sentences": [{"text": "政府需要定期考核官僚的工作表现。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "这位官僚负责全市的户籍和土地管理。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "这个部门有三十多名官僚，负责审批企业的执照。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "学者们认为，官僚的专业化是现代行政的重要标志。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "古代王朝依靠官僚治理广大的地区。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "每位官僚每天要处理几十份文件。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "城市规划需要熟悉情况的官僚参与讨论。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "学者分析了官僚在国家治理中的作用。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "政府改革的目标之一是明确每一位官僚的职责范围。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}, {"text": "现代政府需要训练有素的官僚管理公共事务。", "target_word": "官僚", "complexity_tier": "T3", "furigana": "guān liáo", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官僚机构", "label": "复合"}], "register": "中性", "sense_fingerprint": "在政府里做事、管着很多人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "官僚", "is_correct": true, "explanation": "正确：在政府里做事、管着很多人的人，可以被考核工作表现，与“定期考核”相合。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡是照明用品，不是政府工作人员，不存在被考核的工作表现。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不在政府任职，“考核工作表现”说不通。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“工作表现”指人或单位的工作成绩，河流不能说有工作表现。"}], "explanations": {"官僚": "正确：在政府里做事、管着很多人的人，可以被考核工作表现，与“定期考核”相合。", "灯泡": "语义：灯泡是照明用品，不是政府工作人员，不存在被考核的工作表现。", "小猫": "语义：小猫不在政府任职，“考核工作表现”说不通。", "河流": "搭配：“工作表现”指人或单位的工作成绩，河流不能说有工作表现。"}, "sentence_index": 0, "correct_answer": "官僚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位官僚每天开出租车接送乘客。", "explanation": "这里应该用〈司机〉。“官僚”指在政府里做事、管着很多人的人，不开车接送乘客。"}, {"text": "官僚在工厂里生产零件。", "explanation": "这里应该用〈工人〉。“官僚”指在政府里做事的人，不在工厂里生产零件。"}, {"text": "官僚每天给病人看很多病。", "explanation": "这里应该用〈医生〉。“官僚”指在政府里做事的人，不给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官僚", "is_correct": true, "explanation": "正确：在政府里做事的人，可以参与城市规划的讨论，与“熟悉情况”相合。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“参与讨论”的主体须是人或团体，石头不能参与讨论。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能熟悉情况，也不能参与讨论。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不会参与讨论，与“熟悉情况”也不相合。"}], "explanations": {"官僚": "正确：在政府里做事的人，可以参与城市规划的讨论，与“熟悉情况”相合。", "石头": "配价：“参与讨论”的主体须是人或团体，石头不能参与讨论。", "厨房": "语义：厨房是房间，不能熟悉情况，也不能参与讨论。", "植物": "语义：植物不会参与讨论，与“熟悉情况”也不相合。"}, "sentence_index": 6, "correct_answer": "官僚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位官僚在码头上装卸货物。", "explanation": "这里应该用〈装卸工〉。“官僚”指在政府里做事的人，不做装卸货物的体力活。"}, {"text": "这位官僚每天在学校操场上给学生上体育课。", "explanation": "这里应该用〈体育老师〉。“官僚”指在政府里做事的人，不在学校上体育课。"}, {"text": "这位官僚在河里撒网打鱼，全家靠打鱼过日子。", "explanation": "这里应该用〈渔夫〉。“官僚”指在政府里做事的人，不靠打鱼为生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熟悉情况地官僚都参加了这次会议。", "corrected_sentence": "熟悉情况的官僚都参加了这次会议。", "error_description": "结构助词错误：“熟悉情况”修饰名词，应用“的”，不能用“地”。应说“熟悉情况的官僚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府把两只官僚调走了。", "corrected_sentence": "政府把两名官僚调走了。", "error_description": "量词错误：指人的“官僚”应用量词“名”，不能用“只”（“只”多用于动物等）。应说“把两名官僚调走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
