INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指政府中脱离群众、办事拖拉、只讲形式的官员（含贬义）。", "primary_collocate": null, "pronunciation": "guān liáo", "ipa": "kwan˥ ljaʊ˧˥", "syllable_count": 2, "sentences": [{"text": "这个官僚办事很慢，一件小事拖了半年。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些官僚只关心自己的位子，不关心老百姓。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们都不喜欢脱离群众的官僚。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位官僚从来不到农村看一看。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想变成只会开会的官僚。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓去办事，总是遇到不负责的官僚。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说写了一个懒惰又自大的官僚。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了官僚以后，再也不听群众的话。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧社会的官僚常常欺负普通人。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸批评了几个只会拖着不办事的官僚。", "target_word": "官僚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "官僚主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "脱离群众、办事拖拉的官员（贬义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "官僚", "is_correct": true, "explanation": "正确：“官僚”指办事拖拉、脱离群众的官员，与“办事很慢”和“拖了半年”相合。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不是人，不能办事，与“办事很慢”相矛盾。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是作品，不会办事，与“办事很慢”不符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“办事”的主体须是人或机构，石头不能办事。"}], "explanations": {"官僚": "正确：“官僚”指办事拖拉、脱离群众的官员，与“办事很慢”和“拖了半年”相合。", "蛋糕": "语义：蛋糕不是人，不能办事，与“办事很慢”相矛盾。", "小说": "语义：小说是作品，不会办事，与“办事很慢”不符。", "石头": "配价：“办事”的主体须是人或机构，石头不能办事。"}, "sentence_index": 0, "correct_answer": "官僚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位官僚每天在工地上搬砖，一天要搬几百块。", "explanation": "这里应该用〈建筑工人〉。“官僚”指政府里的官员，不做搬砖的体力活。"}, {"text": "这位官僚每天在饭店后厨炒菜，给食客做饭。", "explanation": "这里应该用〈厨师〉。“官僚”指政府里的官员，不在饭店后厨炒菜谋生。"}, {"text": "这位官僚每天在田里插秧，腰都直不起来。", "explanation": "这里应该用〈农民〉。“官僚”指政府里的官员，不下田插秧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "官僚", "is_correct": true, "explanation": "正确：“官僚”含贬义，指脱离群众、办事拖拉的人，与“懒惰又自大”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能是懒惰又自大的人物。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程是学习内容，不能像人一样懒惰又自大。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“懒惰又自大”形容人，不能用来形容天气。"}], "explanations": {"官僚": "正确：“官僚”含贬义，指脱离群众、办事拖拉的人，与“懒惰又自大”相合。", "桌子": "语义：桌子是家具，不能是懒惰又自大的人物。", "课程": "语义：课程是学习内容，不能像人一样懒惰又自大。", "天气": "搭配：“懒惰又自大”形容人，不能用来形容天气。"}, "sentence_index": 6, "correct_answer": "官僚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位官僚在医院里给病人打针。", "explanation": "这里应该用〈护士〉。“官僚”指政府里的官员，不负责给病人打针。"}, {"text": "这位官僚在课堂上教孩子们写字。", "explanation": "这里应该用〈老师〉。“官僚”指政府里的官员，不在课堂上教学。"}, {"text": "这位官僚在码头上扛着大包。", "explanation": "这里应该用〈搬运工〉。“官僚”指政府里的官员，不做体力搬运。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他后来当上了一只官僚，就不再关心群众。", "corrected_sentence": "他后来当上了一个官僚，就不再关心群众。", "error_description": "量词错误：指人的“官僚”应用量词“个”，不能用“只”（“只”多用于动物等）。应说“当上了一个官僚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个懒惰又自大地官僚。", "corrected_sentence": "他是一个懒惰又自大的官僚。", "error_description": "结构助词错误：修饰名词的形容词后应用“的”，不能用“地”（“地”用于修饰动词）。应说“懒惰又自大的官僚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
