INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97237, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "问别人这样是不是正确。", "primary_collocate": null, "pronunciation": "duì bu duì", "ipa": "tweɪ̯˥˩ pu tweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "我不知道这样做对不对。", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你看看我写的字对不对。", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他问老师这个答案对不对。", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说这样写对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想问问这样走对不对。", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师，我这样读对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题我算得对不对，请你看看。", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不确定自己的想法对不对。", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你听听我说得对不对。", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我这样回答对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "作谓语或补语，询问某个做法、答案或说法是否正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对不对", "is_correct": true, "explanation": "对不对：作谓语，询问这样做的做法是否正确，与“不知道”相符。"}, {"text": "懂不懂", "is_correct": false, "explanation": "搭配：“懂不懂”问对方能否理解，不能用来询问做法是否正确。"}, {"text": "对吗", "is_correct": false, "explanation": "配价：“吗”问句不能嵌入“不知道”之后作宾语，应说“对不对”。"}, {"text": "有没有", "is_correct": false, "explanation": "搭配：“有没有”问是否存在，与“这样做”搭配不当。"}], "explanations": {"对不对": "对不对：作谓语，询问这样做的做法是否正确，与“不知道”相符。", "懂不懂": "搭配：“懂不懂”问对方能否理解，不能用来询问做法是否正确。", "对吗": "配价：“吗”问句不能嵌入“不知道”之后作宾语，应说“对不对”。", "有没有": "搭配：“有没有”问是否存在，与“这样做”搭配不当。"}, "sentence_index": 0, "correct_answer": "对不对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你为什么迟到，对不对？", "explanation": "这里不能把“对不对”附在疑问词提问后面。“对不对”用于询问做法、答案或说法是否正确，不用于特殊疑问句，应直接提问，不加〈对不对〉。"}, {"text": "——这样写对吗？——对不对。", "explanation": "这里应该用〈是的〉。“对不对”是正反形式，不能用来肯定回答；肯定回答应说〈是的〉。"}, {"text": "这样写很对不对。", "explanation": "这里不能用〈很〉修饰〈对不对〉。“对不对”是正反形式，不能受程度副词修饰；应说〈很对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对不对", "is_correct": true, "explanation": "对不对：作补语，表示算得正确与否，与“请你看看”的核对意图相符。"}, {"text": "错", "is_correct": false, "explanation": "搭配：“算得”后不接“错”，应说“算错了”。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“算得”后面要接补语，“吗”是语气词，不能作补语。"}, {"text": "熟", "is_correct": false, "explanation": "搭配：“熟”不能直接作“算得”的补语，应说“算得熟练”。"}], "explanations": {"对不对": "对不对：作补语，表示算得正确与否，与“请你看看”的核对意图相符。", "错": "搭配：“算得”后不接“错”，应说“算错了”。", "吗": "语法：“算得”后面要接补语，“吗”是语气词，不能作补语。", "熟": "搭配：“熟”不能直接作“算得”的补语，应说“算得熟练”。"}, "sentence_index": 6, "correct_answer": "对不对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你借我一支笔，对不对？", "explanation": "这里不能把“对不对”附在请求句末。“对不对”只用于询问做法或说法是否正确，请求应说〈好不好〉。"}, {"text": "我这样回答很对不对？", "explanation": "这里不能用〈很〉修饰〈对不对〉。“对不对”是正反形式，不能受程度副词修饰；应说〈很对〉。"}, {"text": "谁这样回答，对不对？", "explanation": "这里不能把“对不对”附在疑问词提问后面。“对不对”只用于询问做法或说法是否正确，应直接提问，不加〈对不对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这样做对不对的？", "corrected_sentence": "我这样做对不对？", "error_description": "“对不对”作谓语，后面不能加“的”；应说“我这样做对不对？”，不说“对不对的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你看看我的答案对不对的。", "corrected_sentence": "请你看看我的答案对不对。", "error_description": "“对不对”作谓语，后面不能加“的”；应说“请你看看我的答案对不对。”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
