INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97238, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "询问是否正确的说法。", "primary_collocate": null, "pronunciation": "duì bu duì", "ipa": "tweɪ̯˥˩ pu tweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "你明天去学校，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书是你的，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天是星期五，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你是小王的朋友，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们八点见面，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住在北京，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你昨天没来上课，对不对？", "target_word": "对不对", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈说你喜欢吃鱼，对不对？", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店周日不开门，对不对？", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们明天交作业，对不对？", "target_word": "对不对", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在句末，向对方确认前面说的话是否正确的附加问句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e367c5db-bc30-4878-ac37-5d47087517c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对不对", "is_correct": true, "explanation": "对不对：句末附加问句，请对方确认前面说的“去学校”是否正确。"}, {"text": "懂不懂", "is_correct": false, "explanation": "语义：“懂不懂”问对方是否听明白，不是核对前面说的话是否正确。"}, {"text": "贵不贵", "is_correct": false, "explanation": "语义：“贵不贵”问价格高低，不能用来确认“明天去学校”这件事是否属实。"}, {"text": "是否", "is_correct": false, "explanation": "语域：“是否”是书面语，口语的句末附加问句应用“对不对”。"}], "explanations": {"对不对": "对不对：句末附加问句，请对方确认前面说的“去学校”是否正确。", "懂不懂": "语义：“懂不懂”问对方是否听明白，不是核对前面说的话是否正确。", "贵不贵": "语义：“贵不贵”问价格高低，不能用来确认“明天去学校”这件事是否属实。", "是否": "语域：“是否”是书面语，口语的句末附加问句应用“对不对”。"}, "sentence_index": 0, "correct_answer": "对不对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你帮我开一下门，对不对？", "explanation": "这里应该用〈好吗〉。“对不对”用于确认所说的事实，不用于请求别人做事；请求应说〈好吗〉。"}, {"text": "——你是小王的朋友吗？——对不对。", "explanation": "这里应该用〈是的〉。“对不对”是正反形式，不能单独用来肯定回答；肯定回答应说〈是的〉。"}, {"text": "你为什么迟到，对不对？", "explanation": "这里不能把“对不对”附在疑问词提问后面。“对不对”用于求证陈述是否属实，应直接用疑问词提问，不加〈对不对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对不对", "is_correct": true, "explanation": "对不对：句末附加问句，请对方确认“昨天没来上课”是否属实。"}, {"text": "能不能", "is_correct": false, "explanation": "语义：“能不能”问能力或许可，不是确认昨天发生的事实。"}, {"text": "要不要", "is_correct": false, "explanation": "语义：“要不要”问意愿或邀请，与“你昨天没来上课”的叙述无关。"}, {"text": "与否", "is_correct": false, "explanation": "语域：“与否”是书面语，口语的句末附加问句不用“与否”。"}], "explanations": {"对不对": "对不对：句末附加问句，请对方确认“昨天没来上课”是否属实。", "能不能": "语义：“能不能”问能力或许可，不是确认昨天发生的事实。", "要不要": "语义：“要不要”问意愿或邀请，与“你昨天没来上课”的叙述无关。", "与否": "语域：“与否”是书面语，口语的句末附加问句不用“与否”。"}, "sentence_index": 6, "correct_answer": "对不对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你明天早点来，对不对？", "explanation": "这里不能把“对不对”附在请求句末。“对不对”用于求证陈述是否属实，请求应说〈好不好〉。"}, {"text": "谢谢你帮我，对不对？", "explanation": "这里不能把“对不对”附在感谢句后。感谢不是待求证的陈述，应直接表达感谢，不加〈对不对〉。"}, {"text": "谁来打扫，对不对？", "explanation": "这里不能把“对不对”附在疑问词提问后面。“对不对”只用于求证陈述，应直接用疑问词提问，不加〈对不对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下午开会，对不对吗？", "corrected_sentence": "我们下午开会，对不对？", "error_description": "“对不对”作句末附加问句时，句尾不能再加“吗”；应说“……，对不对？”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天不舒服，对不对不？", "corrected_sentence": "他今天不舒服，对不对？", "error_description": "错误形式：“对不对不”；正确形式：“对不对”。句末附加问句“对不对”后面不能再加“不”，多出的“不”使句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '218d8b30-4b8c-4810-87ae-4cf061d522d3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
