INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和你家的门面对面的那一家。", "primary_collocate": null, "pronunciation": "duì mén", "ipa": "tweɪ˥˩ mən˧˥", "syllable_count": 2, "sentences": [{"text": "我家对门是一家小面馆。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门家的灯一直亮着。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去对门借了一点盐。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门最近在装修，很吵。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门的门口放着一双红鞋。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在我对门，上楼就能看到。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门家养了一只大白狗。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敲了对门的门，没有人开。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天对门请我们去吃饭。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对门有人在弹钢琴。", "target_word": "对门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对门儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "门面对面的那一家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97239, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对门", "is_correct": true, "explanation": "正确：「对门」指门对门的那一家，与「我家对门是一家小面馆」的位置关系相符。"}, {"text": "对头", "is_correct": false, "explanation": "语义：「对头」指仇敌，不能指家门对面的人家或店铺。"}, {"text": "对方", "is_correct": false, "explanation": "语义：「对方」指对手或对立的一方，不指房屋的位置。"}, {"text": "对桌", "is_correct": false, "explanation": "搭配：「对桌」指隔着桌子的人，不能用来指一家店铺的位置。"}], "explanations": {"对门": "正确：「对门」指门对门的那一家，与「我家对门是一家小面馆」的位置关系相符。", "对头": "语义：「对头」指仇敌，不能指家门对面的人家或店铺。", "对方": "语义：「对方」指对手或对立的一方，不指房屋的位置。", "对桌": "搭配：「对桌」指隔着桌子的人，不能用来指一家店铺的位置。"}, "sentence_index": 0, "correct_answer": "对门"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试时，对门坐着我的同学。", "explanation": "这里应该用「对面」。「对门」指和你家门面对面的那一家，不指考场中坐在对面的人。"}, {"text": "他每天早上都对门一次。", "explanation": "「对门」是名词，指和你家门面对面的那一家，不能当动词用。"}, {"text": "这次比赛他是我的对门。", "explanation": "「对门」只指邻居，不能指比赛中的对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对门", "is_correct": true, "explanation": "正确：「对门家养了一只大白狗」指住在对门的人家，符合语境。"}, {"text": "对头", "is_correct": false, "explanation": "语义：「对头」指仇敌，与「养狗」的日常生活不合。"}, {"text": "对手", "is_correct": false, "explanation": "语义：「对手」指竞争者，不能指养狗的人家。"}, {"text": "对联", "is_correct": false, "explanation": "语义：「对联」是贴在门两边的字，不是人家，不能养狗。"}], "explanations": {"对门": "正确：「对门家养了一只大白狗」指住在对门的人家，符合语境。", "对头": "语义：「对头」指仇敌，与「养狗」的日常生活不合。", "对手": "语义：「对手」指竞争者，不能指养狗的人家。", "对联": "语义：「对联」是贴在门两边的字，不是人家，不能养狗。"}, "sentence_index": 6, "correct_answer": "对门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛，对门的队员都很高。", "explanation": "这里应该用「对方」。「对门」指邻居，不指比赛中的对方球队。"}, {"text": "这次谈判，他对门了很多条件。", "explanation": "这里应该用「提出」。「对门」是名词，不能当动词用。"}, {"text": "对门这个问题，你怎么看？", "explanation": "这里应该用「对于」。「对门」指和你家门面对面的那一家，不能用来引出话题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家对门着一家小超市。", "corrected_sentence": "他家对门开着一家小超市。", "error_description": "「对门」是名词，不能带「着」当动词用，应加动词「开」：「对门开着一家小超市」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家对门着一位老师。", "corrected_sentence": "我家对门住着一位老师。", "error_description": "「对门」是名词，不能带「着」当动词用，应加动词「住」：「对门住着一位老师」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
