INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中国古代官名，掌管文书政务的高级官员。", "primary_collocate": null, "pronunciation": "shàng shū", "ipa": "ʂaŋ˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "唐朝的尚书负责管理国家的文书和政务。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在朝中做尚书，每天处理很多文书。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皇帝很信任这位管文书的尚书，把政务交给他。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的尚书是高级官员，地位很高。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位尚书写的文书，皇帝每一份都认真看。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明朝有六部，每个部都有一位尚书。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吏部的老尚书年纪大了，向皇帝请求回家养老。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "尚书把大臣们的意见写成文书交给皇帝。", "target_word": "尚书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书很用功，后来当上了六部的尚书。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "尚书每天早上到宫里，帮皇帝处理政务。", "target_word": "尚书", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "尚書", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "古代掌管文书政务的高级官员（官名）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尚书", "is_correct": true, "explanation": "正确：“尚书”是唐代中央的高级官员，负责管理文书和政务。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民不管理国家文书和政务，与句子描述的职责不符。"}, {"text": "船", "is_correct": false, "explanation": "语义：“船”是器物，不能负责管理国家的文书和政务。"}, {"text": "老板", "is_correct": false, "explanation": "语域：“老板”是现代用语，用在唐朝官制的叙述中不合语域。"}], "explanations": {"尚书": "正确：“尚书”是唐代中央的高级官员，负责管理文书和政务。", "农民": "语义：农民不管理国家文书和政务，与句子描述的职责不符。", "船": "语义：“船”是器物，不能负责管理国家的文书和政务。", "老板": "语域：“老板”是现代用语，用在唐朝官制的叙述中不合语域。"}, "sentence_index": 0, "correct_answer": "尚书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地方做尚书，管理一个郡的百姓。", "explanation": "这里应该用〈太守〉。“尚书”是朝中掌管政务的中央官，管理一郡的地方事务要用〈太守〉。"}, {"text": "他担任尚书，负责监察百官，向皇帝报告官员的过失。", "explanation": "这里应该用〈御史〉。“尚书”掌管政务和文书，监察百官、弹劾过失要用〈御史〉。"}, {"text": "他是一位尚书，带兵打仗，保卫边疆。", "explanation": "这里应该用〈将军〉。“尚书”是文官，带兵打仗、保卫边疆要用〈将军〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尚书", "is_correct": true, "explanation": "正确：“尚书”是朝中的高级官员，吏部的老尚书请求回家养老。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不是吏部官员，不会向皇帝请求回家养老。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”不能向皇帝请求回家养老，句子主语指的是人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命之物，不能向皇帝请求回家养老。"}], "explanations": {"尚书": "正确：“尚书”是朝中的高级官员，吏部的老尚书请求回家养老。", "歌手": "语义：歌手不是吏部官员，不会向皇帝请求回家养老。", "猫": "语义：“猫”不能向皇帝请求回家养老，句子主语指的是人。", "石头": "语义：“石头”是无生命之物，不能向皇帝请求回家养老。"}, "sentence_index": 6, "correct_answer": "尚书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在县里做尚书，负责收税和审案。", "explanation": "这里应该用〈县令〉。“尚书”是中央的高级官员，管一县的收税审案要用〈县令〉。"}, {"text": "他在御膳房做尚书，每天为皇帝准备饭菜。", "explanation": "这里应该用〈御厨〉。“尚书”是朝中掌管政务的高官，在御膳房为皇帝做饭要用〈御厨〉。"}, {"text": "他是宫里的尚书，每天为皇帝诊脉。", "explanation": "这里应该用〈太医〉。“尚书”是朝中掌管政务的官员，为皇帝诊脉要用〈太医〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝中有两本尚书，共同管理文书。", "corrected_sentence": "朝中有两位尚书，共同管理文书。", "error_description": "量词错误：“尚书”指官员，应用量词“位”。“本”用于书籍，不能说“两本尚书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当着三年尚书，每天到宫里处理政务。", "corrected_sentence": "他当过三年尚书，每天到宫里处理政务。", "error_description": "体标错误：说做过某官职一段时间的经历，“当”后要用“过”，不能用表示持续的“着”。应说“当过三年尚书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
