INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97249, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "打仗时用的，能发射出去的东西。", "primary_collocate": null, "pronunciation": "dàn yào", "ipa": "tan˥˩ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "士兵的弹药用完了，只好撤退。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们背着很多弹药往山上走。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库里放着一批新送来的弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战斗打了三天，双方的弹药都不多了。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有足够的弹药，不敢继续打仗。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车把弹药运到了前线。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，弹药和粮食一样重要。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队正在检查仓库里的弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵打完了所有的弹药，等着补给。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前线缺少弹药，后方连夜送了过去。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "弹药库", "label": "复合"}], "register": "中性", "sense_fingerprint": "打仗时士兵用的、能发射出去的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹药", "is_correct": true, "explanation": "正确：战时用的枪炮弹药，与“用完了”和“撤退”相合。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不能“用完”，“士兵的学生用完了”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不是战时消耗品，与“撤退”没有关系，读来不通。"}, {"text": "信件", "is_correct": false, "explanation": "搭配：“用完”多说纸张、物资，不说信件用完，且与“撤退”无关。"}], "explanations": {"弹药": "正确：战时用的枪炮弹药，与“用完了”和“撤退”相合。", "学生": "语义：学生是人，不能“用完”，“士兵的学生用完了”说不通。", "课本": "语义：课本不是战时消耗品，与“撤退”没有关系，读来不通。", "信件": "搭配：“用完”多说纸张、物资，不说信件用完，且与“撤退”无关。"}, "sentence_index": 0, "correct_answer": "弹药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在矿山里用了很多弹药。", "explanation": "这里应该用〈炸药〉。开矿用的是炸药，弹药是枪炮用的武器弹，不用于开矿。"}, {"text": "医生给病人开了一些弹药。", "explanation": "这里应该用〈药品〉。给病人开的是药品，弹药是枪炮用的武器装备，不能用来治病。"}, {"text": "春节晚上，大家在院子里放弹药。", "explanation": "这里应该用〈烟花〉。春节放的是烟花，弹药是武器用的，不用来庆祝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹药", "is_correct": true, "explanation": "正确：弹药是战争必需的物资，与“战争中”和“和粮食一样重要”相合。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是战争物资，放在“战争中”的语境里与粮食相比说不通。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不属于战争必需品，与“战争中”和粮食的比较不相合。"}, {"text": "派对", "is_correct": false, "explanation": "语义：派对是娱乐活动，不是战争中必需的物资，不能和粮食相比。"}], "explanations": {"弹药": "正确：弹药是战争必需的物资，与“战争中”和“和粮食一样重要”相合。", "玩具": "语义：玩具不是战争物资，放在“战争中”的语境里与粮食相比说不通。", "游戏": "语义：游戏不属于战争必需品，与“战争中”和粮食的比较不相合。", "派对": "语义：派对是娱乐活动，不是战争中必需的物资，不能和粮食相比。"}, "sentence_index": 6, "correct_answer": "弹药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民每天给猪喂弹药。", "explanation": "这里应该用〈饲料〉。饲料用来喂牲畜，弹药是枪炮用的，不能拿来喂猪。"}, {"text": "工人正在更换机器的弹药。", "explanation": "这里应该用〈零件〉。零件是机器上的部件，弹药是枪炮用的，不能用来更换机器。"}, {"text": "妈妈在厨房里揉弹药。", "explanation": "这里应该用〈面粉〉。揉的是面粉，弹药是枪炮用的，不能用来揉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车运来了三个弹药。", "corrected_sentence": "卡车运来了三箱弹药。", "error_description": "量词错误：“弹药”前应用“箱”（或“批”），不能用“个”。“个”是通用量词，不适合数成批的弹药。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卡车运来了一批地弹药。", "corrected_sentence": "卡车运来了一批弹药。", "error_description": "结构助词错误：“地”用于修饰动词，不能修饰名词“弹药”，应说“一批弹药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
