INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "枪炮等武器所用的子弹、炮弹、手榴弹等的总称。", "primary_collocate": null, "pronunciation": "dàn yào", "ipa": "tan˥˩ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "弹药包括子弹、炮弹和手榴弹。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个弹药库专门存放枪炮用的弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在工厂里生产枪炮和弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里展出着很多旧时代的弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批弹药有子弹，也有炮弹。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存放弹药的地方必须远离城市，以免发生危险。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在山洞里发现了大量枪支和弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的枪要用不同的弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须小心保管弹药。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在军工厂负责检查弹药的质量。", "target_word": "弹药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "弹药库", "label": "复合"}], "register": "中性", "sense_fingerprint": "子弹、炮弹、手榴弹等武器用弹的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弹药", "is_correct": true, "explanation": "正确：“弹药”是子弹、炮弹、手榴弹等的总称，与“包括”后的并列项相合。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品不是武器，子弹、炮弹、手榴弹不属于食品，无法这样概括。"}, {"text": "服装", "is_correct": false, "explanation": "搭配：“包括”后面的并列项须是同类事物，“服装”与子弹、炮弹不同类。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不是武器，与子弹、炮弹、手榴弹无法并列概括。"}], "explanations": {"弹药": "正确：“弹药”是子弹、炮弹、手榴弹等的总称，与“包括”后的并列项相合。", "食品": "语义：食品不是武器，子弹、炮弹、手榴弹不属于食品，无法这样概括。", "服装": "搭配：“包括”后面的并列项须是同类事物，“服装”与子弹、炮弹不同类。", "乐器": "语义：乐器不是武器，与子弹、炮弹、手榴弹无法并列概括。"}, "sentence_index": 0, "correct_answer": "弹药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在公路边用弹药开山。", "explanation": "这里应该用〈炸药〉。开山用的是炸药，弹药是武器用的，不能用来爆破。"}, {"text": "过年时，孩子们喜欢放弹药。", "explanation": "这里应该用〈鞭炮〉。过年放的是鞭炮，弹药是武器装备，不用于节日燃放。"}, {"text": "这种弹药用来制造烟花。", "explanation": "这里应该用〈火药〉。制造烟花用的是火药，弹药是装进武器里的成品，不能当烟花的原料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "弹药", "is_correct": true, "explanation": "正确：枪支和弹药都是可以在山洞里搜获的武器物资，与“发现了大量”相合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳不能在山洞里被“发现了大量”，与语境不符。"}, {"text": "学期", "is_correct": false, "explanation": "搭配：“发现大量”后接具体可见之物，“学期”是抽象的时间，不能说“大量发现”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是可以被大量搜获的东西，与“枪支”并列读来不通。"}], "explanations": {"弹药": "正确：枪支和弹药都是可以在山洞里搜获的武器物资，与“发现了大量”相合。", "太阳": "语义：太阳不能在山洞里被“发现了大量”，与语境不符。", "学期": "搭配：“发现大量”后接具体可见之物，“学期”是抽象的时间，不能说“大量发现”。", "老师": "语义：老师是人，不是可以被大量搜获的东西，与“枪支”并列读来不通。"}, "sentence_index": 6, "correct_answer": "弹药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里准备了很多弹药。", "explanation": "这里应该用〈食物〉。弹药是枪炮用的武器装备，不能拿来做饭。"}, {"text": "农民们把弹药运进了田里。", "explanation": "这里应该用〈化肥〉。化肥用于田间施肥，弹药是枪炮用的，不能撒进田里。"}, {"text": "她每天早上用弹药化妆。", "explanation": "这里应该用〈化妆品〉。化妆品用于美容，弹药是枪炮用的，不能用来化妆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里堆着很多弹药们。", "corrected_sentence": "仓库里堆着很多弹药。", "error_description": "复数错误：“弹药”是集合名词，不能加“们”表示复数，应说“很多弹药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本弹药已经运到了前线。", "corrected_sentence": "这批弹药已经运到了前线。", "error_description": "量词错误：“弹药”的量词应用“批”，不能用“本”（“本”用于书册）。应说“这批弹药”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
