INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97251, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过了一会儿又放进去。", "primary_collocate": null, "pronunciation": "hòu jiā", "ipa": "xoʊ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "盐要后加，不然肉会变硬。", "target_word": "后加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做汤时，青菜要后加。", "target_word": "后加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肉先煮十分钟，青菜后加。", "target_word": "后加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼先煎一会儿，豆腐后加。", "target_word": "后加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭快好时，把鸡蛋后加进去。", "target_word": "后加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药材要后加，煮太久会没有味道。", "target_word": "后加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖可以后加，不用一开始就放。", "target_word": "后加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤开了以后，把虾后加进去。", "target_word": "后加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶要后加，不能和茶叶一起煮。", "target_word": "后加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蘑菇容易熟，请你后加。", "target_word": "后加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "后加了", "label": "体标"}, {"form": "后加过", "label": "体标"}], "register": "中性", "sense_fingerprint": "做饭时过一会儿再放入", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后加", "is_correct": true, "explanation": "正确：「后加」指过一会儿再放入，与「不然肉会变硬」的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：盐在这里是调味品，「盐要煮」与调味的语境不符。"}, {"text": "冻", "is_correct": false, "explanation": "语义：盐不能被「冻」，与做饭调味的语境不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」的对象不能是盐，说「盐要切」不成立。"}], "explanations": {"后加": "正确：「后加」指过一会儿再放入，与「不然肉会变硬」的语境相符。", "煮": "语义：盐在这里是调味品，「盐要煮」与调味的语境不符。", "冻": "语义：盐不能被「冻」，与做饭调味的语境不通。", "切": "搭配：「切」的对象不能是盐，说「盐要切」不成立。"}, "sentence_index": 0, "correct_answer": "后加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上把牙刷后加在抽屉里。", "explanation": "语义：「后加」是添加的动作，不能表示把牙刷存放在抽屉里；存放要用〈放〉。"}, {"text": "他把水杯后加在衣柜里。", "explanation": "语义：「后加」是添加的动作，不能表示把水杯存放在衣柜里；存放要用〈放〉。"}, {"text": "我一直把钥匙后加在口袋里。", "explanation": "语义：「后加」是添加的动作，不能表示把东西放在口袋里存放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后加", "is_correct": true, "explanation": "正确：「后加」指过一会儿再放入，与「不用一开始就放」的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：糖不能被「洗」，「糖可以洗」说不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」与「不用一开始就放」的语境矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：糖不能唱，「糖可以唱」荒谬。"}], "explanations": {"后加": "正确：「后加」指过一会儿再放入，与「不用一开始就放」的语境相符。", "洗": "搭配：糖不能被「洗」，「糖可以洗」说不通。", "扔": "语义：「扔」与「不用一开始就放」的语境矛盾。", "唱": "语义：糖不能唱，「糖可以唱」荒谬。"}, "sentence_index": 6, "correct_answer": "后加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份名单后加在书架上。", "explanation": "语义：「后加」是添加的动作，不能表示把名单放在书架上存放；存放要用〈放〉。"}, {"text": "请你把蘑菇后加在盘子边上。", "explanation": "语义：「后加」是添加的动作，不能表示把蘑菇摆在盘子边上；摆放要用〈放〉。"}, {"text": "蘑菇容易熟，请你把它后加了二十分钟。", "explanation": "这里应该用〈煮〉。后加表示过一会儿再放入，不表示持续的时长；时长要用〈煮〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "葱花要后加出去，不然颜色会变深。", "corrected_sentence": "葱花要后加进去，不然颜色会变深。", "error_description": "趋向补语错误：把东西加入锅内要用「进去」，说「后加出去」是错误的，应为「后加进去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蔬菜要后加着，煮太久会变软。", "corrected_sentence": "蔬菜要后加，煮太久会变软。", "error_description": "「后加」之后不能接「着」：「后加」表示一次性放入的动作，不表示持续的状态，应说「要后加」，不能说「要后加着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
