INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想了很久，最后找到了答案。", "primary_collocate": null, "pronunciation": "dé chū", "ipa": "tɤ˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "想了很久，他终于得出了答案。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了一晚上，才得出这个办法。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她得出的答案和我的不一样。", "target_word": "得出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题太难，我半天也没得出答案。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，得出了一个好主意。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家商量了一下午，得出了办法。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了又想，终于得出了结果。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明做了很久，终于得出了答案。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想一想，能得出什么办法？", "target_word": "得出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想了很久，最后得出一个解法。", "target_word": "得出", "complexity_tier": "T3", "furigana": "tā xiǎng le hěn jiǔ, zuìhòu dé chū yí gè jiěfǎ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "得出了", "label": "体标"}, {"form": "得出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "思考很久后想出答案或办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得出", "is_correct": true, "explanation": "得出：经思考找到答案，与“答案”搭配，句意通顺。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能说“发明答案”。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”不能与“答案”搭配，句子不通。"}, {"text": "挂断", "is_correct": false, "explanation": "搭配：“挂断”的对象是电话或通话，不能用于“答案”。"}], "explanations": {"得出": "得出：经思考找到答案，与“答案”搭配，句意通顺。", "发明": "语义：“发明”指创造新事物，不能说“发明答案”。", "吃掉": "搭配：“吃掉”不能与“答案”搭配，句子不通。", "挂断": "搭配：“挂断”的对象是电话或通话，不能用于“答案”。"}, "sentence_index": 0, "correct_answer": "得出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快得出了一双鞋。", "explanation": "这里应该用〈买〉。得出指经思考想出答案或办法，「鞋」这类实物要用买。"}, {"text": "他得出了一瓶牛奶。", "explanation": "这里应该用〈拿出〉。得出用于答案、办法，「牛奶」这类实物要用拿出。"}, {"text": "这次考试他得出了好成绩。", "explanation": "这里应该用〈取得〉。得出用于答案、办法，“成绩”要用取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得出", "is_correct": true, "explanation": "得出：经反复思考得到结果，与“结果”搭配，句意通顺。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”指使物体破裂，不能用于“结果”。"}, {"text": "擦干", "is_correct": false, "explanation": "搭配：“擦干”的对象是液体或表面，不能用于“结果”。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体着火，与“结果”的意思无关。"}], "explanations": {"得出": "得出：经反复思考得到结果，与“结果”搭配，句意通顺。", "摔碎": "语义：“摔碎”指使物体破裂，不能用于“结果”。", "擦干": "搭配：“擦干”的对象是液体或表面，不能用于“结果”。", "点燃": "语义：“点燃”指使物体着火，与“结果”的意思无关。"}, "sentence_index": 6, "correct_answer": "得出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于得出了钥匙。", "explanation": "这里应该用〈找到〉。得出指经思考得到答案或办法，具体的东西要用找到。"}, {"text": "他一用力，得出了一声巨响。", "explanation": "这里应该用〈发出〉。得出用于答案、办法，“声音”要用发出。"}, {"text": "她从包里得出了证件。", "explanation": "这里应该用〈拿出〉。得出用于答案、办法，从包里取东西要用拿出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想了很久，终于得出了一个颜色。", "corrected_sentence": "他想了很久，终于得出了一个办法。", "error_description": "搭配错误：「得出」指经思考得到答案、办法，不能搭配「颜色」；应为「得出了一个办法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我琢磨了一个晚上，终于得出着一个方案。", "corrected_sentence": "我琢磨了一个晚上，终于得出了一个方案。", "error_description": "“着”表示持续，而“得出”是一次完成的结果，不能加“着”；应为“得出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
