INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97256, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经推算、分析得到结论或结果。", "primary_collocate": null, "pronunciation": "dé chū", "ipa": "tɤ˧˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师根据数据得出了结论。", "target_word": "得出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个实验得出的结果很有意思。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们算了三遍，得出的数字一样。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员得出了一个重要结论。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这些材料中，我们得出了什么结论？", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他分析了公司的情况，得出了结果。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他根据地图和时间推算，得出了两地的距离。", "target_word": "得出", "complexity_tier": "T3", "furigana": "tā gēnjù dìtú hé shíjiān tuīsuàn, dé chū le liǎng dì de jùlí.", "sentence_source": "generated"}, {"text": "大家比较了两种方法，得出了不同结果。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查得出的结果让人吃惊。", "target_word": "得出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生看了检查报告，得出了判断。", "target_word": "得出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "得出了", "label": "体标"}, {"form": "得出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "经分析推算得到结论或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6dc540-0643-4325-bf37-66b94a5ab4e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得出", "is_correct": true, "explanation": "得出：经推算、分析得到结论，与“结论”搭配，句意通顺。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能用来得到“结论”。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是可以吃的东西，不能说“吃掉结论”。"}, {"text": "听说", "is_correct": false, "explanation": "语义：「听说」指听闻消息，与「根据数据」得出结论的推导过程不符。"}], "explanations": {"得出": "得出：经推算、分析得到结论，与“结论”搭配，句意通顺。", "发明": "语义：“发明”指创造新事物，不能用来得到“结论”。", "吃掉": "搭配：“吃掉”的宾语应是可以吃的东西，不能说“吃掉结论”。", "听说": "语义：「听说」指听闻消息，与「根据数据」得出结论的推导过程不符。"}, "sentence_index": 0, "correct_answer": "得出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨师得出了一道好菜。", "explanation": "这里应该用〈做出〉。得出用于结论、结果，「菜」要用做出。"}, {"text": "记者得出了一张照片。", "explanation": "这里应该用〈拍〉。得出用于结论、结果，「照片」要用拍。"}, {"text": "工人们在矿里得出了一块金子。", "explanation": "这里应该用〈挖出〉。得出指经推算、分析得到结论，具体的实物要用挖出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得出", "is_correct": true, "explanation": "得出：经推算得到结果，与“距离”搭配，句意通顺。"}, {"text": "寄出", "is_correct": false, "explanation": "语义：“寄出”指邮寄物品，不能用于推算得到的“距离”。"}, {"text": "拆开", "is_correct": false, "explanation": "搭配：“拆开”的对象是包装或信件，不能说“拆开两地的距离”。"}, {"text": "切开", "is_correct": false, "explanation": "搭配：“切开”要求有形的物体作宾语，“距离”是抽象概念。"}], "explanations": {"得出": "得出：经推算得到结果，与“距离”搭配，句意通顺。", "寄出": "语义：“寄出”指邮寄物品，不能用于推算得到的“距离”。", "拆开": "搭配：“拆开”的对象是包装或信件，不能说“拆开两地的距离”。", "切开": "搭配：“切开”要求有形的物体作宾语，“距离”是抽象概念。"}, "sentence_index": 6, "correct_answer": "得出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于得出了朋友的一本书。", "explanation": "这里应该用〈借〉。得出用于结论、结果，「书」这类实物要用借。"}, {"text": "她得出了一个新称号。", "explanation": "这里应该用〈获得〉。得出用于结论、结果，“称号”要用获得。"}, {"text": "公司得出了一款新产品。", "explanation": "这里应该用〈推出〉。得出用于结论、结果，“新产品”要用推出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们根据这个实验得出了一个颜色。", "corrected_sentence": "我们根据这个实验得出了一个结论。", "error_description": "搭配错误：「得出」用于结论、结果等，不能搭配「颜色」；应为「得出了一个结论」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们比较了两份报告，得出着一个判断。", "corrected_sentence": "他们比较了两份报告，得出了一个判断。", "error_description": "“着”表示持续，而“得出”是一次完成的结果，不能加“着”；应为“得出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d60076-5c2e-437a-a6bd-2409b9e85bfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
