INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97257, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很难受，可是还是忍着，不叫出来。", "primary_collocate": null, "pronunciation": "rěn shòu", "ipa": "ʐən˨˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "牙疼得厉害，他还是忍受着，没有出声。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生打针的时候，小明忍受着疼痛，没有哭。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肚子很疼，却忍受着不叫出来。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伤口很痛，他咬着牙忍受，一句话也不说。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手术后伤口很疼，病人一直忍受着。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热水烫了他的脚，他忍受着没喊疼。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拔牙那么疼，你怎么能忍受得了？", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然腿很疼，他还是忍受着走完了路。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸胃疼了一晚上，一直忍受着没有叫我们。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她疼得流眼泪，但是忍受着不让别人知道。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忍受了", "label": "体标"}, {"form": "忍受着", "label": "体标"}, {"form": "忍受过", "label": "体标"}, {"form": "忍受不了", "label": "复合"}, {"form": "难以忍受", "label": "复合"}], "register": "通用", "sense_fingerprint": "身体很难受却忍着不喊叫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忍受", "is_correct": true, "explanation": "正确。“忍受”表示身体难受却忍着，与“没有出声”的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：牙疼时不会去欣赏，“欣赏”表示喜爱和赏识，与句中的痛苦矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”会发出声音，与“没有出声”矛盾。"}, {"text": "讨厌", "is_correct": false, "explanation": "配价：“讨厌”需要带明确的宾语，句中缺少可讨厌的对象，搭配不成立。"}], "explanations": {"忍受": "正确。“忍受”表示身体难受却忍着，与“没有出声”的语境相符。", "欣赏": "语义：牙疼时不会去欣赏，“欣赏”表示喜爱和赏识，与句中的痛苦矛盾。", "唱": "语义：“唱”会发出声音，与“没有出声”矛盾。", "讨厌": "配价：“讨厌”需要带明确的宾语，句中缺少可讨厌的对象，搭配不成立。"}, "sentence_index": 0, "correct_answer": "忍受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他忍受了眼泪，没有哭出来。", "explanation": "这里应该用〈忍住〉。忍受承受的是痛苦，眼泪要说忍住，不说忍受眼泪。"}, {"text": "他忍受着按摩带来的舒服。", "explanation": "这里应该用〈享受〉。忍受表示勉强承受痛苦，按摩带来的舒服是愉快的，要用享受。"}, {"text": "她忍受着窗外的风景。", "explanation": "这里应该用〈欣赏〉。忍受表示勉强承受不如意的事，窗外的风景令人愉悦，要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忍受", "is_correct": true, "explanation": "正确。“忍受得了”表示能够承受，与“拔牙那么疼”的语境相符。"}, {"text": "表达", "is_correct": false, "explanation": "语义：“表达得了”指能说清楚，与“拔牙的疼”不搭，句子问的是能否承受痛苦。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”指愉快地受用，拔牙的疼不能享受，句子问的是能否承受痛苦。"}, {"text": "证明", "is_correct": false, "explanation": "语义：“证明得了”指能证实，与“拔牙那么疼”的语境不符。"}], "explanations": {"忍受": "正确。“忍受得了”表示能够承受，与“拔牙那么疼”的语境相符。", "表达": "语义：“表达得了”指能说清楚，与“拔牙的疼”不搭，句子问的是能否承受痛苦。", "享受": "语义：“享受”指愉快地受用，拔牙的疼不能享受，句子问的是能否承受痛苦。", "证明": "语义：“证明得了”指能证实，与“拔牙那么疼”的语境不符。"}, "sentence_index": 6, "correct_answer": "忍受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她忍受着背上的暖意，心里很安静。", "explanation": "这里应该用〈感受〉。忍受表示勉强承受痛苦，背上的暖意是舒服的，要用感受。"}, {"text": "我们在草地上忍受了午餐。", "explanation": "这里应该用〈享用〉。忍受表示勉强承受，午餐是愉快的享受，吃东西要用享用。"}, {"text": "登上山顶后，我们忍受着美丽的风景。", "explanation": "这里应该用〈欣赏〉。忍受强调勉强承受痛苦，美丽的风景令人愉快，要用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "伤口这么疼，你怎么能忍受了得？", "corrected_sentence": "伤口这么疼，你怎么能忍受得了？", "error_description": "错误：“了得”顺序颠倒。正确：“忍受得了”，可能补语是“得了”，“得”在前，“了”在后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她咬着牙，忍受了着疼痛，一声不吭。", "corrected_sentence": "她咬着牙，忍受着疼痛，一声不吭。", "error_description": "错误：“了”和“着”同时用在动词“忍受”之后，两个动态助词不能并用。正确：“忍受着”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
