INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "勉强承受痛苦、困难或不如意的事。", "primary_collocate": null, "pronunciation": "rěn shòu", "ipa": "ʐən˨˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他每天都要忍受很大的噪音。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我再也无法忍受这么冷的房间了。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她忍受了十年的孤独，终于回到了家乡。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天没有空调，我们只能忍受这种闷热。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板脾气很坏，同事们都在忍受他。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么要忍受这样不公平的对待？", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天很冷，你得学会忍受寒冷。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忍受着生活的困难，从不向别人抱怨。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我实在忍受不了邻居半夜唱歌。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了孩子，她忍受了很多委屈。", "target_word": "忍受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "忍受了", "label": "体标"}, {"form": "忍受着", "label": "体标"}, {"form": "忍受过", "label": "体标"}, {"form": "忍受不了", "label": "复合"}, {"form": "难以忍受", "label": "复合"}], "register": "通用", "sense_fingerprint": "勉强承受痛苦、困难或不如意的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "忍受", "is_correct": true, "explanation": "正确。“忍受”表示勉强承受不愉快的事，与“很大的噪音”搭配，符合“每天都要”的语境。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示喜爱和赏识，噪音令人烦躁，不能欣赏。"}, {"text": "喜爱", "is_correct": false, "explanation": "语义：“喜爱”表示喜欢，与“每天都要”承受噪音的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能和“噪音”搭配。"}], "explanations": {"忍受": "正确。“忍受”表示勉强承受不愉快的事，与“很大的噪音”搭配，符合“每天都要”的语境。", "欣赏": "语义：“欣赏”表示喜爱和赏识，噪音令人烦躁，不能欣赏。", "喜爱": "语义：“喜爱”表示喜欢，与“每天都要”承受噪音的语境相反。", "吃": "搭配：“吃”不能和“噪音”搭配。"}, "sentence_index": 0, "correct_answer": "忍受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在音乐会上忍受着美妙的旋律。", "explanation": "这里应该用〈享受〉。忍受表示勉强承受不如意的事，美妙的旋律令人愉快，要用享受。"}, {"text": "假期里，他坐在窗边忍受着香浓的咖啡。", "explanation": "这里应该用〈品尝〉。忍受表示勉强承受不如意的事，香浓的咖啡令人愉快，要用品尝。"}, {"text": "这笔费用由公司忍受。", "explanation": "这里应该用〈承担〉。忍受强调勉强承受痛苦或困难，费用由公司负担要用承担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忍受", "is_correct": true, "explanation": "正确。“忍受”表示勉强承受困难，与“寒冷”搭配，符合“你得学会”的语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐意接受，与“你得学会”所说的困难语境相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，寒冷无法被拒绝，句子强调要适应它。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”通常接声音、光或热，不说发出寒冷。"}], "explanations": {"忍受": "正确。“忍受”表示勉强承受困难，与“寒冷”搭配，符合“你得学会”的语境。", "欢迎": "语义：“欢迎”表示乐意接受，与“你得学会”所说的困难语境相反。", "拒绝": "语义：“拒绝”表示不接受，寒冷无法被拒绝，句子强调要适应它。", "发出": "搭配：“发出”通常接声音、光或热，不说发出寒冷。"}, "sentence_index": 6, "correct_answer": "忍受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客们忍受着湖边的风景。", "explanation": "这里应该用〈欣赏〉。忍受表示勉强承受不如意的事，美丽的风景令人愉悦，要用欣赏。"}, {"text": "他们在海边忍受了新鲜的海鲜。", "explanation": "这里应该用〈享用〉。忍受表示勉强承受，新鲜的海鲜是美味的，吃东西要用享用。"}, {"text": "这次旅行让我们忍受了很多快乐。", "explanation": "这里应该用〈收获〉。忍受强调勉强承受，快乐是令人愉快的，要用收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种刺鼻的气味，我实在忍受了不了。", "corrected_sentence": "这种刺鼻的气味，我实在忍受不了。", "error_description": "错误：“了”插在“忍受”和“不了”之间。正确：“忍受不了”，“不了”是可能补语，“了”不能放在补语前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这份委屈忍受下了来。", "corrected_sentence": "他把这份委屈忍受下来了。", "error_description": "错误：补语“下来”被拆开，“了”插在“下”和“来”之间。正确：“忍受下来了”，“下来”是一个整体的趋向补语，中间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
