INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97261, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "和你结了婚的那个人。", "primary_collocate": null, "pronunciation": "ài rén", "ipa": "aɪ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我爱人是医生，每天工作很忙。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和爱人一起生活了二十年。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我带着爱人和孩子去公园玩。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的爱人在外地工作，一个月回家一次。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你爱人今天怎么没来参加聚会？", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张很爱自己的爱人，每天都给她做饭。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚纪念日那天，我给爱人买了一件新衣服。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱人是中学老师，教语文。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱人做的菜特别好吃。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚以后，他把工资都交给爱人。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位爱人", "label": "量词"}, {"form": "一个爱人", "label": "量词"}, {"form": "愛人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "和自己结了婚的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97261, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确答案。ài rén，指和你结了婚的人。"}, {"text": "大人", "is_correct": false, "explanation": "dà 比 ài 多一个声母 d，声调相同，意思是大人（成年人）。"}, {"text": "待人", "is_correct": false, "explanation": "dài 比 ài 多一个声母 d，意思是对待别人。"}, {"text": "矮人", "is_correct": false, "explanation": "ǎi（第三声）与 ài（第四声）声调不同，意思是个子矮的人。"}], "explanations": {"爱人": "正确答案。ài rén，指和你结了婚的人。", "大人": "dà 比 ài 多一个声母 d，声调相同，意思是大人（成年人）。", "待人": "dài 比 ài 多一个声母 d，意思是对待别人。", "矮人": "ǎi（第三声）与 ài（第四声）声调不同，意思是个子矮的人。"}, "sentence_index": null, "correct_answer": "爱人"}, "level_3": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确。“爱人”指配偶，与“我……是医生”的语境相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能是医生，句子说的是“我”的配偶。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能当医生，与句子的主语语境不符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能作“是医生”的主语，与“医生”搭配不当。"}], "explanations": {"爱人": "正确。“爱人”指配偶，与“我……是医生”的语境相符。", "小狗": "语义：小狗不能是医生，句子说的是“我”的配偶。", "手机": "语义：手机不能当医生，与句子的主语语境不符。", "工资": "搭配：“工资”不能作“是医生”的主语，与“医生”搭配不当。"}, "sentence_index": 0, "correct_answer": "爱人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班新来了一位爱人，老师让他坐在我旁边。", "explanation": "这里应该用〈同学〉。爱人指配偶，班里新来的人不能叫爱人。"}, {"text": "我的爱人都在老家。", "explanation": "这里应该用〈亲人〉。爱人只指配偶，一个人只有一位，不能用“都”指多人。"}, {"text": "这盆花是我的爱人。", "explanation": "这里应该用〈植物〉。爱人指和你结了婚的人，花属于植物，不能说爱人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97261, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确答案。ài rén，指和你结了婚的人。"}, {"text": "外人", "is_correct": false, "explanation": "wài 比 ài 多一个声母 w，声调相同，意思是外面的人、局外人。"}, {"text": "害人", "is_correct": false, "explanation": "hài 比 ài 多一个声母 h，声调相同，意思是伤害别人。"}, {"text": "带人", "is_correct": false, "explanation": "dài 比 ài 多一个声母 d，意思是带领别人。"}], "explanations": {"爱人": "正确答案。ài rén，指和你结了婚的人。", "外人": "wài 比 ài 多一个声母 w，声调相同，意思是外面的人、局外人。", "害人": "hài 比 ài 多一个声母 h，声调相同，意思是伤害别人。", "带人": "dài 比 ài 多一个声母 d，意思是带领别人。"}, "sentence_index": null, "correct_answer": "爱人"}, "level_3": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确。“爱人”指配偶，给配偶买衣服符合纪念日的语境。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能穿衣服，“买衣服”的对象应是人或宠物。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能穿衣服，与“买了一件新衣服”的语境不合。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能穿衣服，“买……衣服”的对象不能是“空气”。"}], "explanations": {"爱人": "正确。“爱人”指配偶，给配偶买衣服符合纪念日的语境。", "房子": "语义：房子不能穿衣服，“买衣服”的对象应是人或宠物。", "电脑": "语义：电脑不能穿衣服，与“买了一件新衣服”的语境不合。", "空气": "搭配：“空气”不能穿衣服，“买……衣服”的对象不能是“空气”。"}, "sentence_index": 6, "correct_answer": "爱人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请来了一位爱人，大家一起吃饭。", "explanation": "这里应该用〈客人〉。爱人指配偶，不能用来指请来的客人。"}, {"text": "这所学校有很多爱人。", "explanation": "这里应该用〈学生〉。爱人指已结婚的配偶，学校里的人要说学生。"}, {"text": "他在车站迷了路，一位爱人热心地给他指了方向。", "explanation": "这里应该用〈路人〉。爱人指配偶，不认识的路人不能叫爱人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班以后，我和一只爱人去超市买菜。", "corrected_sentence": "下班以后，我和爱人去超市买菜。", "error_description": "错误：“只”是动物的量词，不能用于指人的“爱人”。正确：去掉“一只”，说“我和爱人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的一张爱人在医院当护士。", "corrected_sentence": "我的爱人在医院当护士。", "error_description": "错误：“张”用于平面的东西，不能用来指人的“爱人”。正确：去掉“一张”，说“我的爱人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
