INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指丈夫或妻子。", "primary_collocate": null, "pronunciation": "ài rén", "ipa": "aɪ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我爱人今天出差，晚上才能回来。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您爱人在哪家公司上班？", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生的爱人是他大学同学。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和爱人一起开了一家小饭店。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师的爱人也是老师，他们都教英语。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月给爱人打两次电话。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱人明天过生日，我想送她一束花。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的爱人喜欢吃辣的吗？", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爱人是司机，常常很晚才回家。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱人生病的时候，他一直在身边照顾。", "target_word": "爱人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位爱人", "label": "量词"}, {"form": "一个爱人", "label": "量词"}, {"form": "愛人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "指丈夫或妻子，夫妻中的一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46ee9e0b-68ba-46f4-b9a7-5e8554882c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97262, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确答案。ài rén，指丈夫或妻子。"}, {"text": "大人", "is_correct": false, "explanation": "dà 比 ài 多一个声母 d，声调相同，意思是大人（成年人）。"}, {"text": "待人", "is_correct": false, "explanation": "dài 比 ài 多一个声母 d，意思是对待别人。"}, {"text": "矮人", "is_correct": false, "explanation": "ǎi（第三声）与 ài（第四声）声调不同，意思是个子矮的人。"}], "explanations": {"爱人": "正确答案。ài rén，指丈夫或妻子。", "大人": "dà 比 ài 多一个声母 d，声调相同，意思是大人（成年人）。", "待人": "dài 比 ài 多一个声母 d，意思是对待别人。", "矮人": "ǎi（第三声）与 ài（第四声）声调不同，意思是个子矮的人。"}, "sentence_index": null, "correct_answer": "爱人"}, "level_3": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确。“爱人”指丈夫或妻子，与“今天出差”的语境相符。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能出差，句中的主语应是人。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“出差”的主语应是有工作的人，钥匙不能说出差。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能出差，与句子的语境不合。"}], "explanations": {"爱人": "正确。“爱人”指丈夫或妻子，与“今天出差”的语境相符。", "小狗": "语义：小狗不能出差，句中的主语应是人。", "钥匙": "搭配：“出差”的主语应是有工作的人，钥匙不能说出差。", "房子": "语义：房子不能出差，与句子的语境不合。"}, "sentence_index": 0, "correct_answer": "爱人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在公交车上遇到一位爱人，两人聊了一路。", "explanation": "这里应该用〈陌生人〉。爱人指配偶，刚认识的陌生人不能叫爱人。"}, {"text": "我的爱人都在外地，只有我一个人在城里。", "explanation": "这里应该用〈亲戚〉。爱人只指一位配偶，不能用“都”指多人。"}, {"text": "这间屋子是我的爱人。", "explanation": "这里应该用〈家〉。爱人指和你结了婚的人，房屋要说家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97262, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确答案。ài rén，指丈夫或妻子。"}, {"text": "外人", "is_correct": false, "explanation": "wài 比 ài 多一个声母 w，声调相同，意思是外面的人、局外人。"}, {"text": "害人", "is_correct": false, "explanation": "hài 比 ài 多一个声母 h，声调相同，意思是伤害别人。"}, {"text": "带人", "is_correct": false, "explanation": "dài 比 ài 多一个声母 d，意思是带领别人。"}], "explanations": {"爱人": "正确答案。ài rén，指丈夫或妻子。", "外人": "wài 比 ài 多一个声母 w，声调相同，意思是外面的人、局外人。", "害人": "hài 比 ài 多一个声母 h，声调相同，意思是伤害别人。", "带人": "dài 比 ài 多一个声母 d，意思是带领别人。"}, "sentence_index": null, "correct_answer": "爱人"}, "level_3": {"options": [{"text": "爱人", "is_correct": true, "explanation": "正确。“爱人”指丈夫或妻子，与后文的“她”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能过生日，句子的主语应是人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能过生日，与句子的主语语境不合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会过生日，句子的主语应是人。"}], "explanations": {"爱人": "正确。“爱人”指丈夫或妻子，与后文的“她”相符。", "桌子": "语义：桌子不能过生日，句子的主语应是人。", "窗户": "语义：窗户不能过生日，与句子的主语语境不合。", "汽车": "语义：汽车不会过生日，句子的主语应是人。"}, "sentence_index": 6, "correct_answer": "爱人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚养的那只小狗，是我的爱人。", "explanation": "这里应该用〈宠物〉。爱人指配偶，不能用来指小狗。"}, {"text": "在火车上，我们都是爱人。", "explanation": "这里应该用〈陌生人〉。爱人指已婚的配偶，火车上素不相识的人不能叫爱人。"}, {"text": "他最大的爱人是打篮球。", "explanation": "这里应该用〈爱好〉。爱人指和你结了婚的人，说兴趣要用爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一只爱人在银行工作，每天很早出门。", "corrected_sentence": "我爱人在银行工作，每天很早出门。", "error_description": "错误：“一只”用于动物，不能加在指人的“爱人”前。正确：去掉“一只”，说“我爱人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爱人了去年换了工作，现在在银行上班。", "corrected_sentence": "我爱人去年换了工作，现在在银行上班。", "error_description": "错误：“了”直接加在名词“爱人”之后，名词后不能加动态助词“了”。正确：“我爱人去年换了工作”，“了”应放在动词“换”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9de262d-c604-4a20-b411-a3443186dc3b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
