INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力打，把人或动物打死。", "primary_collocate": null, "pronunciation": "dǎ shā", "ipa": "ta²¹⁴ ʂa⁵⁵", "syllable_count": 2, "sentences": [{"text": "他用棍子打杀了一条蛇。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农夫打杀了偷鸡的黄鼠狼。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎来了，大家一起把它打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条疯狗咬了人，村民把它打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一棍子打杀了那只老鼠。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人打杀过一头野猪。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用石头打杀小鸟。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强盗闯进村里，村民打杀了两个强盗。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猎人打杀了一只狼。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗太凶，主人也没有打杀它。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打杀了", "label": "体标"}, {"form": "打杀过", "label": "体标"}, {"form": "打殺", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用力打，把人或动物打死", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打，把人或动物打死。"}, {"text": "打伤", "is_correct": false, "explanation": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。"}, {"text": "大厦", "is_correct": false, "explanation": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。"}, {"text": "打傻", "is_correct": false, "explanation": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}], "explanations": {"打杀": "目标词：用力打，把人或动物打死。", "打伤": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。", "大厦": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。", "打傻": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}, "sentence_index": null, "correct_answer": "打杀"}, "level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打死动物，符合“用棍子打杀了一条蛇”的情节。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指养育动物，与“用棍子”的动作不合，句子意思不通。"}, {"text": "抚摸", "is_correct": false, "explanation": "搭配：“抚摸”要用手，不能用棍子，搭配不当。"}, {"text": "救活", "is_correct": false, "explanation": "语义：“救活”是使其存活，与“打”的动作相反。"}], "explanations": {"打杀": "目标词：用力打死动物，符合“用棍子打杀了一条蛇”的情节。", "饲养": "语义：“饲养”指养育动物，与“用棍子”的动作不合，句子意思不通。", "抚摸": "搭配：“抚摸”要用手，不能用棍子，搭配不当。", "救活": "语义：“救活”是使其存活，与“打”的动作相反。"}, "sentence_index": 0, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兽医打杀了那只受伤的狗，几天后狗的伤就好了。", "explanation": "这里应该用〈救治〉。打杀指用力打死，而句子说狗的伤好了，前后矛盾。"}, {"text": "他用棍子打杀了那条狗，那条狗却还在院子里跑。", "explanation": "这里应该用〈打伤〉。打杀指打死，而句子说狗还在院子里跑，前后矛盾。"}, {"text": "村民用石头打杀了那群狼，狼群却全都逃走了。", "explanation": "这里应该用〈击退〉。打杀指打死，而句子说狼群全都逃走，并未死去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：用力打死动物，符合“别用石头打杀小鸟”的语境。"}, {"text": "放生", "is_correct": false, "explanation": "语义：“放生”是放走动物使其活命，与“用石头”的动作相反。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：“驯养”多指养成家畜或宠物，与“用石头”的动作不搭配。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护卫，与“用石头打”的动作相反。"}], "explanations": {"打杀": "目标词：用力打死动物，符合“别用石头打杀小鸟”的语境。", "放生": "语义：“放生”是放走动物使其活命，与“用石头”的动作相反。", "驯养": "搭配：“驯养”多指养成家畜或宠物，与“用石头”的动作不搭配。", "保护": "语义：“保护”是护卫，与“用石头打”的动作相反。"}, "sentence_index": 6, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这匹野马很烈，打杀后就能骑了。", "explanation": "这里应该用〈驯服〉。打杀指打死，马被打死后就无法骑了。"}, {"text": "猫受了惊，主人轻声打杀它。", "explanation": "这里应该用〈安抚〉。打杀要用力打死，与“轻声”的动作相矛盾。"}, {"text": "农民每天打杀那几只狗，让它们听话。", "explanation": "这里应该用〈驯养〉。打杀指用力打死，被打死的狗无法再听话，与“让它们听话”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农夫用棍子把那只狐狸打杀死了。", "corrected_sentence": "农夫用棍子把那只狐狸打杀了。", "error_description": "“打杀”本身已含“打死”之义，后面再加“死”属于重复补语。正确说法：农夫用棍子把那只狐狸打杀了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老鼠偷吃粮食，村民已经把它打杀着。", "corrected_sentence": "老鼠偷吃粮食，村民已经把它打杀了。", "error_description": "“着”表示持续，不能与表示完成的“已经”及结果义的“打杀”连用，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "殴打致死；多见于方言和旧小说。", "primary_collocate": null, "pronunciation": "dǎ shā", "ipa": "ta²¹⁴ ʂa⁵⁵", "syllable_count": 2, "sentences": [{"text": "那个恶霸把长工打杀了。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕自己一生气，会失手打杀了人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里写他一怒之下打杀了仇人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，当年有人在村口打杀了一个小偷。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了酒，差点打杀了邻居。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官府说，是他打杀了那个商人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的恶霸打杀过好几个人。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打杀了人，只好连夜逃走。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都说是王二打杀了他的哥哥。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥一时失手，打杀了那个欺负人的恶棍。", "target_word": "打杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打杀了", "label": "体标"}, {"form": "打杀过", "label": "体标"}, {"form": "打殺", "label": "繁体"}], "register": "方言", "sense_fingerprint": "殴打致死，方言或旧小说用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f717fd14-6503-4f57-9a9e-7991918eabcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：殴打致死，多见于方言和旧小说。"}, {"text": "打伤", "is_correct": false, "explanation": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。"}, {"text": "大厦", "is_correct": false, "explanation": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。"}, {"text": "打傻", "is_correct": false, "explanation": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}], "explanations": {"打杀": "目标词：殴打致死，多见于方言和旧小说。", "打伤": "打伤（dǎ shāng）第二音节韵母不同（-āng 与 -ā），意思是打得受伤而没有死。", "大厦": "大厦（dà shà）两个音节的声调都与 dǎ shā 不同，意思是高楼。", "打傻": "打傻（dǎ shǎ）第二音节声调不同（shǎ 第三声，shā 第一声），意思是打得神志失常。"}, "sentence_index": null, "correct_answer": "打杀"}, "level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：殴打致死，符合恶霸杀害长工的情节。"}, {"text": "善待", "is_correct": false, "explanation": "语义：“善待”是好好对待，与“恶霸”的身份和“打杀了”的情节矛盾。"}, {"text": "尊敬", "is_correct": false, "explanation": "语义：“尊敬”表示敬重，与恶霸欺压长工的情节不合。"}, {"text": "体谅", "is_correct": false, "explanation": "搭配：“体谅”多用于理解对方的难处，与“恶霸”的身份不搭配。"}], "explanations": {"打杀": "目标词：殴打致死，符合恶霸杀害长工的情节。", "善待": "语义：“善待”是好好对待，与“恶霸”的身份和“打杀了”的情节矛盾。", "尊敬": "语义：“尊敬”表示敬重，与恶霸欺压长工的情节不合。", "体谅": "搭配：“体谅”多用于理解对方的难处，与“恶霸”的身份不搭配。"}, "sentence_index": 0, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被对方打杀后，第二天还照常去上班。", "explanation": "这里应该用〈殴打〉。打杀指殴打致死，而句子说他第二天还照常上班，两者矛盾，应用〈殴打〉。"}, {"text": "他把小偷打杀后送去了医院。", "explanation": "这里应该用〈打伤〉。打杀指打死，而句子说被送去了医院，人还活着。"}, {"text": "几个孩子在院子里打杀同伴，玩得很开心。", "explanation": "这里应该用〈打闹〉。打杀指殴打致死，把“打杀同伴”用来形容玩耍，与“玩得很开心”矛盾，应用〈打闹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打杀", "is_correct": true, "explanation": "目标词：“过”表示经历，指恶霸曾经殴打致死好几个人。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，与恶霸的凶狠形象不符。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与恶霸杀人的情节相反。"}, {"text": "疼爱", "is_correct": false, "explanation": "搭配：“疼爱”多用于对亲近的人，用于“恶霸”搭配不当。"}], "explanations": {"打杀": "目标词：“过”表示经历，指恶霸曾经殴打致死好几个人。", "感谢": "语义：“感谢”表示感激，与恶霸的凶狠形象不符。", "赞美": "语义：“赞美”表示称赞，与恶霸杀人的情节相反。", "疼爱": "搭配：“疼爱”多用于对亲近的人，用于“恶霸”搭配不当。"}, "sentence_index": 6, "correct_answer": "打杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在巷子里打杀了那个小偷，直到他认错。", "explanation": "这里应该用〈教训〉。打杀指殴打致死，而句子说“直到他认错”，死人不能认错，前后矛盾，应用〈教训〉。"}, {"text": "他被对方一拳打杀，过了一会儿就醒了。", "explanation": "这里应该用〈打晕〉。打杀意味着致死，而句子说“过了一会儿就醒了”，前后矛盾。"}, {"text": "小男孩调皮，被大孩子打杀得鼻青脸肿。", "explanation": "这里应该用〈揍〉。打杀指殴打致死，而句子说“鼻青脸肿”，人仍然活着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个恶霸没把长工打杀了。", "corrected_sentence": "那个恶霸没把长工打杀。", "error_description": "“没”表示否定时，“打杀”后不加“了”。正确说法：那个恶霸没把长工打杀。加“了”与否定相矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那伙强盗抢了粮食，村民把他们打杀死了。", "corrected_sentence": "那伙强盗抢了粮食，村民把他们打杀了。", "error_description": "“打杀”本身已含“打死”之义，后面不必再加“死”，属于重复补语。正确说法：村民把他们打杀了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1d7d98-af65-45b4-9887-b6f426775e29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
