INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97267, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体或东西向前伸，看一看里面。", "primary_collocate": null, "pronunciation": "tàn", "ipa": "tʰan˥˩", "syllable_count": 1, "sentences": [{"text": "他探着身子往井里看。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫从盒子里探出头来。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子探头看了看窗外。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她探过身子，想看清桌上的书。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把头探出车窗外，太危险。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟探着头，偷偷看门里的人。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口探了探头，又走开了。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟从树洞里探出头来。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈探身看了看睡着的孩子。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我探进头去，屋里一个人也没有。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "探了", "label": "完成体"}, {"form": "探着", "label": "持续体"}, {"form": "探过", "label": "经历体"}, {"form": "探探", "label": "重叠"}, {"form": "探头", "label": "复合"}], "register": "中性", "sense_fingerprint": "身子或头向前伸出去看里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97267, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "探", "is_correct": true, "explanation": "tàn（第四声），意思是身子或头向前伸出去看，即本题的词。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是贪婪。"}, {"text": "谈", "is_correct": false, "explanation": "tán（第二声）与 tàn（第四声）声调不同，意思是说话、交谈。"}, {"text": "烫", "is_correct": false, "explanation": "tàng 与 tàn 韵母不同（ang 与 an），意思是温度高、烫手。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（第三声）与 tàn（第四声）声调不同，意思是毯子。"}, {"text": "淡", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），意思是味道或颜色浅。"}], "explanations": {"探": "tàn（第四声），意思是身子或头向前伸出去看，即本题的词。", "贪": "tān（第一声）与 tàn（第四声）声调不同，意思是贪婪。", "谈": "tán（第二声）与 tàn（第四声）声调不同，意思是说话、交谈。", "烫": "tàng 与 tàn 韵母不同（ang 与 an），意思是温度高、烫手。", "毯": "tǎn（第三声）与 tàn（第四声）声调不同，意思是毯子。", "淡": "dàn 与 tàn 声母不同（d 与 t），意思是味道或颜色浅。"}, "sentence_index": null, "correct_answer": "探"}, "level_3": {"options": [{"text": "探", "is_correct": true, "explanation": "探指身子向前伸出去，与“着身子往井里看”搭配。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是搬运，不能用来描述身子向前伸去看井里。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是发声，与“着身子往井里看”的动作意思不合。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者，“送着身子”不成立。"}], "explanations": {"探": "探指身子向前伸出去，与“着身子往井里看”搭配。", "搬": "语义：搬是搬运，不能用来描述身子向前伸去看井里。", "唱": "语义：唱是发声，与“着身子往井里看”的动作意思不合。", "送": "配价：“送”需要接受者，“送着身子”不成立。"}, "sentence_index": 0, "correct_answer": "探"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她探了个懒腰。", "explanation": "这里应该用〈伸〉。“伸懒腰”是伸展身体，“探”只指身子或头向前伸出去看，不能用于伸懒腰。"}, {"text": "他探出援手帮我。", "explanation": "这里应该用〈伸〉。“伸出援手”指主动帮助别人，“探”没有这个用法。"}, {"text": "他探了个喷嚏，准备去洗手。", "explanation": "这里应该用〈打〉。“打喷嚏”是口鼻的动作，“探”指身子或头向前伸出去看里面，不能用于喷嚏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97267, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "探", "is_correct": true, "explanation": "tàn（第四声），意思是身子或头向前伸出去看，即本题的词。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是摊位、摊开。"}, {"text": "坦", "is_correct": false, "explanation": "tǎn（第三声）与 tàn（第四声）声调不同，意思是平坦、坦率。"}, {"text": "趟", "is_correct": false, "explanation": "tàng 与 tàn 韵母不同（ang 与 an），意思是量词，用于次数或来回。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），意思是鸡蛋等。"}, {"text": "瘫", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是身体失去活动能力。"}], "explanations": {"探": "tàn（第四声），意思是身子或头向前伸出去看，即本题的词。", "摊": "tān（第一声）与 tàn（第四声）声调不同，意思是摊位、摊开。", "坦": "tǎn（第三声）与 tàn（第四声）声调不同，意思是平坦、坦率。", "趟": "tàng 与 tàn 韵母不同（ang 与 an），意思是量词，用于次数或来回。", "蛋": "dàn 与 tàn 声母不同（d 与 t），意思是鸡蛋等。", "瘫": "tān（第一声）与 tàn（第四声）声调不同，意思是身体失去活动能力。"}, "sentence_index": null, "correct_answer": "探"}, "level_3": {"options": [{"text": "探", "is_correct": true, "explanation": "“探了探头”表示把头向前伸出去看一下，与“又走开了”的动作顺序相符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛弃，不能说“扔了扔头”。"}, {"text": "喊", "is_correct": false, "explanation": "语义：喊是发出声音，不能与“头”组成这样的动作。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”指取下果实，不能与“头”搭配。"}], "explanations": {"探": "“探了探头”表示把头向前伸出去看一下，与“又走开了”的动作顺序相符。", "扔": "语义：扔是抛弃，不能说“扔了扔头”。", "喊": "语义：喊是发出声音，不能与“头”组成这样的动作。", "摘": "搭配：“摘”指取下果实，不能与“头”搭配。"}, "sentence_index": 6, "correct_answer": "探"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他要为母亲探冤。", "explanation": "这里应该用〈伸〉。“伸冤”指洗清冤屈，“探”没有这个用法。"}, {"text": "他探探筋骨，准备出门。", "explanation": "这里应该用〈伸〉。“伸筋骨”指活动身体，“探”不能这样用。"}, {"text": "他探了个哈欠，准备睡觉。", "explanation": "这里应该用〈打〉。“打哈欠”是口部的动作，“探”只指身子或头向前伸出去看，不能用于哈欠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗从门缝里出探头来看外面。", "corrected_sentence": "小狗从门缝里探出头来看外面。", "error_description": "语序错误：“探”与补语“出”应连用为“探出”，不能把“出”放在“探”前面。正确的说法是“探出头来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把头探出门里，看了看屋子。", "corrected_sentence": "他把头探进门里，看了看屋子。", "error_description": "补语方向错误：伸入门里要用“进”，“探出”是向外伸，与“门里”的方向相反。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
