INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "试着寻找、打听或了解情况。", "primary_collocate": null, "pronunciation": "tàn", "ipa": "tʰan˥˩", "syllable_count": 1, "sentences": [{"text": "他用脚探了探水有多深。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先派人去探探路。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想探一探学生的想法。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着探了探我的口风。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想探一探这家公司的底细。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先去探探情况，再告诉大家。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他探过我的口气，我什么也没说。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里下雪，爸爸拿着棍子探着路走。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想探探老板愿不愿意加工资。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子伸手探了探水温，说有点烫。", "target_word": "探", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "探了", "label": "完成体"}, {"form": "探着", "label": "持续体"}, {"form": "探过", "label": "经历体"}, {"form": "探探", "label": "重叠"}, {"form": "探路", "label": "复合"}], "register": "中性", "sense_fingerprint": "试着寻找、打听、了解情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "探", "is_correct": true, "explanation": "tàn（第四声），意思是试着寻找、打听或了解情况，即本题的词。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是贪婪。"}, {"text": "谈", "is_correct": false, "explanation": "tán（第二声）与 tàn（第四声）声调不同，意思是交谈。"}, {"text": "烫", "is_correct": false, "explanation": "tàng 与 tàn 韵母不同（ang 与 an），意思是温度高。"}, {"text": "坦", "is_correct": false, "explanation": "tǎn（第三声）与 tàn（第四声）声调不同，意思是平坦、坦率。"}, {"text": "蛋", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），意思是鸡蛋等。"}], "explanations": {"探": "tàn（第四声），意思是试着寻找、打听或了解情况，即本题的词。", "贪": "tān（第一声）与 tàn（第四声）声调不同，意思是贪婪。", "谈": "tán（第二声）与 tàn（第四声）声调不同，意思是交谈。", "烫": "tàng 与 tàn 韵母不同（ang 与 an），意思是温度高。", "坦": "tǎn（第三声）与 tàn（第四声）声调不同，意思是平坦、坦率。", "蛋": "dàn 与 tàn 声母不同（d 与 t），意思是鸡蛋等。"}, "sentence_index": null, "correct_answer": "探"}, "level_3": {"options": [{"text": "探", "is_correct": true, "explanation": "“探了探水有多深”表示试着测量水的深浅，与句意相符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢是用脚击打，不能用来测量水深。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“水有多深”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是吞咽，不能用来测量水深。"}], "explanations": {"探": "“探了探水有多深”表示试着测量水的深浅，与句意相符。", "踢": "语义：踢是用脚击打，不能用来测量水深。", "洗": "搭配：“洗”不能与“水有多深”搭配。", "喝": "语义：喝是吞咽，不能用来测量水深。"}, "sentence_index": 0, "correct_answer": "探"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他冷得探了个寒颤。", "explanation": "这里应该用〈打〉。“打寒颤”是身体发抖，“探”指试着寻找、打听或了解情况，不能用于寒颤。"}, {"text": "她探了个懒腰。", "explanation": "这里应该用〈伸〉。“伸懒腰”是伸展身体，“探”没有这个用法。"}, {"text": "他探出援手帮我。", "explanation": "这里应该用〈伸〉。“伸出援手”指主动帮助别人，“探”没有这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "探", "is_correct": true, "explanation": "tàn（第四声），意思是试着寻找、打听或了解情况，即本题的词。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是摊位、摊开。"}, {"text": "毯", "is_correct": false, "explanation": "tǎn（第三声）与 tàn（第四声）声调不同，意思是毯子。"}, {"text": "趟", "is_correct": false, "explanation": "tàng 与 tàn 韵母不同（ang 与 an），意思是量词，用于次数或来回。"}, {"text": "淡", "is_correct": false, "explanation": "dàn 与 tàn 声母不同（d 与 t），意思是味道或颜色浅。"}, {"text": "瘫", "is_correct": false, "explanation": "tān（第一声）与 tàn（第四声）声调不同，意思是身体失去活动能力。"}], "explanations": {"探": "tàn（第四声），意思是试着寻找、打听或了解情况，即本题的词。", "摊": "tān（第一声）与 tàn（第四声）声调不同，意思是摊位、摊开。", "毯": "tǎn（第三声）与 tàn（第四声）声调不同，意思是毯子。", "趟": "tàng 与 tàn 韵母不同（ang 与 an），意思是量词，用于次数或来回。", "淡": "dàn 与 tàn 声母不同（d 与 t），意思是味道或颜色浅。", "瘫": "tān（第一声）与 tàn（第四声）声调不同，意思是身体失去活动能力。"}, "sentence_index": null, "correct_answer": "探"}, "level_3": {"options": [{"text": "探", "is_correct": true, "explanation": "“探过我的口气”表示试着打听我的想法，与“我什么也没说”的语境相符。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸是用力击打，不能用来指打听口气。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“口气”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不能用来指打听口气。"}], "explanations": {"探": "“探过我的口气”表示试着打听我的想法，与“我什么也没说”的语境相符。", "砸": "语义：砸是用力击打，不能用来指打听口气。", "吃": "搭配：“吃”不能与“口气”搭配。", "扔": "语义：扔是丢弃，不能用来指打听口气。"}, "sentence_index": 6, "correct_answer": "探"}, "level_6": {"correct_sentence_index": 4, "wrong_sentences": [{"text": "他要为母亲探冤。", "explanation": "这里应该用〈伸〉。“伸冤”指洗清冤屈，“探”没有这个用法。"}, {"text": "他探探筋骨，准备出门。", "explanation": "这里应该用〈伸〉。“伸筋骨”指活动身体，“探”不能这样用。"}, {"text": "他探了个哈欠，准备睡觉。", "explanation": "这里应该用〈打〉。“打哈欠”是口部的动作，“探”指试着寻找或了解，不能用于哈欠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里很黑，他拿着手电探路着往前走。", "corrected_sentence": "夜里很黑，他拿着手电探着路往前走。", "error_description": "语序错误：“着”是“探”的持续体标记，应紧跟“探”，说“探着路”，不能说“探路着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想先探一他的口风。", "corrected_sentence": "我想先探一探他的口风。", "error_description": "重叠错误：“探一探”是动词重叠（V一V），表示试一试；这里少了后面的“探”，不能说“探一他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
