INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97271, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体猛地向前，朝着一个东西冲过去。", "primary_collocate": null, "pronunciation": "pū", "ipa": "pʰu˥", "syllable_count": 1, "sentences": [{"text": "小狗向我扑过来。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一下子扑到妈妈怀里。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫扑向桌上的小鸟。", "target_word": "扑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他扑过去抱住了那个孩子。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎突然向前扑去。", "target_word": "扑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小女孩哭着扑进奶奶的怀里。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "守门员飞身扑向足球。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只狗朝陌生人扑了过去。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他高兴地扑上去拥抱朋友。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老鹰从天上扑下来抓小鸡。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "扑了", "label": "体标"}, {"form": "扑过", "label": "体标"}, {"form": "扑向", "label": "复合"}, {"form": "撲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体猛地向前冲向目标，如猫扑老鼠、孩子扑进怀里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97271, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扑", "is_correct": true, "explanation": "扑（第一声）：身体猛地向前冲过去，是本词的读音与义项。"}, {"text": "普", "is_correct": false, "explanation": "普（第三声）与扑（第一声）声调不同，意思是普遍。"}, {"text": "葡", "is_correct": false, "explanation": "葡（第二声）与扑（第一声）声调不同，意思是葡萄。"}, {"text": "曝", "is_correct": false, "explanation": "曝（第四声）与扑（第一声）声调不同，意思是曝晒或曝光。"}, {"text": "朴", "is_correct": false, "explanation": "朴（第三声）与扑（第一声）声调不同，意思是朴素。"}], "explanations": {"扑": "扑（第一声）：身体猛地向前冲过去，是本词的读音与义项。", "普": "普（第三声）与扑（第一声）声调不同，意思是普遍。", "葡": "葡（第二声）与扑（第一声）声调不同，意思是葡萄。", "曝": "曝（第四声）与扑（第一声）声调不同，意思是曝晒或曝光。", "朴": "朴（第三声）与扑（第一声）声调不同，意思是朴素。"}, "sentence_index": null, "correct_answer": "扑"}, "level_3": {"options": [{"text": "扑", "is_correct": true, "explanation": "正确：小狗朝说话人猛地冲过来，用“扑过来”。"}, {"text": "飞", "is_correct": false, "explanation": "语义：小狗不会飞，“飞过来”与动物的动作不符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”多用于搬运物品，不能说小狗自己“搬过来”。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”需要施事把某物抛出，小狗自己移动不能说“扔过来”。"}], "explanations": {"扑": "正确：小狗朝说话人猛地冲过来，用“扑过来”。", "飞": "语义：小狗不会飞，“飞过来”与动物的动作不符。", "搬": "搭配：“搬”多用于搬运物品，不能说小狗自己“搬过来”。", "扔": "配价：“扔”需要施事把某物抛出，小狗自己移动不能说“扔过来”。"}, "sentence_index": 0, "correct_answer": "扑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "篮球扑在了地板上。", "explanation": "这里应该用〈弹〉。扑指身体猛地向前冲，篮球落地后反跳应说〈弹〉。"}, {"text": "他把水扑在地上。", "explanation": "这里应该用〈泼〉。扑指身体猛地向前冲，把水倒在地上应说〈泼〉。"}, {"text": "汽车扑进了院子。", "explanation": "这里应该用〈冲〉。扑指人或动物的身体猛地向前扑去，汽车进院子应说〈冲〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97271, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扑", "is_correct": true, "explanation": "扑（第一声）：身体猛地向前冲过去，是本词的读音与义项。"}, {"text": "谱", "is_correct": false, "explanation": "谱（第三声）与扑（第一声）声调不同，意思是乐谱或图谱。"}, {"text": "蒲", "is_correct": false, "explanation": "蒲（第二声）与扑（第一声）声调不同，意思是蒲草。"}, {"text": "瀑", "is_correct": false, "explanation": "瀑（第四声）与扑（第一声）声调不同，意思是瀑布。"}, {"text": "圃", "is_correct": false, "explanation": "圃（第三声）与扑（第一声）声调不同，意思是菜园。"}], "explanations": {"扑": "扑（第一声）：身体猛地向前冲过去，是本词的读音与义项。", "谱": "谱（第三声）与扑（第一声）声调不同，意思是乐谱或图谱。", "蒲": "蒲（第二声）与扑（第一声）声调不同，意思是蒲草。", "瀑": "瀑（第四声）与扑（第一声）声调不同，意思是瀑布。", "圃": "圃（第三声）与扑（第一声）声调不同，意思是菜园。"}, "sentence_index": null, "correct_answer": "扑"}, "level_3": {"options": [{"text": "扑", "is_correct": true, "explanation": "正确：守门员身体猛地向前冲去，用“扑向”。"}, {"text": "游", "is_correct": false, "explanation": "语义：足球场上守门员不能“游”，与“飞身”也不相合。"}, {"text": "潜", "is_correct": false, "explanation": "搭配：“潜”多指钻入水中或物体之下，不能与“飞身”搭配。"}, {"text": "爬", "is_correct": false, "explanation": "体貌：“爬”动作缓慢，与“飞身”的急速动作相抵触。"}], "explanations": {"扑": "正确：守门员身体猛地向前冲去，用“扑向”。", "游": "语义：足球场上守门员不能“游”，与“飞身”也不相合。", "潜": "搭配：“潜”多指钻入水中或物体之下，不能与“飞身”搭配。", "爬": "体貌：“爬”动作缓慢，与“飞身”的急速动作相抵触。"}, "sentence_index": 6, "correct_answer": "扑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "箭扑向了靶子。", "explanation": "这里应该用〈射〉。扑指有生命的身体猛地向前冲，箭飞向靶子应说〈射〉。"}, {"text": "电梯慢慢扑到了五楼。", "explanation": "这里应该用〈升〉。扑指有生命的身体猛地向前冲，电梯慢慢上到五楼应说〈升〉。"}, {"text": "他朝我扑了一拳。", "explanation": "这里应该用〈打〉。扑指身体猛地向前冲，不指用拳头打人，出拳打人应说〈打〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97271, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子一下子扑妈妈的怀里。", "corrected_sentence": "孩子一下子扑进妈妈的怀里。", "error_description": "“扑”后缺少趋向补语“进”。身体扑入怀中要说“扑进……的怀里”，不能直接接处所宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97271, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "猫扑老鼠身上。", "corrected_sentence": "猫扑在老鼠身上。", "error_description": "“扑”带处所宾语时缺少介词“在”。应说“扑在……身上”，“猫扑老鼠身上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
