INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97272, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体猛地向前冲压；也指拍打。", "primary_collocate": null, "pronunciation": "pū", "ipa": "pʰu˥", "syllable_count": 1, "sentences": [{"text": "他用扇子扑蝴蝶。", "target_word": "扑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她拿毛巾扑掉身上的灰。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用手扑蚊子。", "target_word": "扑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他累得扑在桌子上睡着了。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用书本扑苍蝇。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一头扑在床上，不动了。", "target_word": "扑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们拿着网扑蜻蜓。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用衣服扑火苗。", "target_word": "扑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用湿布扑了几下，火就小了。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进门前先用力扑了扑身上的雪。", "target_word": "扑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扑了", "label": "体标"}, {"form": "扑打", "label": "复合"}, {"form": "扑粉", "label": "复合"}, {"form": "撲", "label": "繁体"}], "register": "口语", "sense_fingerprint": "用手或工具拍打（扑蚊子、扑火），或身体猛地压伏在物体上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26884cc9-df6b-4baa-9d09-a978904c3385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97272, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扑", "is_correct": true, "explanation": "扑（第一声）：用手或工具拍打，或身体压伏在物体上，是本词的读音与义项。"}, {"text": "谱", "is_correct": false, "explanation": "谱（第三声）与扑（第一声）声调不同，意思是乐谱或图谱。"}, {"text": "葡", "is_correct": false, "explanation": "葡（第二声）与扑（第一声）声调不同，意思是葡萄。"}, {"text": "曝", "is_correct": false, "explanation": "曝（第四声）与扑（第一声）声调不同，意思是曝晒或曝光。"}, {"text": "朴", "is_correct": false, "explanation": "朴（第三声）与扑（第一声）声调不同，意思是朴素。"}], "explanations": {"扑": "扑（第一声）：用手或工具拍打，或身体压伏在物体上，是本词的读音与义项。", "谱": "谱（第三声）与扑（第一声）声调不同，意思是乐谱或图谱。", "葡": "葡（第二声）与扑（第一声）声调不同，意思是葡萄。", "曝": "曝（第四声）与扑（第一声）声调不同，意思是曝晒或曝光。", "朴": "朴（第三声）与扑（第一声）声调不同，意思是朴素。"}, "sentence_index": null, "correct_answer": "扑"}, "level_3": {"options": [{"text": "扑", "is_correct": true, "explanation": "正确：用扇子拍打蝴蝶，用“扑”表示拍打。"}, {"text": "唱", "is_correct": false, "explanation": "语义：扇子不能用来“唱”，“唱蝴蝶”也说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象多是衣物等，蝴蝶不能用来“洗”。"}, {"text": "叠", "is_correct": false, "explanation": "配价：“叠”需要纸张作材料，用扇子叠蝴蝶不成立。"}], "explanations": {"扑": "正确：用扇子拍打蝴蝶，用“扑”表示拍打。", "唱": "语义：扇子不能用来“唱”，“唱蝴蝶”也说不通。", "洗": "搭配：“洗”的对象多是衣物等，蝴蝶不能用来“洗”。", "叠": "配价：“叠”需要纸张作材料，用扇子叠蝴蝶不成立。"}, "sentence_index": 0, "correct_answer": "扑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一抬手，把碗扑在了地上。", "explanation": "这里应该用〈摔〉。扑指身体猛地向前冲压，把碗摔在地上应说〈摔〉。"}, {"text": "他把石头扑在纸上，防止纸被风吹走。", "explanation": "这里应该用〈压〉。扑指人的身体压伏在物体上，石头压纸应说〈压〉。"}, {"text": "他慢慢扑进了房间。", "explanation": "这里应该用〈走〉。扑指身体猛地向前冲，与“慢慢”矛盾，慢慢进房间应说〈走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97272, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扑", "is_correct": true, "explanation": "扑（第一声）：用手或工具拍打，或身体压伏在物体上，是本词的读音与义项。"}, {"text": "普", "is_correct": false, "explanation": "普（第三声）与扑（第一声）声调不同，意思是普遍。"}, {"text": "蒲", "is_correct": false, "explanation": "蒲（第二声）与扑（第一声）声调不同，意思是蒲草。"}, {"text": "瀑", "is_correct": false, "explanation": "瀑（第四声）与扑（第一声）声调不同，意思是瀑布。"}, {"text": "圃", "is_correct": false, "explanation": "圃（第三声）与扑（第一声）声调不同，意思是菜园。"}], "explanations": {"扑": "扑（第一声）：用手或工具拍打，或身体压伏在物体上，是本词的读音与义项。", "普": "普（第三声）与扑（第一声）声调不同，意思是普遍。", "蒲": "蒲（第二声）与扑（第一声）声调不同，意思是蒲草。", "瀑": "瀑（第四声）与扑（第一声）声调不同，意思是瀑布。", "圃": "圃（第三声）与扑（第一声）声调不同，意思是菜园。"}, "sentence_index": null, "correct_answer": "扑"}, "level_3": {"options": [{"text": "扑", "is_correct": true, "explanation": "正确：孩子们拿网向蜻蜓猛地扑去，用“扑”。"}, {"text": "吹", "is_correct": false, "explanation": "语义：用网“吹”蜻蜓说不通，网不能用来吹东西。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，蜻蜓不能用来“煮”。"}, {"text": "缝", "is_correct": false, "explanation": "配价：“缝”需要布料或线作材料，网不能用来缝蜻蜓。"}], "explanations": {"扑": "正确：孩子们拿网向蜻蜓猛地扑去，用“扑”。", "吹": "语义：用网“吹”蜻蜓说不通，网不能用来吹东西。", "煮": "搭配：“煮”的对象应是食物，蜻蜓不能用来“煮”。", "缝": "配价：“缝”需要布料或线作材料，网不能用来缝蜻蜓。"}, "sentence_index": 6, "correct_answer": "扑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他朝我扑了一拳。", "explanation": "这里应该用〈打〉。扑指身体猛地向前冲或拍打物体，不指用拳头打人，应说〈打〉。"}, {"text": "汽车扑上了路边的树。", "explanation": "这里应该用〈撞〉。扑指人或动物身体的动作，汽车撞树应说〈撞〉。"}, {"text": "他把书扑在桌上。", "explanation": "这里应该用〈放〉。扑指身体压伏在物体上，把书放在桌上应说〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =