INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用毛巾了扑几下沙发上的灰。", "corrected_sentence": "她用毛巾扑了几下沙发上的灰。", "error_description": "“了”放错位置。体标“了”应紧跟动词“扑”之后，应说“扑了几下”，不能放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用手扑了掉蚊子。", "corrected_sentence": "她用手扑掉了蚊子。", "error_description": "“了”插在“扑”与“掉”之间，位置错误。结果补语“掉”应紧跟“扑”，体标“了”应放在“掉”之后，应说“扑掉了蚊子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e091866e-eec5-4ea3-8e19-52d69fbbd659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
