INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97273, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在国家里管大事、很有名的人。", "primary_collocate": null, "pronunciation": "zhèng zhì rén wù", "ipa": "ʈʂɤŋ˥˩ ʈʂɻ̩˥˩ ɻən˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "他是国家里管大事的政治人物。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上的人都认识那位政治人物。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位政治人物每天要处理很多大事。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问爸爸：“什么是政治人物？”", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上那位政治人物笑着向大家招手。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成了政治人物以后，就很少回家了。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位政治人物走进了会场，大家都站了起来。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想采访一位真正的政治人物。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位政治人物把国家的大事放在第一位。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请来了一位有名的政治人物讲话。", "target_word": "政治人物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "在国家里管大事、很有名的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f32410c-6e6d-4437-8075-dcd4e51788af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治人物", "is_correct": true, "explanation": "政治人物指在国家里管大事、很有名的人，与“他是……的”搭配。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师管的是做饭，不管国家大事，不能说“管大事的厨师”。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生还不能管国家大事，句子的意思说不通。"}, {"text": "窗口", "is_correct": false, "explanation": "搭配：“窗口”指服务台，不能与“管大事”搭配。"}], "explanations": {"政治人物": "政治人物指在国家里管大事、很有名的人，与“他是……的”搭配。", "厨师": "语义：厨师管的是做饭，不管国家大事，不能说“管大事的厨师”。", "小学生": "语义：小学生还不能管国家大事，句子的意思说不通。", "窗口": "搭配：“窗口”指服务台，不能与“管大事”搭配。"}, "sentence_index": 0, "correct_answer": "政治人物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位每天在电视上演戏的人，是一位政治人物。", "explanation": "这里应该用〈影星〉。“政治人物”指在国家里管大事、很有名的人，演戏的人不管国家大事，不属于这个范围。"}, {"text": "这位每天帮人打官司的人，是一位政治人物。", "explanation": "这里应该用〈律师〉。“政治人物”指在国家里管大事、很有名的人，帮人打官司的人不属于这个范围。"}, {"text": "这位球星在比赛中很出色，是一位政治人物。", "explanation": "这里应该用〈体育明星〉。“政治人物”指在国家里管大事、很有名的人，球星属于体育领域，不属于这个范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治人物", "is_correct": true, "explanation": "政治人物是人，能够“走进会场”，也能让“大家站起来”。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“一位小猫”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会走进会场，也不会让大家站起来。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会走进会场，句子的意思说不通。"}], "explanations": {"政治人物": "政治人物是人，能够“走进会场”，也能让“大家站起来”。", "小猫": "搭配：量词“位”只用于人，不能说“一位小猫”。", "河流": "语义：河流不会走进会场，也不会让大家站起来。", "钥匙": "语义：钥匙不会走进会场，句子的意思说不通。"}, "sentence_index": 6, "correct_answer": "政治人物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位每天在厨房做饭的人，是一位政治人物。", "explanation": "这里应该用〈厨师〉。“政治人物”指在国家里管大事、很有名的人，在厨房做饭的人不属于这个范围。"}, {"text": "这位每天在医院给病人看病的人，是一位政治人物。", "explanation": "这里应该用〈医生〉。“政治人物”指在国家里管大事、很有名的人，在医院给病人看病的人不属于这个范围。"}, {"text": "政治人物是一个很大的圈子。", "explanation": "这里应该用〈政界〉。“政界”指政治领域这个圈子，“政治人物”只指人，不能指圈子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室里坐着一只政治人物。", "corrected_sentence": "会议室里坐着一位政治人物。", "error_description": "量词错误：“政治人物”指人，应该用量词“位”（或“个”），不能用“只”，因为“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位真正地政治人物。", "corrected_sentence": "他是一位真正的政治人物。", "error_description": "结构助词错误：修饰名词“政治人物”要用“的”，不能用“地”（“地”用于修饰动词或形容词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b743a-3728-4230-becb-6fceb180a2c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
