INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个数字站的位置，比如个位、十位。", "primary_collocate": null, "pronunciation": "shù wèi", "ipa": "ʂu˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "个位、十位和百位都是数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数字三百四十五有三个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个数位上只能写一个数字。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说出这个数的每一个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数位不一样，数字的大小也不一样。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了几个数位的名字。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数一共有四个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先看清数位，再读这个数。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个位是最右边的那个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个数字在不同的数位上，意思不同。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数位", "label": "量词"}], "register": "中性", "sense_fingerprint": "数字在一个数里所站的位置，如个位、十位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97277, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：一个数字所站的位置，个位、十位、百位都是数位。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字是表示数目的符号，个位、十位是位置，不是符号。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是一门学科，个位、十位不是学科。"}, {"text": "数量", "is_correct": false, "explanation": "语义：数量指东西或数的多少，个位、十位是位置，不是数量。"}], "explanations": {"数位": "数位：一个数字所站的位置，个位、十位、百位都是数位。", "数字": "语义：数字是表示数目的符号，个位、十位是位置，不是符号。", "数学": "语义：数学是一门学科，个位、十位不是学科。", "数量": "语义：数量指东西或数的多少，个位、十位是位置，不是数量。"}, "sentence_index": 0, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "图书馆的数位在学校东边。", "explanation": "这里应该用〈位置〉。“位置”指物体所在的地方，“数位”只指数字中每一位的位置，不能用来说图书馆的地点。"}, {"text": "他把这个数的数位写得很大，几乎占满了整张纸。", "explanation": "这里应该用〈数字〉。“数位”指位置，不能说写得很大；写大的是数字符号。"}, {"text": "这家商店的货物数位很多。", "explanation": "这里应该用〈数量〉。“数量”说东西的多少，“数位”只指数字中的位，不指货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数位", "is_correct": true, "explanation": "数位：数中每一个数码所占的位置，这个数有四位。"}, {"text": "数值", "is_correct": false, "explanation": "语义：数值指数的大小，一个数只有一个数值，不能数“四个”。"}, {"text": "数目", "is_correct": false, "explanation": "搭配：“数目”指总量，不能用“四个”来计数。"}, {"text": "数列", "is_correct": false, "explanation": "语义：数列是按顺序排列的一串数，一个数不能有四个数列。"}], "explanations": {"数位": "数位：数中每一个数码所占的位置，这个数有四位。", "数值": "语义：数值指数的大小，一个数只有一个数值，不能数“四个”。", "数目": "搭配：“数目”指总量，不能用“四个”来计数。", "数列": "语义：数列是按顺序排列的一串数，一个数不能有四个数列。"}, "sentence_index": 6, "correct_answer": "数位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数的数位很大，比一千还大。", "explanation": "这里应该用〈数值〉。“数值”指数的大小，“数位”指数中每一位的位置，不能说“很大”。"}, {"text": "这个数的数位是三。", "explanation": "这里应该用〈位数〉。“位数”指数有几位，“数位”指某一位的位置，不能说“是三”。"}, {"text": "这个数的数位很高，最重要。", "explanation": "这里应该用〈地位〉。“地位”指在某个范围中的重要程度，“数位”指数中某一位的位置，不能说“很高，最重要”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数一共有五只数位。", "corrected_sentence": "这个数一共有五个数位。", "error_description": "量词错误：“数位”前应用“个”，“只”用于动物，不能说“五只数位”，应改为“五个数位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数的最高一只数位是千位。", "corrected_sentence": "这个数的最高数位是千位。", "error_description": "量词错误：“数位”前不能加“一只”，“只”用于动物，这里应直接说“最高数位”，去掉“一只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '636c151e-b994-4b5f-8500-504b5486b973') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
