INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (97278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数中每个数码所占的位置，如个位、十位、百位。", "primary_collocate": null, "pronunciation": "shù wèi", "ipa": "ʂu˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "一万有五个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数位从右往左，先是个位，再是十位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过了数位，知道百位在十位的左边。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明算的时候漏掉了一个数位，答案也错了。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "计算时，数位要对齐。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "九百八十七有三个数位，各数位上的数字都不同。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要说出这个数的最高数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从数位来看，十位在个位的左边。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么读每个数位。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多了一个数位，这个数就大了很多。", "target_word": "数位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个数位", "label": "量词"}], "register": "中性", "sense_fingerprint": "数学中一个数里每个数码所占的位置，决定它的数值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1f89697-2640-4f78-af69-4e841118ae85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
